INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('buildworksai/EUCORA/devops-cicd', 'community', 'buildworksai', 'EUCORA', 'buildworksai/EUCORA', 'devops-cicd', 0, 0, 36, '2026-03-06T06:23:00.216Z', '2026-03-06T08:26:07.724Z', 'b75f0182cf36c0994f4b8baceab8e37e0d5a7c81ae51f6307d48306d4b8a8d56', '{"id":"buildworksai/EUCORA/devops-cicd","name":"devops-cicd","description":{"en":"The devops-cicd skill enables AI agents to standardize application engineering, approval, packaging, and delivery using EUCORA. It benefits developers and DevOps teams by providing a standardized control plane.","zh":"EUCORA是一个AI-enabled的控制平面，标准化应用的工程、审批、打包和交付。使用GitHub Actions和Docker Compose实现CI/CD","ja":"EUCORAはAIを活用した制御平面で、アプリケーションのエンジニアリング、承認、パッケージング、配信を標準化します。GitHub ActionsとDocker Composeを使用してCI/CDを実現","ko":"EUCORA는 AI를 활용한 제어 평면으로, 애플리케이션의 엔지니어링, 승인, 패키징 및 배포를 표준화합니다. GitHub Actions와 Docker Compose를 사용하여 CI/CD를 구현합니다","es":"EUCORA es una arquitectura de control que estandariza la ingeniería, aprobación, empaquetado y entrega de aplicaciones. Implementa patrones de DevOps & CI/CD con GitHub Actions y Docker Compose.","fr":"EUCORA est une architecture de contrôle qui standardise l''ingénierie, l''approbation, l''empaquetage et la livraison d''applications. Mettez en place des modèles de DevOps & CI/CD avec GitHub Actions et Docker Compose.","de":"EUCORA ist eine Steuerungsarchitektur, die die Ingenierie, Genehmigung, Verpackung und Lieferung von Anwendungen standardisiert. Implementieren Sie DevOps- & CI/CD-Muster mit GitHub Actions und Docker Compose.","pt":"EUCORA é uma arquitetura de orquestração de computação de ponta que padroniza a engenharia, aprovação, embalagem e entrega de aplicações","ru":"EUCORA — это архитектура оркестровки конечных вычислений, которая стандартизирует разработку, утверждение, упаковку и доставку приложений","ar":"EUCORA هي هندسة أوركسترا الحوسبة النهاية التي توحد معايير هندسة التطبيقات واعتمادها وتغليفها وتسليمها"},"seo":{"title":{"en":"devops-cicd: CI/CD Setup Guide for AI Agents","zh":"DevOps-CICD.setup指南：使用EUCORA和GitHub Actions","ja":"DevOps-CICDベストプラクティス：EUCORAとGitHub Actionsの活用","ko":"DevOps-CICD 설정 가이드: EUCORA와 GitHub Actions 사용","es":"Guía de configuración de DevOps & CI/CD con EUCORA","fr":"Mise en place de DevOps & CI/CD avec EUCORA","de":"Einrichtungsleitfaden für DevOps & CI/CD mit EUCORA","pt":"Guia de Configuração DevOps CI/CD com EUCORA","ru":"ИИ Агенты для DevOps CI/CD: Руководство по настройке","ar":"دليل إعداد DevOps CI/CD باستخدام EUCORA"},"description":{"en":"Discover how to implement EUCORA with GitHub Actions, Docker Compose, and Kubernetes for streamlined DevOps and CI/CD workflows - learn more and get started ...","zh":"了解如何使用EUCORA和GitHub Actions实现DevOps-CICD，提高代码质量和交付速度","ja":"EUCORAとGitHub Actionsを使用してDevOps-CICDを実現し、コード品質とデリバリー速度を向上させる方法を学びます","ko":"EUCORA와 GitHub Actions를 사용하여 DevOps-CICD를 구현하고 코드 품질 및 배포 속도를 개선하는 방법을 알아보세요","es":"Aprende a implementar patrones de DevOps & CI/CD con EUCORA, incluyendo GitHub Actions y Docker Compose","fr":"Découvrez comment mettre en place des modèles de DevOps & CI/CD avec EUCORA, y compris GitHub Actions et Docker Compose","de":"Erfahren Sie, wie Sie DevOps- & CI/CD-Muster mit EUCORA umsetzen, einschließlich GitHub Actions und Docker Compose","pt":"Aprenda a configurar o pipeline DevOps CI/CD com EUCORA, utilizando GitHub Actions e Docker Compose","ru":"Узнайте, как настроить конвейер DevOps CI/CD с помощью EUCORA, GitHub Actions и Docker Compose","ar":"تعرف على كيفية إعداد خط أنابيب DevOps CI/CD باستخدام EUCORA و GitHub Actions و Docker Compose"},"definition":{"en":"devops-cicd is an AI-enabled control plane that standardizes DevOps and CI/CD patterns for the EUCORA platform, utilizing technologies like GitHub Actions and Kubernetes.","zh":"DevOps-CICD是指使用EUCORA和GitHub Actions等工具实现持续集成和持续交付的实践","ja":"DevOps-CICDとは、EUCORAやGitHub Actionsなどのツールを使用して継続的インテグレーションと継続的デリバリーを実現する実践のこと","ko":"DevOps-CICD는 EUCORA와 GitHub Actions 등의 도구를 사용하여 지속적 통합 및 지속적 배포를 구현하는 실践입니다","es":"EUCORA es una arquitectura de control que estandariza la entrega de aplicaciones mediante patrones de DevOps & CI/CD","fr":"EUCORA est une architecture de contrôle qui standardise la livraison d''applications via des modèles de DevOps & CI/CD","de":"EUCORA ist eine Steuerungsarchitektur, die die Lieferung von Anwendungen durch DevOps- & CI/CD-Muster standardisiert","pt":"DevOps CI/CD é um conjunto de práticas que visa integrar desenvolvimento e operações de TI","ru":"DevOps CI/CD — это набор практик, направленных на интеграцию разработки и эксплуатации ИТ-систем","ar":"DevOps CI/CD هو مجموعة من الممارسات التي تهدف إلى دمج التطوير والتشغيل في مجال تكنولوجيا المعلومات"},"features":{"en":["Utilizes GitHub Actions for CI/CD workflows","Employs Docker Compose for development and Kubernetes for production","Enforces quality gates with pre-commit hooks and CI enforcement","Maintains ≥90% code coverage","Implements zero warnings tolerance for linting"],"zh":["使用GitHub Actions实现CI/CD","Docker Compose用于开发环境","Kubernetes用于生产环境","预提交钩子和CI强制执行质量门","≥90%的代码覆盖率","零警告容忍度"],"ja":["GitHub Actionsを使用してCI/CDを実現","Docker Composeを開発環境で使用","Kubernetesを生产環境で使用","プレコミットフックとCI強制実行による品質ゲート","≥90%のコードカバレッジ","ゼロ警告許容"],"ko":["GitHub Actions를 사용하여 CI/CD를 구현","Docker Compose를 개발 환경에서 사용","Kubernetes를 생산 환경에서 사용","프리 커밋 훅과 CI 강제 실행을 통한 품질 게이트","≥90%의 코드 커버리지","제로 경고 허용"],"es":["Implementación de GitHub Actions para CI/CD","Uso de Docker Compose para la gestión de contenedores","Aplicación de calidad con pre-commit hooks y CI enforcement","Cobertura de código ≥90%","Tolerancia cero para warnings de linting"],"fr":["Mise en place de GitHub Actions pour CI/CD","Utilisation de Docker Compose pour la gestion de conteneurs","Application de la qualité avec des hooks pre-commit et une mise en application de CI","Couverture de code ≥90%","Tolérance zéro pour les avertissements de linting"],"de":["Implementierung von GitHub Actions für CI/CD","Verwendung von Docker Compose für die Containerverwaltung","Anwendung von Qualität mit Pre-Commit-Hooks und CI-Enforcement","Codeabdeckung ≥90%","Null-Toleranz für Linting-Warnings"],"pt":["Utilização de GitHub Actions para automação de pipelines","Orquestração de contêineres com Docker Compose e Kubernetes","Portas de qualidade com pré-commit hooks e CI enforcement","Cobertura de código ≥90%","Tolerância zero para warnings de linting"],"ru":["Использование GitHub Actions для автоматизации конвейеров","Оркестровка контейнеров с помощью Docker Compose и Kubernetes","Качественные ворота с предкоммит-хуками и принудительным CI","Покрытие кода ≥90%","Нулевая толерантность к предупреждениям линтинга"],"ar":["استخدام GitHub Actions لتأتمتة خطوط الأنابيب","أوركسترا حاويات مع Docker Compose و Kubernetes","بوابات جودة مع pré-commit hooks و CI enforcement","تغطية الرمز ≥90%","التحمل الصفري للتحذيرات من لينтинج"]},"keywords":{"en":["how to use devops-cicd","devops-cicd setup guide","EUCORA platform tutorial","GitHub Actions workflow examples","Kubernetes vs Docker Compose","devops-cicd install","CI/CD pipeline optimization","devops-cicd best practices","AI-enabled DevOps tools"],"zh":["DevOps-CICD","EUCORA","GitHub Actions","Docker Compose","Kubernetes","CI/CD","代码质量","持续集成","持续交付"],"ja":["DevOps-CICD","EUCORA","GitHub Actions","Docker Compose","Kubernetes","CI/CD","コード品質","継続的インテグレーション","継続的デリバリー","AIエージェント"],"ko":["DevOps-CICD","EUCORA","GitHub Actions","Docker Compose","Kubernetes","CI/CD","코드 품질","지속적 통합","지속적 배포","AI 에이전트"],"es":["DevOps & CI/CD","EUCORA","GitHub Actions","Docker Compose","pre-commit hooks","CI enforcement","cobertura de código","linting","Herramientas de AI para DevOps"],"fr":["DevOps & CI/CD","EUCORA","GitHub Actions","Docker Compose","hooks pre-commit","mise en application de CI","couverture de code","linting","Outils d''AI pour DevOps"],"de":["DevOps & CI/CD","EUCORA","GitHub Actions","Docker Compose","Pre-Commit-Hooks","CI-Enforcement","Codeabdeckung","Linting","AI-Tools für DevOps"],"pt":["DevOps CI/CD","EUCORA","GitHub Actions","Docker Compose","Kubernetes","orquestração de contêineres","portas de qualidade","cobertura de código"],"ru":["DevOps CI/CD","EUCORA","ИИ Агенты","GitHub Actions","Docker Compose","Kubernetes","оркестровка контейнеров","качественные ворота","покрытие кода"],"ar":["DevOps CI/CD","EUCORA","أدوات الذكاء الاصطناعي","GitHub Actions","Docker Compose","Kubernetes","أوركسترا حاويات","بوابات جودة","تغطية الرمز"]}},"owner":"buildworksai","repo":"EUCORA","repoPath":"buildworksai/EUCORA","stars":0,"forks":0,"updatedAt":"2026-03-06T06:23:00.216Z","topics":[],"category":"community","skillMd":{"name":"devops-cicd","description":"DevOps and CI/CD patterns for EUCORA including GitHub Actions workflows, Docker Compose orchestration, quality gates, and pre-commit hooks. Use when creating pipelines, configuring containers, or implementing quality enforcement.","bodyPreview":"# DevOps & CI/CD Patterns\n\nCI/CD and container orchestration patterns for the EUCORA platform.\n\n---\n\n## Quick Reference\n\n| Technology | Pattern |\n|------------|---------|\n| CI/CD | GitHub Actions |\n| Containers | Docker Compose (dev), Kubernetes (prod) |\n| Quality Gates | Pre-commit hooks + CI enforcement |\n| Coverage | ≥90% enforced |\n| Linting | Zero warnings tolerance |\n\n---\n\n## GitHub Actions Workflows\n\n### Workflow Structure\n\n```yaml\n# .github/workflows/code-quality.yml\nname: Code Quality","body":"# DevOps & CI/CD Patterns\n\nCI/CD and container orchestration patterns for the EUCORA platform.\n\n---\n\n## Quick Reference\n\n| Technology | Pattern |\n|------------|---------|\n| CI/CD | GitHub Actions |\n| Containers | Docker Compose (dev), Kubernetes (prod) |\n| Quality Gates | Pre-commit hooks + CI enforcement |\n| Coverage | ≥90% enforced |\n| Linting | Zero warnings tolerance |\n\n---\n\n## GitHub Actions Workflows\n\n### Workflow Structure\n\n```yaml\n# .github/workflows/code-quality.yml\nname: Code Quality\n\non:\n  push:\n    branches: [main, develop]\n  pull_request:\n    branches: [main]\n\njobs:\n  backend-tests:\n    runs-on: ubuntu-latest\n\n    services:\n      postgres:\n        image: postgres:16\n        env:\n          POSTGRES_DB: test_db\n          POSTGRES_USER: test\n          POSTGRES_PASSWORD: test\n        ports:\n          - 5432:5432\n        options: >-\n          --health-cmd pg_isready\n          --health-interval 10s\n          --health-timeout 5s\n          --health-retries 5\n\n    steps:\n      - uses: actions/checkout@v4\n\n      - name: Set up Python\n        uses: actions/setup-python@v5\n        with:\n          python-version: ''3.12''\n          cache: ''pip''\n\n      - name: Install dependencies\n        run: pip install -r requirements.txt\n\n      - name: Run tests with coverage\n        run: pytest --cov --cov-fail-under=90 --cov-report=xml\n        env:\n          DATABASE_URL: postgres://test:test@localhost:5432/test_db\n\n      - name: Upload coverage\n        uses: codecov/codecov-action@v4\n        with:\n          files: coverage.xml\n          fail_ci_if_error: true\n\n  frontend-tests:\n    runs-on: ubuntu-latest\n\n    steps:\n      - uses: actions/checkout@v4\n\n      - name: Set up Node\n        uses: actions/setup-node@v4\n        with:\n          node-version: ''20''\n          cache: ''npm''\n          cache-dependency-path: frontend/package-lock.json\n\n      - name: Install dependencies\n        run: npm ci\n        working-directory: frontend\n\n      - name: TypeScript check\n        run: npx tsc --noEmit\n        working-directory: frontend\n\n      - name: ESLint (zero warnings)\n        run: npm run lint -- --max-warnings 0\n        working-directory: frontend\n\n      - name: Run tests\n        run: npm test -- --coverage\n        working-directory: frontend\n```\n\n### Quality Gate Enforcement\n\n```yaml\n# Quality gate job - blocks merge if failed\nquality-gate:\n  runs-on: ubuntu-latest\n  needs: [backend-tests, frontend-tests, security-scan]\n\n  steps:\n    - name: Check all jobs passed\n      run: |\n        echo \"All quality gates passed ✅\"\n        echo \"- Backend tests: ${{ needs.backend-tests.result }}\"\n        echo \"- Frontend tests: ${{ needs.frontend-tests.result }}\"\n        echo \"- Security scan: ${{ needs.security-scan.result }}\"\n```\n\n---\n\n## Docker Compose\n\n### Development Configuration\n\n```yaml\n# docker-compose.dev.yml\nversion: ''3.8''\n\nservices:\n  web:\n    build:\n      context: .\n      dockerfile: Dockerfile.dev\n    ports:\n      - \"8000:8000\"\n    volumes:\n      - ./backend:/app\n      - static_volume:/app/staticfiles\n    environment:\n      - DEBUG=True\n      - DATABASE_URL=postgres://user:pass@db:5432/eucora\n      - REDIS_URL=redis://redis:6379/0\n    depends_on:\n      db:\n        condition: service_healthy\n      redis:\n        condition: service_healthy\n    healthcheck:\n      test: [\"CMD\", \"curl\", \"-f\", \"http://localhost:8000/health/\"]\n      interval: 30s\n      timeout: 10s\n      retries: 3\n\n  db:\n    image: postgres:16\n    volumes:\n      - postgres_data:/var/lib/postgresql/data\n    environment:\n      POSTGRES_DB: eucora\n      POSTGRES_USER: user\n      POSTGRES_PASSWORD: pass\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -U user -d eucora\"]\n      interval: 10s\n      timeout: 5s\n      retries: 5\n\n  redis:\n    image: redis:7-alpine\n    healthcheck:\n      test: [\"CMD\", \"redis-cli\", \"ping\"]\n      interval: 10s\n      timeout: 5s\n      retries: 3\n\n  celery-worker:\n    build:\n      context: .\n      dockerfile: Dockerfile.dev\n    command: celery -A config worker -l info\n    volumes:\n      - ./backend:/app\n    environment:\n      - DATABASE_URL=postgres://user:pass@db:5432/eucora\n      - REDIS_URL=redis://redis:6379/0\n    depends_on:\n      - web\n      - redis\n\n  celery-beat:\n    build:\n      context: .\n      dockerfile: Dockerfile.dev\n    command: celery -A config beat -l info\n    volumes:\n      - ./backend:/app\n    depends_on:\n      - celery-worker\n    deploy:\n      replicas: 1  # Singleton pattern\n\nvolumes:\n  postgres_data:\n  static_volume:\n```\n\n### Production Configuration\n\n```yaml\n# docker-compose.prod.yml\nversion: ''3.8''\n\nservices:\n  web:\n    image: eucora/backend:${TAG:-latest}\n    deploy:\n      replicas: 3\n      resources:\n        limits:\n          cpus: ''1''\n          memory: 1G\n        reservations:\n          cpus: ''0.5''\n          memory: 512M\n      update_config:\n        parallelism: 1\n        delay: 10s\n        failure_action: rollback\n    healthcheck:\n      test: [\"CMD\", \"curl\", \"-f\", \"http://localhost:8000/health/\"]\n      interval: 30s\n      timeout: 10s\n      retries: 3\n      start_period: 40s\n```\n\n---\n\n## Pre-Commit Hooks\n\n### Configuration\n\n```yaml\n# .pre-commit-config.yaml\nrepos:\n  # Python\n  - repo: https://github.com/astral-sh/ruff-pre-commit\n    rev: v0.3.0\n    hooks:\n      - id: ruff\n        args: [--fix]\n      - id: ruff-format\n\n  - repo: https://github.com/pre-commit/mirrors-mypy\n    rev: v1.8.0\n    hooks:\n      - id: mypy\n        additional_dependencies: [types-all]\n\n  # JavaScript/TypeScript\n  - repo: https://github.com/pre-commit/mirrors-eslint\n    rev: v8.56.0\n    hooks:\n      - id: eslint\n        args: [--max-warnings, ''0'']\n        files: \\.[jt]sx?$\n\n  # Security\n  - repo: https://github.com/Yelp/detect-secrets\n    rev: v1.4.0\n    hooks:\n      - id: detect-secrets\n        args: [''--baseline'', ''.secrets.baseline'']\n\n  # General\n  - repo: https://github.com/pre-commit/pre-commit-hooks\n    rev: v4.5.0\n    hooks:\n      - id: trailing-whitespace\n      - id: end-of-file-fixer\n      - id: check-yaml\n      - id: check-json\n      - id: check-merge-conflict\n      - id: no-commit-to-branch\n        args: [--branch, main]\n```\n\n### Installation\n\n```bash\n# Install pre-commit\npip install pre-commit\n\n# Install hooks\npre-commit install\n\n# Run on all files\npre-commit run --all-files\n```\n\n---\n\n## Dockerfile Patterns\n\n### Multi-Stage Build\n\n```dockerfile\n# Dockerfile\n# Stage 1: Build\nFROM python:3.12-slim as builder\n\nWORKDIR /app\n\nCOPY requirements.txt .\nRUN pip wheel --no-cache-dir --no-deps --wheel-dir /wheels -r requirements.txt\n\n# Stage 2: Production\nFROM python:3.12-slim\n\nENV PYTHONDONTWRITEBYTECODE=1 \\\n    PYTHONUNBUFFERED=1\n\nWORKDIR /app\n\n# Install system deps\nRUN apt-get update && apt-get install -y --no-install-recommends \\\n    libpq5 \\\n    && rm -rf /var/lib/apt/lists/*\n\n# Install Python deps\nCOPY --from=builder /wheels /wheels\nRUN pip install --no-cache /wheels/*\n\n# Copy app\nCOPY backend/ .\n\n# Create non-root user\nRUN adduser --disabled-password --gecos '''' appuser\nUSER appuser\n\nEXPOSE 8000\n\nCMD [\"gunicorn\", \"config.wsgi:application\", \"--bind\", \"0.0.0.0:8000\", \"--workers\", \"4\"]\n```\n\n### Development Dockerfile\n\n```dockerfile\n# Dockerfile.dev\nFROM python:3.12-slim\n\nENV PYTHONDONTWRITEBYTECODE=1 \\\n    PYTHONUNBUFFERED=1\n\nWORKDIR /app\n\n# Install system deps\nRUN apt-get update && apt-get install -y --no-install-recommends \\\n    libpq-dev gcc curl \\\n    && rm -rf /var/lib/apt/lists/*\n\nCOPY requirements.txt requirements-dev.txt ./\nRUN pip install -r requirements-dev.txt\n\nEXPOSE 8000\n\nCMD [\"python\", \"manage.py\", \"runserver\", \"0.0.0.0:8000\"]\n```\n\n---\n\n## Quality Gates Checklist\n\n### CI Pipeline Must Enforce\n\n```\n☐ Backend tests pass (pytest)\n☐ Frontend tests pass (vitest)\n☐ Coverage ≥90% (pytest-cov, vitest --coverage)\n☐ TypeScript check passes (tsc --noEmit)\n☐ ESLint zero warnings (--max-warnings 0)\n☐ Python linting passes (ruff)\n☐ Security scan passes (trivy, detect-secrets)\n☐ SPDX compliance check passes\n```\n\n### Pre-Commit Must Block\n\n```\n☐ Trailing whitespace\n☐ Merge conflicts\n☐ Invalid YAML/JSON\n☐ Secrets in code\n☐ Direct commits to main\n☐ Type errors (mypy)\n☐ Linting errors (ruff, eslint)\n```\n\n---\n\n## Commands Reference\n\n```bash\n# Docker Compose\ndocker compose -f docker-compose.dev.yml up -d\ndocker compose -f docker-compose.dev.yml logs -f web\ndocker compose -f docker-compose.dev.yml exec web python manage.py migrate\ndocker compose -f docker-compose.dev.yml down -v\n\n# Pre-commit\npre-commit install\npre-commit run --all-files\npre-commit autoupdate\n\n# Testing with coverage\npytest --cov --cov-fail-under=90 --cov-report=html\nnpm test -- --coverage\n\n# Build and push\ndocker build -t eucora/backend:latest .\ndocker push eucora/backend:latest\n```\n\n---\n\n## Anti-Patterns\n\n| ❌ FORBIDDEN | ✅ CORRECT |\n|--------------|------------|\n| Skipping CI checks | All checks must pass |\n| Coverage < 90% | Enforce ≥90% in CI |\n| `--no-verify` commits | Pre-commit hooks mandatory |\n| Secrets in Dockerfile | Use build args or vault |\n| Root user in container | Create non-root user |\n| No health checks | Always define health checks |\n"},"lastSynced":"2026-03-06T08:26:07.724Z","agentAnalysis":{"suitability":{"en":"Ideal for Automated Deployment Agents requiring standardized CI/CD pipelines with GitHub Actions and container orchestration using Docker Compose and Kubernetes.","zh":"适用于需要使用 GitHub Actions 和 Docker Compose 以及 Kubernetes 进行标准化的 CI/CD 流水线的自动化部署代理。","ja":"GitHub Actions と Docker Compose、Kubernetes を使用した標準化された CI/CD パイプラインを必要とする自動化されたデプロイ エージェントに適しています。","ko":"GitHub Actions와 Docker Compose 및 Kubernetes를 사용한 표준화된 CI/CD 파이프라인이 필요한 자동화된 배포 에이전트에게 적합합니다.","es":"Ideal para agentes de implementación automatizados que requieren tuberías de CI/CD estandarizadas con GitHub Actions y orquestación de contenedores utilizando Docker Compose y Kubernetes.","fr":"Idéal pour les agents de déploiement automatisés nécessitant des pipelines de CI/CD standardisés avec GitHub Actions et une orchestration de conteneurs à l''aide de Docker Compose et Kubernetes.","de":"Ideal für automatisierte Bereitstellungsagenten, die standardisierte CI/CD-Pipelines mit GitHub Actions und Container-Orchestrierung unter Verwendung von Docker Compose und Kubernetes erfordern.","pt":"Ideal para Agentes de Implantação Automatizados que exigem pipelines de CI/CD padronizados com GitHub Actions e orquestração de contêineres usando Docker Compose e Kubernetes.","ru":"Идеально подходит для автоматических агентов развертывания, требующих стандартизированных конвейеров CI/CD с GitHub Actions и оркестровкой контейнеров с помощью Docker Compose и Kubernetes.","ar":"مثالية لعمليات نشر آلي تتطلب خطوط أنابيب CI/CD معيارية باستخدام GitHub Actions وتنسيق حاويات باستخدام Docker Compose وKubernetes."},"recommendation":{"en":"Empowers agents to enforce code quality gates with pre-commit hooks, CI enforcement, and zero warnings tolerance, ensuring ≥90% code coverage and streamlined DevOps workflows using EUCORA.","zh":"赋予代理人使用预提交钩子、CI 强制执行和零警告容忍度执行代码质量门槛的能力，确保 ≥90% 的代码覆盖率和使用 EUCORA 的流畅 DevOps 工作流。","ja":"事前コミットフック、CI の適用、警告ゼロの耐性を使用してコード品質ゲートを適用する機能をエージェントに与え、EUCORA を使用して ≥90% のコードカバー率とスムーズな DevOps ワークフローを実現します。","ko":"사전 커밋 훅, CI 적용 및 경고 0의 관용성을 사용하여 코드 품질 게이트를 적용하는 기능을 에이전트에게 부여하여 EUCORA를 사용하여 ≥90%의 코드 커버리지와 원활한 DevOps 워크플로를 보장합니다.","es":"Habilita a los agentes a aplicar puertas de calidad de código con ganchos de precompromiso, aplicación de CI y tolerancia cero de advertencias, garantizando ≥90% de cobertura de código y flujos de trabajo de DevOps optimizados mediante EUCORA.","fr":"Permet aux agents d''appliquer des portes de qualité de code avec des crochets de pré-validation, une application de CI et une tolérance zéro d''avertissements, en garantissant ≥90% de couverture de code et des flux de travail DevOps optimisés à l''aide d''EUCORA.","de":"Ermächtigt Agenten, Code-Qualitätstore mit Pre-Commit-Hooks, CI-Durchsetzung und Null-Warnungen-Toleranz zu erzwingen, wodurch ≥90% Codeabdeckung und optimierte DevOps-Workflows unter Verwendung von EUCORA sichergestellt werden.","pt":"Habilita os agentes a impor portas de qualidade de código com ganchos de pré-compromisso, aplicação de CI e tolerância zero de avisos, garantindo ≥90% de cobertura de código e fluxos de trabalho de DevOps otimizados usando EUCORA.","ru":"Наделяет агентов возможностью обеспечивать ворота качества кода с помощью хуков до фиксации, обеспечения CI и нулевой терпимости предупреждений, гарантируя ≥90% покрытия кода и оптимизированные рабочие потоки DevOps с помощью EUCORA.","ar":"تمكّن الوكلاء من فرض بوابات جودة الشفرة باستخدام مشابك ما قبل الالتزام وتنفيذ CI وعدم تحمل لأي تحذيرات، مما يضمن ≥90% تغطية الشفرة وعمليات عمل DevOps المُستَملة باستخدام EUCORA."},"useCases":{"en":["Automating code quality checks with GitHub Actions workflows","Deploying containerized applications using Docker Compose and Kubernetes","Enforcing consistent coding standards with linting and pre-commit hooks"],"zh":["使用 GitHub Actions 工作流自动执行代码质量检查","使用 Docker Compose 和 Kubernetes 部署容器化应用程序","使用 linter 和预提交钩子执行一致的编码标准"],"ja":["GitHub Actions ワークフローを使用したコード品質チェックの自動化","Docker Compose と Kubernetes を使用したコンテナ化アプリケーションのデプロイ","linter と事前コミットフックを使用した一貫したコーディング規約の適用"],"ko":["GitHub Actions 워크플ロー 사용 코드 품질 체크 자동화","Docker Compose 및 Kubernetes 사용 컨테이너화된 애플리케이션 배포","linter 및 사전 커밋 훅 사용 일관된 코딩 표준 적용"],"es":["Automatizar las comprobaciones de calidad de código con flujos de trabajo de GitHub Actions","Implementar aplicaciones contenedorizadas utilizando Docker Compose y Kubernetes","Aplicar normas de codificación consistentes con linting y ganchos de precompromiso"],"fr":["Automatiser les vérifications de la qualité du code avec des flux de travail GitHub Actions","Déployer des applications conteneurisées à l''aide de Docker Compose et Kubernetes","Appliquer des normes de codage cohérentes avec linting et des crochets de pré-validation"],"de":["Automatisieren von Code-Qualitätsprüfungen mit GitHub Actions-Workflows","Bereitstellen von containerisierten Anwendungen unter Verwendung von Docker Compose und Kubernetes","Durchsetzen von konsistenten Codierungsstandards mit Linting und Pre-Commit-Hooks"],"pt":["Automatizar verificações de qualidade de código com fluxos de trabalho do GitHub Actions","Implantar aplicações contêinerizadas usando Docker Compose e Kubernetes","Impor padrões de codificação consistentes com linting e ganchos de pré-compromisso"],"ru":["Автоматизировать проверки качества кода с помощью рабочих процессов GitHub Actions","Развертывать контейнеризированные приложения с помощью Docker Compose и Kubernetes","Обеспечивать последовательные стандарты кодирования с помощью linting и хуков до фиксации"],"ar":["أتمتة فحوصات جودة الشفرة باستخدام سلاسل مهام GitHub Actions","نشر تطبيقات محتوية في حاويات باستخدام Docker Compose وKubernetes","فرض معايير ترميز متسقة باستخدام linting ومشابك ما قبل الالتزام"]},"limitations":{"en":["Requires GitHub Actions setup","Limited to EUCORA platform","Dependent on Docker Compose and Kubernetes for container orchestration"],"zh":["需要 GitHub Actions 设置","仅限 EUCORA 平台","依赖 Docker Compose 和 Kubernetes 进行容器编排"],"ja":["GitHub Actions の設定が必要","EUCORA プラットフォームのみ","コンテナオーケストレーションに Docker Compose と Kubernetes 依存"],"ko":["GitHub Actions 설정 필요","EUCORA 플랫폼만 해당","컨테이너 오케스트레이션에 Docker Compose 및 Kubernetes 의존"],"es":["Requiere configuración de GitHub Actions","Limitado a la plataforma EUCORA","Dependiente de Docker Compose y Kubernetes para la orquestación de contenedores"],"fr":["Nécessite une configuration de GitHub Actions","Limité à la plate-forme EUCORA","Dépend de Docker Compose et Kubernetes pour l''orchestration de conteneurs"],"de":["Benötigt GitHub Actions-Setup","Begrenzt auf die EUCORA-Plattform","Abhängig von Docker Compose und Kubernetes für die Container-Orchestrierung"],"pt":["Exige configuração do GitHub Actions","Limitado à plataforma EUCORA","Dependente do Docker Compose e Kubernetes para orquestração de contêineres"],"ru":["Требует настройки GitHub Actions","Ограничен платформой EUCORA","Зависит от Docker Compose и Kubernetes для оркестровки контейнеров"],"ar":["يتطلب إعداد GitHub Actions","محدود منصة EUCORA","يعتمد على Docker Compose وKubernetes لتنسيق الحاويات"]},"version":4},"contentHash":"b75f0182cf36c0994f4b8baceab8e37e0d5a7c81ae51f6307d48306d4b8a8d56","qualityScore":36}');
