INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('arttttt/CMIDCABot/fix', 'fix', 'arttttt', 'CMIDCABot', 'community', 'fix arttttt CMIDCABot community The Fix skill automates code review fixes, benefiting developers by resolving issues efficiently. It follows the developer behavior profile and conventions outlined in CLAUDE.md and ARCHITECTURE.md. Fix 是一个代码审查和自动修复工具，帮助开发者提高代码质量和效率 Fix はコードレビューと自動修復ツールで、開発者のコード品質と効率を向上させる Fix는 코드 리뷰 및 자동 수정 도구로 개발자의 코드 품질과 효율성을 향상시킵니다 El comando fix es una herramienta para corregir errores en código, utilizando un perfil de comportamiento de desarrollador y siguiendo reglas específicas La commande fix est un outil pour corriger les bogues dans le code, en utilisant un profil de comportement de développeur et en suivant des règles spécifiques Der Fix-Befehl ist ein Tool zur Fehlerbehebung in Code, das ein Entwickler-Verhaltensprofil verwendet und bestimmte Regeln befolgt O Fix é uma habilidade que corrige erros de código identificados em revisões. Ele segue um perfil de comportamento do desenvolvedor e segue regras específicas. Fix - это навык, который исправляет кодовые ошибки, выявленные при ревью. Он следует поведенческому профилю разработчика и соблюдает определенные правила. Fix هو مهارة تصحيح أخطاء الكود المحددة في المراجعات. يتبع ملف تعريف سلوك المطور ويتابع قواعد محددة. how to use fix skill fix skill setup guide automated code review fixes fix skill vs manual review fix skill install what is fix skill fix skill for AI agents fix skill best practices fix skill tutorial 代码审查工具 自动修复解决方案 AI 代码审查 代码质量提高 开发效率提高 Fix AI Agent 代码审查和修复 开发者工具 Fetches review findings and produces a fix plan Implements fixes, commits, and pushes changes following explicit approval Normalizes IDs by adding the DCATgBot- prefix Follows the developer behavior profile and conventions outlined in CLAUDE.md and ARCHITECTURE.md Waits for explicit approval before implementing fixes Fix is a skill that automates the resolution of code review issues, using a behavior profile and following specific conventions and architecture guidelines.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mattfuster/aisef-setup/wo-create', 'community', 'mattfuster', 'aisef-setup', 'mattfuster/aisef-setup', 'wo-create', 0, 0, 36, '2026-02-26T18:08:22Z', '2026-03-07T03:51:14.674Z', '47bdaba16156343800afe109326e81473515acdc934a156de4a6ce65bf0f2ef4', '{"id":"mattfuster/aisef-setup/wo-create","name":"wo-create","description":{"en":"The wo-create skill creates work orders by decomposing blueprints or from conversations. It''s designed for AI agents to manage work orders efficiently.","zh":"WO Create是一个可部署的AISEF中心模板，用于创建工作订单，支持蓝图分解和个别工作订单创建","ja":"WO Createは、AISEFハブテンプレートを使用して作業指令を作成するAIエージェントです","ko":"WO Create는 작업 주문을 생성하기 위한 deployable AISEF hub 템플릿입니다","es":"wo-create es un agente de creación de órdenes de trabajo que permite descomponer planos en varias órdenes de trabajo o crear órdenes de trabajo individuales a partir de conversaciones, entradas de QA, decisiones o otros desencadenadores.","fr":"wo-create est un agent de création d''ordres de travail qui permet de décomposer des plans en plusieurs ordres de travail ou de créer des ordres de travail individuels à partir de conversations, d''entrées de QA, de décisions ou d''autres déclencheurs.","de":"wo-create ist ein Agent für die Erstellung von Arbeitsaufträgen, der es ermöglicht, Pläne in mehrere Arbeitsaufträge aufzuteilen oder einzelne Arbeitsaufträge aus Konversationen, QA-Einträgen, Entscheidungen oder anderen Auslösern zu erstellen.","pt":"O WO Create é um agente de criação de ordens de trabalho que permite decompor blueprints em várias ordens ou criar ordens ad-hoc a partir de conversas, entradas de QA, decisões ou outros gatilhos","ru":"WO Create - это агент создания заказов на работу, который позволяет разбить blueprints на несколько заказов или создать индивидуальные заказы на основе разговоров, записей QA, решений или других триггеров","ar":"WO Create هو وكيل إنشاء أوامر العمل التي يسمح بتحليل مخططات إلى أوامر متعددة أو إنشاء أوامر فردية من محادثات، مدخلات QA، قرارات أو محفزات أخرى"},"seo":{"title":{"en":"wo-create: Work Order Creation Setup Guide | AI Agent Skill","zh":"WO Create 工作订单创建指南","ja":"WO Create AIエージェントのセットアップガイド","ko":"WO Create 작업 주문 생성 BEST PRACTICES","es":"Guía de configuración de wo-create: Creación de órdenes d...","fr":"Guide de configuration de wo-create : Création d''ordres d...","de":"Einrichtungsleitfaden für wo-create: Erstellung von Arbei...","pt":"Guia de Configuração do WO Create - Criação de Ordens de ...","ru":"Настройка WO Create - Создание Заказов на Работу для AISE...","ar":"دليل إعداد WO Create - إنشاء أوامر العمل ل AISEF باستخدام..."},"description":{"en":"Discover how to deploy the AISEF hub template with wo-create. Clone and set up your product''s work order creation system today!","zh":"了解WO Create的核心行为规则和功能，实现工作订单的高效创建和管理","ja":"WO Create AIエージェントの使い方と 機能をマスターし、作業指令の作成を最適化する","ko":"WO Create의 핵심 행동 규칙과 기능을 알아보고 작업 주문 생성과 관리를 최적화 하세요","es":"Aprende a configurar wo-create para crear órdenes de trabajo personalizadas con AISEF. Descubre cómo descomponer planos y crear órdenes de trabajo individuales.","fr":"Découvrez comment configurer wo-create pour créer des ordres de travail personnalisés avec AISEF. Apprenez à décomposer des plans et à créer des ordres de tr...","de":"Erfahren Sie, wie Sie wo-create konfigurieren, um individuelle Arbeitsaufträge mit AISEF zu erstellen. Erfahren Sie, wie Sie Pläne aufteilen und einzelne Arb...","pt":"Aprenda a configurar o WO Create para criar ordens de trabalho personalizadas para o seu produto com o template de hub deployável AISEF","ru":"Узнайте, как настроить WO Create для создания индивидуальных заказов на работу для вашего продукта с помощью deployable шаблона хаба AISEF и ИИ Агентов","ar":"تعرف على كيفية إعداد WO Create لإنشاء أوامر عمل مخصصة لمنتجك باستخدام قالب حب deployable AISEF وأدوات الذكاء الاصطناعي"},"definition":{"en":"wo-create is a deployable AISEF hub template for creating work orders, either by decomposing blueprints or generating individual ad-hoc work orders.","zh":"WO Create是一个用于创建和管理工作订单的AI工具","ja":"WO Createは、作業指令の作成と管理を行うAIエージェントです","ko":"WO Create는 작업 주문을 생성하고 관리하기 위한 AI 에이전트입니다","es":"wo-create es un agente de creación de órdenes de trabajo que utiliza AISEF para crear órdenes de trabajo personalizadas.","fr":"wo-create est un agent de création d''ordres de travail qui utilise AISEF pour créer des ordres de travail personnalisés.","de":"wo-create ist ein Agent für die Erstellung von Arbeitsaufträgen, der AISEF verwendet, um individuelle Arbeitsaufträge zu erstellen.","pt":"O WO Create é um agente de criação de ordens de trabalho que cria ordens personalizadas para produtos","ru":"WO Create - это агент создания заказов на работу, который создает индивидуальные заказы для продуктов","ar":"WO Create هو وكيل إنشاء أوامر العمل التي يخلق أوامر عمل مخصصة للمنتجات"},"features":{"en":["Creates work orders by decomposing blueprints into multiple work orders","Generates individual ad-hoc work orders from conversations, QA entries, or decisions","Uses the `wo-plan` skill for file-level implementation planning on a specific work order","Utilizes the `wo-review` skill for quality checks on existing work orders","Always reads upstream documents first, including blueprints and other relevant files","Operates as the AISEF Work Order Creation agent for efficient work order management"],"zh":["支持蓝图分解和个别工作订单创建","核心行为规则包括先读取上游文档","使用wo-plan技能进行文件级别的实施计划","使用wo-review技能进行质量检查"],"ja":["ブループリントの分解と個別の作業指令の作成をサポート","コア行動ルールには、上流ドキュメントの読み取りが含まれる","wo-planスキルを使用してファイルレベルの実施計画を行う","wo-reviewスキルを使用して品質チェックを行う"],"ko":["블루프린트 분해 및 개별 작업 주문을 지원","핵심 행동 규칙에는 상류 문서 읽기가 포함","wo-plan 스킬을 사용하여 파일 수준의 구현 계획을 수행","wo-review 스킬을 사용하여 품질 검사를 수행"],"es":["Descomposición de planos en varias órdenes de trabajo","Creación de órdenes de trabajo individuales a partir de conversaciones o entradas de QA","Integración con AISEF para crear órdenes de trabajo personalizadas","Uso de la habilidad wo-plan para la planificación de implementación de archivos","Uso de la habilidad wo-review para la revisión de órdenes de trabajo existentes"],"fr":["Décomposition de plans en plusieurs ordres de travail","Création d''ordres de travail individuels à partir de conversations ou d''entrées de QA","Intégration avec AISEF pour créer des ordres de travail personnalisés","Utilisation de la compétence wo-plan pour la planification de mise en œuvre de fichiers","Utilisation de la compétence wo-review pour la révision d''ordres de travail existants"],"de":["Aufteilung von Plänen in mehrere Arbeitsaufträge","Erstellung einzelner Arbeitsaufträge aus Konversationen oder QA-Einträgen","Integration mit AISEF zur Erstellung individueller Arbeitsaufträge","Verwendung der Fähigkeit wo-plan für die Implementierungsplanung von Dateien","Verwendung der Fähigkeit wo-review für die Überprüfung von vorhandenen Arbeitsaufträgen"],"pt":["Criação de ordens de trabalho personalizadas","Decomposição de blueprints em várias ordens","Criação de ordens ad-hoc a partir de conversas ou entradas de QA","Integração com o template de hub deployável AISEF","Suporte à planificação de implementação de arquivo em nível de ordem de trabalho","Suporte à verificação de qualidade de ordens de trabalho existentes"],"ru":["Создание индивидуальных заказов на работу","Разбивка blueprints на несколько заказов","Создание индивидуальных заказов на основе разговоров или записей QA","Интеграция с deployable шаблоном хаба AISEF","Поддержка планирования реализации файла на уровне заказа на работу","Поддержка проверки качества существующих заказов на работу"],"ar":["إنشاء أوامر عمل مخصصة","تحليل مخططات إلى أوامر متعددة","إنشاء أوامر فردية من محادثات أو مدخلات QA","التكامل مع قالب حب deployable AISEF","دعم التخطيط التنفيذي للملف في مستوى أمر العمل","دعم التحقق من جودة أوامر العمل الحالية"]},"keywords":{"en":["how to use wo-create","what is wo-create","wo-create setup guide","wo-create alternative","wo-create vs AISEF","deploying AISEF hub template","work order creation AI agent","wo-create install","AISEF work order management"],"zh":["WO Create","AISEF","工作订单创建","AI工具","蓝图分解","工作订单管理"],"ja":["WO Create","AISEF","作業指令作成","AIエージェント","ブループリント分解","作業指令管理"],"ko":["WO Create","AISEF","작업 주문 생성","AI 에이전트","블루프린트 분해","작업 주문 관리"],"es":["wo-create","AISEF","creación de órdenes de trabajo","descomposición de planos","órdenes de trabajo personalizadas","integración con AISEF","Herramientas de AI para desarrolladores","Agentes de AI para la creación de órdenes de trabajo"],"fr":["wo-create","AISEF","création d''ordres de travail","décomposition de plans","ordres de travail personnalisés","intégration avec AISEF","Outils d''IA pour les développeurs","Agents d''IA pour la création d''ordres de travail"],"de":["wo-create","AISEF","Erstellung von Arbeitsaufträgen","Aufteilung von Plänen","individuelle Arbeitsaufträge","Integration mit AISEF","AI-Tools für Entwickler","AI-Agents für die Erstellung von Arbeitsaufträgen"],"pt":["WO Create","criação de ordens de trabalho","AISEF","template de hub deployável","ordens de trabalho personalizadas","desenvolvimento de software","ferramentas de desenvolvimento","agente de criação de ordens de trabalho"],"ru":["WO Create","создание заказов на работу","AISEF","deployable шаблон хаба","индивидуальные заказы на работу","разработка программного обеспечения","инструменты разработки","агент создания заказов на работу","ИИ Агенты"],"ar":["WO Create","إنشاء أوامر العمل","AISEF","قالب حب deployable","أوامر عمل مخصصة","تطوير البرمجيات","أدوات التطوير","وكيل إنشاء أوامر العمل","أدوات الذكاء الاصطناعي"]}},"owner":"mattfuster","repo":"aisef-setup","repoPath":"mattfuster/aisef-setup","stars":0,"forks":0,"updatedAt":"2026-02-26T18:08:22Z","topics":[],"category":"community","skillMd":{"name":"wo-create","description":">","bodyPreview":"# WO Create\n\nYou are operating as the AISEF Work Order Creation agent. Your job is to create work orders — either by decomposing blueprints into multiple WOs, or by creating individual ad-hoc WOs from conversations, QA entries, decisions, or other triggers.\n\nFor file-level implementation planning on a specific WO, use the `wo-plan` skill. For quality checks on existing WOs, use the `wo-review` skill.\n\n## Core Behavioral Rules\n\n1. **Always read upstream documents first**: Read the blueprint AND F","body":"# WO Create\n\nYou are operating as the AISEF Work Order Creation agent. Your job is to create work orders — either by decomposing blueprints into multiple WOs, or by creating individual ad-hoc WOs from conversations, QA entries, decisions, or other triggers.\n\nFor file-level implementation planning on a specific WO, use the `wo-plan` skill. For quality checks on existing WOs, use the `wo-review` skill.\n\n## Core Behavioral Rules\n\n1. **Always read upstream documents first**: Read the blueprint AND FRD before creating work orders. Search the codebase for existing implementation.\n2. **Never execute without approval**: Present proposed work orders and wait for explicit confirmation before creating files.\n3. **Respect existing work orders**: Check `03-work-orders/_backlog.md` for existing work orders before creating new ones. Decide whether to CREATE, EDIT, or DO NOTHING for each piece of functionality.\n4. **Scope appropriately**: Each work order should be completable in a single PR and be independently testable.\n5. **Do not estimate effort**: Numeric effort estimates (days, hours, story points) are NOT part of work order creation. The 1–3 day scoping guidance is a size constraint, not an estimate. Estimation is exclusively a sprint-planning activity (see `sprint-plan` skill).\n6. **Apply the independent PR test**: When a WO involves multiple engineers, check whether each person''s contribution could ship as an independent PR. If yes, split into separate WOs. Multi-person WOs are valid only for collaborative research or paired knowledge transfer.\n\n## Workflow\n\n**Trigger:** \"Break down [blueprint] into work orders\", \"extract work orders from [feature]\"\n\n### Step 1: Multi-Source Context Gathering\n\n- Read the target blueprint (`02-blueprints/features/[feature]/`)\n- Read the associated FRD (`01-requirements/features/[feature]/`)\n- Search the codebase for existing implementation\n- Check git history for recent changes to related files\n- List existing work orders for this feature from `_backlog.md`\n\n### Step 2: Smart Analysis\n\n- Identify natural separation points (backend/frontend/data layers)\n- Find buildable and testable units\n- Assess what''s already built vs. what needs creation\n- **Route each item:** Determine whether it should be a Work Order, a Task, or nothing\n\n**Routing heuristic — Task vs. Work Order:**\n\n| Signal | Route to |\n|--------|----------|\n| Produces a PR or research artifact | **Work Order** |\n| Has testable acceptance criteria | **Work Order** |\n| Estimated >1 day of effort | **Work Order** |\n| Is a meeting action item (<4 hours) | **Task** |\n| Is an admin/access/config action | **Task** |\n| Is \"write down X\", \"share Y\", or \"set up Z\" (no code) | **Task** |\n\n**Tasks** go directly to the sprint board (`04-sprints/current-sprint.md`) with a `T-NNN` ID and no file in `03-work-orders/`.\n\n**Multi-person test (DEC-031 #2):** Before finalizing a WO with multiple engineers, apply the independent PR test. If each person''s contribution could ship independently, split into separate WOs with dependencies between them. Exceptions:\n- **Collaborative analysis/research** — two people producing one shared artifact\n- **Paired work for knowledge transfer** — senior + junior, one owner, one learner\n\n**Decision matrix (for items routed to Work Order):**\n\n| Condition | Action |\n|-----------|--------|\n| Unimplemented functionality, missing components, new requirements | **CREATE** (implementation WO) |\n| Decision needs research, evaluation, or POC before implementation | **CREATE** (research WO) |\n| Existing backlog work orders need alignment with blueprint updates | **EDIT** |\n| Already implemented, minor/cosmetic, placeholder content | **DO NOTHING** |\n\n**Work order types:**\n- **Implementation WO** — deliverable is production code in a PR. Use the standard template.\n- **Research WO** — deliverable is a research artifact + decision record. Use the research template.\n\n### Step 3: Strategic Proposal\n\nPresent specific proposed work orders with:\n- Title and purpose (must name the origin — DEC-031 #7)\n- Technical reasoning for the breakdown\n- Acceptance criteria derived from the FRD\n- Dependencies between work orders\n- Any existing work orders that need updates\n- Owner assignment as intent signal (tech lead pre-assignment is acceptable; sprint planning confirms — DEC-031 #5)\n\n**Do NOT include numeric effort estimates.** Scoping is implicit in the 1–3 day constraint and the splitting signals.\n\n### Step 4: User Validation\n\n**Never execute without explicit approval.** Present the plan and wait.\n\n### Step 5: Execution\n\nAfter approval:\n\n**For work orders:**\n- Create work order files in `03-work-orders/intake/` (all new WOs start in intake until triaged)\n- Update `03-work-orders/_backlog.md` with new entries (add to Intake — Pending Assignment section)\n- Set status to `backlog`\n- Ensure `owner` in frontmatter is the single source of assignment (no `Assigned` field in body)\n\n**For tasks:**\n- Add directly to the Tasks section of `04-sprints/current-sprint.md`\n- Assign the next available `T-NNN` ID (sequential within the sprint)\n- Set status to Open\n- Include source (e.g., \"Meeting: Sprint Planning\", \"Ad-hoc request\")\n\nFor the work order template, see [references/work-order-template.md](references/work-order-template.md).\nFor research/evaluation work orders, see [references/research-work-order-template.md](references/research-work-order-template.md).\n\n## Work Order Lifecycle\n\n```\nbacklog → ready → in_progress → in_review → completed\n```\n\n| Status | Meaning |\n|--------|---------|\n| `backlog` | Extracted from blueprint, awaiting implementation plan |\n| `ready` | Implementation plan attached, dependencies clear |\n| `in_progress` | Developer is actively working |\n| `in_review` | Code submitted for review; Delivery section populated with repo + PR |\n| `completed` | Acceptance criteria verified; Delivery section finalized |\n| `blocked` | Cannot proceed — blocker documented |\n\n**Terminal removal:** WOs that are no longer needed are deleted (file removed, backlog entry removed). Cancellation of committed WOs (status `ready` or beyond) requires a DEC record via decision-capture before deletion. WOs that never left `backlog` can be deleted without a DEC. See DEC-031 #8 and #9.\n\n## File Placement\n\n```\n03-work-orders/\n├── _backlog.md           # Master index of ALL work orders (status-grouped)\n├── intake/               # New WOs awaiting sprint triage\n├── working/              # Graduated WOs (backlog, ready, in_progress, in_review)\n└── done/                 # Completed WOs\n```\n\nNew work orders are always created in `intake/`. They move to `working/` when they pass sprint triage (see `sprint-plan` skill, Step 0). They move to `done/` when completed (see `wo-update` skill).\n\n## Commit Convention\n\n```\nwork-orders: [action] [scope]\n```\nExamples:\n- `work-orders: create WO-012 through WO-014 for password-reset`\n- `work-orders: update WO-012 status to in_progress`\n"},"lastSynced":"2026-03-07T03:51:14.674Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing efficient work order management through blueprint decomposition and conversation-driven creation.","zh":"适用于需要通过蓝图分解和对话驱动创建高效工作订单管理的AI代理。","ja":"ブループリントの分解と会話駆動の作成を通じて効率的なワークオーダー管理が必要なAIエージェントに適しています。","ko":"블루프린트 분해 및 대화 주도 생성을 통해 효율적인 작업 주문 관리가 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan una gestión eficiente de órdenes de trabajo a través de la descomposición de planos y la creación impulsada por conversaciones.","fr":"Parfait pour les agents IA ayant besoin d''une gestion efficace des ordres de travail via la décomposition de plans et la création pilotée par conversation.","de":"Perfekt für KI-Agents, die eine effiziente Arbeitsauftragsverwaltung durch Blueprint-Zerlegung und konversationsgesteuerte Erstellung benötigen.","pt":"Perfeito para Agentes de IA que precisam de gerenciamento eficiente de ordens de trabalho por meio da decomposição de blueprints e criação impulsionada por conversas.","ru":"Идеально для ИИ-агентов, которым необходим эффективный менеджмент заказов на работу через декомпозицию blueprints и разговорно-ориентированное создание.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يحتاج إلى إدارة كفؤة لأوامر العمل من خلال تفكيك الخطط الرئيسية والخلق الموجه بالحوار."},"recommendation":{"en":"Empowers agents to create work orders from blueprints or conversations, utilizing triggers like QA entries and decisions, and integrating with skills like `wo-plan` for file-level implementation planning and `wo-review` for quality checks, all while adhering to core behavioral rules such as reading upstream documents first.","zh":"赋予代理创建从蓝图或对话创建工作订单的能力，利用诸如QA条目和决策等触发器，并集成诸如`wo-plan`的文件级实现规划和`wo-review`的质量检查等技能，同时遵循核心行为规则，例如先阅读上游文档。","ja":"エージェントがブループリントまたは会話からワークオーダーを作成する機能を提供し、QAエントリや決定などのトリガーを利用し、`wo-plan`などのファイルレベルの実装計画や`wo-review`などの品質チェックなどのスキルと統合し、同時にコアの動作ルールに従う、たとえば上流のドキュメントを最初に読む。","ko":"에이전트가 블루프린트 또는 대화에서 작업 주문을 생성할 수 있는 기능을 제공하며 QA 항목 및 quyết định과 같은 트리거를 활용하며 `wo-plan`과 같은 파일 수준의 구현 계획 및 `wo-review`와 같은 품질 체크와 같은 기능을 통합，同时遵循核心行为规则，例如先读取上游文档。","es":"Habilita a los agentes a crear órdenes de trabajo a partir de planos o conversaciones, utilizando desencadenadores como entradas de QA y decisiones, e integrándose con habilidades como `wo-plan` para la planificación de implementación a nivel de archivo y `wo-review` para controles de calidad, todo mientras se adhiere a reglas de comportamiento básicas como leer documentos upstream primero.","fr":"Permet aux agents de créer des ordres de travail à partir de plans ou de conversations, en utilisant des déclencheurs tels que des entrées QA et des décisions, et en s''intégrant avec des compétences comme `wo-plan` pour la planification de la mise en œuvre au niveau du fichier et `wo-review` pour les vérifications de qualité, tout en respectant les règles de comportement de base telles que la lecture des documents upstream en premier.","de":"Ermöglicht es Agents, Arbeitsaufträge aus Plänen oder Konversationen zu erstellen, indem sie Auslöser wie QA-Einträge und Entscheidungen nutzen und sich mit Fähigkeiten wie `wo-plan` für die Implementierungsplanung auf Dateiebene und `wo-review` für Qualitätskontrollen integrieren, während sie grundlegende Verhaltensregeln wie das Lesen von Upstream-Dokumenten als Erstes einhalten.","pt":"Habilita os agentes a criar ordens de trabalho a partir de blueprints ou conversas, utilizando gatilhos como entradas de QA e decisões, e integrando com habilidades como `wo-plan` para planejamento de implementação em nível de arquivo e `wo-review` para verificações de qualidade, tudo enquanto adere às regras comportamentais centrais, como ler documentos de upstream primeiro.","ru":"Наделяет агентов возможностью создавать заказы на работу из blueprints или разговоров, используя триггеры, такие как записи QA и решения, и интегрируя с навыками, такими как `wo-plan` для планирования реализации на уровне файла и `wo-review` для проверок качества, все при этом соблюдая основные поведенческие правила, такие как чтение документов upstream сначала.","ar":"يُمكّن الوكلاء من إنشاء أوامر العمل من الخطط الرئيسية أو المحادثات، باستخدام محفزات مثل إدخالات QA والقرارات، وتكامل مع مهارات مثل `wo-plan` لتخطيط التنفيذ على مستوى الملف و `wo-review` لفحص الجودة، وكل ذلك مع اتباع القواعد السلوكية الأساسية مثل قراءة الوثائق المسندة أولاً."},"useCases":{"en":["Decomposing complex blueprints into manageable work orders","Generating ad-hoc work orders from conversations and QA entries","Automating work order creation based on decisions and other triggers"],"zh":["将复杂的蓝图分解为可管理的工作订单","从对话和QA条目生成即席工作订单","基于决策和其他触发器自动创建工作订单"],"ja":["複雑なブループリントを管理可能なワークオーダーに分解する","会話とQAエントリからアドホックなワークオーダーを生成する","決定やその他のトリガーに基づいてワークオーダーを作成する"],"ko":["복잡한 블루프린트를 관리 가능한 작업 주문으로 분해하는 것","대화 및 QA 항목에서 즉석 작업 주문을 생성하는 것","결정 및 기타 트리거를 기반으로 작업 주문을 자동으로 생성하는 것"],"es":["Descomponer planos complejos en órdenes de trabajo manejables","Generar órdenes de trabajo ad-hoc a partir de conversaciones y entradas de QA","Automatizar la creación de órdenes de trabajo en función de decisiones y otros desencadenadores"],"fr":["Décomposer des plans complexes en ordres de travail gérables","Générer des ordres de travail ad-hoc à partir de conversations et d''entrées QA","Automatiser la création d''ordres de travail en fonction de décisions et d''autres déclencheurs"],"de":["Komplexe Pläne in handhabbare Arbeitsaufträge zerlegen","Ad-hoc-Arbeitsaufträge aus Konversationen und QA-Einträgen generieren","Arbeitsauftragserstellung automatisieren basierend auf Entscheidungen und anderen Auslösern"],"pt":["Decompor blueprints complexos em ordens de trabalho gerenciáveis","Gerar ordens de trabalho ad-hoc a partir de conversas e entradas de QA","Automatizar a criação de ordens de trabalho com base em decisões e outros gatilhos"],"ru":["Декомпозиция сложных blueprints в управляемые заказы на работу","Генерация заказов на работу ad-hoc из разговоров и записей QA","Автоматизация создания заказов на работу на основе решений и других триггеров"],"ar":["تفكيك الخطط الرئيسية المعقدة إلى أوامر عمل قابلة للإدارة","توليد أوامر العمل العرضية من المحادثات وإدخالات QA","توفير آلي لإنشاء أوامر العمل بناءً على القرارات والمحفزات الأخرى"]},"limitations":{"en":["Requires access to blueprints and conversation data","Needs integration with `wo-plan` and `wo-review` skills for comprehensive work order management"],"zh":["需要访问蓝图和对话数据","需要集成`wo-plan`和`wo-review`技能以实现全面的工作订单管理"],"ja":["ブループリントと会話データへのアクセスが必要","`wo-plan`と`wo-review`スキルとの統合が、包括的なワークオーダー管理に必要"],"ko":["블루프린트 및 대화 데이터에 대한 액세스가 필요함","`wo-plan` 및 `wo-review` 기능과 통합해야 함으로써 포괄적인 작업 주문 관리가 필요"],"es":["Requiere acceso a planos y datos de conversación","Necesita integración con habilidades `wo-plan` y `wo-review` para una gestión integral de órdenes de trabajo"],"fr":["Nécessite un accès aux plans et aux données de conversation","Nécessite une intégration avec les compétences `wo-plan` et `wo-review` pour une gestion complète des ordres de travail"],"de":["Erfordert Zugriff auf Pläne und Konversationsdaten","Benötigt Integration mit Fähigkeiten `wo-plan` und `wo-review` für eine umfassende Arbeitsauftragsverwaltung"],"pt":["Requer acesso a blueprints e dados de conversa","Necessita de integração com as habilidades `wo-plan` e `wo-review` para gerenciamento abrangente de ordens de trabalho"],"ru":["Требует доступа к blueprints и данным разговора","Требует интеграции с навыками `wo-plan` и `wo-review` для комплексного менеджмента заказов на работу"],"ar":["يتطلب الوصول إلى الخطط الرئيسية وبيانات المحادثة","يحتاج إلى التكامل مع المهارات `wo-plan` و `wo-review` لإدارة شاملة لأوامر العمل"]},"version":4},"contentHash":"47bdaba16156343800afe109326e81473515acdc934a156de4a6ce65bf0f2ef4","qualityScore":36}');
DELETE FROM skills_fts WHERE id = 'mattfuster/aisef-setup/wo-create';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mattfuster/aisef-setup/wo-create', 'wo-create', 'mattfuster', 'aisef-setup', 'community', 'wo-create mattfuster aisef-setup community The wo-create skill creates work orders by decomposing blueprints or from conversations. It''s designed for AI agents to manage work orders efficiently. WO Create是一个可部署的AISEF中心模板，用于创建工作订单，支持蓝图分解和个别工作订单创建 WO Createは、AISEFハブテンプレートを使用して作業指令を作成するAIエージェントです WO Create는 작업 주문을 생성하기 위한 deployable AISEF hub 템플릿입니다 wo-create es un agente de creación de órdenes de trabajo que permite descomponer planos en varias órdenes de trabajo o crear órdenes de trabajo individuales a partir de conversaciones, entradas de QA, decisiones o otros desencadenadores. wo-create est un agent de création d''ordres de travail qui permet de décomposer des plans en plusieurs ordres de travail ou de créer des ordres de travail individuels à partir de conversations, d''entrées de QA, de décisions ou d''autres déclencheurs. wo-create ist ein Agent für die Erstellung von Arbeitsaufträgen, der es ermöglicht, Pläne in mehrere Arbeitsaufträge aufzuteilen oder einzelne Arbeitsaufträge aus Konversationen, QA-Einträgen, Entscheidungen oder anderen Auslösern zu erstellen. O WO Create é um agente de criação de ordens de trabalho que permite decompor blueprints em várias ordens ou criar ordens ad-hoc a partir de conversas, entradas de QA, decisões ou outros gatilhos WO Create - это агент создания заказов на работу, который позволяет разбить blueprints на несколько заказов или создать индивидуальные заказы на основе разговоров, записей QA, решений или других триггеров WO Create هو وكيل إنشاء أوامر العمل التي يسمح بتحليل مخططات إلى أوامر متعددة أو إنشاء أوامر فردية من محادثات، مدخلات QA، قرارات أو محفزات أخرى how to use wo-create what is wo-create wo-create setup guide wo-create alternative wo-create vs AISEF deploying AISEF hub template work order creation AI agent wo-create install AISEF work order management WO Create AISEF 工作订单创建 AI工具 蓝图分解 工作订单管理 Creates work orders by decomposing blueprints into multiple work orders Generates individual ad-hoc work orders from conversations, QA entries, or decisions Uses the `wo-plan` skill for file-level implementation planning on a specific work order Utilizes the `wo-review` skill for quality checks on existing work orders Always reads upstream documents first, including blueprints and other relevant files Operates as the AISEF Work Order Creation agent for efficient work order management wo-create is a deployable AISEF hub template for creating work orders, either by decomposing blueprints or generating individual ad-hoc work orders.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JoeKarow/motw-campaign-tracker/skeleton-ui', 'community', 'JoeKarow', 'motw-campaign-tracker', 'JoeKarow/motw-campaign-tracker', 'skeleton-ui', 0, 0, 36, '2026-03-06T16:04:31Z', '2026-03-07T03:53:20.377Z', 'e6301732297a62681763ebc3bb03fadb57c4c899b9a5c377f5743ef4f6b38934', '{"id":"JoeKarow/motw-campaign-tracker/skeleton-ui","name":"skeleton-ui","description":{"en":"skeleton-ui is a UI component skill that provides pre-built components for efficient development. It benefits developers by offering a catalog of available components to avoid hand-rolling markup.","zh":"Skeleton UI是一种基于Svelte的UI组件库，提供了一套简单易用的组件和工具","ja":"Skeleton UIはSvelteベースのUIコンポーネントライブラリで、シンプルで使いやすいコンポーネントとツールを提供します","ko":"스켈레톤 UI는 스벨트 기반의 UI 컴포넌트 라이브러리로서, 간단하고 사용하기 쉬운 컴포넌트와 도구를 제공합니다","es":"Skeleton UI es un conjunto de componentes de interfaz de usuario para desarrolladores, que ofrece una forma sencilla de crear interfaces de usuario consistentes","fr":"Skeleton UI est un ensemble de composants d''interface utilisateur pour les développeurs, qui offre une façon simple de créer des interfaces utilisateur cohérentes","de":"Skeleton UI ist ein Satz von Benutzeroberflächenkomponenten für Entwickler, der eine einfache Möglichkeit bietet, konsistente Benutzeroberflächen zu erstellen","pt":"O Skeleton UI é um componente de interface do usuário que fornece uma variedade de elementos pré-concebidos para desenvolvedores. Aprenda a utilizá-lo com nosso guia","ru":"Skeleton UI — это компонент пользовательского интерфейса, который предоставляет ряд предустановленных элементов для разработчиков ИИ Агентов","ar":"أداة الواجهة العظمية هي مكون واجهة المستخدم التي توفر مجموعة من العناصر المسبقة لبرامج المرء. تعلم كيفية استخدامها مع دليلنا"},"seo":{"title":{"en":"skeleton-ui: Setup Guide for AI Agents | AI Agent Skill","zh":"Skeleton UI组件集成指南","ja":"Skeleton UIコンポーネントのベストプラクティス","ko":"스켈레톤 UI 컴포넌트 설정 가이드","es":"Guía de configuración de Skeleton UI para desarrolladores","fr":"Guide de mise en place de Skeleton UI pour les développeurs","de":"Einrichtungsanleitung für Skeleton UI für Entwickler","pt":"Guia de Configuração do Skeleton UI para Desenvolvedores","ru":"ИИ Агенты: Руководство по Настройке Skeleton UI","ar":"إعداد أداة الواجهة العظمية للبرمجيين"},"description":{"en":"Discover how to leverage skeleton-ui for efficient UI development. Explore its core principles, import patterns, and composition techniques to streamline you...","zh":"了解Skeleton UI的核心原则、导入模式和组合模式，提升您的开发效率","ja":"Skeleton UIのコアプリンシプル、インポートパターン、コンポジションパターンをマスターして開発を効率化","ko":"스켈레톤 UI의 핵심 원칙,导入 패턴, 컴포지션 패턴을 익혀 개발 효율성을 높여보세요","es":"Aprende a utilizar Skeleton UI de manera efectiva con nuestros consejos y mejores prácticas para desarrolladores","fr":"Découvrez comment utiliser Skeleton UI de manière efficace avec nos conseils et meilleures pratiques pour les développeurs","de":"Erfahren Sie, wie Sie Skeleton UI effektiv nutzen können, mit unseren Tipps und Best Practices für Entwickler","pt":"Aprenda a utilizar o Skeleton UI de forma eficaz com nosso guia de configuração e melhores práticas para desenvolvedores","ru":"Узнайте, как использовать Skeleton UI с помощью нашего руководства по настройке и лучших практик для разработчиков ИИ Агентов","ar":"تعرف على كيفية استخدام أداة الواجهة العظمية بفعالية مع دليلنا الإعداد والأساليب المثلى للبرمجيين"},"definition":{"en":"skeleton-ui is a set of pre-built UI components and styled elements for efficient development, following core principles and import patterns.","zh":"Skeleton UI是一种UI组件库，提供预制的组件和样式，帮助开发者快速构建Web应用","ja":"Skeleton UIは、事前に作成されたコンポーネントとスタイルを提供するUIコンポーネントライブラリで、ウェブアプリの迅速な構築を支援します","ko":"스켈레톤 UI는 미리 정의된 컴포넌트와 스타일을 제공하는 UI 컴포넌트 라이브러리로, 웹 애플리케이션의 빠른 구축을 지원합니다","es":"Skeleton UI es un conjunto de componentes de interfaz de usuario reutilizables para desarrolladores","fr":"Skeleton UI est un ensemble de composants d''interface utilisateur réutilisables pour les développeurs","de":"Skeleton UI ist ein Satz von wiederverwendbaren Benutzeroberflächenkomponenten für Entwickler","pt":"Skeleton UI é um conjunto de componentes de interface do usuário pré-concebidos para desenvolvedores","ru":"Skeleton UI — это набор предустановленных компонентов пользовательского интерфейса для разработчиков","ar":"أداة الواجهة العظمية هي مجموعة من مكونات واجهة المستخدم المسبقة للبرمجيين"},"features":{"en":["Uses granular child components for composition","Follows import pattern using @skeletonlabs/skeleton-svelte","Provides a catalog of available components to avoid hand-rolling markup","Supports specific components like Avatar and Portal","Utilizes Svelte for component development","Adheres to a core principle of checking for existing components before building"],"zh":["基于Svelte的UI组件","预制的组件和样式","简单易用的导入模式","灵活的组合模式","支持自定义组件"],"ja":["SvelteベースのUIコンポーネント","事前に作成されたコンポーネントとスタイル","シンプルで使いやすいインポートパターン","柔軟なコンポジションパターン","カスタムコンポーネントのサポート"],"ko":["스벨트 기반의 UI 컴포넌트","미리 정의된 컴포넌트와 스타일","간단하고 사용하기 쉬운导入 패턴","柔軟한 컴포지션 패턴","커스텀 컴포넌트 지원"],"es":["Componentes de interfaz de usuario granulares","Patrón de importación sencillo con @skeletonlabs/skeleton-svelte","Composición de componentes con hijos","Compatibilidad con Svelte","Código de ejemplo para Avatar y otros componentes"],"fr":["Composants d''interface utilisateur granulaires","Modèle d''importation simple avec @skeletonlabs/skeleton-svelte","Composition de composants avec des enfants","Compatibilité avec Svelte","Exemple de code pour Avatar et d''autres composants"],"de":["Granulare Benutzeroberflächenkomponenten","Einfaches Importmuster mit @skeletonlabs/skeleton-svelte","Komposition von Komponenten mit Kindern","Kompatibilität mit Svelte","Codebeispiel für Avatar und andere Komponenten"],"pt":["Componentes de interface do usuário pré-concebidos","Importação de componentes via @skeletonlabs/skeleton-svelte","Padrão de composição granular com componentes filhos","Suporte a imagens e texto de fallback","Integração com Portal para renderização de componentes"],"ru":["Предустановленные компоненты пользовательского интерфейса","Импорт компонентов через @skeletonlabs/skeleton-svelte","Гранулярный шаблон составления с дочерними компонентами","Поддержка изображений и текста обратного вызова","Интеграция с Portal для рендеринга компонентов"],"ar":["مكونات واجهة المستخدم المسبقة","استيراد المكونات عبر @skeletonlabs/skeleton-svelte","نمط تكوين حبيبي مع مكونات الأبناء","دعم الصور والنص الافتراضي","التكامل مع Portal لتحويل المكونات"]},"keywords":{"en":["how to use skeleton-ui","skeleton-ui setup guide","skeleton-ui alternative","skeleton-ui vs Svelte","what is skeleton-ui","skeleton-ui install","skeleton-ui for AI agents","skeleton-ui Svelte integration","skeleton-ui component catalog","skeleton-ui development best practices"],"zh":["Skeleton UI","Svelte","UI组件","前端开发","快速构建","AIエージェント","Skeleton UI组件库","Svelte开发","UI设计"],"ja":["Skeleton UI","Svelte","UIコンポーネント","フロントエンド開発","迅速な構築","AIエージェント","Skeleton UIコンポーネントライブラリ","Svelte開発","UIデザイン"],"ko":["스켈레톤 UI","스벨트","UI 컴포넌트","프론트엔드 개발","빠른 구축","AI 에이전트","스켈레톤 UI 컴포넌트 라이브러리","스벨트 개발","UI 디자인"],"es":["Skeleton UI","componentes de interfaz de usuario","Svelte","desarrollo de software","interfaz de usuario","componentes reutilizables","patrones de diseño","Herramientas de desarrollo","IA Agents","Herramientas de desarrollo de software"],"fr":["Skeleton UI","composants d''interface utilisateur","Svelte","développement de logiciels","interface utilisateur","composants réutilisables","modèles de conception","Outils de développement","Agents IA","Outils de développement de logiciels"],"de":["Skeleton UI","Benutzeroberflächenkomponenten","Svelte","Softwareentwicklung","Benutzeroberfläche","wiederverwendbare Komponenten","Entwurfsmuster","Entwicklungstools","KI-Agents","Software-Entwicklungstools"],"pt":["skeleton ui","componentes de interface do usuário","desenvolvimento de software","guias de configuração","melhores práticas para desenvolvedores","importação de componentes","composição granular","suporte a imagens"],"ru":["skeleton ui","компоненты пользовательского интерфейса","разработка программного обеспечения","руководства по настройке","лучшие практики для разработчиков","импорт компонентов","гранулярный шаблон составления","поддержка изображений"],"ar":["أداة الواجهة العظمية","مكونات واجهة المستخدم","برمجة البرامج","دلائل الإعداد","أفضل الأساليب للبرمجيين","استيراد المكونات","نمط تكوين حبيبي","دعم الصور"]}},"owner":"JoeKarow","repo":"motw-campaign-tracker","repoPath":"JoeKarow/motw-campaign-tracker","stars":0,"forks":0,"updatedAt":"2026-03-06T16:04:31Z","topics":[],"category":"community","skillMd":{"name":"skeleton-ui","description":">","bodyPreview":"# Skeleton UI Component Skill\n\n## Core Principle\n\n**Before building ANY UI element, check if Skeleton has a component or styled element for it.** Do not hand-roll markup when a Skeleton component exists. This catalog lists everything available.\n\n## Import Pattern\n\n```ts\nimport { ComponentName, Portal } from ''@skeletonlabs/skeleton-svelte'';\n```\n\n## Composition Pattern\n\nSkeleton uses granular child components:\n\n```svelte\n<Avatar>\n  <Avatar.Image src=\"...\" />\n  <Avatar.Fallback>JD</Avatar.Fallback>","body":"# Skeleton UI Component Skill\n\n## Core Principle\n\n**Before building ANY UI element, check if Skeleton has a component or styled element for it.** Do not hand-roll markup when a Skeleton component exists. This catalog lists everything available.\n\n## Import Pattern\n\n```ts\nimport { ComponentName, Portal } from ''@skeletonlabs/skeleton-svelte'';\n```\n\n## Composition Pattern\n\nSkeleton uses granular child components:\n\n```svelte\n<Avatar>\n  <Avatar.Image src=\"...\" />\n  <Avatar.Fallback>JD</Avatar.Fallback>\n</Avatar>\n```\n\n## Data Flow\n\n- Props in, `onXxxChange` callbacks out (e.g., `onValueChange`, `onOpenChange`)\n- Collections use `useListCollection()` helper for item mapping\n\n## Positioned Content\n\nComponents that render floating/overlay content need `<Portal>`:\nCombobox, Popover, Tooltip, Dialog, Select, Toast\n\n---\n\n## Component Catalog\n\n### Layout & Navigation\n\n| Component      | Use When                                                  |\n| -------------- | --------------------------------------------------------- |\n| **Navigation** | App-level nav bars, sidebar navigation                    |\n| **Tabs**       | Switching between views/panels in the same context        |\n| **Accordion**  | Collapsible sections, FAQ lists, expandable details       |\n| **Segment**    | Toggle between a small set of options (like button group) |\n\n### Overlays & Feedback\n\n| Component    | Use When                                              |\n| ------------ | ----------------------------------------------------- |\n| **Dialog**   | Confirmation prompts, modal forms, detail views       |\n| **Drawer**   | Side panels, mobile menus, supplementary content      |\n| **Popover**  | Rich contextual content on click (menus, info panels) |\n| **Tooltip**  | Brief hover hints for icons/buttons                   |\n| **Toast**    | Temporary notifications, success/error messages       |\n| **Alert**    | Inline banners, warnings, info messages               |\n| **Progress** | Loading indicators, completion bars                   |\n\n### Form Components\n\n| Component      | Use When                                          |\n| -------------- | ------------------------------------------------- |\n| **Combobox**   | Searchable dropdown, autocomplete, multi-select   |\n| **Select**     | Simple dropdown selection (no search needed)      |\n| **Switch**     | Boolean toggles                                   |\n| **Slider**     | Numeric range input                               |\n| **Checkbox**   | Multiple selections from a list                   |\n| **Radio**      | Single selection from a list                      |\n| **TagsInput**  | Freeform tag/token entry                          |\n| **FileUpload** | File selection with drag-and-drop                 |\n| **Clipboard**  | Copy-to-clipboard buttons                         |\n| **PinInput**   | Verification codes, OTP entry                     |\n\n### Data Display\n\n| Component  | Use When                                |\n| ---------- | --------------------------------------- |\n| **Avatar** | User/entity profile images with fallback |\n| **Rating** | Star ratings, scoring displays          |\n\n### Styled Elements (Tailwind classes, not components)\n\nThese are applied as CSS classes on standard HTML elements:\n\n| Class        | Element       | Example                                              |\n| ------------ | ------------- | ---------------------------------------------------- |\n| `btn`        | `<button>`    | `<button class=\"btn preset-filled-primary-500\">`     |\n| `card`       | `<div>`       | `<div class=\"card p-4\">`                             |\n| `badge`      | `<span>`      | `<span class=\"badge preset-filled-primary-500\">`     |\n| `input`      | `<input>`     | `<input class=\"input\" type=\"text\" />`                |\n| `select`     | `<select>`    | `<select class=\"select\">`                            |\n| `textarea`   | `<textarea>`  | `<textarea class=\"textarea\">`                        |\n| `table`      | `<table>`     | `<table class=\"table\">`                              |\n| `label`      | `<label>`     | `<label class=\"label\">`                              |\n| `progress`   | `<progress>`  | `<progress class=\"progress\" value=\"50\" max=\"100\">`   |\n| `hr`         | `<hr>`        | `<hr class=\"hr\" />`                                  |\n\n### Preset Classes\n\nStyle variants follow the pattern: `preset-{style}-{color}-{shade}`\n\n- Styles: `filled`, `tonal`, `outlined`\n- Colors: `primary`, `secondary`, `tertiary`, `success`, `warning`, `error`, `surface`\n- Shade: typically `500`\n\nExamples:\n- `preset-filled-primary-500`\n- `preset-tonal-error`\n- `preset-outlined-surface-500`\n\n---\n\n## Documentation Lookup\n\nWhen implementing UI, use **Context7 MCP** for accurate reference docs:\n\n**Skeleton components** — full props, events, and examples:\n```\nLibrary ID: /websites/skeleton_dev_svelte\nQuery: \"[ComponentName] component props examples usage\"\n```\n\n**Tailwind CSS** — utility classes, modifiers, and layout:\n```\nLibrary ID: /tailwindlabs/tailwindcss.com\nQuery: \"[topic] classes usage examples\"\n```\n\nLook up Tailwind docs when unsure about utility classes (grid, flex, spacing, responsive modifiers, dark mode, etc.) rather than guessing class names. This is especially important for Skeleton''s styled elements which are composed with Tailwind utilities.\n\n## Decision Checklist\n\n1. Is there a **Skeleton component** for this? (see catalog above) -> Use it\n2. Is there a **styled element class** for this? (btn, card, badge, etc.) -> Use it\n3. Neither exists? -> Build custom markup with Tailwind, matching Skeleton''s design tokens\n"},"lastSynced":"2026-03-07T03:53:20.377Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing efficient UI component development with Svelte.","zh":"非常适合需要使用Svelte进行高效UI组件开发的前端代理。","ja":"Svelteを使用した効率的なUIコンポーネント開発が必要なフロントエンドエージェントに最適です。","ko":"Svelte를 사용하여 효율적인 UI 컴포넌트 개발이 필요한 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para agentes Frontend que necesitan un desarrollo eficiente de componentes de interfaz de usuario con Svelte.","fr":"Parfait pour les agents Frontend ayant besoin d''un développement efficace de composants d''interface utilisateur avec Svelte.","de":"Perfekt für Frontend-Agents, die eine effiziente Entwicklung von Benutzeroberflächenkomponenten mit Svelte benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de desenvolvimento de componentes de UI eficientes com Svelte.","ru":"Идеально подходит для агентов Frontend, которым требуется эффективное развитие компонентов UI с помощью Svelte.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يحتاج إلى تطوير عناصر واجهة المستخدم الفعال مع Svelte."},"recommendation":{"en":"Empowers agents to rapidly develop UI elements using pre-built Skeleton components, reducing hand-rolled markup and leveraging granular child components like Avatar and Portal, all while utilizing the Svelte framework.","zh":"赋予代理快速开发UI元素的能力，使用预建的Skeleton组件，减少手动编写的标记，并利用细粒度的子组件，如Avatar和Portal，同时利用Svelte框架。","ja":"エージェントが、事前に構築されたSkeletonコンポーネントを使用してUIエレメントを迅速に開発できるようにし、手動でマークアップを記述する必要性を減らし、AvatarやPortalなどの粒度の細かいサブコンポーネントを活用し、Svelteフレームワークを利用します。","ko":"에이전트가 미리 구축된 Skeleton 컴포넌트를 사용하여 UI 요소를 신속하게 개발할 수 있도록 하며, 수동으로 마크업을 작성할 필요를 줄이고, Avatar 및 Portal과 같은 세부적인 하위 컴포넌트를 활용하며, Svelte 프레임워크를 사용합니다.","es":"Empodera a los agentes para desarrollar rápidamente elementos de interfaz de usuario utilizando componentes Skeleton preconstruidos, reduciendo el marcado personalizado y aprovechando componentes secundarios granulares como Avatar y Portal, todo mientras utiliza el framework Svelte.","fr":"Permet aux agents de développer rapidement des éléments d''interface utilisateur en utilisant des composants Skeleton préconstruits, en réduisant le code de markup personnalisé et en exploitant des composants enfants granulaires tels que Avatar et Portal, le tout en utilisant le framework Svelte.","de":"Ermächtigt die Agenten, Benutzeroberflächenelemente schnell mit vorgefertigten Skeleton-Komponenten zu entwickeln, reduziert die handgefertigte Markup und nutzt granulare Kindkomponenten wie Avatar und Portal, alles unter Verwendung des Svelte-Frameworks.","pt":"Habilita os agentes a desenvolver rapidamente elementos de UI usando componentes Skeleton pré-construídos, reduzindo a marcação manual e aproveitando componentes filhos granulares como Avatar e Portal, tudo isso utilizando o framework Svelte.","ru":"Наделяет агентов возможностью быстро разрабатывать элементы UI с помощью предварительно созданных компонентов Skeleton, сокращая ручную разметку и используя гранулярные дочерние компоненты, такие как Avatar и Portal, все это при использовании фреймворка Svelte.","ar":"يمنح الوكلاء القدرة على تطوير عناصر واجهة المستخدم بسرعة باستخدام مكونات الهيكل العظمي المسبقة البناء، وتقليل العلامات اليدوية وتفعيل مكونات الأبناء المتجزئة مثل الصورة والمنفذ، وكل ذلك باستخدام إطار العمل Svelte."},"useCases":{"en":["Streamlining UI development with pre-built components","Implementing consistent design patterns across applications using Skeleton''s catalog","Composing complex UI elements with granular child components like Avatar.Image and Avatar.Fallback"],"zh":["使用预建组件简化UI开发","使用Skeleton目录在应用程序中实现一致的设计模式","使用细粒度的子组件，如Avatar.Image和Avatar.Fallback组合复杂的UI元素"],"ja":["事前に構築されたコンポーネントを使用してUI開発を簡素化する","Skeletonのカタログを使用してアプリケーション全体で一貫したデザインパターンを実装する","Avatar.ImageやAvatar.Fallbackなどの粒度の細かいサブコンポーネントを使用して複雑なUIエレメントを構成する"],"ko":["미리 구축된 컴포넌트를 사용하여 UI 개발을 단순화하는 것","Skeleton 카탈로그를 사용하여 애플리케이션 전반에 걸쳐 일관된 디자인 패턴을 구현하는 것","Avatar.Image 및 Avatar.Fallback와 같은 세부적인 하위 컴포넌트를 사용하여 복잡한 UI 요소를 구성하는 것"],"es":["Optimizar el desarrollo de interfaz de usuario con componentes preconstruidos","Implementar patrones de diseño coherentes en aplicaciones mediante el catálogo de Skeleton","Componer elementos de interfaz de usuario complejos con componentes secundarios granulares como Avatar.Image y Avatar.Fallback"],"fr":["Optimiser le développement d''interface utilisateur avec des composants préconstruits","Mettre en œuvre des modèles de conception cohérents dans les applications à l''aide du catalogue de Skeleton","Composer des éléments d''interface utilisateur complexes avec des composants enfants granulaires tels que Avatar.Image et Avatar.Fallback"],"de":["Optimieren der Benutzeroberflächenerstellung mit vorgefertigten Komponenten","Implementierung konsistenter Designtpatterns in Anwendungen mithilfe des Skeleton-Katalogs","Zusammensetzen komplexer Benutzeroberflächenelemente mit granularen Kindkomponenten wie Avatar.Image und Avatar.Fallback"],"pt":["Otimizar o desenvolvimento de UI com componentes pré-construídos","Implementar padrões de design consistentes em aplicativos usando o catálogo do Skeleton","Compor elementos de UI complexos com componentes filhos granulares como Avatar.Image e Avatar.Fallback"],"ru":["Оптимизировать разработку UI с помощью предварительно созданных компонентов","Реализовывать последовательные шаблоны дизайна во всех приложениях с помощью каталога Skeleton","Составлять сложные элементы UI с гранулярными дочерними компонентами, такими как Avatar.Image и Avatar.Fallback"],"ar":["تحسين تطوير واجهة المستخدم باستخدام المكونات المسبقة البناء","تنفيذ أنماط تصميم متسقة عبر التطبيقات باستخدام كتالوج الهيكل العظمي","تأليف عناصر واجهة المستخدم المعقدة مع مكونات الأبناء المتجزئة مثل الصورة والمنفذ"]},"limitations":{"en":["Requires Svelte framework","Limited to components available in the Skeleton catalog"],"zh":["需要Svelte框架","仅限于Skeleton目录中可用的组件"],"ja":["Svelteフレームワークが必要","Skeletonのカタログに含まれるコンポーネントのみに限定される"],"ko":["Svelte 프레임워크가 필요","Skeleton 카탈로그에 포함된 컴포넌트에만 제한됨"],"es":["Requiere el framework Svelte","Limitado a los componentes disponibles en el catálogo de Skeleton"],"fr":["Nécessite le framework Svelte","Limité aux composants disponibles dans le catalogue de Skeleton"],"de":["Benötigt das Svelte-Framework","Begrenzt auf die im Skeleton-Katalog verfügbaren Komponenten"],"pt":["Requer o framework Svelte","Limitado aos componentes disponíveis no catálogo do Skeleton"],"ru":["Требует фреймворка Svelte","Ограничен компонентами, доступными в каталоге Skeleton"],"ar":["يتطلب إطار العمل Svelte","محدود بالمكونات المتاحة في كتالوج الهيكل العظمي"]},"version":4},"contentHash":"e6301732297a62681763ebc3bb03fadb57c4c899b9a5c377f5743ef4f6b38934","qualityScore":36}');
