INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('JoeKarow/motw-campaign-tracker/skeleton-ui', 'skeleton-ui', 'JoeKarow', 'motw-campaign-tracker', 'community', 'skeleton-ui JoeKarow motw-campaign-tracker community skeleton-ui is a UI component skill that provides pre-built components for efficient development. It benefits developers by offering a catalog of available components to avoid hand-rolling markup. Skeleton UI是一种基于Svelte的UI组件库，提供了一套简单易用的组件和工具 Skeleton UIはSvelteベースのUIコンポーネントライブラリで、シンプルで使いやすいコンポーネントとツールを提供します 스켈레톤 UI는 스벨트 기반의 UI 컴포넌트 라이브러리로서, 간단하고 사용하기 쉬운 컴포넌트와 도구를 제공합니다 Skeleton UI es un conjunto de componentes de interfaz de usuario para desarrolladores, que ofrece una forma sencilla de crear interfaces de usuario consistentes Skeleton UI est un ensemble de composants d''interface utilisateur pour les développeurs, qui offre une façon simple de créer des interfaces utilisateur cohérentes Skeleton UI ist ein Satz von Benutzeroberflächenkomponenten für Entwickler, der eine einfache Möglichkeit bietet, konsistente Benutzeroberflächen zu erstellen O Skeleton UI é um componente de interface do usuário que fornece uma variedade de elementos pré-concebidos para desenvolvedores. Aprenda a utilizá-lo com nosso guia Skeleton UI — это компонент пользовательского интерфейса, который предоставляет ряд предустановленных элементов для разработчиков ИИ Агентов أداة الواجهة العظمية هي مكون واجهة المستخدم التي توفر مجموعة من العناصر المسبقة لبرامج المرء. تعلم كيفية استخدامها مع دليلنا how to use skeleton-ui skeleton-ui setup guide skeleton-ui alternative skeleton-ui vs Svelte what is skeleton-ui skeleton-ui install skeleton-ui for AI agents skeleton-ui Svelte integration skeleton-ui component catalog skeleton-ui development best practices Skeleton UI Svelte UI组件 前端开发 快速构建 AIエージェント Skeleton UI组件库 Svelte开发 UI设计 Uses granular child components for composition Follows import pattern using @skeletonlabs/skeleton-svelte Provides a catalog of available components to avoid hand-rolling markup Supports specific components like Avatar and Portal Utilizes Svelte for component development Adheres to a core principle of checking for existing components before building skeleton-ui is a set of pre-built UI components and styled elements for efficient development, following core principles and import patterns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('venturecrane/crane-console/sod', 'community', 'venturecrane', 'crane-console', 'venturecrane/crane-console', 'sod', 0, 0, 36, '2026-03-03T07:40:04Z', '2026-03-07T03:56:53.322Z', 'e9ed1283becd540049095836354ffe51f4ab84f851e3c77e230b3361f8fbcc07', '{"id":"venturecrane/crane-console/sod","name":"sod","description":{"en":"The sod skill prepares your session using MCP tools to validate context and ensure you''re ready to code. It provides a structured briefing with session context, behavioral directives, and continuity information.","zh":"sod 是 Venture Crane 基础架构控制台的一部分，用于产品开发的工厂工具。它可以初始化会话、显示工作优先级和确保代码准备就绪","ja":"sod は Venture Crane インフラストラクチャ コンソールの一部で、製品開発のファクトリーツールとして使用されます。セッションの初期化、作業の優先順位の表示、コードの準備など","ko":"sod 는 Venture Crane 인프라스트럭처 콘솔의 일부로, 제품 개발을 위한 공장 도구입니다. 세션 초기화, 작업 우선 순위 표시, 코드 준비 등","es":"sod es una herramienta de infraestructura de Venture Crane que valida contextos y prioridades de trabajo para desarrolladores","fr":"sod est un outil d''infrastructure de Venture Crane qui valide les contextes et les priorités de travail pour les développeurs","de":"sod ist ein Infrastruktur-Tool von Venture Crane, das Kontexte und Arbeitsprioritäten für Entwickler überprüft","pt":"O Sod é uma ferramenta de desenvolvimento de produtos que utiliza MCP tools para validar contexto e prioridades de trabalho.","ru":"Sod - это инструмент разработки продукции, использующий инструменты MCP для проверки контекста и приоритетов работы для ИИ Агентов","ar":"أداة Sod هي أداة تطوير منتجات تستخدم أدوات المسيطر المركزي MCP لتحقق السياق وأولويات العمل لعمليات الذكاء الاصطناعي"},"seo":{"title":{"en":"sod: Venture Crane Infrastructure Console Setup Guide | A...","zh":"sod 工厂工具设置指南 - Venture Crane 基础架构控制台","ja":"sod Setup Guide - Venture Crane インフラストラクチャ コンソール","ko":"sod 설정 가이드 - Venture Crane 인프라스트럭처 콘솔","es":"Guía de configuración de sod - Herramienta de infraestruc...","fr":"Guide de mise en route de sod - Outil d''infrastructure de...","de":"Einrichtungsleitfaden für sod - Infrastruktur-Tool von Ve...","pt":"Guia de Configuração do Sod: Ferramentas de Desenvolvimen...","ru":"Настройка Sod: Инструменты разработки продукции для ИИ Аг...","ar":"إعداد أداة Sod: أدوات تطوير المنتجات لعمليات الذكاء الاصط..."},"description":{"en":"Discover how to initialize your session with crane_sod MCP tool and get ready to code with sod''s structured briefing and continuity features. Learn more now!","zh":"使用 sod 工厂工具提高开发效率，包括会话初始化、工作优先级和代码准备","ja":"sod を使用して開発効率を向上させます。セッションの初期化、作業の優先順位、コードの準備など","ko":"sod 를 사용하여 개발 효율성을 높이세요. 세션 초기화, 작업 우선 순위, 코드 준비 등","es":"Aprende a utilizar sod, la herramienta de infraestructura de Venture Crane, para validar contextos y prioridades de trabajo","fr":"Découvrez comment utiliser sod, l''outil d''infrastructure de Venture Crane, pour valider les contextes et les priorités de travail","de":"Erfahren Sie, wie Sie sod, das Infrastruktur-Tool von Venture Crane, verwenden, um Kontexte und Arbeitsprioritäten zu überprüfen","pt":"Aprenda a configurar o Sod para desenvolver produtos com eficiência, utilizando ferramentas de linha de comando e MCP","ru":"Узнайте, как настроить Sod для разработки продуктов с помощью командной строки и инструментов MCP для ИИ Агентов","ar":"تعلم كيفية إعداد أداة Sod لتطوير المنتجات بفعالية باستخدام أدوات سطر الأوامر والمCP لعمليات الذكاء الاصطناعي"},"definition":{"en":"sod is a factory tooling skill for product development that initializes sessions using the crane_sod MCP tool to provide a structured briefing and ensure coding readiness.","zh":"sod 是一种工厂工具，用于初始化会话、显示工作优先级和确保代码准备就绪","ja":"sod は、セッションの初期化、作業の優先順位の表示、コードの準備などを行うファクトリーツールの一種です","ko":"sod 는 세션 초기화, 작업 우선 순위 표시, 코드 준비 등을 수행하는 공장 도구의 일종입니다","es":"sod es una herramienta de inicio de sesión que prepara la sesión de un desarrollador con MCP","fr":"sod est un outil de démarrage de session qui prépare la session d''un développeur avec MCP","de":"sod ist ein Tool zum Starten einer Sitzung, das die Sitzung eines Entwicklers mit MCP vorbereitet","pt":"O que é Sod? É uma ferramenta de desenvolvimento de produtos que utiliza MCP tools para inicializar sessões e validar contexto.","ru":"Что такое Sod? Это инструмент разработки продукции, использующий инструменты MCP для инициализации сессий и проверки контекста для ИИ Агентов","ar":"ما هي أداة Sod؟ هي أداة تطوير منتجات تستخدم أدوات المسيطر المركزي MCP لإعداد الجلسات وตรวจ السياق لعمليات الذكاء الاصطناعي"},"features":{"en":["Initializes sessions using the crane_sod MCP tool","Provides a structured briefing with session context, venture, repo, and branch information","Returns behavioral directives, including enterprise rules and continuity information","Displays alerts for P0 issues, active sessions, and weekly plan status","Offers a cadence briefing with overdue and pending tasks"],"zh":["会话初始化","工作优先级显示","代码准备","行为指令","连续性","警报"],"ja":["セッションの初期化","作業の優先順位の表示","コードの準備","行動指令","連続性","アラート"],"ko":["세션 초기화","작업 우선 순위 표시","코드 준비","행동 지시","연속성","알림"],"es":["Inicialización de sesión con MCP","Validación de contexto y prioridades de trabajo","Visualización de directivas de comportamiento y alertas","Planificación semanal y briefing de cadencia","Integración con herramientas de desarrollo de Venture Crane"],"fr":["Initialisation de session avec MCP","Validation du contexte et des priorités de travail","Affichage des directives de comportement et des alertes","Planification hebdomadaire et briefing de cadence","Intégration avec les outils de développement de Venture Crane"],"de":["Sitzungsinitialisierung mit MCP","Überprüfung von Kontext und Arbeitsprioritäten","Anzeige von Verhaltensrichtlinien und Warnungen","Wöchentliche Planung und Cadence-Briefing","Integration mit Entwicklertools von Venture Crane"],"pt":["Iniciação de sessão com MCP tools","Validação de contexto e prioridades de trabalho","Exibição de diretrizes comportamentais e continuidade","Alertas para problemas críticos e sessões ativas","Plano semanal e briefing de cadência"],"ru":["Инициализация сессии с помощью инструментов MCP","Проверка контекста и приоритетов работы","Отображение директив поведения и непрерывности","Предупреждения о критических проблемах и активных сессиях","Недельный план и брифинг по каденции для ИИ Агентов"],"ar":["إعداد الجلسة باستخدام أدوات المسيطر المركزي MCP","تحقق السياق وأولويات العمل","عرض التوجيهات السلوكية والاستمرارية","تنبيهات للمشاكل الحرجة والجلسات النشطة","خطة أسبوعية وتقرير الكادنس لعمليات الذكاء الاصطناعي"]},"keywords":{"en":["how to use sod","sod setup guide","what is sod","sod alternative","sod vs crane","crane_sod MCP tool","venture crane infrastructure","factory tooling for product development","sod install","sod documentation"],"zh":["sod 工厂工具","Venture Crane 基础架构控制台","产品开发","会话初始化","工作优先级","代码准备","AIエージェント","工厂工具设置"],"ja":["sod ファクトリーツール","Venture Crane インフラストラクチャ コンソール","製品開発","セッションの初期化","作業の優先順位","コードの準備","AIエージェント","ファクトリーツール設定"],"ko":["sod 공장 도구","Venture Crane 인프라스트럭처 콘솔","제품 개발","세션 초기화","작업 우선 순위","코드 준비","AI 에이전트","공장 도구 설정"],"es":["herramientas de infraestructura de Venture Crane","sod AI Agent","desarrollo de productos con MCP","validación de contexto y prioridades","planificación semanal y briefing de cadencia","integración con herramientas de desarrollo","Agentes de Inteligencia Artificial para desarrolladores"],"fr":["outils d''infrastructure de Venture Crane","sod Agent IA","développement de produits avec MCP","validation du contexte et des priorités","planification hebdomadaire et briefing de cadence","intégration avec les outils de développement","Agents d''Intelligence Artificielle pour développeurs"],"de":["Infrastruktur-Tools von Venture Crane","sod KI-Agent","Produktentwicklung mit MCP","Überprüfung von Kontext und Arbeitsprioritäten","wöchentliche Planung und Cadence-Briefing","Integration mit Entwicklertools","KI-Agents für Entwickler"],"pt":["Sod","MCP tools","desenvolvimento de produtos","ferramentas de linha de comando","validação de contexto","prioridades de trabalho","diretrizes comportamentais","continuidade","alertas"],"ru":["Sod","инструменты MCP","разработка продукции","командная строка","проверка контекста","приоритеты работы","директивы поведения","непрерывность","предупреждения","ИИ Агенты"],"ar":["أداة Sod","أدوات المسيطر المركزي MCP","تطوير المنتجات","أدوات سطر الأوامر","تحقق السياق","أولويات العمل","التوجيهات السلوكية","الاستمرارية","تنبيهات","عمليات الذكاء الاصطناعي"]}},"owner":"venturecrane","repo":"crane-console","repoPath":"venturecrane/crane-console","stars":0,"forks":0,"updatedAt":"2026-03-03T07:40:04Z","topics":[],"category":"community","skillMd":{"name":"sod","description":"Start of Day","bodyPreview":"# /sod - Start of Day\n\nThis command prepares your session using MCP tools to validate context, show work priorities, and ensure you''re ready to code.\n\n## Execution\n\n### Step 1: Start Session\n\nCall the `crane_sod` MCP tool to initialize the session.\n\nThe tool returns a structured briefing with:\n\n- Session context (venture, repo, branch)\n- Behavioral directives (enterprise rules)\n- Continuity (recent handoffs)\n- Alerts (P0 issues, active sessions)\n- Weekly plan status\n- Cadence briefing (overdue/d","body":"# /sod - Start of Day\n\nThis command prepares your session using MCP tools to validate context, show work priorities, and ensure you''re ready to code.\n\n## Execution\n\n### Step 1: Start Session\n\nCall the `crane_sod` MCP tool to initialize the session.\n\nThe tool returns a structured briefing with:\n\n- Session context (venture, repo, branch)\n- Behavioral directives (enterprise rules)\n- Continuity (recent handoffs)\n- Alerts (P0 issues, active sessions)\n- Weekly plan status\n- Cadence briefing (overdue/due recurring activities)\n- Knowledge base and enterprise context\n\n> **Note:** The MCP tool reads the weekly plan but does not auto-create it. If the plan is missing, Step 4 below guides you through creating it.\n\n### Step 2: Display Context Confirmation\n\nPresent a clear context confirmation box:\n\n```\nVENTURE:  {venture_name} ({venture_code})\nREPO:     {repo}\nBRANCH:   {branch}\nSESSION:  {session_id}\n```\n\nState: \"You''re in the correct repository and on the {branch} branch.\"\n\n### Step 3: Handle P0 Issues\n\nIf the Alerts section shows P0 issues:\n\n1. Display prominently with warning icon\n2. Say: \"**There are P0 issues that need immediate attention.**\"\n3. List each issue\n\n### Step 4: Check Weekly Plan\n\nThe weekly plan is a **portfolio-level** artifact that lives in crane-console (vc). Only prompt for creation when the active venture is `vc`.\n\nBased on `weekly_plan` status in the response:\n\n- **valid**: Note the priority venture and proceed\n- **stale**: Warn user: \"Weekly plan is {age_days} days old. Consider updating.\"\n- **missing**:\n  - **If venture is `vc`**: Ask user:\n    - \"What venture is priority this week? (vc/dfg/sc/ke)\"\n    - \"Any specific issues to target? (optional)\"\n    - \"Any capacity constraints? (optional)\"\n\n    Then create `docs/planning/WEEKLY_PLAN.md`:\n\n    ```markdown\n    # Weekly Plan - Week of {DATE}\n\n    ## Priority Venture\n\n    {venture code}\n\n    ## Target Issues\n\n    {list or \"None specified\"}\n\n    ## Capacity Notes\n\n    {notes or \"Normal capacity\"}\n\n    ## Created\n\n    {ISO timestamp}\n    ```\n\n  - **If venture is NOT `vc`**: Skip silently. Do not prompt the user to create a weekly plan.\n\n### Step 5: STOP and Wait\n\n**CRITICAL**: Do NOT automatically start working.\n\nPresent a brief summary and ask: **\"What would you like to focus on?\"**\n\nIf user wants to see the full work queue, call `crane_status` MCP tool.\n\n## Wrong Repo Prevention\n\nAll GitHub issues created this session MUST target the repo shown in context confirmation. If you find yourself targeting a different repo, STOP and verify with the user.\n\n## Troubleshooting\n\nIf MCP tools aren''t available:\n\n1. Check `claude mcp list` shows crane connected\n2. Ensure started with: `crane vc`\n3. Try: `cd ~/dev/crane-console/packages/crane-mcp && npm run build && npm link`\n"},"lastSynced":"2026-03-07T03:56:53.322Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing structured session briefings and MCP tool integration.","zh":"非常适合需要结构化会议简报和MCP工具集成的开发代理。","ja":"構造化されたセッションブリーフィングとMCPツールの統合を必要とする開発エージェントに最適です。","ko":"구조화된 세션 브리핑과 MCP 도구 통합이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan sesiones de briefings estructuradas y integración de herramientas MCP.","fr":"Parfait pour les agents de développement ayant besoin de briefings de session structurés et d''intégration d''outils MCP.","de":"Perfekt für Entwicklungsmittel, die strukturierte Sitzungsbriefings und MCP-Tool-Integration benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de briefings de sessão estruturados e integração da ferramenta MCP.","ru":"Идеально подходит для агентов разработки, которым необходимы структурированные брифинги сессий и интеграция инструмента MCP.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى إيجاز جلسة منظم وتكامل أداة MCP."},"recommendation":{"en":"Empowers agents to validate context, prioritize work, and ensure coding readiness using MCP tools, providing session context, behavioral directives, and continuity information through structured briefings.","zh":"赋予代理人验证上下文、优先处理工作、并确保使用MCP工具编码准备就绪的能力，提供结构化的简报，包含会话上下文、行为指令和连续性信息。","ja":"MCPツールを使用してコンテキストを検証し、作業を優先し、コードの準備就緒を確保する能力をエージェントに与え、構造化されたブリーフィングを提供し、セッションのコンテキスト、動作指令、継続性情報を含みます。","ko":"MCP 도구를 사용하여 컨텍스트를 검증하고, 작업을 우선순위화하며, 코드 준비를 보장하는 능력을 에이전트에게 부여하여, 구조화된 브리핑을 제공하고, 세션 컨텍스트, 동작 지시 및 연속성 정보를 포함합니다.","es":"Habilita a los agentes a validar el contexto, priorizar el trabajo y garantizar la preparación para la codificación utilizando herramientas MCP, proporcionando contexto de sesión, directivas de comportamiento e información de continuidad a través de briefings estructurados.","fr":"Permet aux agents de valider le contexte, de prioriser le travail et de garantir la préparation au codage en utilisant les outils MCP, en fournissant le contexte de session, les directives de comportement et les informations de continuité via des briefings structurés.","de":"Ermächtigt die Agenten, den Kontext zu validieren, die Arbeit zu priorisieren und die Kodierbereitschaft unter Verwendung von MCP-Tools sicherzustellen, indem sie Sitzungskontext, Verhaltensrichtlinien und Kontinuitätsinformationen über strukturierte Briefings bereitstellen.","pt":"Habilita os agentes a validar o contexto, priorizar o trabalho e garantir a prontidão de codificação usando as ferramentas MCP, fornecendo contexto de sessão, diretivas comportamentais e informações de continuidade por meio de briefings estruturados.","ru":"Наделяет агентов возможностью проверить контекст, расставить приоритеты работы и обеспечить готовность кодирования с помощью инструментов MCP, предоставляя контекст сессии, поведенческие директивы и информацию о непрерывности через структурированные брифинги.","ar":"يمنح الوكلاء القدرة على التحقق من السياق وتحديد أولويات العمل وضمان جاهزية الترميز باستخدام أدوات MCP، وتقديم سياق الجلسة والتوجيهات السلوكية ومعلومات الاستمرارية من خلال إيجازات منظمات."},"useCases":{"en":["Initializing coding sessions with crane_sod tool","Validating session context and enterprise rules","Reviewing weekly plan status and cadence briefings"],"zh":["使用crane_sod工具初始化编码会话","验证会话上下文和企业规则","查看每周计划状态和cadence简报"],"ja":["crane_sodツールを使用してコード化セッションを初期化する","セッションコンテキストと企業ルールを検証する","毎週の計画状況とcadenceブリーフィングを確認する"],"ko":["crane_sod 도구를 사용하여 코딩 세션 초기화","세션 컨텍스트 및 기업 규칙 검증","주간 계획 상태 및 캐드언스 브리핑 검토"],"es":["Inicializar sesiones de codificación con la herramienta crane_sod","Validar el contexto de sesión y las reglas empresariales","Revisar el estado del plan semanal y las briefings de cadencia"],"fr":["Initialiser des sessions de codage avec l''outil crane_sod","Valider le contexte de session et les règles d''entreprise","Examiner le statut du plan hebdomadaire et les briefings de cadence"],"de":["Initialisieren von Kodiersitzungen mit dem crane_sod-Tool","Validieren des Sitzungskontexts und der Unternehmensregeln","Überprüfen des Status des wöchentlichen Plans und der Kadenz-Briefings"],"pt":["Inicializando sessões de codificação com a ferramenta crane_sod","Validando contexto de sessão e regras da empresa","Revisando o status do plano semanal e briefings de cadência"],"ru":["Инициализация сессий кодирования с помощью инструмента crane_sod","Проверка контекста сессии и правил предприятия","Просмотр статуса плана на неделю и брифингов по каденции"],"ar":["تأسيس جلسات الترميز مع أداة crane_sod"," التحقق من سياق الجلسة وقواعد الشركة","استعراض حالة الخطة الأسبوعية وإيجازات الإيقاع"]},"limitations":{"en":["Requires MCP tool access","Limited to sessions with predefined venture, repo, and branch structures"],"zh":["需要MCP工具访问","仅限于具有预定义的Venture、仓库和分支结构的会话"],"ja":["MCPツールへのアクセスが必要","事前に定義されたVenture、リポジトリ、ブランチ構造を持つセッションのみに限定"],"ko":["MCP 도구 액세스가 필요함","사전 정의된 벤처, 저장소 및 분기 구조가 있는 세션만 해당"],"es":["Requiere acceso a herramientas MCP","Limitado a sesiones con estructuras de empresa, repositorio y rama predefinidas"],"fr":["Nécessite un accès aux outils MCP","Limité aux sessions avec des structures d''entreprise, de référentiel et de branche prédéfinies"],"de":["Erfordert Zugriff auf MCP-Tools","Begrenzt auf Sitzungen mit vordefinierten Unternehmens-, Repository- und Branchenstrukturen"],"pt":["Requer acesso à ferramenta MCP","Limitado a sessões com estruturas de venture, repo e branch predefinidas"],"ru":["Требует доступа к инструменту MCP","Ограничен сессиями со структурами venture, repo и branch, предопределенными"],"ar":["يتطلب الوصول إلى أداة MCP","محدد بالجلسات التي لها هيكل مشروع ومخزن وفرع محددة مسبقا"]},"version":4},"contentHash":"e9ed1283becd540049095836354ffe51f4ab84f851e3c77e230b3361f8fbcc07","qualityScore":36}');
