INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('venturecrane/crane-console/sod', 'sod', 'venturecrane', 'crane-console', 'community', 'sod venturecrane crane-console community The sod skill prepares your session using MCP tools to validate context and ensure you''re ready to code. It provides a structured briefing with session context, behavioral directives, and continuity information. sod 是 Venture Crane 基础架构控制台的一部分，用于产品开发的工厂工具。它可以初始化会话、显示工作优先级和确保代码准备就绪 sod は Venture Crane インフラストラクチャ コンソールの一部で、製品開発のファクトリーツールとして使用されます。セッションの初期化、作業の優先順位の表示、コードの準備など sod 는 Venture Crane 인프라스트럭처 콘솔의 일부로, 제품 개발을 위한 공장 도구입니다. 세션 초기화, 작업 우선 순위 표시, 코드 준비 등 sod es una herramienta de infraestructura de Venture Crane que valida contextos y prioridades de trabajo para desarrolladores sod est un outil d''infrastructure de Venture Crane qui valide les contextes et les priorités de travail pour les développeurs sod ist ein Infrastruktur-Tool von Venture Crane, das Kontexte und Arbeitsprioritäten für Entwickler überprüft O Sod é uma ferramenta de desenvolvimento de produtos que utiliza MCP tools para validar contexto e prioridades de trabalho. Sod - это инструмент разработки продукции, использующий инструменты MCP для проверки контекста и приоритетов работы для ИИ Агентов أداة Sod هي أداة تطوير منتجات تستخدم أدوات المسيطر المركزي MCP لتحقق السياق وأولويات العمل لعمليات الذكاء الاصطناعي how to use sod sod setup guide what is sod sod alternative sod vs crane crane_sod MCP tool venture crane infrastructure factory tooling for product development sod install sod documentation sod 工厂工具 Venture Crane 基础架构控制台 产品开发 会话初始化 工作优先级 代码准备 AIエージェント 工厂工具设置 Initializes sessions using the crane_sod MCP tool Provides a structured briefing with session context, venture, repo, and branch information Returns behavioral directives, including enterprise rules and continuity information Displays alerts for P0 issues, active sessions, and weekly plan status Offers a cadence briefing with overdue and pending tasks sod is a factory tooling skill for product development that initializes sessions using the crane_sod MCP tool to provide a structured briefing and ensure coding readiness.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('venturecrane/dc-console/sod', 'community', 'venturecrane', 'dc-console', 'venturecrane/dc-console', 'sod', 0, 0, 36, '2026-03-03T02:32:59Z', '2026-03-07T13:08:40.886Z', 'e9ed1283becd540049095836354ffe51f4ab84f851e3c77e230b3361f8fbcc07', '{"id":"venturecrane/dc-console/sod","name":"sod","description":{"en":"The sod skill prepares your session using MCP tools to validate context and show work priorities. It benefits developers by ensuring they''re ready to code with a structured briefing.","zh":"SOD 是一个会话启动工具，使用 MCP 工具初始化会话，提供结构化的简报和会话上下文","ja":"SOD はセッションを開始するツールで、MCP ツールを使用してセッションを初期化し、構造化されたブリーフィングとセッションコンテキストを提供します","ko":"SOD는 세션을 시작하는 도구로, MCP 도구를 사용하여 세션을 초기화하고 구조화된 브리핑과 세션 컨텍스트를 제공합니다","es":"Sod es una consola para dc venture que utiliza MCP para validar contexto y mostrar prioridades de trabajo.","fr":"Sod est une console pour dc venture qui utilise MCP pour valider le contexte et afficher les priorités de travail.","de":"Sod ist eine Konsole für dc venture, die MCP verwendet, um den Kontext zu überprüfen und Arbeitsschwerpunkte anzuzeigen.","pt":"O Sod é uma ferramenta de console para inicializar sessões com MCP, fornecendo briefing estruturado e diretrizes comportamentais","ru":"Sod - это консольная утилита для запуска сессий с помощью ИИ Агентов MCP, обеспечивающая структурированный брифинг и поведенческие директивы","ar":"Sod هو أداة واجهة 命令ية لتشغيل الجلسات باستخدام أدوات MCP، وتوفر إحاطة منظمة وتوجيهات سلوكية"},"seo":{"title":{"en":"sod: Setup Guide for AI Agents | Console for dc venture","zh":"SOD 会话启动指南 - AIエージェント","ja":"SOD セッション開始ガイド - AIエージェント","ko":"SOD 세션 시작 가이드 - AI 에이전트","es":"Guía de Configuración de Sod: Inicio de Sesión con MCP","fr":"Guide de Configuration de Sod: Lancement de Session avec MCP","de":"Sod-Setup-Anleitung: Sitzungsstart mit MCP-Tools","pt":"Guia de Configuração do Sod: Inicializando Sessões com MCP","ru":"Настройка Sod: Руководство по запуску сессий с помощью ИИ...","ar":"دليل إعداد Sod: تشغيل الجلسات باستخدام أدوات MCP"},"description":{"en":"Discover how to initialize your session with sod and get ready to code with MCP tools. Learn more and start your day with a structured briefing","zh":"了解 SOD 会话启动的技术细节，包括 MCP 工具和会话上下文","ja":"SOD セッション開始の技術的詳細を学びます。MCP ツールとセッションコンテキストを含みます","ko":"SOD 세션 시작의 기술적 세부 사항을 알아보세요. MCP 도구 및 세션 컨텍스트 포함","es":"Aprende a configurar Sod para iniciar sesión con MCP y obtener una breve descripción de contexto, directivas y alertas.","fr":"Découvrez comment configurer Sod pour lancer une session avec MCP et obtenir un briefing structuré.","de":"Erfahren Sie, wie Sie Sod einrichten, um eine Sitzung mit MCP-Tools zu starten und eine strukturierte Zusammenfassung zu erhalten.","pt":"Aprenda a configurar o Sod para inicializar sessões com MCP e otimizar seu fluxo de trabalho","ru":"Узнайте, как настроить Sod для запуска сессий с помощью ИИ Агентов MCP и оптимизировать рабочий процесс","ar":"تعرف على كيفية إعداد Sod لتشغيل الجلسات باستخدام أدوات MCP وتحسين تدفق العمل"},"definition":{"en":"sod is a console for dc venture that initializes a session using the crane_sod MCP tool to provide a structured briefing with session context and behavioral directives","zh":"SOD 是一个会话启动工具，用于初始化会话和提供会话上下文","ja":"SOD はセッションを開始するツールで、セッションを初期化し、セッションコンテキストを提供することです","ko":"SOD는 세션을 시작하는 도구로, 세션을 초기화하고 세션 컨텍스트를 제공하는 것입니다","es":"Sod es una herramienta de inicio de sesión que utiliza MCP para proporcionar un briefing estructurado.","fr":"Sod est un outil de lancement de session qui utilise MCP pour fournir un briefing structuré.","de":"Sod ist ein Tool zum Starten einer Sitzung, das MCP verwendet, um eine strukturierte Zusammenfassung bereitzustellen.","pt":"O Sod é uma ferramenta de console que inicializa sessões com MCP, fornecendo contexto e diretrizes para desenvolvedores","ru":"Sod - это консольная утилита, которая запускает сессии с помощью ИИ Агентов MCP, предоставляя контекст и директивы для разработчиков","ar":"Sod هو أداة واجهة 命令ية لتشغيل الجلسات باستخدام أدوات MCP، وتوفر سياق وتوجيهات للמطورين"},"features":{"en":["Initializes session using crane_sod MCP tool","Provides structured briefing with session context, venture, repo, and branch","Returns behavioral directives, including enterprise rules and continuity","Displays alerts, including P0 issues and active sessions","Shows weekly plan status and cadence briefing with overdue items"],"zh":["使用 MCP 工具初始化会话","提供结构化的简报，包括会话上下文和行为指令","支持会话连续性和警报","显示每周计划状态和节奏简报"],"ja":["MCP ツールを使用してセッションを初期化","構造化されたブリーフィングを提供、セッションコンテキストとビヘイビア指令を含み","セッションの連続性とアラートをサポート","毎週の計画状態とカデンスブリーフィングを表示"],"ko":["MCP 도구를 사용하여 세션을 초기화","구조화된 브리핑을 제공, 세션 컨텍스트와 행동 지침을 포함","세션의 연속성과 경보를 지원","매주 계획 상태와 카덴스 브리핑을 표시"],"es":["Inicio de sesión con MCP","Validación de contexto de sesión","Mostrado de prioridades de trabajo","Alertas de problemas críticos","Estado del plan semanal","Resumen de continuidad"],"fr":["Lancement de session avec MCP","Validation du contexte de session","Affichage des priorités de travail","Alertes de problèmes critiques","État du plan hebdomadaire","Résumé de continuité"],"de":["Sitzungsstart mit MCP-Tools","Überprüfung des Sitzungskontexts","Anzeige von Arbeitsschwerpunkten","Warnungen bei kritischen Problemen","Status des wöchentlichen Plans","Zusammenfassung der Kontinuität"],"pt":["Inicialização de sessões com MCP","Briefing estruturado com contexto e diretrizes","Diretrizes comportamentais com regras de empresa","Continuidade com entregas recentes","Alertas para problemas críticos e sessões ativas","Plano semanal e briefing de cadência"],"ru":["Запуск сессий с помощью ИИ Агентов MCP","Структурированный брифинг с контекстом и директивами","Поведенческие директивы с правилами предприятия","Непрерывность с недавними передачами","Оповещения о критических проблемах и активных сессиях","Еженедельный план и брифинг по каденции"],"ar":["تشغيل الجلسات باستخدام أدوات MCP","إحاطة منظمة مع السياق والتوجيهات","توجيهات سلوكية مع قواعد المؤسسة","الاستمرارية مع التسليم الأخير","تنبيهات للأخطاء الحرجة والجلسات النشطة","خطة أسبوعية وإحاطة الكادنس"]},"keywords":{"en":["how to use sod","sod setup guide","sod alternative","sod vs crane","what is sod","sod install","mcp tools","crane_sod","dc venture"],"zh":["SOD 会话启动","MCP 工具","会话上下文","AIエージェント","会话启动指南","技术细节"],"ja":["SOD セッション開始","MCP ツール","セッションコンテキスト","AIエージェント","セッション開始ガイド","技術的詳細"],"ko":["SOD 세션 시작","MCP 도구","세션 컨텍스트","AI 에이전트","세션 시작 가이드","기술적 세부 사항"],"es":["Sod","MCP","inicio de sesión","validación de contexto","prioridades de trabajo","herramientas de desarrollo","consola de desarrollo","dc venture"],"fr":["Sod","MCP","lancement de session","validation du contexte","priorités de travail","outils de développement","console de développement","dc venture"],"de":["Sod","MCP","Sitzungsstart","Überprüfung des Kontexts","Arbeitsschwerpunkte","Entwicklungstools","Entwicklerkonsole","dc venture","AI-Tools","Entwickler-Workflow"],"pt":["Sod","MCP","console","inicializar sessões","briefing estruturado","diretrizes comportamentais","desenvolvedores","ferramentas de desenvolvimento"],"ru":["Sod","ИИ Агенты","MCP","консоль","запуск сессий","структурированный брифинг","поведенческие директивы","разработчики","инструменты разработки"],"ar":["Sod","أدوات MCP","واجهة 命令ية","تشغيل الجلسات","إحاطة منظمة","توجيهات سلوكية","المطورين","أدوات التطوير"]}},"owner":"venturecrane","repo":"dc-console","repoPath":"venturecrane/dc-console","stars":0,"forks":0,"updatedAt":"2026-03-03T02:32:59Z","topics":[],"category":"community","skillMd":{"name":"sod","description":"Start of Day","bodyPreview":"# /sod - Start of Day\n\nThis command prepares your session using MCP tools to validate context, show work priorities, and ensure you''re ready to code.\n\n## Execution\n\n### Step 1: Start Session\n\nCall the `crane_sod` MCP tool to initialize the session.\n\nThe tool returns a structured briefing with:\n\n- Session context (venture, repo, branch)\n- Behavioral directives (enterprise rules)\n- Continuity (recent handoffs)\n- Alerts (P0 issues, active sessions)\n- Weekly plan status\n- Cadence briefing (overdue/d","body":"# /sod - Start of Day\n\nThis command prepares your session using MCP tools to validate context, show work priorities, and ensure you''re ready to code.\n\n## Execution\n\n### Step 1: Start Session\n\nCall the `crane_sod` MCP tool to initialize the session.\n\nThe tool returns a structured briefing with:\n\n- Session context (venture, repo, branch)\n- Behavioral directives (enterprise rules)\n- Continuity (recent handoffs)\n- Alerts (P0 issues, active sessions)\n- Weekly plan status\n- Cadence briefing (overdue/due recurring activities)\n- Knowledge base and enterprise context\n\n> **Note:** The MCP tool reads the weekly plan but does not auto-create it. If the plan is missing, Step 4 below guides you through creating it.\n\n### Step 2: Display Context Confirmation\n\nPresent a clear context confirmation box:\n\n```\nVENTURE:  {venture_name} ({venture_code})\nREPO:     {repo}\nBRANCH:   {branch}\nSESSION:  {session_id}\n```\n\nState: \"You''re in the correct repository and on the {branch} branch.\"\n\n### Step 3: Handle P0 Issues\n\nIf the Alerts section shows P0 issues:\n\n1. Display prominently with warning icon\n2. Say: \"**There are P0 issues that need immediate attention.**\"\n3. List each issue\n\n### Step 4: Check Weekly Plan\n\nThe weekly plan is a **portfolio-level** artifact that lives in crane-console (vc). Only prompt for creation when the active venture is `vc`.\n\nBased on `weekly_plan` status in the response:\n\n- **valid**: Note the priority venture and proceed\n- **stale**: Warn user: \"Weekly plan is {age_days} days old. Consider updating.\"\n- **missing**:\n  - **If venture is `vc`**: Ask user:\n    - \"What venture is priority this week? (vc/dfg/sc/ke)\"\n    - \"Any specific issues to target? (optional)\"\n    - \"Any capacity constraints? (optional)\"\n\n    Then create `docs/planning/WEEKLY_PLAN.md`:\n\n    ```markdown\n    # Weekly Plan - Week of {DATE}\n\n    ## Priority Venture\n\n    {venture code}\n\n    ## Target Issues\n\n    {list or \"None specified\"}\n\n    ## Capacity Notes\n\n    {notes or \"Normal capacity\"}\n\n    ## Created\n\n    {ISO timestamp}\n    ```\n\n  - **If venture is NOT `vc`**: Skip silently. Do not prompt the user to create a weekly plan.\n\n### Step 5: STOP and Wait\n\n**CRITICAL**: Do NOT automatically start working.\n\nPresent a brief summary and ask: **\"What would you like to focus on?\"**\n\nIf user wants to see the full work queue, call `crane_status` MCP tool.\n\n## Wrong Repo Prevention\n\nAll GitHub issues created this session MUST target the repo shown in context confirmation. If you find yourself targeting a different repo, STOP and verify with the user.\n\n## Troubleshooting\n\nIf MCP tools aren''t available:\n\n1. Check `claude mcp list` shows crane connected\n2. Ensure started with: `crane vc`\n3. Try: `cd ~/dev/crane-console/packages/crane-mcp && npm run build && npm link`\n"},"lastSynced":"2026-03-07T13:08:40.886Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing structured session briefings and MCP tool integration.","zh":"非常适合需要结构化会议简报和MCP工具集成的开发代理。","ja":"開発エージェントが構造化されたセッションブリーフィングとMCPツールの統合を必要とする場合に最適です。","ko":"구조화된 세션 브리핑과 MCP 도구 통합이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan sesiones de briefing estructuradas e integración de herramientas MCP.","fr":"Parfait pour les agents de développement nécessitant des briefings de session structurés et une intégration d''outils MCP.","de":"Perfekt für Entwicklungssagenten, die strukturierte Sitzungsbriefings und MCP-Tool-Integration benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de briefings de sessão estruturados e integração da ferramenta MCP.","ru":"Идеально для агентов разработки, которым требуются структурированные брифинги сессий и интеграция инструмента MCP.","ar":"مثالي لعمليات تطوير الوكلاء الذين يحتاجون إلى إطارات جلسة منظمة وتكامل أداة MCP."},"recommendation":{"en":"Empowers agents to validate context, prioritize work, and ensure coding readiness using MCP tools, providing session context, behavioral directives, and continuity information via the crane_sod tool.","zh":"赋予代理人使用MCP工具验证上下文、优先处理工作并确保编码就绪性的能力，通过crane_sod工具提供会话上下文、行为指令和连续性信息。","ja":"MCPツールを使用してコンテキストを検証し、作業を優先し、コーディングの準備を確実に行うことができるようにエージェントをEmpowerし、crane_sodツールを介してセッションコンテキスト、動作指令、連続性情報を提供します。","ko":"MCP 도구를 사용하여 컨텍스트를 검증하고, 작업을 우선순위화하며, 코딩 준비를 확보하는 등의 작업을 수행할 수 있도록 에이전트를 Empower하고, crane_sod 도구를 통해 세션 컨텍스트, 행동 지시, 연속성 정보를 제공합니다.","es":"Habilita a los agentes a validar el contexto, priorizar el trabajo y garantizar la preparación para la codificación utilizando herramientas MCP, proporcionando contexto de sesión, directivas de comportamiento e información de continuidad a través de la herramienta crane_sod.","fr":"Permet aux agents de valider le contexte, de prioriser le travail et de garantir la préparation au codage en utilisant les outils MCP, en fournissant le contexte de session, les directives de comportement et les informations de continuité via l''outil crane_sod.","de":"Ermächtigt die Agenten, den Kontext zu validieren, die Arbeit zu priorisieren und die Kodierbereitschaft unter Verwendung von MCP-Tools sicherzustellen, indem sie Sitzungskontext, Verhaltensrichtlinien und Kontinuitätsinformationen über das Tool crane_sod bereitstellen.","pt":"Habilita os agentes a validar o contexto, priorizar o trabalho e garantir a prontidão de codificação usando as ferramentas MCP, fornecendo contexto de sessão, diretivas comportamentais e informações de continuidade via a ferramenta crane_sod.","ru":"Наделяет агентов возможностью проверить контекст, расставить приоритеты в работе и обеспечить готовность кодирования с помощью инструментов MCP, предоставляя контекст сессии, поведенческие директивы и информацию о непрерывности через инструмент crane_sod.","ar":"يمنح الوكلاء صلاحية التحقق من السياق وتحديد الأولويات في العمل وضمان جاهزية البرمجة باستخدام أدوات MCP، وتقديم سياق الجلسة والتوجيهات السلوكية ومعلومات الاستمرارية عبر أداة crane_sod."},"useCases":{"en":["Initializing sessions with validated context","Prioritizing work based on enterprise rules and alerts","Ensuring continuity with recent handoffs and weekly plan status"],"zh":["使用验证的上下文初始化会话","根据企业规则和警报优先处理工作","确保连续性，最近的交接和每周计划状态"],"ja":["検証されたコンテキストを使用してセッションを初期化する","企業ルールとアラートに基づいて作業を優先する","最近のハンドオフと週次計画の状態を使用して連続性を確保する"],"ko":["검증된 컨텍스트를 사용하여 세션을 초기화하는 것","企業 규칙과 경고를 기준으로 작업을 우선순위화하는 것","최근의 핸드오버와 주간 계획 상태를 사용하여 연속성을 보장하는 것"],"es":["Inicializar sesiones con contexto validado","Priorizar el trabajo según las reglas y alertas empresariales","Garantizar la continuidad con entregas recientes y estado del plan semanal"],"fr":["Initialiser des sessions avec un contexte validé","Prioriser le travail en fonction des règles et des alertes d''entreprise","Assurer la continuité avec les récentes passes et le statut du plan hebdomadaire"],"de":["Sitzungen mit validiertem Kontext initialisieren","Arbeit basierend auf Unternehmensregeln und -warnungen priorisieren","Kontinuität mit kürzlichen Übergaben und Wochenplanstatus sicherstellen"],"pt":["Inicializar sessões com contexto validado","Priorizar trabalho com base em regras e alertas da empresa","Garantir continuidade com entregas recentes e status do plano semanal"],"ru":["Инициализировать сессии с проверенным контекстом","Приоритизировать работу на основе правил и уведомлений предприятия","Обеспечить непрерывность с недавними передачами и статусом плана на неделю"],"ar":["تENCHMARK الجلسات مع سياق التحقق","تحديد الأولويات في العمل بناءً على قواعد وتنبيهات المؤسسة","ضمان الاستمرارية مع عمليات التسليم الأخيرة وحالة الخطة الأسبوعية"]},"limitations":{"en":["Requires access to MCP tools and crane_sod functionality","Dependent on session context and venture-specific data"],"zh":["需要访问MCP工具和crane_sod功能","依赖于会话上下文和项目特定数据"],"ja":["MCPツールとcrane_sod機能へのアクセスが必要","セッションコンテキストとベンチャー特有のデータに依存する"],"ko":["MCP 도구와 crane_sod 기능에 대한 액세스가 필요함","세션 컨텍스트와 벤처 특유의 데이터에 의존함"],"es":["Requiere acceso a herramientas MCP y funcionalidad crane_sod","Dependiente del contexto de sesión y datos específicos de la empresa"],"fr":["Nécessite un accès aux outils MCP et à la fonctionnalité crane_sod","Dépendant du contexte de session et des données spécifiques à l''entreprise"],"de":["Erfordert Zugriff auf MCP-Tools und crane_sod-Funktionalität","Abhängig vom Sitzungskontext und unternehmensspezifischen Daten"],"pt":["Requer acesso às ferramentas MCP e funcionalidade crane_sod","Dependente do contexto da sessão e dados específicos da empresa"],"ru":["Требует доступа к инструментам MCP и функциональности crane_sod","Зависит от контекста сессии и данных, специфичных для предприятия"],"ar":["يتطلب الوصول إلى أدوات MCP ووظيفة crane_sod","يعتمد على سياق الجلسة والبيانات المحددة للمشروع"]},"version":4},"contentHash":"e9ed1283becd540049095836354ffe51f4ab84f851e3c77e230b3361f8fbcc07","qualityScore":36}');
