INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('venturecrane/dc-console/sod', 'sod', 'venturecrane', 'dc-console', 'community', 'sod venturecrane dc-console community The sod skill prepares your session using MCP tools to validate context and show work priorities. It benefits developers by ensuring they''re ready to code with a structured briefing. SOD 是一个会话启动工具，使用 MCP 工具初始化会话，提供结构化的简报和会话上下文 SOD はセッションを開始するツールで、MCP ツールを使用してセッションを初期化し、構造化されたブリーフィングとセッションコンテキストを提供します SOD는 세션을 시작하는 도구로, MCP 도구를 사용하여 세션을 초기화하고 구조화된 브리핑과 세션 컨텍스트를 제공합니다 Sod es una consola para dc venture que utiliza MCP para validar contexto y mostrar prioridades de trabajo. Sod est une console pour dc venture qui utilise MCP pour valider le contexte et afficher les priorités de travail. Sod ist eine Konsole für dc venture, die MCP verwendet, um den Kontext zu überprüfen und Arbeitsschwerpunkte anzuzeigen. O Sod é uma ferramenta de console para inicializar sessões com MCP, fornecendo briefing estruturado e diretrizes comportamentais Sod - это консольная утилита для запуска сессий с помощью ИИ Агентов MCP, обеспечивающая структурированный брифинг и поведенческие директивы Sod هو أداة واجهة 命令ية لتشغيل الجلسات باستخدام أدوات MCP، وتوفر إحاطة منظمة وتوجيهات سلوكية how to use sod sod setup guide sod alternative sod vs crane what is sod sod install mcp tools crane_sod dc venture SOD 会话启动 MCP 工具 会话上下文 AIエージェント 会话启动指南 技术细节 Initializes session using crane_sod MCP tool Provides structured briefing with session context, venture, repo, and branch Returns behavioral directives, including enterprise rules and continuity Displays alerts, including P0 issues and active sessions Shows weekly plan status and cadence briefing with overdue items sod is a console for dc venture that initializes a session using the crane_sod MCP tool to provide a structured briefing with session context and behavioral directives');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('venturecrane/dfg-console/sod', 'community', 'venturecrane', 'dfg-console', 'venturecrane/dfg-console', 'sod', 0, 0, 36, '2026-03-03T02:33:04Z', '2026-03-07T13:09:05.305Z', 'e9ed1283becd540049095836354ffe51f4ab84f851e3c77e230b3361f8fbcc07', '{"id":"venturecrane/dfg-console/sod","name":"sod","description":{"en":"The sod skill prepares your session using MCP tools, validating context and showing work priorities. It''s designed for developers to ensure they''re ready to code.","zh":"SOD是一种AI开发工具，用于初始化会话和提供结构化简报。它返回会话上下文、行为指令和连续性等信息","ja":"SODはAI開発ツールであり、セッションの初期化と構造化ブリーフィングの提供に使用されます。セッションコンテキスト、行動指令、連続性などの情報を返します","ko":"SOD는 AI 개발 도구로, 세션 초기화와 구조化 브리핑을 제공합니다. 세션 컨텍스트, 행동 지침, 연속성 등 정보를 반환","es":"sod es una herramienta que prepara tu sesión de codificación con MCP, validando el contexto y mostrando prioridades de trabajo.","fr":"sod est un outil qui prépare votre session de codage avec les outils MCP, en validant le contexte et en affichant les priorités de travail.","de":"sod ist ein Tool, das Ihre Codiersitzung mit MCP-Tools vorbereitet, indem es den Kontext überprüft und die Arbeitsprioritäten anzeigt.","pt":"O sod é uma ferramenta que inicializa a sessão usando MCP para validar o contexto e garantir que você esteja pronto para codificar","ru":"ИИ Агент sod - это инструмент, который запускает сессию с помощью MCP для проверки контекста и обеспечения того, что вы готовы к кодированию","ar":"sod هو أداة تشغيل الجلسة باستخدام أدوات MCP للتحقق من السياق وضمان جاهزيتك للتشفير"},"seo":{"title":{"en":"sod: DFG Operator Console Setup Guide | AI Agent Skill","zh":"SOD Setup Guide - AIエージェント开发工具","ja":"SOD Setup Guide - AIエージェント開発ツール","ko":"SOD 설정 가이드 - AI 에이전트 개발 도구","es":"Guía de configuración de sod - Inicio de día con MCP","fr":"Guide de setup sod - Début de journée avec les outils MCP","de":"Einrichtungsleitfaden für sod - Start des Tages mit MCP-T...","pt":"Guia de Configuração do sod: Inicialização de Sessão com MCP","ru":"Настройка ИИ Агента sod: Руководство по запуску сессии с MCP","ar":"دليل إعداد sod: تشغيل الجلسة باستخدام أدوات MCP"},"description":{"en":"Unlock efficient coding sessions with sod, the DFG Operator Console. Learn how to initialize sessions, validate context, and prioritize work with our expert ...","zh":"了解SOD的技术细节和使用方法，包括会话上下文、行为指令和连续性","ja":"SODの技術的詳細と使用方法について学びます。セッションコンテキスト、行動指令、連続性など","ko":"SOD의 기술적 세부 정보와 사용 방법을 알아보세요. 세션 컨텍스트, 행동 지침, 연속성 등","es":"Aprende a configurar sod para iniciar tu sesión de codificación con MCP. Obtén un resumen estructurado de tu contexto, prioridades y alertas.","fr":"Découvrez comment configurer sod pour lancer votre session de codage avec les outils MCP. Obtenez un briefing structuré de votre contexte, priorités et alertes.","de":"Erfahren Sie, wie Sie sod einrichten, um Ihre Codiersitzung mit MCP-Tools zu starten. Erhalten Sie eine strukturierte Zusammenfassung Ihres Kontexts, Priorit...","pt":"Aprenda a configurar o sod para inicializar suas sessões de codificação com ferramentas MCP e obtenha uma visão geral clara do contexto da sessão","ru":"Узнайте, как настроить ИИ Агент sod для запуска сессий кодирования с помощью инструментов MCP и получить четкое представление о контексте сессии","ar":"تعلم كيفية cấufigure sod لتشغيل جلسات التشفير باستخدام أدوات MCP و الحصول على نظرة عامة واضحة على سياق الجلسة"},"definition":{"en":"sod is a command-line tool that initializes coding sessions with MCP tools, providing a structured briefing on session context, behavioral directives, and continuity.","zh":"SOD是AI开发工具中的一个命令，用于启动会话和提供相关信息","ja":"SODはAI開発ツールにおけるコマンドであり、セッションの起動と関連情報の提供に使用されます","ko":"SOD는 AI 개발 도구에서 세션을 시작하고 관련 정보를 제공하는 명령어","es":"sod es un comando que inicializa la sesión de codificación con MCP, proporcionando un resumen del contexto y prioridades.","fr":"sod est une commande qui initialise la session de codage avec les outils MCP, fournissant un résumé du contexte et des priorités.","de":"sod ist ein Befehl, der die Codiersitzung mit MCP-Tools initialisiert und eine Zusammenfassung des Kontexts und der Prioritäten bereitstellt.","pt":"sod é uma ferramenta de inicialização de sessão que utiliza MCP para validar contexto e fornecer informações relevantes","ru":"ИИ Агент sod - это инструмент запуска сессии, который использует MCP для проверки контекста и предоставления релевантной информации","ar":"sod هو أداة تشغيل الجلسة التي تستخدم أدوات MCP للتحقق من السياق وتقديم المعلومات ذات الصلة"},"features":{"en":["Initializes sessions using the crane_sod MCP tool","Provides a structured briefing with session context, venture, repo, and branch information","Includes behavioral directives, such as enterprise rules and continuity","Displays alerts for P0 issues and active sessions","Shows weekly plan status and cadence briefing for overdue tasks"],"zh":["会话上下文验证","行为指令提供","连续性和最近交接信息","警报和P0问题通知","每周计划状态和节奏简报"],"ja":["セッションコンテキストの検証","行動指令の提供","連続性と最近のハンドオーバー情報","アラートとP0問題の通知","毎週のプラン状況とケイデンスブリーフィング"],"ko":["세션 컨텍스트 검증","행동 지침 제공","연속성과 최근 핸드오버 정보","알림과 P0 문제 통지","주간 계획 상태와 케이던스 브리핑"],"es":["Inicialización de sesión con MCP","Validación de contexto de sesión","Prioridades de trabajo y alertas","Resumen estructurado de la sesión","Integración con herramientas de codificación"],"fr":["Initialisation de la session avec les outils MCP","Validation du contexte de la session","Priorités de travail et alertes","Résumé structuré de la session","Intégration avec les outils de codage"],"de":["Initialisierung der Sitzung mit MCP-Tools","Überprüfung des Sitzungskontexts","Arbeitsprioritäten und Warnungen","Strukturierte Zusammenfassung der Sitzung","Integration mit Codierungstools"],"pt":["Inicialização de sessão com MCP","Validação de contexto de sessão","Fornecimento de informações de prioridade de trabalho","Exibição de alertas e problemas ativos","Plano semanal e briefing de cadência","Integração com ferramentas de continuidade"],"ru":["Запуск сессии с помощью MCP","Проверка контекста сессии","Предоставление информации о приоритете работы","Отображение оповещений и активных проблем","Недельный план и брифинг по каденции","Интеграция с инструментами непрерывности"],"ar":["تشغيل الجلسة باستخدام أدوات MCP","التحقق من سياق الجلسة","تقديم معلومات عن أولوية العمل","عرض التنبيهات والمشاكل النشطة","الخطة الأسبوعية وتقارير الكادنس","التكامل مع أدوات الاستمرارية"]},"keywords":{"en":["how to use sod","sod setup guide","DFG Operator Console tutorial","MCP tool integration","sod alternative","sod vs crane","sod install","what is sod","sod benefits for developers"],"zh":["AI开发工具","SOD命令","会话上下文","行为指令","连续性","结构化简报","AIエージェント开发"],"ja":["AI開発ツール","SODコマンド","セッションコンテキスト","行動指令","連続性","構造化ブリーフィング","AIエージェント開発"],"ko":["AI 개발 도구","SOD 명령어","세션 컨텍스트","행동 지침","연속성","구조화 브리핑","AI 에이전트 개발"],"es":["sod MCP","inicio de día","codificación","herramientas de desarrollo","MCP tools","configuración de sod","sesión de codificación","prioridades de trabajo"],"fr":["sod MCP","début de journée","codage","outils de développement","MCP outils","configuration de sod","session de codage","priorités de travail"],"de":["sod MCP","Start des Tages","Codierung","Entwicklungstools","MCP-Tools","Einrichtung von sod","Codiersitzung","Arbeitsprioritäten"],"pt":["sod","MCP","inicialização de sessão","validação de contexto","prioridade de trabalho","ferramentas de codificação","desenvolvimento de software","productividade de desenvolvedor"],"ru":["ИИ Агент sod","MCP","запуск сессии","проверка контекста","приоритет работы","инструменты кодирования","разработка программного обеспечения","продуктивность разработчика"],"ar":["sod","MCP","تشغيل الجلسة","التحقق من السياق","أولوية العمل","أدوات التشفير","تطوير البرمجيات","إنتاجية المطور"]}},"owner":"venturecrane","repo":"dfg-console","repoPath":"venturecrane/dfg-console","stars":0,"forks":0,"updatedAt":"2026-03-03T02:33:04Z","topics":[],"category":"community","skillMd":{"name":"sod","description":"Start of Day","bodyPreview":"# /sod - Start of Day\n\nThis command prepares your session using MCP tools to validate context, show work priorities, and ensure you''re ready to code.\n\n## Execution\n\n### Step 1: Start Session\n\nCall the `crane_sod` MCP tool to initialize the session.\n\nThe tool returns a structured briefing with:\n\n- Session context (venture, repo, branch)\n- Behavioral directives (enterprise rules)\n- Continuity (recent handoffs)\n- Alerts (P0 issues, active sessions)\n- Weekly plan status\n- Cadence briefing (overdue/d","body":"# /sod - Start of Day\n\nThis command prepares your session using MCP tools to validate context, show work priorities, and ensure you''re ready to code.\n\n## Execution\n\n### Step 1: Start Session\n\nCall the `crane_sod` MCP tool to initialize the session.\n\nThe tool returns a structured briefing with:\n\n- Session context (venture, repo, branch)\n- Behavioral directives (enterprise rules)\n- Continuity (recent handoffs)\n- Alerts (P0 issues, active sessions)\n- Weekly plan status\n- Cadence briefing (overdue/due recurring activities)\n- Knowledge base and enterprise context\n\n> **Note:** The MCP tool reads the weekly plan but does not auto-create it. If the plan is missing, Step 4 below guides you through creating it.\n\n### Step 2: Display Context Confirmation\n\nPresent a clear context confirmation box:\n\n```\nVENTURE:  {venture_name} ({venture_code})\nREPO:     {repo}\nBRANCH:   {branch}\nSESSION:  {session_id}\n```\n\nState: \"You''re in the correct repository and on the {branch} branch.\"\n\n### Step 3: Handle P0 Issues\n\nIf the Alerts section shows P0 issues:\n\n1. Display prominently with warning icon\n2. Say: \"**There are P0 issues that need immediate attention.**\"\n3. List each issue\n\n### Step 4: Check Weekly Plan\n\nThe weekly plan is a **portfolio-level** artifact that lives in crane-console (vc). Only prompt for creation when the active venture is `vc`.\n\nBased on `weekly_plan` status in the response:\n\n- **valid**: Note the priority venture and proceed\n- **stale**: Warn user: \"Weekly plan is {age_days} days old. Consider updating.\"\n- **missing**:\n  - **If venture is `vc`**: Ask user:\n    - \"What venture is priority this week? (vc/dfg/sc/ke)\"\n    - \"Any specific issues to target? (optional)\"\n    - \"Any capacity constraints? (optional)\"\n\n    Then create `docs/planning/WEEKLY_PLAN.md`:\n\n    ```markdown\n    # Weekly Plan - Week of {DATE}\n\n    ## Priority Venture\n\n    {venture code}\n\n    ## Target Issues\n\n    {list or \"None specified\"}\n\n    ## Capacity Notes\n\n    {notes or \"Normal capacity\"}\n\n    ## Created\n\n    {ISO timestamp}\n    ```\n\n  - **If venture is NOT `vc`**: Skip silently. Do not prompt the user to create a weekly plan.\n\n### Step 5: STOP and Wait\n\n**CRITICAL**: Do NOT automatically start working.\n\nPresent a brief summary and ask: **\"What would you like to focus on?\"**\n\nIf user wants to see the full work queue, call `crane_status` MCP tool.\n\n## Wrong Repo Prevention\n\nAll GitHub issues created this session MUST target the repo shown in context confirmation. If you find yourself targeting a different repo, STOP and verify with the user.\n\n## Troubleshooting\n\nIf MCP tools aren''t available:\n\n1. Check `claude mcp list` shows crane connected\n2. Ensure started with: `crane vc`\n3. Try: `cd ~/dev/crane-console/packages/crane-mcp && npm run build && npm link`\n"},"lastSynced":"2026-03-07T13:09:05.305Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing to validate context and prioritize tasks using MCP tools.","zh":"非常适合需要使用MCP工具验证上下文并根据优先级确定任务的开发代理。","ja":"MCPツールを使用してコンテキストを検証し、タスクを優先順位付けする必要がある開発エージェントに最適です。","ko":"MCP 도구를 사용하여 컨텍스트를 검증하고 작업을 우선 순위화해야 하는 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan validar el contexto y priorizar tareas utilizando herramientas MCP.","fr":"Parfait pour les agents de développement ayant besoin de valider le contexte et de prioriser les tâches à l''aide d''outils MCP.","de":"Perfekt für Entwicklungssagenten, die Kontext validieren und Aufgaben mit MCP-Tools priorisieren müssen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam validar contexto e priorizar tarefas usando ferramentas MCP.","ru":"Идеально для агентов разработки, которым необходимо проверить контекст и расставить приоритеты задач с помощью инструментов MCP.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى التحقق من السياق وتحديد أولويات المهام باستخدام أدوات MCP."},"recommendation":{"en":"Empowers agents to initialize sessions with structured briefings, including session context, behavioral directives, and continuity information, using the crane_sod MCP tool and handling data formats like venture, repo, and branch details.","zh":"赋予代理初始化会话的能力，使用crane_sod MCP工具进行结构化的简报，包括会话上下文、行为指令和连续性信息，并处理venture、repo和branch详细信息等数据格式。","ja":"crane_sod MCPツールを使用して、セッションコンテキスト、行動指令、連続性情報を含む構造化されたブリーフィングを使用してセッションを初期化するエージェントの能力を提供し、venture、repo、branchの詳細などのデータ形式を処理します。","ko":"crane_sod MCP 도구를 사용하여 세션 컨텍스트, 행동 지침 및 연속성 정보를 포함하는 구조화된 브리핑을 사용하여 세션을 초기화하는 에이전트의 능력을 제공하며, venture, repo 및 branch 세부 정보などの 데이터 형식을 처리합니다.","es":"Habilita a los agentes a inicializar sesiones con breves estructurados, incluyendo contexto de sesión, directivas de comportamiento e información de continuidad, utilizando la herramienta MCP crane_sod y manejando formatos de datos como detalles de empresa, repositorio y rama.","fr":"Permet aux agents d''initialiser des sessions avec des briefings structurés, incluant le contexte de session, les directives de comportement et les informations de continuité, en utilisant l''outil MCP crane_sod et en gérant des formats de données tels que les détails de l''entreprise, du référentiel et de la branche.","de":"Ermächtigt Agenten, Sitzungen mit strukturierten Briefings zu initialisieren, einschließlich Sitzungskontext, Verhaltensrichtlinien und Kontinuitätsinformationen, unter Verwendung des MCP-Tools crane_sod und der Verarbeitung von Datenformaten wie Unternehmens-, Repository- und Branchendetails.","pt":"Habilita os agentes a inicializar sessões com briefings estruturados, incluindo contexto de sessão, diretivas comportamentais e informações de continuidade, usando a ferramenta MCP crane_sod e lidando com formatos de dados como detalhes de venture, repo e branch.","ru":"Наделяет агентов возможностью инициализировать сессии с структурированными брифингами, включая контекст сессии, поведенческие директивы и информацию о непрерывности, используя инструмент MCP crane_sod и обрабатывая форматы данных, такие как подробности venture, repo и branch.","ar":"يمنح الوكلاء khảية 初始化 الجلسات مع إحاطات منظمّة، بما في ذلك سياق الجلسة والتوجيهات السلوكية ومعلومات الاستمرارية، باستخدام أداة MCP crane_sod ومعالجة تنسيقات البيانات مثل تفاصيل المشروع والمتجر والفرع."},"useCases":{"en":["Initializing coding sessions with validated context","Prioritizing tasks based on work priorities and alerts","Retrieving weekly plan status and cadence briefings"],"zh":["使用验证的上下文初始化编码会话","根据工作优先级和警报优先级确定任务","检索每周计划状态和节奏简报"],"ja":["検証されたコンテキストを使用してコード化セッションを初期化する","作業の優先順位とアラートに基づいてタスクを優先順位付けする","週次計画のステータスとリズムのブリーフィングを取得する"],"ko":["검증된 컨텍스트를 사용하여 코딩 세션을 초기화하는 것","작업 우선 순위 및 경고를 기준으로 작업을 우선 순위화하는 것","주간 계획 상태 및 리듬 브리핑을 검색하는 것"],"es":["Inicializar sesiones de codificación con contexto validado","Priorizar tareas en función de las prioridades de trabajo y alertas","Recuperar el estado y la cadencia del plan semanal"],"fr":["Initialiser des sessions de codage avec un contexte validé","Donner la priorité aux tâches en fonction des priorités de travail et des alertes","Récupérer le statut et la cadence du plan hebdomadaire"],"de":["Initialisieren von Codierungssitzungen mit validiertem Kontext","Priorisieren von Aufgaben basierend auf Arbeitsprioritäten und Warnungen","Abrufen des Status und der Kadenz der wöchentlichen Pläne"],"pt":["Inicializar sessões de codificação com contexto validado","Priorizar tarefas com base em prioridades de trabalho e alertas","Recuperar status do plano semanal e briefings de cadência"],"ru":["Инициализировать сессии кодирования с проверенным контекстом","Приоритизировать задачи на основе приоритетов работы и оповещений","Получить статус плана на неделю и брифинги по тактике"],"ar":["تهيئة جلسات البرمجة مع سياق محقق","تحديد أولويات المهام بناءً على أولويات العمل والتنبيهات","استرجاع حالة الخطة الأسبوعية وإحاطات الإيقاع"]},"limitations":{"en":["Requires access to MCP tools","Specific to development environments with crane_sod tool integration"],"zh":["需要访问MCP工具","特定于具有crane_sod工具集成的开发环境"],"ja":["MCPツールへのアクセスが必要","crane_sodツールの統合がある開発環境に特有"],"ko":["MCP 도구에 대한 액세스가 필요함","crane_sod 도구 통합이 있는 개발 환경에 특정"],"es":["Requiere acceso a herramientas MCP","Específico para entornos de desarrollo con integración de la herramienta crane_sod"],"fr":["Nécessite un accès aux outils MCP","Spécifique aux environnements de développement avec une intégration de l''outil crane_sod"],"de":["Benötigt Zugriff auf MCP-Tools","Spezifisch für Entwicklungsumgebungen mit crane_sod-Tool-Integration"],"pt":["Requer acesso às ferramentas MCP","Específico para ambientes de desenvolvimento com integração da ferramenta crane_sod"],"ru":["Требует доступа к инструментам MCP","Спецефичен для сред разработки с интеграцией инструмента crane_sod"],"ar":["يتطلب الوصول إلى أدوات MCP","محدد للبيئات التطويرية مع دمج أداة crane_sod"]},"version":4},"contentHash":"e9ed1283becd540049095836354ffe51f4ab84f851e3c77e230b3361f8fbcc07","qualityScore":36}');
