INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('venturecrane/dfg-console/sod', 'sod', 'venturecrane', 'dfg-console', 'community', 'sod venturecrane dfg-console community The sod skill prepares your session using MCP tools, validating context and showing work priorities. It''s designed for developers to ensure they''re ready to code. SOD是一种AI开发工具，用于初始化会话和提供结构化简报。它返回会话上下文、行为指令和连续性等信息 SODはAI開発ツールであり、セッションの初期化と構造化ブリーフィングの提供に使用されます。セッションコンテキスト、行動指令、連続性などの情報を返します SOD는 AI 개발 도구로, 세션 초기화와 구조化 브리핑을 제공합니다. 세션 컨텍스트, 행동 지침, 연속성 등 정보를 반환 sod es una herramienta que prepara tu sesión de codificación con MCP, validando el contexto y mostrando prioridades de trabajo. sod est un outil qui prépare votre session de codage avec les outils MCP, en validant le contexte et en affichant les priorités de travail. sod ist ein Tool, das Ihre Codiersitzung mit MCP-Tools vorbereitet, indem es den Kontext überprüft und die Arbeitsprioritäten anzeigt. O sod é uma ferramenta que inicializa a sessão usando MCP para validar o contexto e garantir que você esteja pronto para codificar ИИ Агент sod - это инструмент, который запускает сессию с помощью MCP для проверки контекста и обеспечения того, что вы готовы к кодированию sod هو أداة تشغيل الجلسة باستخدام أدوات MCP للتحقق من السياق وضمان جاهزيتك للتشفير how to use sod sod setup guide DFG Operator Console tutorial MCP tool integration sod alternative sod vs crane sod install what is sod sod benefits for developers AI开发工具 SOD命令 会话上下文 行为指令 连续性 结构化简报 AIエージェント开发 Initializes sessions using the crane_sod MCP tool Provides a structured briefing with session context, venture, repo, and branch information Includes behavioral directives, such as enterprise rules and continuity Displays alerts for P0 issues and active sessions Shows weekly plan status and cadence briefing for overdue tasks sod is a command-line tool that initializes coding sessions with MCP tools, providing a structured briefing on session context, behavioral directives, and continuity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kissMyApps-tlm/kissmychat/hotkey', 'community', 'kissMyApps-tlm', 'kissmychat', 'kissMyApps-tlm/kissmychat', 'hotkey', 0, 0, 36, '2026-03-06T12:59:22.217Z', '2026-03-06T14:00:47.487Z', '06629806123ba243a0222e25e96ab402889832694e529498aee4543f613778bd', '{"id":"kissMyApps-tlm/kissmychat/hotkey","name":"hotkey","description":{"en":"The hotkey skill allows developers to add new keyboard shortcuts by updating the HotkeyEnum constant and registering default hotkeys. This benefits AI agent developers who need to customize keyboard interactions.","zh":"本文介绍如何在代码中添加自定义热键，包括更新热键常量和注册默认热键","ja":"この記事では、コードにカスタムホットキーを追加する方法を説明します。ホットキーコンスタントの更新とデフォルトホットキーの登録を含みます","ko":"이 문서는 코드에서 사용자 정의 핫키를 추가하는 방법을 설명합니다. 핫키 상수 업데이트 및 기본 핫키 등록 포함","es":"El skill hotkey permite agregar atajos de teclado personalizados con TypeScript. Actualiza la constante HotkeyEnum y registra la tecla por defecto.","fr":"Le skill hotkey permet d''ajouter des raccourcis clavier personnalisés avec TypeScript. Mettre à jour la constante HotkeyEnum et enregistrer la touche par défaut.","de":"Der Skill hotkey ermöglicht die Hinzufügung benutzerdefinierter Tastenkombinationen mit TypeScript. Aktualisieren Sie die Konstante HotkeyEnum und registrieren Sie die Standardtaste.","pt":"O hotkey permite adicionar atalhos de teclado personalizados ao seu aplicativo. Atualize as constantes e registre os atalhos padrão para melhorar a experiência do usuário.","ru":"Hotkey позволяет добавлять пользовательские горячие клавиши в ваше приложение. Обновите константы и зарегистрируйте стандартные горячие клавиши, чтобы улучшить опыт пользователя ИИ Агенты.","ar":"الهوتكاي يسمح بإضافة اختصارات لوحة مفاتيح مخصصة إلى تطبيقك. قم بتحديث الثوابت وتسجيل الاختصارات الافتراضية لتحسين تجربة المستخدم"},"seo":{"title":{"en":"hotkey: Setup Guide for AI Agents | AI Agent Skill","zh":"热键设置指南 - 添加自定义快捷键","ja":"ホットキーの設定方法 - カスタムショートカットの追加","ko":"핫키 설정 가이드 - 사용자 정의 단축키 추가","es":"Guía de Configuración de Atajos de Teclado con Herramient...","fr":"Guide d''Installation de Raccourcis Clavier pour Outils d''IA","de":"Einrichtungsanleitung für Tastenkombinationen mit KI-Tools","pt":"Guia de Configuração de Atalhos de Teclado - Hotkey","ru":"Настройка горячих клавиш - Руководство по Hotkey ИИ Агенты","ar":"دليل إعداد اختصارات لوحة المفاتيح - هوتكاي"},"description":{"en":"Discover how to register default hotkeys and update hotkey constants with our hotkey setup guide. Learn more about hotkey implementation now!","zh":"学习如何在代码中添加自定义热键，包括更新热键常量和注册默认热键","ja":"コードにカスタムホットキーを追加する方法を学びます。ホットキーコンスタントの更新とデフォルトホットキーの登録を含みます","ko":"코드에서 사용자 정의 핫키를 추가하는 방법을 배우세요. 핫키 상수 更新 및 기본 핫키 등록 포함","es":"Aprende a agregar atajos de teclado personalizados con TypeScript y registro de teclas en Herramientas de AI","fr":"Découvrez comment ajouter des raccourcis clavier personnalisés avec TypeScript et l''enregistrement de touches dans les Outils d''IA","de":"Erfahren Sie, wie Sie benutzerdefinierte Tastenkombinationen mit TypeScript und Tastenregistrierung in KI-Tools hinzufügen","pt":"Aprenda a adicionar novos atalhos de teclado ao seu aplicativo com o guia de hotkey. Descubra como atualizar constantes e registrar atalhos padrão.","ru":"Узнайте, как добавить новые горячие клавиши в ваше приложение с помощью руководства по hotkey. Откройте для себя, как обновить константы и зарегистрировать с...","ar":"تعلم كيفية إضافة اختصارات لوحة مفاتيح جديدة إلى تطبيقك مع دليل الهوتكاي. اكتشف كيفية تحديث الثوابت وتسجيل الاختصارات الافتراضية"},"definition":{"en":"hotkey is a feature that enables developers to assign custom keyboard shortcuts to specific actions in AI agents, using constants and registrations defined in TypeScript files.","zh":"热键是指在代码中定义的快捷键","ja":"ホットキーとは、コードで定義されたショートカットキーのこと","ko":"핫키는 코드에서 정의된 단축키를 말합니다","es":"Un atajo de teclado es una combinación de teclas que realizan una acción específica en una aplicación de AI","fr":"Un raccourci clavier est une combinaison de touches qui effectuent une action spécifique dans une application d''IA","de":"Ein Tastenkombination ist eine Kombination von Tasten, die eine bestimmte Aktion in einer KI-Anwendung ausführen","pt":"O hotkey é uma funcionalidade que permite adicionar atalhos de teclado personalizados ao seu aplicativo.","ru":"Hotkey - это функция, которая позволяет добавлять пользовательские горячие клавиши в ваше приложение ИИ Агенты.","ar":"الهوتكاي هو ميزة تسمح بإضافة اختصارات لوحة مفاتيح مخصصة إلى تطبيقك"},"features":{"en":["Updates HotkeyEnum constant in src/types/hotkey.ts to add new hotkeys","Registers default hotkeys using the HOTKEYS_REGISTRATION array in src/const/hotkeys.ts","Utilizes the combineKeys function from @lobehub/ui to define hotkey combinations","Supports hotkey groups, such as HotkeyGroupEnum.Conversation, for organized registration","Exports HotkeyRegistration type for custom hotkey definitions","Integrates with TypeScript for typed hotkey constants and registrations"],"zh":["更新热键常量","注册默认热键","使用 TypeScript 编写代码","结合 KeyMapEnum 和 combineKeys 功能","支持自定义热键添加","适用于对话和其他场景"],"ja":["ホットキーコンスタントの更新","デフォルトホットキーの登録","TypeScript を使用したコード作成","KeyMapEnum と combineKeys 機能の組み合わせ","カスタムホットキーの追加サポート","会話や他のシナリオでの利用"],"ko":["핫키 상수 업데이트","기본 핫키 등록","TypeScript를 사용한 코드 작성","KeyMapEnum과 combineKeys 기능의 조합","사용자 정의 핫키 추가 지원","대화와 다른 시나리오에서 사용"],"es":["Actualización de la constante HotkeyEnum en TypeScript","Registro de teclas por defecto con combineKeys","Integración con la biblioteca @lobehub/ui","Compatibilidad con tipos de teclas personalizados","Soporte para registro de teclas en diferentes grupos de conversación"],"fr":["Mise à jour de la constante HotkeyEnum en TypeScript","Enregistrement de touches par défaut avec combineKeys","Intégration avec la bibliothèque @lobehub/ui","Compatibilité avec des types de touches personnalisés","Support pour l''enregistrement de touches dans différents groupes de conversation"],"de":["Aktualisierung der Konstante HotkeyEnum in TypeScript","Registrierung von Standardtasten mit combineKeys","Integration mit der Bibliothek @lobehub/ui","Kompatibilität mit benutzerdefinierten Tastentypen","Unterstützung für die Registrierung von Tasten in verschiedenen Konversationsgruppen"],"pt":["Atualização de constantes de atalho de teclado","Registro de atalhos padrão","Integração com o tipo HotkeyEnum","Utilização da biblioteca @lobehub/ui","Combinação de teclas com a função combineKeys","Definição de grupos de atalhos de teclado"],"ru":["Обновление констант горячих клавиш","Регистрация стандартных горячих клавиш","Интеграция с типом HotkeyEnum ИИ Агенты","Использование библиотеки @lobehub/ui","Комбинация клавиш с функцией combineKeys","Определение групп горячих клавиш"],"ar":["تحديث ثوابت اختصارات لوحة المفاتيح","تسجيل اختصارات افتراضية","التكامل مع نوع الهوتكاي إينوم","استخدام المكتبة @lobehub/ui","مجموعة مفاتيح مع دالة combineKeys","تحديد مجموعات اختصارات لوحة المفاتيح"]},"keywords":{"en":["how to use hotkey in AI agents","hotkey setup guide","hotkey vs keyboard shortcut","hotkey installation for AI agents","what is hotkey in AI development","hotkey alternative for custom keyboard interactions","hotkey implementation in TypeScript","hotkey registration process","hotkey constant update"],"zh":["热键设置","添加自定义热键","TypeScript","KeyMapEnum","combineKeys","代码优化","热键注册","AIエージェント","热键常量更新"],"ja":["ホットキーの設定","カスタムホットキーの追加","TypeScript","KeyMapEnum","combineKeys","コード最適化","ホットキーの登録","AIエージェント","ホットキーコンスタントの更新"],"ko":["핫키 설정","사용자 정의 핫키 추가","TypeScript","KeyMapEnum","combineKeys","코드 최적화","핫키 등록","AI 에이전트","핫키 상수 업데이트"],"es":["atajos de teclado","TypeScript","registro de teclas","Herramientas de AI","personalización de teclas","combinação de teclas","HotkeyEnum","combineKeys","biblioteca @lobehub/ui"],"fr":["raccourcis clavier","TypeScript","enregistrement de touches","Outils d''IA","personnalisation de touches","combinaison de touches","HotkeyEnum","combineKeys","bibliothèque @lobehub/ui"],"de":["Tastenkombinationen","TypeScript","Tastenregistrierung","KI-Tools","Anpassung von Tasten","Kombination von Tasten","HotkeyEnum","combineKeys","Bibliothek @lobehub/ui"],"pt":["hotkey","atalhos de teclado","guias de configuração","desenvolvimento de aplicativos","typescript","react","bibliotecas de ui","combinação de teclas","grupos de atalhos de teclado"],"ru":["hotkey","горячие клавиши","руководства по настройке","разработка приложений ИИ Агенты","typescript","react","библиотеки ui","комбинация клавиш","группы горячих клавиш"],"ar":["هوتكاي","اختصارات لوحة المفاتيح","دلائل الإعداد","تطوير التطبيقات","typescript","react","مكتبات واجهة المستخدم","مجموعة مفاتيح","مجموعات اختصارات لوحة المفاتيح"]}},"owner":"kissMyApps-tlm","repo":"kissmychat","repoPath":"kissMyApps-tlm/kissmychat","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.217Z","topics":[],"category":"community","skillMd":{"name":"hotkey","description":"Guide for adding keyboard shortcuts. Use when implementing new hotkeys, registering shortcuts, or working with keyboard interactions. Triggers on hotkey implementation or keyboard shortcut tasks.","bodyPreview":"# Adding Keyboard Shortcuts Guide\n\n## Steps to Add a New Hotkey\n\n### 1. Update Hotkey Constant\n\nIn `src/types/hotkey.ts`:\n\n```typescript\nexport const HotkeyEnum = {\n  // existing...\n  ClearChat: ''clearChat'', // Add new\n} as const;\n```\n\n### 2. Register Default Hotkey\n\nIn `src/const/hotkeys.ts`:\n\n```typescript\nimport { KeyMapEnum as Key, combineKeys } from ''@lobehub/ui'';\n\nexport const HOTKEYS_REGISTRATION: HotkeyRegistration = [\n  {\n    group: HotkeyGroupEnum.Conversation,\n    id: HotkeyEnum.Clear","body":"# Adding Keyboard Shortcuts Guide\n\n## Steps to Add a New Hotkey\n\n### 1. Update Hotkey Constant\n\nIn `src/types/hotkey.ts`:\n\n```typescript\nexport const HotkeyEnum = {\n  // existing...\n  ClearChat: ''clearChat'', // Add new\n} as const;\n```\n\n### 2. Register Default Hotkey\n\nIn `src/const/hotkeys.ts`:\n\n```typescript\nimport { KeyMapEnum as Key, combineKeys } from ''@lobehub/ui'';\n\nexport const HOTKEYS_REGISTRATION: HotkeyRegistration = [\n  {\n    group: HotkeyGroupEnum.Conversation,\n    id: HotkeyEnum.ClearChat,\n    keys: combineKeys([Key.Mod, Key.Shift, Key.Backspace]),\n    scopes: [HotkeyScopeEnum.Chat],\n  },\n];\n```\n\n### 3. Add i18n Translation\n\nIn `src/locales/default/hotkey.ts`:\n\n```typescript\nconst hotkey: HotkeyI18nTranslations = {\n  clearChat: {\n    desc: ''清空当前会话的所有消息记录'',\n    title: ''清空聊天记录'',\n  },\n};\n```\n\n### 4. Create and Register Hook\n\nIn `src/hooks/useHotkeys/chatScope.ts`:\n\n```typescript\nexport const useClearChatHotkey = () => {\n  const clearMessages = useChatStore((s) => s.clearMessages);\n  return useHotkeyById(HotkeyEnum.ClearChat, clearMessages);\n};\n\nexport const useRegisterChatHotkeys = () => {\n  useClearChatHotkey();\n  // ...other hotkeys\n};\n```\n\n### 5. Add Tooltip (Optional)\n\n```tsx\nconst clearChatHotkey = useUserStore(settingsSelectors.getHotkeyById(HotkeyEnum.ClearChat));\n\n<Tooltip hotkey={clearChatHotkey} title={t(''clearChat.title'', { ns: ''hotkey'' })}>\n  <Button icon={<DeleteOutlined />} onClick={clearMessages} />\n</Tooltip>;\n```\n\n## Best Practices\n\n1. **Scope**: Choose global or chat scope based on functionality\n2. **Grouping**: Place in appropriate group (System/Layout/Conversation)\n3. **Conflict check**: Ensure no conflict with system/browser shortcuts\n4. **Platform**: Use `Key.Mod` instead of hardcoded `Ctrl` or `Cmd`\n5. **Clear description**: Provide title and description for users\n\n## Troubleshooting\n\n- **Not working**: Check scope and RegisterHotkeys hook\n- **Not in settings**: Verify HOTKEYS_REGISTRATION config\n- **Conflict**: HotkeyInput component shows warnings\n- **Page-specific**: Ensure correct scope activation\n"},"lastSynced":"2026-03-06T14:00:47.487Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor and AutoGPT needing customized keyboard interactions and shortcuts.","zh":"适用于像 Cursor 和 AutoGPT 这样的 AI Agent，它们需要自定义的键盘交互和快捷键。","ja":"Cursor や AutoGPT などのカスタマイズされたキーボードのやり取りとショートカットが必要な AI エージェントに適しています。","ko":"Cursor 및 AutoGPT와 같은 사용자 지정 키보드 상호 작용 및 바로 가기가 필요한 AI 에이전트에 적합합니다.","es":"Ideal para Agentes de IA como Cursor y AutoGPT que necesitan interacciones personalizadas del teclado y accesos directos.","fr":"Idéal pour les agents IA comme Cursor et AutoGPT ayant besoin d''interactions clavier personnalisées et de raccourcis.","de":"Ideal für KI-Agents wie Cursor und AutoGPT, die benutzerdefinierte Tastaturinteraktionen und Tastenkombinationen benötigen.","pt":"Ideal para Agentes de IA como Cursor e AutoGPT que necessitam de interações de teclado personalizadas e atalhos.","ru":"Идеально для агентов ИИ, таких как Cursor и AutoGPT, которые требуют настраиваемых взаимодействий с клавиатурой и сокращений.","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Cursor و AutoGPT الذين يحتاجون إلى تفاعلات لوحة المفاتيح ومقاطع مخصصة."},"recommendation":{"en":"Empowers agents to register custom hotkeys using HotkeyEnum and KeyMapEnum, enabling seamless keyboard interactions with combineKeys from @lobehub/ui, and updating default hotkeys in HOTKEYS_REGISTRATION.","zh":"使代理能够使用 HotkeyEnum 和 KeyMapEnum 注册自定义热键，实现与 @lobehub/ui 中的 combineKeys 无缝的键盘交互，并在 HOTKEYS_REGISTRATION 中更新默认热键。","ja":"HotkeyEnum と KeyMapEnum を使用してカスタム ホットキーを登録できるようにエージェントを有効にし、@lobehub/ui の combineKeys とシームレスなキーボードのやり取りを実現し、HOTKEYS_REGISTRATION の既定のホットキーを更新します。","ko":"HotkeyEnum 및 KeyMapEnum을 사용하여 사용자 지정 핫키를 등록할 수 있는 에이전트를 활성화하여 @lobehub/ui의 combineKeys와의 시ーム리스 키보드 상호 작용을 가능하게 하고 HOTKEYS_REGISTRATION의 기본 핫키를 업데이트합니다.","es":"Permite a los agentes registrar teclas rápidas personalizadas utilizando HotkeyEnum y KeyMapEnum, lo que permite interacciones de teclado sin problemas con combineKeys desde @lobehub/ui, y actualiza las teclas rápidas predeterminadas en HOTKEYS_REGISTRATION.","fr":"Permet aux agents d''enregistrer des raccourcis clavier personnalisés en utilisant HotkeyEnum et KeyMapEnum, ce qui permet des interactions clavier sans interruption avec combineKeys depuis @lobehub/ui, et met à jour les raccourcis clavier par défaut dans HOTKEYS_REGISTRATION.","de":"Ermöglicht es Agents, benutzerdefinierte Hotkeys mit HotkeyEnum und KeyMapEnum zu registrieren, was eine nahtlose Tastaturinteraktion mit combineKeys von @lobehub/ui ermöglicht und die Standard-Hotkeys in HOTKEYS_REGISTRATION aktualisiert.","pt":"Habilita os agentes a registrar atalhos personalizados usando HotkeyEnum e KeyMapEnum, permitindo interações de teclado sem problemas com combineKeys de @lobehub/ui e atualizando atalhos padrão em HOTKEYS_REGISTRATION.","ru":"Предоставляет агентам возможность регистрировать пользовательские горячие клавиши с помощью HotkeyEnum и KeyMapEnum, обеспечивая бесперебойное взаимодействие с клавиатурой с combineKeys из @lobehub/ui и обновление стандартных горячих клавиш в HOTKEYS_REGISTRATION.","ar":"تمكين الوكلاء من تسجيل الاختصارات المخصصة باستخدام HotkeyEnum و KeyMapEnum، وتمكين التفاعلات السهلة مع لوحة المفاتيح مع combineKeys من @lobehub/ui، وتحديث الاختصارات الافتراضية في HOTKEYS_REGISTRATION."},"useCases":{"en":["Registering new hotkeys for conversation management","Updating default hotkey mappings for agent-specific tasks","Customizing keyboard shortcuts for enhanced user experience"],"zh":["为会话管理注册新的热键","更新代理特定任务的默认热键映射","自定义键盘快捷方式以增强用户体验"],"ja":["会話管理のための新しいホットキーを登録する","エージェント固有のタスクの既定のホットキーマッピングを更新する","ユーザー エクスペリエンスを向上させるためのキーボード ショートカットのカスタマイズ"],"ko":["대화 관리를 위한 새로운 핫키 등록","에이전트 특정 작업의 기본 핫키 매핑 업데이트","사용자 경험 향상을 위한 키보드 바로 가기 사용자 지정"],"es":["Registrar nuevas teclas rápidas para la gestión de conversaciones","Actualizar los mapeos de teclas rápidas predeterminados para tareas específicas del agente","Personalizar los atajos de teclado para una experiencia del usuario mejorada"],"fr":["Enregistrer de nouvelles touches de raccourci pour la gestion des conversations","Mettre à jour les mappages de touches de raccourci par défaut pour les tâches spécifiques à l''agent","Personnaliser les raccourcis clavier pour améliorer l''expérience utilisateur"],"de":["Registrieren neuer Hotkeys für die Konversationsverwaltung","Aktualisieren der Standard-Hotkey-Zuordnungen für agentenspezifische Aufgaben","Anpassen der Tastenkombinationen für eine verbesserte Benutzererfahrung"],"pt":["Registro de novos atalhos para gerenciamento de conversas","Atualização de mapeamentos de atalhos padrão para tarefas específicas de agente","Personalização de atalhos de teclado para experiência do usuário aprimorada"],"ru":["Регистрация новых горячих клавиш для управления разговорами","Обновление стандартных сопоставлений горячих клавиш для задач, специфичных для агента","Настройка клавиатурных сокращений для улучшения пользовательского опыта"],"ar":["تسجيل اختصارات جديدة لإدارة المحادثات","تحديث تعيينات الاختصارات الافتراضية للمهام المحددة للوكيل","تخصيص اختصارات لوحة المفاتيح لتجربة المستخدم المحسنة"]},"limitations":{"en":["Requires updating HotkeyEnum constant in src/types/hotkey.ts","Needs registration of default hotkeys in src/const/hotkeys.ts"],"zh":["需要在 src/types/hotkey.ts 中更新 HotkeyEnum 常量","需要在 src/const/hotkeys.ts 中注册默认热键"],"ja":["src/types/hotkey.ts の HotkeyEnum 定数を更新する必要がある","src/const/hotkeys.ts に既定のホットキーを登録する必要がある"],"ko":["src/types/hotkey.ts의 HotkeyEnum 상수를 업데이트해야 함","src/const/hotkeys.ts에 기본 핫키를 등록해야 함"],"es":["Requiere la actualización de la constante HotkeyEnum en src/types/hotkey.ts","Necesita el registro de las teclas rápidas predeterminadas en src/const/hotkeys.ts"],"fr":["Nécessite la mise à jour de la constante HotkeyEnum dans src/types/hotkey.ts","A besoin de l''enregistrement des touches de raccourci par défaut dans src/const/hotkeys.ts"],"de":["Erfordert die Aktualisierung der Konstanten HotkeyEnum in src/types/hotkey.ts","Benötigt die Registrierung der Standard-Hotkeys in src/const/hotkeys.ts"],"pt":["Requer atualização da constante HotkeyEnum em src/types/hotkey.ts","Necessita registro de atalhos padrão em src/const/hotkeys.ts"],"ru":["Требует обновления константы HotkeyEnum в src/types/hotkey.ts","Требует регистрации стандартных горячих клавиш в src/const/hotkeys.ts"],"ar":["يتطلب تحديث ثابت HotkeyEnum في src/types/hotkey.ts","يتطلب تسجيل الاختصارات الافتراضية في src/const/hotkeys.ts"]},"version":4},"contentHash":"06629806123ba243a0222e25e96ab402889832694e529498aee4543f613778bd","qualityScore":36}');
