INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Absolute-Space-GHCP/leo-participation-translator/session-workflow', 'session-workflow', 'Absolute-Space-GHCP', 'leo-participation-translator', 'community', 'session-workflow Absolute-Space-GHCP leo-participation-translator community The session-workflow skill transforms passive advertising ideas into participation-worthy platforms for developers. It streamlines the development process with a session start checklist. AIエージェント会话工作流是一种AI驱动的参与式翻译平台，通过验证工作空间、检查Git状态和API密钥等步骤来确保开发环境的正确性 AIエージェントのセッションワークフローは、ワークスペースの検証、Gitの状態の確認、APIキーの検証などを通じて開発環境の正確性を確保する、AI駆動の参加型プラットフォームです AI 에이전트 세션 워크플로우는 작업공간 확인, Git 상태 확인, API 키 확인 등 과정을 통해 개발 환경의 정확성을 보장하는 AI 기반의 참여형 플랫폼입니다 Session Workflow es una habilidad que permite a los desarrolladores crear plataformas de participación mediante la configuración de tareas y la verificación del espacio de trabajo Session Workflow est une compétence qui permet aux développeurs de créer des plateformes de participation en configurant des tâches et en vérifiant l''espace de travail Session-Workflow ist eine Fähigkeit, die es Entwicklern ermöglicht, Teilnahmeplattformen durch die Konfiguration von Aufgaben und die Überprüfung des Arbeitsbereichs zu erstellen O Session Workflow é uma habilidade que transforma ideias de publicidade passiva em plataformas de participação ativa com tecnologias como Git e API keys Session Workflow — это навык, который превращает пассивные рекламные идеи в платформы для участия с использованием технологий như Git и API ключи Session Workflow هو مهارة تتحول الأفكار الإعلانية السلبية إلى منصات للمشاركة الفعّالة باستخدام تقنيات مثل Git ومفاتيح API how to use session-workflow session-workflow setup guide session-workflow alternative session-workflow vs participation translator what is session-workflow session-workflow install session-workflow tutorial session-workflow API integration session-workflow git status AIエージェント 会话工作流 开发环境 任务进度 工作空间验证 Git状态检查 API密钥验证 Verifies workspace using pwd and ls commands Checks git status for version control Reviews TASKS.md priorities for task management Validates API keys and services for secure integration Verifies dev server status for seamless development session-workflow is a technical skill that enables AI-powered participation translation, facilitating the transformation of advertising ideas into engaging platforms.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yuiseki/ai-secretary/system-reboot-bringup', 'community', 'yuiseki', 'ai-secretary', 'yuiseki/ai-secretary', 'system-reboot-bringup', 0, 0, 36, '2026-03-03T23:06:32Z', '2026-03-07T04:10:59.515Z', 'c44adc6f0ea82df58e5e6d4c55b7696759cee2befd115c61e83f41bbd3e00d70', '{"id":"yuiseki/ai-secretary/system-reboot-bringup","name":"system-reboot-bringup","description":{"en":"The system-reboot-bringup skill automates the revival of daily operation processes after a system reboot, focusing on tmux-managed processes. It benefits developers and power users who rely on VOICEVOX API, VacuumTube, and other critical tools.","zh":"系统重启启动后恢复日常运用中的常駐プロセス群，包括tmux、VOICEVOX API等技术","ja":"システム再起動後の起動設定を実現するためのRunbook - tmux、VOICEVOX API、VacuumTubeなどの技術を使用","ko":"시스템 재부팅 후 시작 설정을 위한 기술 - tmux, VOICEVOX API, VacuumTube 등","es":"System-reboot-bringup es un runbook para restaurar procesos después de un reinicio del sistema, incluyendo tmux, VOICEVOX y otros.","fr":"System-reboot-bringup est un runbook pour restaurer les processus après un redémarrage du système, y compris tmux, VOICEVOX et d''autres.","de":"System-reboot-bringup ist ein Runbook zur Wiederherstellung von Prozessen nach einem Systemneustart, einschließlich tmux, VOICEVOX und weiterer.","pt":"O system-reboot-bringup é um runbook para restaurar processos após reinicialização","ru":"System-reboot-bringup - это руководство для восстановления процессов после перезагрузки","ar":"نظام system-reboot-bringup هو كتاب إرشادات لاستعادة العمليات بعد إعادة التشغيل"},"seo":{"title":{"en":"system-reboot-bringup: Automated Runbook Setup Guide | AI...","zh":"系统重启启动指南 - system-reboot-bringup Setup Guide","ja":"システム再起動後の起動設定 - system-reboot-bringup ベストプラクティス","ko":"시스템 재부팅 후 시작 설정 - system-reboot-bringup 가이드","es":"Guía de configuración de system-reboot-bringup para agent...","fr":"Guide de configuration de system-reboot-bringup pour les ...","de":"Konfigurationsleitfaden für system-reboot-bringup für KI-...","pt":"Guia de Configuração do system-reboot-bringup para Desenv...","ru":"Руководство по настройке system-reboot-bringup для разраб...","ar":"دليل إعداد نظام system-reboot-bringup لأصحاب المهارات"},"description":{"en":"Learn how to automate post-reboot processes with system-reboot-bringup. Discover how to revive daily operation processes and get back to work quickly.","zh":"了解系统重启启动后恢复日常运用中的常駐プロセス群的方法，包括tmux、VOICEVOX API等技术","ja":"システム再起動後の起動設定を学ぶ - tmux、VOICEVOX API、VacuumTubeなどの技術を使用した再起動後のプロセス復旧","ko":"시스템 재부팅 후 시작 설정을 위한 가이드 - tmux, VOICEVOX API, VacuumTube 등 기술 사용","es":"Aprende a configurar system-reboot-bringup para restaurar procesos después de un reinicio del sistema con tmux, VOICEVOX y más","fr":"Découvrez comment configurer system-reboot-bringup pour restaurer les processus après un redémarrage du système avec tmux, VOICEVOX et plus","de":"Erfahren Sie, wie Sie system-reboot-bringup konfigurieren, um Prozesse nach einem Systemneustart mit tmux, VOICEVOX und mehr wiederherzustellen","pt":"Aprenda a configurar o system-reboot-bringup para restaurar processos após reinicialização","ru":"Узнайте, как настроить system-reboot-bringup для восстановления процессов после перезагрузки","ar":"تعرف على كيفية إعداد نظام system-reboot-bringup لاستعادة العمليات بعد إعادة التشغيل"},"definition":{"en":"system-reboot-bringup is a runbook designed to restore daily operation processes after a system reboot, managing tmux sessions and ensuring seamless functionality of dependent tools.","zh":"系统重启启动后恢复日常运用中的常駐プロセス群的方法","ja":"システム再起動後の起動設定を実現するためのRunbook","ko":"시스템 재부팅 후 시작 설정을 위한 방법","es":"System-reboot-bringup es un runbook que restaura procesos después de un reinicio del sistema","fr":"System-reboot-bringup est un runbook qui restaure les processus après un redémarrage du système","de":"System-reboot-bringup ist ein Runbook, das Prozesse nach einem Systemneustart wiederherstellt","pt":"O system-reboot-bringup é um conjunto de instruções para restaurar processos","ru":"System-reboot-bringup - это набор инструкций для восстановления процессов","ar":"نظام system-reboot-bringup هو مجموعة من الإرشادات لاستعادة العمليات"},"features":{"en":["Manages tmux sessions for VOICEVOX API, VacuumTube, and whisper.cpp","Automates the revival of critical processes, including whisper-server-ja and whisper-agent-ja","Supports Tauri subtitle overlay and GOD MODE webcam + face recognition overlay","Ensures proper logging and confirmation procedures for dependent tools","Compatible with KDE Plasma desktop environment"],"zh":["使用tmux管理プロセス","VOICEVOX API（http://127.0.0.1:50021）支持","VacuumTube远程调试（:9992）和tmux会话（vacuumtube-bg）","whisper.cpp音声コマンド待受一式支持","Tauri字幕オーバーレイ支持"],"ja":["tmuxプロセス管理","VOICEVOX API（http://127.0.0.1:50021）","VacuumTubeリモートデバッグ（:9992）とtmuxセッション（vacuumtube-bg）","whisper.cpp音声コマンド待受一式","Tauri 字幕オーバーレイ"],"ko":["tmux 프로세스 관리","VOICEVOX API（http://127.0.0.1:50021）","VacuumTube 원격 디버깅（:9992）과 tmux 세션（vacuumtube-bg）","whisper.cpp 음성 명령 대기 일체","Tauri 자막 오버레이"],"es":["Restauración de procesos con tmux","Integración con VOICEVOX API","Compatibilidad con VacuumTube y whisper.cpp","Soporte para Tauri y GOD MODE","Gestión de sesiones de tmux"],"fr":["Restauration de processus avec tmux","Intégration avec l''API VOICEVOX","Compatibilité avec VacuumTube et whisper.cpp","Prise en charge de Tauri et GOD MODE","Gestion de sessions tmux"],"de":["Wiederherstellung von Prozessen mit tmux","Integration mit VOICEVOX-API","Kompatibilität mit VacuumTube und whisper.cpp","Unterstützung für Tauri und GOD MODE","Verwaltung von tmux-Sitzungen"],"pt":["Restauração de processos após reinicialização","Gerenciamento de processos com tmux","Suporte a VOICEVOX API","Integração com VacuumTube","Suporte a whisper.cpp","Integração com Tauri"],"ru":["Восстановление процессов после перезагрузки","Управление процессами с помощью tmux","Поддержка VOICEVOX API","Интеграция с VacuumTube","Поддержка whisper.cpp","Интеграция с Tauri"],"ar":["استعادة العمليات بعد إعادة التشغيل","إدارة العمليات باستخدام tmux","دعم VOICEVOX API","دمج مع VacuumTube","دعم whisper.cpp","دمج مع Tauri"]},"keywords":{"en":["how to use system-reboot-bringup","system-reboot-bringup setup guide","automated runbook for tmux","VOICEVOX API management","VacuumTube remote debugging","whisper.cpp automation","Tauri subtitle overlay integration","GOD MODE webcam overlay setup","KDE Plasma compatibility"],"zh":["系统重启启动","tmux","VOICEVOX API","VacuumTube","whisper.cpp","Tauri","AIエージェント","系统再起动","启动设置"],"ja":["システム再起動","tmux","VOICEVOX API","VacuumTube","whisper.cpp","Tauri","AIエージェント","システム再起動後の起動設定","プロセス復旧"],"ko":["시스템 재부팅","tmux","VOICEVOX API","VacuumTube","whisper.cpp","Tauri","AI 에이전트","시스템 재부팅 후 시작 설정","프로세스 복구"],"es":["system-reboot-bringup","agentes de IA","tmux","VOICEVOX","VacuumTube","whisper.cpp","Tauri","GOD MODE","runbook","procesos de sistema"],"fr":["system-reboot-bringup","outils d''IA","tmux","VOICEVOX","VacuumTube","whisper.cpp","Tauri","GOD MODE","runbook","processus système"],"de":["system-reboot-bringup","KI-Tools","tmux","VOICEVOX","VacuumTube","whisper.cpp","Tauri","GOD MODE","Runbook","Systemprozesse"],"pt":["system-reboot-bringup","restauração de processos","tmux","VOICEVOX API","VacuumTube","whisper.cpp","Tauri","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["system-reboot-bringup","восстановление процессов","tmux","VOICEVOX API","VacuumTube","whisper.cpp","Tauri","разработка программного обеспечения","инструменты разработки"],"ar":["نظام system-reboot-bringup","استعادة العمليات","tmux","VOICEVOX API","VacuumTube","whisper.cpp","Tauri","تطوير البرمجيات","أدوات التطوير"]}},"owner":"yuiseki","repo":"ai-secretary","repoPath":"yuiseki/ai-secretary","stars":0,"forks":0,"updatedAt":"2026-03-03T23:06:32Z","topics":[],"category":"community","skillMd":{"name":"system-reboot-bringup","description":"Ubuntu/KDE デスクトップを再起動したあとに、この環境の常駐プロセス群（VOICEVOX API、VacuumTube、whisper.cpp 音声コマンド待受、Tauri 字幕オーバーレイ、GOD MODE ウェブカメラオーバーレイ）を順序よく復旧する。ユーザーが『再起動後の起動手順をやって』『常駐プロセスを全部立ち上げて』『音声待受とカメラ監視を復旧して』など依頼したときに使う。","bodyPreview":"# system-reboot-bringup Skill\n\nこの環境を再起動した後に、日常運用で使っている常駐プロセス群を復旧するための runbook です。  \n`tmux` 管理のプロセスを中心に、起動順・確認手順・ログ確認をまとめています。\n\n## 対象プロセス（このスキルの範囲）\n\n- `VOICEVOX` API（`http://127.0.0.1:50021`）\n- `VacuumTube`（remote debugging `:9992`、通常 `tmux` セッション `vacuumtube-bg`）\n- `whisper.cpp` 音声コマンド待受一式（`whisper-server-ja`, `whisper-agent-ja`）\n- `Tauri` 字幕オーバーレイ（`caption-overlay-poc` または `tauri-overlay`）\n- `GOD MODE` ウェブカメラ + 顔認識オーバーレイ（`god-mode-bg` tmux / port 8765）\n\n## 前提\n\n- KDE Plasma デスクトップにログイン済み\n- 実際に有効","body":"# system-reboot-bringup Skill\n\nこの環境を再起動した後に、日常運用で使っている常駐プロセス群を復旧するための runbook です。  \n`tmux` 管理のプロセスを中心に、起動順・確認手順・ログ確認をまとめています。\n\n## 対象プロセス（このスキルの範囲）\n\n- `VOICEVOX` API（`http://127.0.0.1:50021`）\n- `VacuumTube`（remote debugging `:9992`、通常 `tmux` セッション `vacuumtube-bg`）\n- `whisper.cpp` 音声コマンド待受一式（`whisper-server-ja`, `whisper-agent-ja`）\n- `Tauri` 字幕オーバーレイ（`caption-overlay-poc` または `tauri-overlay`）\n- `GOD MODE` ウェブカメラ + 顔認識オーバーレイ（`god-mode-bg` tmux / port 8765）\n\n## 前提\n\n- KDE Plasma デスクトップにログイン済み\n- 実際に有効な `DISPLAY` を確認して GUI 操作できる（再起動後に `:0` / `:1` が変わることがある）\n- `tmux`, `curl`, `jq`, `python3` 利用可能\n\n## 重要ルール\n\n- 音声待受は `listener` と `agent` を同時起動しない（マイク競合）\n- 再起動後はまず `VOICEVOX` と `VacuumTube` の土台を復旧してから `whisper-agent` を起動する\n- UX（音声・字幕・VacuumTube 操作）は自動テストだけで保証できないため、最後に必ず手動確認する\n\n## 推奨の起動順（再起動後）\n\n### 0) 有効な `DISPLAY` を確認（重要）\n\n再起動後は `DISPLAY` が `:0` になることがあるため、固定値 `:1` を前提にしない。\n\n```bash\nfor d in :0 :1 :2; do\n  echo \"== $d ==\"\n  DISPLAY=\"$d\" XAUTHORITY=\"$HOME/.Xauthority\" xdpyinfo >/dev/null 2>&1 && echo ok || echo ng\ndone\n```\n\n`ok` になった値を以降のコマンドで使う（例: `:0`）。\n\n```bash\nexport DESKTOP_DISPLAY=:0\nexport XAUTHORITY=\"$HOME/.Xauthority\"\n```\n\n### 1) VOICEVOX (VOICEBOX) を起動（`tmux` 推奨, API :50021）\n\n`VOICEVOX` も `tmux` で常駐化しておくと、作業セッション終了時に巻き込まれて落ちにくい。\n\n```bash\ntmux has-session -t voicevox-bg 2>/dev/null && tmux kill-session -t voicevox-bg || true\ntmux new-session -d -s voicevox-bg \\\n  \"bash -lc ''export DISPLAY=${DESKTOP_DISPLAY}; export XAUTHORITY=\\\"$HOME/.Xauthority\\\"; exec \\\"$HOME/.voicevox/VOICEVOX.AppImage\\\"''\"\n```\n\n確認:\n\n```bash\ncurl -fsS http://127.0.0.1:50021/version\ntmux capture-pane -pt voicevox-bg -S -40 | tail -n 20\n```\n\n補足:\n\n- `VOICEVOX` が起動していないと、`whisper-agent` は音声応答できない（字幕だけになる/フォールバックになる）\n\n### 2) VacuumTube を起動（tmux 推奨）\n\n```bash\ntmux new-session -d -s vacuumtube-bg \\\n  \"bash -lc ''export VACUUMTUBE_DISPLAY=${DESKTOP_DISPLAY}; export XAUTHORITY=\\\"$HOME/.Xauthority\\\"; exec ~/vacuumtube.sh''\"\n```\n\n確認:\n\n```bash\npgrep -af ''^/opt/VacuumTube/vacuumtube( |$)''\ncurl -fsS http://127.0.0.1:9992/json/version\n```\n\n起動直後の手動操作（必要な場合）:\n\n- アカウント選択画面で `YuisekinTV` を選択\n- 右上にタイル配置（`desktop-windows-layout` / `vacuumtube` スキル手順）\n\n### 3) Tauri 字幕オーバーレイを起動（`tauri-overlay` tmux セッション）\n\n字幕・ロック画面オーバーレイを **音声待受とは独立して** 起動します。\n`tmux_listen_only.sh`（step 3-b）と重複しても問題ありません（`tmux_listen_only.sh` が `caption-overlay-poc` セッションで同じバイナリを管理します）。\nロック画面単体をテストしたいときや、音声待受なしで字幕 IPC だけ使いたいときに便利です。\n\n```bash\n# 既存セッションがあれば殺してから起動\ntmux has-session -t tauri-overlay 2>/dev/null && tmux kill-session -t tauri-overlay || true\ntmux new-session -d -s tauri-overlay \\\n  \"bash -lc ''cd ~/Workspaces/tmp/tauri-caption-overlay-poc/src-tauri && PKG_CONFIG_PATH=/usr/lib/x86_64-linux-gnu/pkgconfig DISPLAY=${DESKTOP_DISPLAY} XAUTHORITY=\\\"$HOME/.Xauthority\\\" ./target/debug/caption-overlay-poc 2>&1 | tee /tmp/tauri-overlay.log''\"\n```\n\n起動確認（IPC ポート 47832）:\n\n```bash\nsleep 3 && tail -5 /tmp/tauri-overlay.log\n# 期待: \"caption overlay IPC listening on 127.0.0.1:47832\"\n```\n\nロック画面の表示テスト:\n\n```bash\necho ''{\"type\":\"lock_screen_show\",\"text\":\"SYSTEM LOCKED\"}'' | nc -q1 127.0.0.1 47832\n# 解除テスト\necho ''{\"type\":\"lock_screen_hide\"}'' | nc -q1 127.0.0.1 47832\n```\n\n補足:\n\n- バイナリは `feature/biometric-lock-screen` ブランチで管理（HUD デザイン＋生体認証ロック画面）\n- リビルドが必要な場合: `cd ~/Workspaces/tmp/tauri-caption-overlay-poc/src-tauri && PKG_CONFIG_PATH=/usr/lib/x86_64-linux-gnu/pkgconfig asdf exec cargo build`\n- `whisper-agent` が `tauri-overlay` とは別に `caption-overlay-poc` セッション経由でオーバーレイを使う場合は、ポート競合に注意（47832 は1プロセスのみ）\n\n### 3.5) Chromium ロック画面ブリッジを起動（`lock-screen-bridge` tmux セッション）\n\nTauri の代わりに **Chromium でロック画面を表示**するためのブリッジサーバーです（4K 環境で滑らか）。\nポート 47833 (TCP) + 18766 (WebSocket) + 18765 (HTTP static) を使用します。\n\n```bash\n# ブリッジ起動\ntmux has-session -t lock-screen-bridge 2>/dev/null && tmux kill-session -t lock-screen-bridge || true\ntmux new-session -d -s lock-screen-bridge \\\n  \"bash -lc ''cd ~/Workspaces/tmp/tauri-caption-overlay-poc && DISPLAY=${DESKTOP_DISPLAY} python3 lock_screen_bridge.py 2>&1 | tee /tmp/lock-screen-bridge.log''\"\nsleep 2\n\n# Chromium ロック画面ウィンドウを起動\nDISPLAY=${DESKTOP_DISPLAY} chromium \\\n  --app=\"http://127.0.0.1:18765/\" \\\n  --disable-background-timer-throttling \\\n  --disable-renderer-backgrounding \\\n  --no-first-run --no-default-browser-check \\\n  2>/dev/null &\n```\n\n起動確認:\n\n```bash\n# ブリッジログ確認\ntail -5 /tmp/lock-screen-bridge.log\n# 期待: \"Lock screen bridge ready.\"\n\n# ロック画面テスト\npython3 -c \"\nimport socket, json\npayload = json.dumps({''type'': ''lock_screen_show'', ''text'': ''SYSTEM LOCKED''}) + ''\\n''\nwith socket.create_connection((''127.0.0.1'', 47833), timeout=3) as s:\n    s.sendall(payload.encode()); s.shutdown(socket.SHUT_WR)\n    print(s.recv(4096).decode().strip())\n\"\n# 期待: {\"ok\": true}\n\n# 解除テスト\npython3 -c \"\nimport socket, json\npayload = json.dumps({''type'': ''lock_screen_hide''}) + ''\\n''\nwith socket.create_connection((''127.0.0.1'', 47833), timeout=3) as s:\n    s.sendall(payload.encode()); s.shutdown(socket.SHUT_WR)\n    print(s.recv(4096).decode().strip())\n\"\n```\n\n音声待受起動時は `WHISPER_AGENT_LOCK_SCREEN_IPC_PORT=47833` を指定:\n\n```bash\nWHISPER_AGENT_LOCK_SCREEN_IPC_PORT=47833 \\\nSTT_BACKEND=moonshine \\\n... (通常の tmux_listen_only.sh start-agent コマンド)\n```\n\n### 4) 音声待受（tmux 管理）\n\n`tmp/whispercpp-listen/tmux_listen_only.sh` が以下をまとめて管理します。\n\n**STT バックエンドは `STT_BACKEND` 環境変数で切り替えます（デフォルト: `whisper`）:**\n\n| `STT_BACKEND` | 起動するセッション | レイテンシ | 精度 |\n|---------------|-------------------|------------|------|\n| `whisper`（既定）| `whisper-server-ja` + `whisper-agent-ja` + `caption-overlay-poc` | ~4500ms | 100% |\n| `moonshine` | `whisper-agent-ja` + `caption-overlay-poc`（server不要） | ~270ms | 96.6% |\n\n#### whisper バックエンド（既定）\n\n```bash\nCAPTION_OVERLAY_DISPLAY=\"${DESKTOP_DISPLAY}\" \\\nCAPTION_OVERLAY_XAUTHORITY=\"$HOME/.Xauthority\" \\\ntmp/whispercpp-listen/tmux_listen_only.sh start-agent\n```\n\n#### moonshine バックエンド + 声紋認証（推奨構成）\n\n```bash\nSTT_BACKEND=moonshine \\\nWHISPER_AGENT_SPEAKER_ID=1 \\\nCAPTION_OVERLAY_DISPLAY=\"${DESKTOP_DISPLAY}\" \\\nCAPTION_OVERLAY_XAUTHORITY=\"$HOME/.Xauthority\" \\\ntmp/whispercpp-listen/tmux_listen_only.sh start-agent\n```\n\n#### moonshine バックエンド（声紋認証なし）\n\n```bash\nSTT_BACKEND=moonshine \\\nCAPTION_OVERLAY_DISPLAY=\"${DESKTOP_DISPLAY}\" \\\nCAPTION_OVERLAY_XAUTHORITY=\"$HOME/.Xauthority\" \\\ntmp/whispercpp-listen/tmux_listen_only.sh start-agent\n```\n\nmoonshine は `whisper-server-ja` セッションを起動しません。モデルは `voice_command_loop.py` プロセス内にロードされます。\n\nモデルサイズ変更（既定: `base`）:\n\n```bash\nSTT_BACKEND=moonshine MOONSHINE_MODEL_SIZE=tiny \\\nWHISPER_AGENT_SPEAKER_ID=1 \\\ntmp/whispercpp-listen/tmux_listen_only.sh start-agent\n```\n\n状態確認:\n\n```bash\ntmp/whispercpp-listen/tmux_listen_only.sh status\n```\n\nよく使うログ:\n\n```bash\ntmp/whispercpp-listen/tmux_listen_only.sh logs-agent\ntmp/whispercpp-listen/tmux_listen_only.sh logs-agent-tail\ntmp/whispercpp-listen/tmux_listen_only.sh logs-overlay\n```\n\n補足:\n\n- whisper 既定モデルは `ggml-small.bin`\n- DJI マイクを明示したいときは `WHISPER_MIC_SOURCE=... tmp/whispercpp-listen/tmux_listen_only.sh restart-agent`\n- moonshine バックエンドは音声キャプチャに `ffmpeg`（`parec` 不要）を使用します\n- `WHISPER_AGENT_SPEAKER_ID=1` で ECAPA-TDNN 声紋認証を有効化（お嬢様のみコマンド実行可能）\n  - マスターボイスプリント: `tmp/whispercpp-listen/tests/fixtures/master_voiceprint.npy`\n  - 閾値: `WHISPER_AGENT_SPEAKER_THRESHOLD`（既定 0.60、ライブマイク実測値 0.63〜0.78）\n  - 認証失敗時: 「声紋認証に失敗しました。もう一度お試しください。」と返答してコマンドをブロック\n  - マスター再生成: `cd tmp/whispercpp-listen && python3 prototype_speaker_id.py`\n\n### 5) GOD MODE（ウェブカメラ + 顔認識オーバーレイ）を起動（tmux 管理）\n\nGOD MODE はリアルタイム映像をデスクトップ上にオーバーレイ表示する「映像表示系」です。\n\n`tmp/GOD_MODE/god_mode_restart.sh` を `tmux` セッション `god-mode-bg` から実行します。\n内部では `god_mode.sh restart` が各プロセスを `nohup` で起動し PID を `/tmp/god_mode_8765.pids` に保存します。\nその後 `layout --full-screen → --backmost` でウィンドウを全画面・最背面（壁紙代わり）に配置します。\n\n```bash\ntmux has-session -t god-mode-bg 2>/dev/null && tmux kill-session -t god-mode-bg || true\ntmux new-session -d -s god-mode-bg \\\n  \"bash -lc ''cd ~/Workspaces/tmp/GOD_MODE && DISPLAY=${DESKTOP_DISPLAY} XAUTHORITY=\\\"$HOME/.Xauthority\\\" bash god_mode_restart.sh; exec bash''\"\n```\n\n`god_mode_restart.sh` の内容（参考）:\n\n```bash\n./god_mode.sh restart --chromium --port 8765 --cameras 0,2,4\n./god_mode.sh layout --full-screen\n./god_mode.sh layout --backmost\n```\n\n起動確認（起動完了まで 10〜20 秒かかります）:\n\n```bash\n# tmux セッションのログを確認\ntmux capture-pane -pt god-mode-bg -S -40 | tail -n 20\n\n# video server の HTTP 応答を確認\ncurl -fsS http://localhost:8765/status\n```\n\n手動でウィンドウレイアウトを変更したい場合:\n\n```bash\ncd ~/Workspaces/tmp/GOD_MODE\n\n# 前面に出す（ウェブカメラが見たいとき）\nDISPLAY=${DESKTOP_DISPLAY} bash god_mode.sh layout --frontmost\n\n# フルスクリーン\nDISPLAY=${DESKTOP_DISPLAY} bash god_mode.sh layout --full-screen\n\n# 左下コンパクト配置\nDISPLAY=${DESKTOP_DISPLAY} bash god_mode.sh layout --left-bottom\n\n# 最背面に戻す（壁紙モード）\nDISPLAY=${DESKTOP_DISPLAY} bash god_mode.sh layout --backmost\n```\n\n停止したい場合:\n\n```bash\ncd ~/Workspaces/tmp/GOD_MODE && DISPLAY=${DESKTOP_DISPLAY} bash god_mode.sh stop\n```\n\n補足:\n\n- GOD MODE は `--chromium` モードで Chromium ウィンドウを使用（`--chromium` なし: Tauri モード）\n- `--cameras 0,2,4` でカメラ 0・2・4 番を使用（実際のデバイス番号は環境依存）\n- 音声コマンド `システム、ウェブカメラが見たい` 等でも制御可能（`whisper-agent` 運用中の場合）\n\n## まとめて確認（復旧完了チェック）\n\n```bash\ntmux ls | rg ''voicevox-bg|vacuumtube-bg|whisper-server-ja|whisper-agent-ja|caption-overlay-poc|tauri-overlay|god-mode-bg''\ncurl -fsS http://127.0.0.1:50021/version\ncurl -fsS http://127.0.0.1:9992/json/version\ncurl -fsS http://localhost:8765/status\n# Tauri オーバーレイ IPC 確認\necho ''{\"type\":\"notify\",\"text\":\"bringup OK\"}'' | nc -q1 127.0.0.1 47832\n```\n\n期待される `tmux` セッション（通常運用）:\n\n- `voicevox-bg`\n- `vacuumtube-bg`\n- `tauri-overlay`（字幕・ロック画面オーバーレイ / IPC :47832）\n- `whisper-server-ja`（STT_BACKEND=whisper のときのみ）\n- `whisper-agent-ja`\n- `caption-overlay-poc`（`tmux_listen_only.sh` が tauri-overlay と **別に** 起動する場合 — ポート競合に注意）\n- `god-mode-bg`（起動スクリプト完了後は idle、GOD_MODE プロセス自体は nohup で稼働中）\n\n注意:\n\n- `whisper-listen-ja` は `agent` 運用中は `STOPPED` が正常\n- `god-mode-bg` の tmux は起動コマンド実行後に idle になるのが正常（`exec bash` で待機している）\n\n## 最小の手動確認（UX）\n\n1. `システム 状況報告` と話しかける\n2. 字幕オーバーレイ + VOICEVOX 応答が出ることを確認\n3. `YouTubeを小さくして` など簡単なコマンドを試す\n\n## トラブルシュート（再起動直後に多いもの）\n\n### 1) `whisper-agent` は動いているのに喋らない\n\n- `VOICEVOX` が起動していないことが多い\n- 再起動後に `DISPLAY` を取り違えて `VOICEVOX` が即終了していることもある\n- 確認: `curl -fsS http://127.0.0.1:50021/version`\n\n### 2) VacuumTube の CDP が見えない\n\n- `~/vacuumtube.sh` 起動漏れ or `:9992` 未設定\n- 確認: `curl -fsS http://127.0.0.1:9992/json/version`\n\n### 4) Tauri オーバーレイ（IPC :47832）に繋がらない\n\n- `tauri-overlay` セッションが未起動、またはポート競合で落ちている\n- 確認: `nc -zv 127.0.0.1 47832`\n- ログ確認: `tmux capture-pane -pt tauri-overlay -S -40` または `tail -20 /tmp/tauri-overlay.log`\n- 再起動手順は Step 3 を参照\n- 別プロセスがポートを使用中の場合: `lsof -i :47832` で PID を特定して kill\n\n### 5) GOD MODE の video server に繋がらない\n\n- `god_mode.sh restart` が失敗しているか、まだ起動中\n- `tmux capture-pane -pt god-mode-bg -S -40` でログを確認\n- `DISPLAY` が合っていないと Chromium ウィンドウが開かない（step 0 で確認した値を使うこと）\n- 手動で再起動: `cd ~/Workspaces/tmp/GOD_MODE && DISPLAY=${DESKTOP_DISPLAY} bash god_mode_restart.sh`\n\n### 6) GOD MODE ウィンドウが前面に出たまま戻らない\n\n- `--backmost` の KWin スクリプトが効いていない可能性\n- 手動で最背面に: `cd ~/Workspaces/tmp/GOD_MODE && DISPLAY=${DESKTOP_DISPLAY} bash god_mode.sh layout --backmost`\n\n## 関連スキル\n\n- `vacuumtube`（VacuumTube の CDP 操作）\n- `audio-stt-whisper`（whisper-agent 運用）\n- `audio-speak-voicebox`（VOICEVOX + 字幕オーバーレイ）\n- `desktop-windows-layout`（VacuumTube の右上配置など）\n"},"lastSynced":"2026-03-07T04:10:59.515Z","agentAnalysis":{"suitability":{"en":"Ideal for Linux-based AI Agents requiring automated process revival after system reboots, particularly those utilizing tmux-managed processes and tools like VOICEVOX API and VacuumTube.","zh":"适合于需要在系统重启后自动恢复进程的基于Linux的AI Agent，特别是那些使用tmux管理进程和工具如VOICEVOX API和VacuumTube的Agent","ja":"LinuxベースのAIエージェントでシステム再起動後に自動的にプロセスを復元する必要がある場合、特にtmux管理プロセスやVOICEVOX APIおよびVacuumTubeのようなツールを使用する場合に最適","ko":"리눅스 기반 AI 에이전트에서 시스템 재시작 후 자동으로 프로세스를 복구해야 하는 경우, 특히 tmux로 관리되는 프로세스와 VOICEVOX API 및 VacuumTube와 같은 도구를 사용하는 경우에 적합","es":"Ideal para agentes de inteligencia artificial basados en Linux que requieren una revivificación automática de procesos después de reiniciar el sistema, particularmente aquellos que utilizan procesos y herramientas administrados por tmux como VOICEVOX API y VacuumTube.","fr":"Idéal pour les agents d''intelligence artificielle basés sur Linux nécessitant une réactivation automatique de processus après redémarrage du système, en particulier ceux utilisant des processus et des outils gérés par tmux tels que VOICEVOX API et VacuumTube.","de":"Ideal für Linux-basierte KI-Agents, die eine automatische Wiederbelebung von Prozessen nach Systemneustarts benötigen, insbesondere solche, die tmux-verwaltete Prozesse und Tools wie VOICEVOX API und VacuumTube nutzen.","pt":"Ideal para Agentes de IA baseados em Linux que exigem a revivificação automática de processos após reinicializações do sistema, particularmente aqueles que utilizam processos e ferramentas gerenciados por tmux, como VOICEVOX API e VacuumTube.","ru":"Идеально подходит для агентов ИИ на основе Linux, требующих автоматического возрождения процесса после перезагрузки системы, особенно тех, которые используют процессы и инструменты, управляемые tmux, такие как VOICEVOX API и VacuumTube.","ar":"مثالي للوكلاء الذكية التي تعمل بنظام لينكس والتي تتطلب إعادة تشغيل عملية آلي بعد إعادة تشغيل النظام، خاصة تلك التي تستخدم عمليات وأدوات إدارة tmux مثل VOICEVOX API و VacuumTube."},"recommendation":{"en":"Empowers agents to automate the revival of critical tools such as VOICEVOX API, VacuumTube, whisper.cpp, Tauri, and GOD MODE after a system reboot, ensuring seamless daily operation processes via tmux session management and protocol-specific port monitoring like http://127.0.0.1:50021 and :9992.","zh":"赋予代理自动恢复关键工具如VOICEVOX API、VacuumTube、whisper.cpp、Tauri和GOD MODE的能力，确保系统重启后通过tmux会话管理和特定协议端口监控（如http://127.0.0.1:50021和:9992）实现每日操作流程的无缝运行","ja":"VOICEVOX API、VacuumTube、whisper.cpp、Tauri、GOD MODEなどの重要なツールを自動的に復元する機能をエージェントに提供し、tmuxセッション管理とプロトコル固有のポート監視（http://127.0.0.1:50021および:9992など）を介してシステム再起動後の毎日の運用プロセスを無停滞で実行することを保証する","ko":"VOICEVOX API, VacuumTube, whisper.cpp, Tauri 및 GOD MODE와 같은 중요한 도구를 자동으로 복구하는 에이전트의 능력을 부여하여, tmux 세션 관리 및 특정 프로토콜 포트 모니터링(http://127.0.0.1:50021 및 :9992 등)을 통해 시스템 재시작 후 일일 운용 프로세스가 원활하게 실행되도록 보장","es":"Permite a los agentes automatizar la revivificación de herramientas críticas como VOICEVOX API, VacuumTube, whisper.cpp, Tauri y GOD MODE después de un reinicio del sistema, garantizando procesos de operación diaria sin interrupciones a través de la administración de sesiones tmux y la supervisión de puertos específicos de protocolo como http://127.0.0.1:50021 y :9992.","fr":"Permet aux agents d''automatiser la réactivation d''outils critiques tels que VOICEVOX API, VacuumTube, whisper.cpp, Tauri et GOD MODE après un redémarrage du système, assurant ainsi des processus d''exploitation quotidienne sans interruption via la gestion de sessions tmux et la surveillance de ports spécifiques au protocole comme http://127.0.0.1:50021 et :9992.","de":"Ermöglicht es Agenten, die Wiederbelebung kritischer Tools wie VOICEVOX API, VacuumTube, whisper.cpp, Tauri und GOD MODE nach einem Systemneustart zu automatisieren, und gewährleistet so einen unterbrechungsfreien Tagesbetrieb durch tmux-Sitzungsverwaltung und protokollspezifische Portüberwachung wie http://127.0.0.1:50021 und :9992.","pt":"Habilita os agentes a automatizar a revivificação de ferramentas críticas, como VOICEVOX API, VacuumTube, whisper.cpp, Tauri e GOD MODE, após uma reinicialização do sistema, garantindo processos de operação diária sem interrupção via gerenciamento de sessão tmux e monitoramento de porta específico do protocolo, como http://127.0.0.1:50021 e :9992.","ru":"Позволяет агентам автоматизировать возрождение критически важных инструментов, таких как VOICEVOX API, VacuumTube, whisper.cpp, Tauri и GOD MODE, после перезагрузки системы, обеспечивая бесперебойные ежедневные операционные процессы посредством управления сеансами tmux и мониторинга портов, специфичных для протокола, таких как http://127.0.0.1:50021 и :9992.","ar":"تمكّن الوكلاء من توفير إعادة تشغيل أدوات حيوية مثل VOICEVOX API و VacuumTube و whisper.cpp و Tauri و GOD MODE بعد إعادة تشغيل النظام، مما يضمن العمليات التشغيلية اليومية دون انقطاع من خلال إدارة جلسة tmux ومراقبة منفذ محدد بالبروتوكول مثل http://127.0.0.1:50021 و :9992."},"useCases":{"en":["Automating the restart of tmux-managed processes like VacuumTube and whisper.cpp after system reboots","Reviving VOICEVOX API and Tauri services to ensure continuous functionality","Debugging and monitoring logs for processes like GOD MODE and caption-overlay-poc to identify potential issues post-reboot"],"zh":["自动重启系统重启后tmux管理的进程，如VacuumTube和whisper.cpp","恢复VOICEVOX API和Tauri服务以确保连续功能","调试和监视GOD MODE和caption-overlay-poc等进程的日志以识别系统重启后潜在问题"],"ja":["システム再起動後のtmux管理プロセス（VacuumTubeやwhisper.cppなど）を自動的に再起動する","VOICEVOX APIおよびTauriサービスの復元を通じて連続的な機能を確保する","GOD MODEやcaption-overlay-pocなどのプロセスのログをデバッグおよび監視して、システム再起動後の潜在的な問題を特定する"],"ko":["시스템 재시작 후 tmux로 관리되는 프로세스(VacuumTube 및 whisper.cpp 등)를 자동으로 재시작","VOICEVOX API 및 Tauri 서비스를復元하여 연속적인 기능을 보장","GOD MODE 및 caption-overlay-poc와 같은 프로세스의 로그를 디버깅 및 모니터링하여 시스템 재시작 후 잠재적인 문제를 식별"],"es":["Automatizar el reinicio de procesos administrados por tmux como VacuumTube y whisper.cpp después de reiniciar el sistema","Revivir servicios VOICEVOX API y Tauri para garantizar la funcionalidad continua","Depurar y supervisar registros para procesos como GOD MODE y caption-overlay-poc para identificar posibles problemas después del reinicio"],"fr":["Automatiser le redémarrage de processus gérés par tmux tels que VacuumTube et whisper.cpp après redémarrage du système","Réactiver les services VOICEVOX API et Tauri pour assurer une fonctionnalité continue","Déboguer et surveiller les journaux pour les processus tels que GOD MODE et caption-overlay-poc pour identifier les problèmes potentiels après le redémarrage"],"de":["Automatisieren des Neustarts von tmux-verwalteten Prozessen wie VacuumTube und whisper.cpp nach einem Systemneustart","Wiederbelebung von VOICEVOX API- und Tauri-Diensten, um eine kontinuierliche Funktionalität sicherzustellen","Debuggen und Überwachen von Protokollen für Prozesse wie GOD MODE und caption-overlay-poc, um mögliche Probleme nach dem Neustart zu identifizieren"],"pt":["Automatizar a reinicialização de processos gerenciados por tmux, como VacuumTube e whisper.cpp, após reinicializações do sistema","Reviver serviços VOICEVOX API e Tauri para garantir funcionalidade contínua","Depurar e monitorar logs para processos como GOD MODE e caption-overlay-poc para identificar problemas potenciais após a reinicialização"],"ru":["Автоматизировать перезапуск процессов, управляемых tmux, таких как VacuumTube и whisper.cpp, после перезагрузки системы","Возродить службы VOICEVOX API и Tauri, чтобы обеспечить непрерывную функциональность","Отладить и отслеживать журналы для процессов, таких как GOD MODE и caption-overlay-poc, чтобы выявить потенциальные проблемы после перезагрузки"],"ar":["توفير إعادة تشغيل العمليات التي تُدار بواسطة tmux، مثل VacuumTube و whisper.cpp، بعد إعادة تشغيل النظام","إعادة تشغيل خدمات VOICEVOX API و Tauri لضمان الاستمرارية الوظيفية","تصحيح الأخطاء ومراقبة السجلات لعمليات مثل GOD MODE و caption-overlay-poc لتحديد المشكلات المحتملة بعد إعادة التشغيل"]},"limitations":{"en":["Requires KDE Plasma desktop login","Limited to specific processes and tools mentioned, such as VOICEVOX API, VacuumTube, whisper.cpp, Tauri, and GOD MODE","Dependent on tmux for process management"],"zh":["需要KDE Plasma桌面登录","仅限于特定进程和工具，如VOICEVOX API、VacuumTube、whisper.cpp、Tauri和GOD MODE","依赖于tmux进行进程管理"],"ja":["KDE Plasmaデスクトップログインが必要","VOICEVOX API、VacuumTube、whisper.cpp、Tauri、GOD MODEなどの特定のプロセスおよびツールに限定","プロセス管理にtmuxに依存"],"ko":["KDE Plasma 데스크탑 로그인이 필요","VOICEVOX API, VacuumTube, whisper.cpp, Tauri 및 GOD MODE와 같은 특정 프로세스 및 도구에 한정","프로세스 관리에 tmux에 의존"],"es":["Requiere inicio de sesión de escritorio KDE Plasma","Limitado a procesos y herramientas específicas mencionadas, como VOICEVOX API, VacuumTube, whisper.cpp, Tauri y GOD MODE","Dependiente de tmux para la administración de procesos"],"fr":["Nécessite une connexion au bureau KDE Plasma","Limité à des processus et des outils spécifiques mentionnés, tels que VOICEVOX API, VacuumTube, whisper.cpp, Tauri et GOD MODE","Dépendant de tmux pour la gestion des processus"],"de":["Benötigt KDE-Plasma-Desktop-Anmeldung","Begrenzt auf bestimmte Prozesse und Tools, wie VOICEVOX API, VacuumTube, whisper.cpp, Tauri und GOD MODE","Abhängig von tmux für die Prozessverwaltung"],"pt":["Exige login no desktop KDE Plasma","Limitado a processos e ferramentas específicas mencionadas, como VOICEVOX API, VacuumTube, whisper.cpp, Tauri e GOD MODE","Dependente de tmux para gerenciamento de processos"],"ru":["Требует входа в рабочий стол KDE Plasma","Ограничен конкретными процессами и инструментами, упомянутыми выше, такими как VOICEVOX API, VacuumTube, whisper.cpp, Tauri и GOD MODE","Зависит от tmux для управления процессами"],"ar":["يتطلب تسجيل الدخول إلى سطح المكتب KDE Plasma","محدود بالعمليات والأدوات المحددة المذكورة، مثل VOICEVOX API و VacuumTube و whisper.cpp و Tauri و GOD MODE","يعتمد على tmux لإدارة العمليات"]},"version":4},"contentHash":"c44adc6f0ea82df58e5e6d4c55b7696759cee2befd115c61e83f41bbd3e00d70","qualityScore":36}');
