INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yuiseki/ai-secretary/system-reboot-bringup', 'system-reboot-bringup', 'yuiseki', 'ai-secretary', 'community', 'system-reboot-bringup yuiseki ai-secretary community The system-reboot-bringup skill automates the revival of daily operation processes after a system reboot, focusing on tmux-managed processes. It benefits developers and power users who rely on VOICEVOX API, VacuumTube, and other critical tools. 系统重启启动后恢复日常运用中的常駐プロセス群，包括tmux、VOICEVOX API等技术 システム再起動後の起動設定を実現するためのRunbook - tmux、VOICEVOX API、VacuumTubeなどの技術を使用 시스템 재부팅 후 시작 설정을 위한 기술 - tmux, VOICEVOX API, VacuumTube 등 System-reboot-bringup es un runbook para restaurar procesos después de un reinicio del sistema, incluyendo tmux, VOICEVOX y otros. System-reboot-bringup est un runbook pour restaurer les processus après un redémarrage du système, y compris tmux, VOICEVOX et d''autres. System-reboot-bringup ist ein Runbook zur Wiederherstellung von Prozessen nach einem Systemneustart, einschließlich tmux, VOICEVOX und weiterer. O system-reboot-bringup é um runbook para restaurar processos após reinicialização System-reboot-bringup - это руководство для восстановления процессов после перезагрузки نظام system-reboot-bringup هو كتاب إرشادات لاستعادة العمليات بعد إعادة التشغيل how to use system-reboot-bringup system-reboot-bringup setup guide automated runbook for tmux VOICEVOX API management VacuumTube remote debugging whisper.cpp automation Tauri subtitle overlay integration GOD MODE webcam overlay setup KDE Plasma compatibility 系统重启启动 tmux VOICEVOX API VacuumTube whisper.cpp Tauri AIエージェント 系统再起动 启动设置 Manages tmux sessions for VOICEVOX API, VacuumTube, and whisper.cpp Automates the revival of critical processes, including whisper-server-ja and whisper-agent-ja Supports Tauri subtitle overlay and GOD MODE webcam + face recognition overlay Ensures proper logging and confirmation procedures for dependent tools Compatible with KDE Plasma desktop environment system-reboot-bringup is a runbook designed to restore daily operation processes after a system reboot, managing tmux sessions and ensuring seamless functionality of dependent tools.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tarrragon/ccsession/security-review', 'community', 'tarrragon', 'ccsession', 'tarrragon/ccsession', 'security-review', 0, 0, 36, '2026-03-03T19:54:11Z', '2026-03-07T04:11:13.285Z', '27402cf3a6d37ec8d4b52522f8b673e3305822697c5525cf3a68676355466725', '{"id":"tarrragon/ccsession/security-review","name":"security-review","description":{"en":"The security-review skill provides a comprehensive security audit guide for Flutter/Dart projects, helping developers identify and fix vulnerabilities. It benefits developers working with sensitive user data and APIs.","zh":"Security Review Skill 提供 Flutter/Dart 项目的安全审查快速指引，帮助开发者确保代码安全","ja":"Security Review スキルは Flutter/Dart プロジェクトのセキュリティチェックの迅速なガイドを提供し、開発者がコードの安全性を確保するのに役立ちます","ko":"보안 리뷰 스킬은 Flutter/Dart 프로젝트의 보안 검토를 위한 빠른 가이드를 제공하여 개발자가 코드의 안전성을 보장할 수 있습니다","es":"La revisión de seguridad es crucial para proteger tus proyectos Flutter/Dart. Nuestra guía cubre el manejo de secretos, autenticación y más","fr":"La revue de sécurité est essentielle pour protéger vos projets Flutter/Dart. Notre guide couvre la gestion des secrets, l''authentification et plus","de":"Die Sicherheitsprüfung ist entscheidend, um Ihre Flutter/Dart-Projekte zu schützen. Unser Leitfaden behandelt Geheimnisverwaltung, Authentifizierung und mehr","pt":"A revisão de segurança para Flutter/Dart ajuda a proteger aplicativos contra vulnerabilidades. Veja como configurar a segurança corretamente.","ru":"Безопасность для Flutter/Dart помогает защитить приложения от уязвимостей. Узнайте, как настроить безопасность правильно.","ar":"مراقبة الأمن ل Flutter/Dart تساعد على حماية التطبيقات من نقاط الضعف. تعرف على كيفية إعداد الأمن بشكل صحيح."},"seo":{"title":{"en":"security-review: Secure Flutter/Dart Projects Setup Guide...","zh":"Security Review Setup Guide：Flutter/Dart 项目安全审查","ja":"セキュリティレビュー設定ガイド：Flutter/Dart プロジェクトのセキュリティチェック","ko":"보안 리뷰 설정 가이드：Flutter/Dart 프로젝트 보안 검토","es":"Guía de configuración de revisión de seguridad para Flutt...","fr":"Guide de mise en place de la revue de sécurité pour Flutt...","de":"Sicherheitsprüfung-Setup-Leitfaden für Flutter/Dart","pt":"Guia de Configuração de Revisão de Segurança para Flutter...","ru":"ИИ Агент: Руководство по Настройке Безопасности для Flutt...","ar":"إعداد مراقبة الأمن ل Flutter/Dart"},"description":{"en":"Unlock secure coding practices with security-review! Discover how to protect your Flutter/Dart projects from vulnerabilities and ensure a safe user experienc...","zh":"使用 Security Review Skill 进行 Flutter/Dart 项目的安全审查，确保代码安全和合规","ja":"Security Review スキルを使用して Flutter/Dart プロジェクトのセキュリティをチェックし、コードの安全性とコンプライアンスを確保する","ko":"보안 리뷰 스킬을 사용하여 Flutter/Dart 프로젝트의 보안을 검토하고 코드의 안전性 및 준수를 보장합니다","es":"Aprende a proteger tus proyectos Flutter/Dart con nuestra guía de revisión de seguridad, incluyendo el manejo de secretos y la autenticación","fr":"Protégez vos projets Flutter/Dart avec notre guide de revue de sécurité, incluant la gestion des secrets et l''authentification","de":"Schützen Sie Ihre Flutter/Dart-Projekte mit unserem Sicherheitsprüfung-Setup-Leitfaden, einschließlich Geheimnisverwaltung und Authentifizierung","pt":"Aprenda a proteger seu aplicativo Flutter/Dart com nossa revisão de segurança. Veja como evitar vulnerabilidades e proteger dados sensíveis.","ru":"Защитите свое приложение Flutter/Dart с помощью нашего руководства по безопасности. Узнайте, как избежать уязвимостей и защитить конфиденциальные данные.","ar":"تعلم حماية تطبيقك Flutter/Dart باستخدام إعدادات مراقبة الأمن الخاصة بنا. تعرف على كيفية تجنب نقاط الضعف وحماية البيانات الحساسة."},"definition":{"en":"security-review is a skill that provides a set of security principles and checks to ensure Flutter/Dart projects are secure, including machine credential management and secure API integration","zh":"Security Review 是一种帮助开发者进行代码安全审查的 AI 工具","ja":"セキュリティレビューは、開発者がコードのセキュリティをチェックするのを支援する AI エージェントです","ko":"보안 리뷰는 개발자가 코드의 보안을 검토하는 것을 지원하는 AI 에이전트입니다","es":"La revisión de seguridad es un proceso para identificar y mitigar vulnerabilidades en proyectos Flutter/Dart","fr":"La revue de sécurité est un processus pour identifier et atténuer les vulnérabilités dans les projets Flutter/Dart","de":"Die Sicherheitsprüfung ist ein Prozess zur Identifizierung und Minderung von Schwachstellen in Flutter/Dart-Projekten","pt":"Revisão de segurança para Flutter/Dart é um processo de verificação de vulnerabilidades de segurança em aplicativos.","ru":"Безопасность для Flutter/Dart - это процесс проверки уязвимостей безопасности в приложениях.","ar":"مراقبة الأمن ل Flutter/Dart هي عملية فحص نقاط الضعف الأمنية في التطبيقات."},"features":{"en":["Provides a security checklist for Flutter/Dart projects","Supports secure credential management using --dart-define or .env files","Ensures sensitive files like .env and google-services.json are ignored by git","Helps manage device permissions for camera and storage","Guides secure API key and token handling"],"zh":["機密管理：确保 API Key 和 Token 的安全","安全檢查清單：提供詳細的安全檢查項目","核心原則：遵循安全開發的最佳實踐","Dart 和 Flutter 支持：針對 Dart 和 Flutter 項目的安全審查","與第三方 API 整合：安全地整合 Google Books、Dio 等第三方 API","安全性和合規性：確保代碼的安全性和合規性"],"ja":["機密管理：API キーとトークンのセキュリティを確保","セキュリティチェックリスト：詳細なセキュリティチェック項目を提供","コアプリンシプル：セキュアな開発のベストプラクティスに従う","Dart と Flutter サポート：Dart と Flutter プロジェクトのセキュリティチェック","第三者 API との統合：Google Books、Dio などの第三者 API を安全に統合","セキュリティとコンプライアンス：コードのセキュリティとコンプライアンスを確保"],"ko":["기밀 관리：API 키와 토큰의 보안을 확보","보안 검토 목록：詳細한 보안 검토 항목을 제공","핵심 원칙：보안 개발의 최선의 관행을 따름","Dart 및 Flutter 지원：Dart 및 Flutter 프로젝트의 보안 검토","제3자 API와의 통합：Google Books, Dio 등의 제3자 API를 안전하게 통합","보안성과 준수성：코드의 보안성과 준수성을 확보"],"es":["Manejo de secretos con --dart-define o .env","Autenticación y autorización en Flutter/Dart","Protección de API Key y Token","Integración segura con terceras partes","Gestión de permisos de dispositivo"],"fr":["Gestion des secrets avec --dart-define ou .env","Authentification et autorisation dans Flutter/Dart","Protection de la clé API et du Token","Intégration sécurisée avec des tiers","Gestion des autorisations de l''appareil"],"de":["Geheimnisverwaltung mit --dart-define oder .env","Authentifizierung und Autorisierung in Flutter/Dart","Schutz von API-Schlüsseln und Token","Sichere Integration mit Drittanbietern","Verwaltung von Geräteberechtigungen"],"pt":["Verificação de hardcoded API Key e Token","Uso de --dart-define ou .env para injetar segredos","Exclusão de arquivos sensíveis do versionamento","Integração com APIs de terceiros de forma segura"],"ru":["Проверка на наличие硬кодированных API Key и Token","Использование --dart-define или .env для инъекции секретов","Исключение чувствительных файлов из версионирования","Интеграция с API третьих сторон в безопасном режиме"],"ar":["فحص المفاتيح API و Token المضمنة","استخدام --dart-define أو .env لإضافة المفاتيح السرية","استبعاد الملفات الحساسة من التحكم بالإصدار","تكامل مع واجهات برمجة التطبيقات الخارجية بأمان"]},"keywords":{"en":["how to use security-review","security-review for Flutter","secure Dart projects","security-review setup guide","security-review vs OWASP","security-review install","what is security-review","security-review best practices","security-review for API security"],"zh":["Security Review","Flutter 安全审查","Dart 安全审查","机密管理","安全检查清单","核心原则","Dart 安全开发","Flutter 安全开发","API 安全","代码安全"],"ja":["セキュリティレビュー","Flutter セキュリティチェック","Dart セキュリティチェック","機密管理","セキュリティチェックリスト","コアプリンシプル","Dart セキュア開発","Flutter セキュア開発","API セキュリティ","コードセキュリティ"],"ko":["보안 리뷰","Flutter 보안 검토","Dart 보안 검토","기밀 관리","보안 검토 목록","핵심 원칙","Dart 보안 개발","Flutter 보안 개발","API 보안","코드 보안"],"es":["revisión de seguridad Flutter","seguridad en Dart","protección de API Key","autenticación en Flutter","integración segura con terceras partes","gestión de permisos de dispositivo","Herramientas de seguridad para desarrolladores"],"fr":["revue de sécurité Flutter","sécurité dans Dart","protection de la clé API","authentification dans Flutter","intégration sécurisée avec des tiers","gestion des autorisations de l''appareil","Outils de sécurité pour les développeurs"],"de":["Sicherheitsprüfung Flutter","Sicherheit in Dart","Schutz von API-Schlüsseln","Authentifizierung in Flutter","sichere Integration mit Drittanbietern","Verwaltung von Geräteberechtigungen","Sicherheitstools für Entwickler"],"pt":["segurança flutter","revisão de segurança dart","proteção de aplicativos","vulnerabilidades de segurança","configuração de segurança","desenvolvimento de aplicativos seguros"],"ru":["безопасность flutter","проверка безопасности dart","защита приложений","уязвимости безопасности","настройка безопасности","разработка безопасных приложений"],"ar":["أمان فلاتر","فحص أمان دارت","حماية التطبيقات","نقاط الضعف الأمنية","إعداد الأمن","تطوير تطبيقات آمنة"]}},"owner":"tarrragon","repo":"ccsession","repoPath":"tarrragon/ccsession","stars":0,"forks":0,"updatedAt":"2026-03-03T19:54:11Z","topics":[],"category":"community","skillMd":{"name":"security-review","description":"Performs security review for Flutter/Dart code. Use when implementing authentication, handling user input, working with API keys or secrets, managing permissions, storing sensitive data locally, or integrating third-party APIs. Provides Flutter-specific security checklists and patterns.","bodyPreview":"# Security Review（Flutter/Dart）\n\nFlutter/Dart 專案的安全審查快速指引。本 Skill 提供安全檢查清單和核心原則，詳細程式碼範例請參考 `references/flutter-security-patterns.md`。\n\n---\n\n## 適用場景\n\n- 實作認證或授權功能\n- 處理使用者輸入（表單、掃描結果）\n- 使用 API Key 或其他機密\n- 整合第三方 API（Google Books、Dio 等）\n- 儲存或傳輸敏感資料\n- 管理裝置權限（相機、儲存）\n- 準備 Release 建置或上架\n\n---\n\n## 1. 機密管理\n\n**原則**：機密不可出現在原始碼或版本控制中。\n\n### 檢查清單\n\n- [ ] 無硬編碼 API Key、Token、密碼\n- [ ] 機密透過 `--dart-define` 或 `.env` 注入\n- [ ] `.env`、`*.keystore`、`key.properties` 已加入 `.gitignore`\n- [ ] `google-services.json` / `GoogleSer","body":"# Security Review（Flutter/Dart）\n\nFlutter/Dart 專案的安全審查快速指引。本 Skill 提供安全檢查清單和核心原則，詳細程式碼範例請參考 `references/flutter-security-patterns.md`。\n\n---\n\n## 適用場景\n\n- 實作認證或授權功能\n- 處理使用者輸入（表單、掃描結果）\n- 使用 API Key 或其他機密\n- 整合第三方 API（Google Books、Dio 等）\n- 儲存或傳輸敏感資料\n- 管理裝置權限（相機、儲存）\n- 準備 Release 建置或上架\n\n---\n\n## 1. 機密管理\n\n**原則**：機密不可出現在原始碼或版本控制中。\n\n### 檢查清單\n\n- [ ] 無硬編碼 API Key、Token、密碼\n- [ ] 機密透過 `--dart-define` 或 `.env` 注入\n- [ ] `.env`、`*.keystore`、`key.properties` 已加入 `.gitignore`\n- [ ] `google-services.json` / `GoogleService-Info.plist` 已加入 `.gitignore`\n- [ ] Git 歷史中無機密洩漏\n\n### 核心模式\n\n```dart\n// 正確：建置時注入\nconst apiKey = String.fromEnvironment(''API_KEY'', defaultValue: '''');\n\n// 錯誤：硬編碼\nconst apiKey = ''sk-proj-xxxxx''; // 禁止\n```\n\n> 詳細範例：`references/flutter-security-patterns.md` 第 1 節\n\n---\n\n## 2. 輸入驗證\n\n**原則**：所有使用者輸入在處理前必須驗證和清理。\n\n### 檢查清單\n\n- [ ] 所有表單欄位有 `validator`\n- [ ] 設定 `maxLength` 限制輸入長度\n- [ ] 使用白名單驗證（非黑名單）\n- [ ] 掃描結果（ISBN barcode）已清理非預期字元\n- [ ] 錯誤訊息不洩漏技術細節\n\n### 核心模式\n\n```dart\n// 表單驗證\nTextFormField(\n  validator: (value) {\n    if (value == null || value.trim().isEmpty) return ''必填'';\n    if (value.length > maxLength) return ''超過長度限制'';\n    return null;\n  },\n  inputFormatters: [\n    FilteringTextInputFormatter.deny(RegExp(r''[<>{}]'')),\n  ],\n)\n```\n\n> 詳細範例：`references/flutter-security-patterns.md` 第 2 節\n\n---\n\n## 3. 本地資料安全\n\n**原則**：敏感資料使用加密儲存，一般偏好設定可用明文。\n\n### 檢查清單\n\n- [ ] 機密資料使用 `flutter_secure_storage`（非 `SharedPreferences`）\n- [ ] SQLite 查詢使用參數化（`?` 佔位符）\n- [ ] 無 SQL 字串拼接\n- [ ] `SharedPreferences` 中無 Token、密碼、個資\n\n### 核心模式\n\n```dart\n// 正確：參數化查詢\nawait db.rawQuery(''SELECT * FROM books WHERE title LIKE ?'', [''%$query%'']);\n\n// 錯誤：字串拼接（SQL 注入）\nawait db.rawQuery(\"SELECT * FROM books WHERE title LIKE ''%$query%''\");\n```\n\n### 儲存選擇指引\n\n| 資料類型 | 儲存方式 |\n|---------|---------|\n| Token、密碼、API Key | `flutter_secure_storage` |\n| 使用者偏好（主題、語言） | `SharedPreferences` |\n| 結構化業務資料 | `sqflite`（參數化查詢） |\n| 暫存檔案 | `path_provider` 暫存目錄 |\n\n> 詳細範例：`references/flutter-security-patterns.md` 第 3 節\n\n---\n\n## 4. 網路安全\n\n**原則**：所有網路通訊使用 HTTPS，驗證回應結構。\n\n### 檢查清單\n\n- [ ] 所有 API 端點使用 HTTPS\n- [ ] 設定合理的連線逾時（`connectTimeout`、`receiveTimeout`）\n- [ ] API 回應結構已驗證（型別檢查）\n- [ ] Token 透過攔截器注入（非手動拼接）\n- [ ] 401 回應時清除本地 Token\n\n### 核心模式\n\n```dart\n// Dio 安全配置\nfinal dio = Dio(BaseOptions(\n  baseUrl: ''https://api.example.com'', // HTTPS only\n  connectTimeout: const Duration(seconds: 10),\n  receiveTimeout: const Duration(seconds: 15),\n));\n\n// 攔截器注入 Token\ndio.interceptors.add(InterceptorsWrapper(\n  onRequest: (options, handler) async {\n    final token = await storage.readToken();\n    if (token != null) {\n      options.headers[''Authorization''] = ''Bearer $token'';\n    }\n    handler.next(options);\n  },\n));\n```\n\n> 詳細範例：`references/flutter-security-patterns.md` 第 4 節\n\n---\n\n## 5. 權限管理\n\n**原則**：僅請求必要權限，在需要時才請求，並說明用途。\n\n### 檢查清單\n\n- [ ] 僅宣告實際需要的權限（AndroidManifest / Info.plist）\n- [ ] 權限在使用前才請求（非啟動時全部請求）\n- [ ] iOS `Info.plist` 每個權限有用途說明字串\n- [ ] 處理「永久拒絕」狀態（引導到系統設定）\n- [ ] 權限被拒時提供替代方案或提示\n\n### 核心模式\n\n```dart\n// 按需請求，處理各種狀態\nFuture<bool> requestCameraPermission() async {\n  final status = await Permission.camera.status;\n  if (status.isGranted) return true;\n  if (status.isDenied) {\n    final result = await Permission.camera.request();\n    return result.isGranted;\n  }\n  if (status.isPermanentlyDenied) {\n    await openAppSettings();\n    return false;\n  }\n  return false;\n}\n```\n\n> 詳細範例：`references/flutter-security-patterns.md` 第 5 節\n\n---\n\n## 6. 認證與授權\n\n**原則**：Token 安全儲存，過期自動處理，敏感操作前驗證狀態。\n\n### 檢查清單\n\n- [ ] Token 使用 `flutter_secure_storage` 儲存\n- [ ] Token 過期有自動更新機制\n- [ ] 登出時清除所有本地 Token\n- [ ] 敏感操作前驗證使用者認證狀態\n- [ ] Refresh Token 失敗時跳轉登入頁面\n\n> 詳細範例：`references/flutter-security-patterns.md` 第 6 節\n\n---\n\n## 7. 依賴安全\n\n**原則**：定期檢查依賴漏洞，鎖定版本確保可重現建置。\n\n### 檢查清單\n\n- [ ] `flutter pub audit` 無已知漏洞\n- [ ] `flutter pub outdated` 定期執行\n- [ ] `pubspec.lock` 已提交到版本控制\n- [ ] 依賴版本有合理約束（使用 `^` 語法）\n- [ ] CI/CD 使用 `--enforce-lockfile` 確保一致性\n\n### 核心指令\n\n```bash\nflutter pub audit        # 檢查已知漏洞\nflutter pub outdated     # 檢查過時套件\nflutter pub upgrade      # 更新依賴\n```\n\n> 詳細範例：`references/flutter-security-patterns.md` 第 7 節\n\n---\n\n## 8. 敏感資料外洩防護\n\n**原則**：日誌不含敏感資料，錯誤訊息不洩漏技術細節。\n\n### 檢查清單\n\n- [ ] 日誌中無 Token、密碼、個人資料\n- [ ] 使用者看到的錯誤訊息為通用文字（透過 i18n / ErrorHandler）\n- [ ] 技術細節僅記錄到開發日誌（`kDebugMode` 判斷）\n- [ ] Release 建置不輸出除錯日誌\n- [ ] Stack Trace 不暴露給使用者\n\n### 核心模式\n\n```dart\n// 正確：Release 模式下不輸出日誌\nif (kDebugMode) {\n  debugPrint(''API Error: ${error.runtimeType}'');\n}\n\n// 正確：使用 ErrorHandler 轉換錯誤訊息\nfinal userMessage = ErrorHandler.getUserMessage(exception);\n\n// 錯誤：直接暴露技術細節\n// showError(''Database error: $sqlException at line 42'');\n```\n\n> 詳細範例：`references/flutter-security-patterns.md` 第 8 節\n\n---\n\n## 上架前安全檢查清單\n\nRelease 建置或上架前，逐項確認：\n\n- [ ] **機密**：無硬編碼機密，全部透過環境變數注入\n- [ ] **輸入驗證**：所有使用者輸入已驗證\n- [ ] **SQL 注入**：所有查詢參數化\n- [ ] **本地儲存**：敏感資料使用加密儲存\n- [ ] **HTTPS**：所有網路通訊使用 HTTPS\n- [ ] **權限**：僅宣告必要權限，有用途說明\n- [ ] **認證**：Token 安全儲存和自動更新\n- [ ] **日誌**：Release 建置無敏感資料輸出\n- [ ] **依賴**：`flutter pub audit` 無漏洞\n- [ ] **錯誤處理**：使用者看不到技術細節\n- [ ] **ProGuard/R8**：Android Release 啟用程式碼混淆\n- [ ] **App Transport Security**：iOS 已正確設定\n\n---\n\n## 參考資源\n\n- [Flutter Security Best Practices](https://docs.flutter.dev/security)\n- [OWASP Mobile Top 10](https://owasp.org/www-project-mobile-top-10/)\n- [OWASP Mobile Application Security](https://mas.owasp.org/)\n- 詳細程式碼範例：`references/flutter-security-patterns.md`\n\n---\n\n*Last Updated: 2026-03-02*\n"},"lastSynced":"2026-03-07T04:11:13.285Z","agentAnalysis":{"suitability":{"en":"Perfect for Mobile App Security Agents needing comprehensive Flutter/Dart project audits.","zh":"非常适合需要对 Flutter/Dart 项目进行全面审计的移动应用安全代理。","ja":"Flutter/Dart プロジェクトの包括的な監査が必要なモバイルアプリケーションセキュリティエージェントに最適です。","ko":"Flutter/Dart 프로젝트에 대한 종합적인 감사를 필요로 하는 모바일 애플리케이션 보안 에이전트에 적합합니다.","es":"Perfecto para Agentes de Seguridad de Aplicaciones Móviles que necesitan auditorías de proyectos Flutter/Dart integrales.","fr":"Parfait pour les agents de sécurité d''applications mobiles ayant besoin d''audits de projets Flutter/Dart complets.","de":"Perfekt für Mobile App Security Agents, die umfassende Audits von Flutter/Dart-Projekten benötigen.","pt":"Perfeito para Agentes de Segurança de Aplicativos Móveis que precisam de auditorias abrangentes de projetos Flutter/Dart.","ru":"Идеально подходит для агентов мобильной безопасности, которым необходимы комплексные аудиты проектов Flutter/Dart.","ar":"مثالي لعمليات وكالات أمن التطبيقات المحمولة التي تحتاج إلى عمليات تدقيق شاملة لمشاريع Flutter/Dart."},"recommendation":{"en":"Empowers agents to identify and fix vulnerabilities in Flutter/Dart projects, ensuring secure handling of sensitive user data and APIs through principles like secret management and secure API key handling.","zh":"赋予代理识别和修复 Flutter/Dart 项目中的漏洞，确保通过诸如密钥管理和安全 API 密钥处理等原则，安全地处理敏感用户数据和 API。","ja":"エージェントが Flutter/Dart プロジェクト内の脆弱性を識別および修復することを可能にし、シークレット管理やセキュア API キー ハンドリングなどの原則を通じて、機密性の高いユーザー データおよび API を安全に処理します。","ko":"에이전트가 Flutter/Dart 프로젝트 내의 취약성을 식별하고 수정할 수 있도록 하여, 비밀키 관리 및 보안 API 키 처리와 같은 원칙을 통하여, 민감한 사용자 데이터 및 API를 안전하게 처리합니다.","es":"Habilita a los agentes a identificar y solucionar vulnerabilidades en proyectos Flutter/Dart, garantizando el manejo seguro de datos de usuario sensibles y APIs a través de principios como la gestión de secretos y el manejo seguro de claves de API.","fr":"Permet aux agents d''identifier et de corriger les vulnérabilités dans les projets Flutter/Dart, assurant ainsi la gestion sécurisée des données d''utilisateur sensibles et des APIs à travers des principes tels que la gestion des secrets et la gestion sécurisée des clés d''API.","de":"Ermächtigt die Agenten, Schwachstellen in Flutter/Dart-Projekten zu erkennen und zu beheben, sodass der sichere Umgang mit sensitiven Benutzerdaten und APIs durch Grundsätze wie Secret-Management und sichere API-Schlüsselverwaltung gewährleistet ist.","pt":"Habilita os agentes a identificar e corrigir vulnerabilidades em projetos Flutter/Dart, garantindo o tratamento seguro de dados de usuário sensíveis e APIs por meio de princípios como gerenciamento de segredos e manipulação segura de chaves de API.","ru":"Наделяет агентов возможностью выявлять и исправлять уязвимости в проектах Flutter/Dart, обеспечивая безопасную обработку конфиденциальных пользовательских данных и API посредством принципов, таких как управление секретами и безопасное обращение с ключами API.","ar":"يمنح الوكالات قدرة على تحديد وتصحيح الثغرات الأمنية في مشاريع Flutter/Dart، مما يضمن التعامل الآمن مع البيانات الحساسة للمستخدم وواجهات برمجة التطبيقات من خلال مبادئ مثل إدارة الأسرار وتعامل مفتاح واجهة برمجة التطبيقات الآمن."},"useCases":{"en":["Auditing Flutter/Dart projects for security vulnerabilities","Implementing secure authentication and authorization mechanisms","Validating API key and secret management practices"],"zh":["审计 Flutter/Dart 项目以发现安全漏洞","实施安全的认证和授权机制","验证 API 密钥和密钥管理实践"],"ja":["セキュリティ脆弱性のある Flutter/Dart プロジェクトの監査","セキュアな認証および認可メカニズムの実装","API キーおよびシークレット管理の実践の検証"],"ko":["보안 취약성 있는 Flutter/Dart 프로젝트의 감사","안전한 인증 및 인가 메커니즘의 구현","API 키 및 비밀키 관리 관행의 검증"],"es":["Auditoría de proyectos Flutter/Dart para vulnerabilidades de seguridad","Implementación de mecanismos de autenticación y autorización seguros","Validación de prácticas de gestión de claves de API y secretos"],"fr":["Audit de projets Flutter/Dart pour les vulnérabilités de sécurité","Mise en œuvre de mécanismes d''authentification et d''autorisation sécurisés","Validation des pratiques de gestion des clés d''API et des secrets"],"de":["Prüfung von Flutter/Dart-Projekten auf Sicherheitsschwachstellen","Implementierung sicherer Authentifizierungs- und Autorisierungsmechanismen","Überprüfung der Verfahren für die Verwaltung von API-Schlüsseln und Geheimnissen"],"pt":["Auditoria de projetos Flutter/Dart para vulnerabilidades de segurança","Implementação de mecanismos de autenticação e autorização seguros","Validação de práticas de gerenciamento de chaves de API e segredos"],"ru":["Аудит проектов Flutter/Dart на предмет уязвимостей безопасности","Реализация безопасных механизмов аутентификации и авторизации","Проверка практик управления ключами API и секретами"],"ar":["تدقيق مشاريع Flutter/Dart للثغرات الأمنية","تنفيذ آليات التحقق والتصريح الآمن","التحقق من ممارسات إدارة مفتاح واجهة برمجة التطبيقات والأسرار"]},"limitations":{"en":["Requires knowledge of Flutter/Dart ecosystem","Limited to Flutter/Dart projects","Needs access to project codebase for comprehensive analysis"],"zh":["需要 Flutter/Dart 生态系统的知识","仅限 Flutter/Dart 项目","需要访问项目代码库以进行全面分析"],"ja":["Flutter/Dart エコシステムの知識が必要","Flutter/Dart プロジェクトに限定される","包括的な分析のためにプロジェクトコードベースへのアクセスが必要"],"ko":["Flutter/Dart 생태계에 대한 지식이 필요","Flutter/Dart 프로젝트에만 국한","종합적인 분석을 위해 프로젝트 코드베이스에 대한 액세스가 필요"],"es":["Requiere conocimiento del ecosistema Flutter/Dart","Limitado a proyectos Flutter/Dart","Necesita acceso a la base de código del proyecto para un análisis integral"],"fr":["Nécessite des connaissances de l''écosystème Flutter/Dart","Limité aux projets Flutter/Dart","Nécessite l''accès à la base de code du projet pour une analyse complète"],"de":["Benötigt Kenntnisse des Flutter/Dart-Ökosystems","Begrenzt auf Flutter/Dart-Projekte","Benötigt Zugriff auf den Codebestand des Projekts für eine umfassende Analyse"],"pt":["Exige conhecimento do ecossistema Flutter/Dart","Limitado a projetos Flutter/Dart","Necessita acesso à base de código do projeto para análise abrangente"],"ru":["Требует знания экосистемы Flutter/Dart","Ограничен проектами Flutter/Dart","Требует доступа к кодовой базе проекта для комплексного анализа"],"ar":["يتطلب معرفة ببيئة Flutter/Dart","محدود بمشاريع Flutter/Dart","يحتاج إلى الوصول إلى قاعدة الشفرة للمشروع للتحليل الشامل"]},"version":4},"contentHash":"27402cf3a6d37ec8d4b52522f8b673e3305822697c5525cf3a68676355466725","qualityScore":36}');
