INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mywaffles/ai-backup-mac/obsidian-cli', 'obsidian-cli', 'mywaffles', 'ai-backup-mac', 'community', 'obsidian-cli mywaffles ai-backup-mac community The obsidian-cli skill provides AI automation tools and config backups for Mac Mini M4, allowing developers to interact with Obsidian instances via the command line. Obsidian CLI 是一个命令行工具，用于与运行中的 Obsidian 实例交互 Obsidian CLI は、実行中の Obsidian インスタンスと対話するためのコマンドラインツール Obsidian CLI 는 실행 중인 Obsidian 인스턴스와 상호 작용하기 위한 명령줄 도구 Obsidian CLI es una herramienta de línea de comandos para interactuar con instancias de Obsidian en ejecución. Requiere que Obsidian esté abierto. Obsidian CLI est un outil de ligne de commande pour interagir avec des instances Obsidian en cours d''exécution. Obsidian doit être ouvert. Obsidian CLI ist ein Kommandozeilen-Tool, um mit laufenden Obsidian-Instanzen zu interagieren. Obsidian muss geöffnet sein. O Obsidian-CLI é uma ferramenta de linha de comando para interagir com instâncias em execução do Obsidian, permitindo automação de tarefas e backups de configuração. Obsidian-CLI — это командная строка для взаимодействия с запущенными экземплярами Obsidian, позволяющая автоматизировать задачи и создавать резервные копии конфигураций. Obsidian-CLI هو أداة سطر أوامر لتفاعل مع مثيلات Obsidian التي تعمل، مما يسمح بتحسين أداء تلقائي للمهام وتخزين نسخة احتياطية من الإعدادات. how to use obsidian-cli obsidian-cli setup guide obsidian-cli alternative obsidian-cli vs other automation tools obsidian-cli install what is obsidian-cli obsidian-cli command reference obsidian-cli automation examples Obsidian CLI AI 工具 命令行工具 配置备份 Mac Mini M4 Obsidian 开发效率 命令行交互 Run `obsidian help` to access the full list of available commands Use parameters with `=` and quote values with spaces for precise control Utilize flags as boolean switches with no value for flexible automation Create new notes with `obsidian create` and specify name and content Access full documentation at https://help.obsidian.md/cli for advanced usage obsidian-cli is a command-line interface for interacting with Obsidian instances, enabling automation and customization of workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('uygnoey/autonomous-dev-agent-ts/dev-agent-orchestration', 'community', 'uygnoey', 'autonomous-dev-agent-ts', 'uygnoey/autonomous-dev-agent-ts', 'dev-agent-orchestration', 0, 0, 36, '2026-03-04T12:04:40Z', '2026-03-07T04:13:23.394Z', 'd2eb8bd918273dc19c3ca7de2142896ee61df83855ef32a772e8592d2e205910', '{"id":"uygnoey/autonomous-dev-agent-ts/dev-agent-orchestration","name":"dev-agent-orchestration","description":{"en":"dev-agent-orchestration is a system that automates the development cycle using Claude Agent SDK V2 and RAG, benefiting developers by streamlining design, code, test, and verification phases.","zh":"dev-agent-orchestration是一种自主开发代理系统，使用Claude Agent SDK和RAG实现设计、编码、测试和验证的自动化","ja":"dev-agent-orchestrationは、Claude Agent SDKとRAGを使用して設計、コード、テスト、検証を自動化する自律的な開発エージェントシステムです","ko":"dev-agent-orchestration은 Claude Agent SDK와 RAG 기반의 자율 개발 에이전트 시스템으로 설계부터 검증까지 전체 개발 사이클을 자율적으로 수행합니다","es":"dev-agent-orchestration es un sistema de agente de desarrollo autónomo basado en Claude Agent SDK y RAG que automatiza el ciclo de desarrollo","fr":"dev-agent-orchestration est un système d''agent de développement autonome basé sur Claude Agent SDK et RAG qui automatise le cycle de développement","de":"dev-agent-orchestration ist ein autonomes Entwicklungsagenten-System basierend auf Claude Agent SDK und RAG, das den Entwicklungszyklus automatisiert","pt":"O dev-agent-orchestration é um sistema de agentes autônomos que executa todo o ciclo de desenvolvimento com Claude Agent SDK e RAG.","ru":"dev-agent-orchestration - это система автономных агентов, которая выполняет весь цикл разработки с помощью ИИ Агентов и RAG.","ar":"dev-agent-orchestration هو نظام وكلاء自ونی یقوم بتنفیذ کل دورة التطوير باستخدام وكلاء إيه إيه و RAG."},"seo":{"title":{"en":"dev-agent-orchestration: Autonomous Development Workflow ...","zh":"开发智能代理编排设置指南","ja":"AIエージェントのオーケストレーションセットアップガイド","ko":"dev-agent-orchestration 설정 가이드","es":"Guía de configuración de dev-agent-orchestration para des...","fr":"Mise en place de dev-agent-orchestration pour les dévelop...","de":"Einrichtungsleitfaden für dev-agent-orchestration für Ent...","pt":"Guia de Configuração do dev-agent-orchestration para Dese...","ru":"Настройка dev-agent-orchestration: ИИ Агенты для Автомати...","ar":"دليل إعداد dev-agent-orchestration لتنفيذ وكلاء إيه إيه"},"description":{"en":"Discover how dev-agent-orchestration streamlines development cycles with Claude Agent SDK V2 and RAG. Learn to set up autonomous development workflows now!","zh":"了解如何使用Claude Agent SDK和RAG实现自主开发代理系统，自动执行整个开发周期","ja":"Claude Agent SDKとRAGを使用して自律的な開発エージェントシステムを実現し、開発サイクル全体を自動化する方法を学びます","ko":"Claude Agent SDK와 RAG 기반의 자율 개발 에이전트 시스템을 구축하여 전체 개발 사이클을 자동화하는 방법","es":"Aprende a utilizar dev-agent-orchestration con Claude Agent SDK y RAG para automatizar el ciclo de desarrollo","fr":"Découvrez comment utiliser dev-agent-orchestration avec Claude Agent SDK et RAG pour automatiser le cycle de développement","de":"Erfahren Sie, wie Sie dev-agent-orchestration mit Claude Agent SDK und RAG verwenden, um den Entwicklungszyklus zu automatisieren","pt":"Aprenda a configurar o dev-agent-orchestration com Claude Agent SDK e RAG para automação de desenvolvimento","ru":"Откройте возможности dev-agent-orchestration с ИИ Агентами и автоматизируйте процесс разработки","ar":"تعرف على كيفية إعداد dev-agent-orchestration مع وكلاء إيه إيه لتنفيذ تطبيقات ذكية"},"definition":{"en":"dev-agent-orchestration is an autonomous development agent system based on Claude Agent SDK V2 and RAG, executing entire development cycles through 7 specialized agents.","zh":"dev-agent-orchestration是一种使用Claude Agent SDK和RAG的自主开发代理系统","ja":"dev-agent-orchestrationは、Claude Agent SDKとRAGを使用した自律的な開発エージェントシステムです","ko":"dev-agent-orchestration은 Claude Agent SDK와 RAG 기반의 자율 개발 에이전트 시스템입니다","es":"dev-agent-orchestration es un sistema que utiliza Claude Agent SDK y RAG para automatizar el ciclo de desarrollo","fr":"dev-agent-orchestration est un système qui utilise Claude Agent SDK et RAG pour automatiser le cycle de développement","de":"dev-agent-orchestration ist ein System, das Claude Agent SDK und RAG verwendet, um den Entwicklungszyklus zu automatisieren","pt":"O que é dev-agent-orchestration? Um sistema de agentes autônomos para automação de desenvolvimento","ru":"Что такое dev-agent-orchestration? Система автономных агентов для автоматизации разработки","ar":"ما هو dev-agent-orchestration؟ نظام وكلاء tựونی لتنفيذ تطبيقات ذكية"},"features":{"en":["Utilizes unstable_v2_createSession() for session creation and session.stream() for execution","Employs hooks for monitoring and supports different execution methods per phase","Executes DESIGN phase with session.stream() and Agent Teams environment activation","Performs CODE phase with unstable_v2_prompt() using Promise.all for concurrent execution","Runs TEST/VERIFY phase with sequential unstable_v2_prompt() execution","Configures with settingSources and permissionMode options for customized operation"],"zh":["使用Claude Agent SDK V2 Session API执行代理","支持设计、编码、测试和验证的自动化","使用unstable_v2_createSession()创建会话","使用session.stream()执行代理","使用hooks进行监控","支持Promise.all和顺序执行"],"ja":["Claude Agent SDK V2 Session APIを使用してエージェントを実行","設計、コード、テスト、検証の自動化をサポート","unstable_v2_createSession()を使用してセッションを作成","session.stream()を使用してエージェントを実行","hooksを使用して監視","Promise.allと順次実行をサポート"],"ko":["Claude Agent SDK V2 Session API를 사용하여 에이전트를 실행","설계, 코드, 테스트, 검증의 자동화를 지원","unstable_v2_createSession()를 사용하여 세션을 생성","session.stream()를 사용하여 에이전트를 실행","hooks를 사용하여 모니터링","Promise.all과 순차 실행을 지원"],"es":["Utiliza Claude Agent SDK V2 Session API para ejecutar agentes","Soporta la ejecución de 7 agentes especializados","Incorpora hooks para monitorear la ejecución de los agentes","Permite la creación de sesiones con unstable_v2_createSession()","Soporta la ejecución de agentes en paralelo con Promise.all"],"fr":["Utilise Claude Agent SDK V2 Session API pour exécuter les agents","Prend en charge l''exécution de 7 agents spécialisés","Intègre des hooks pour surveiller l''exécution des agents","Permet la création de sessions avec unstable_v2_createSession()","Prend en charge l''exécution d''agents en parallèle avec Promise.all"],"de":["Verwendet Claude Agent SDK V2 Session API, um Agenten auszuführen","Unterstützt die Ausführung von 7 spezialisierten Agenten","Integriert Hooks, um die Ausführung der Agenten zu überwachen","Ermöglicht die Erstellung von Sitzungen mit unstable_v2_createSession()","Unterstützt die Ausführung von Agenten in Parallel mit Promise.all"],"pt":["Execução autônoma do ciclo de desenvolvimento com 7 agentes especializados","Utilização do Claude Agent SDK V2 Session API para execução de agentes","Monitoramento com hooks e unstable_v2_createSession()","Suporte a DESIGN, CODE, TEST/VERIFY com execução diferenciada"],"ru":["Автономное выполнение цикла разработки с 7 специализированными агентами","Использование ИИ Агентов и RAG для автоматизации разработки","Мониторинг с помощью хуков и unstable_v2_createSession()","Поддержка DESIGN, CODE, TEST/VERIFY с различными режимами выполнения"],"ar":["تنفيذ tựونی لدورة التطوير مع 7 وكلاء متخصصين","استخدام وكلاء إيه إيه و RAG لتنفيذ تطبيقات ذكية","مراقبة باستخدام hooks و unstable_v2_createSession()","دعم DESIGN, CODE, TEST/VERIFY مع تنفيذ مختلف"]},"keywords":{"en":["dev-agent-orchestration setup guide","how to use Claude Agent SDK V2","RAG-based development workflows","autonomous development agent systems","dev-agent-orchestration vs traditional development methods","installing dev-agent-orchestration","what is dev-agent-orchestration","dev-agent-orchestration tutorial","dev-agent-orchestration best practices"],"zh":["开发智能代理","AI代理系统","Claude Agent SDK","RAG","自动化开发","设计自动化","代码自动化","测试自动化","验证自动化"],"ja":["AIエージェント","エージェントシステム","Claude Agent SDK","RAG","自動化開発","設計自動化","コード自動化","テスト自動化","検証自動化"],"ko":["개발 에이전트","AI 에이전트 시스템","Claude Agent SDK","RAG","자동화 개발","설계 자동화","코드 자동화","테스트 자동화","검증 자동화"],"es":["dev-agent-orchestration","Claude Agent SDK","RAG","agente de desarrollo autónomo","automatización del ciclo de desarrollo","desarrollo de software","herramientas de desarrollo","Agente AI","Herramientas de Agente AI"],"fr":["dev-agent-orchestration","Claude Agent SDK","RAG","agent de développement autonome","automatisation du cycle de développement","développement de logiciels","outils de développement","Agent IA","Outils d''Agent IA"],"de":["dev-agent-orchestration","Claude Agent SDK","RAG","autonomer Entwicklungsagent","Automatisierung des Entwicklungszyklus","Softwareentwicklung","Entwicklungstools","KI-Agent","KI-Tool"],"pt":["dev-agent-orchestration","Claude Agent SDK","RAG","automação de desenvolvimento","agentes autônomos","desenvolvimento de software"],"ru":["dev-agent-orchestration","ИИ Агенты","RAG","автоматизация разработки","автономные агенты","разработка программного обеспечения"],"ar":["dev-agent-orchestration","وكلاء إيه إيه","RAG","تنفيذ تطبيقات ذكية","وكلاء tựونی","تطوير البرمجيات"]}},"owner":"uygnoey","repo":"autonomous-dev-agent-ts","repoPath":"uygnoey/autonomous-dev-agent-ts","stars":0,"forks":0,"updatedAt":"2026-03-04T12:04:40Z","topics":[],"category":"community","skillMd":{"name":"dev-agent-orchestration","description":"SDK V2 Session API 기반 에이전트 오케스트레이션 패턴. layer2 코드 구현 시 참조.","bodyPreview":"# 에이전트 오케스트레이션\n\nadev의 2계층은 Claude Agent SDK V2 Session API를 사용하여 에이전트를 실행한다.\n\n## 핵심 패턴\n\nunstable_v2_createSession()으로 세션 생성 → session.stream()으로 실행 + hooks로 모니터링.\n\nPhase별 실행 방식이 다르다:\n- DESIGN: session.stream() 1개 + Agent Teams env 활성화 (팀 토론)\n- CODE: unstable_v2_prompt() ×N 동시 (Promise.all)\n- TEST/VERIFY: unstable_v2_prompt() 순차\n\n## 필수 옵션\n\n```typescript\n{\n  settingSources: [],              // 파일시스템 설정 의존 없음\n  permissionMode: ''bypassPermissions'',  // 자율 운영\n  env: { \"CLAUDE_CODE_EXPERIMENTAL_AGENT_","body":"# 에이전트 오케스트레이션\n\nadev의 2계층은 Claude Agent SDK V2 Session API를 사용하여 에이전트를 실행한다.\n\n## 핵심 패턴\n\nunstable_v2_createSession()으로 세션 생성 → session.stream()으로 실행 + hooks로 모니터링.\n\nPhase별 실행 방식이 다르다:\n- DESIGN: session.stream() 1개 + Agent Teams env 활성화 (팀 토론)\n- CODE: unstable_v2_prompt() ×N 동시 (Promise.all)\n- TEST/VERIFY: unstable_v2_prompt() 순차\n\n## 필수 옵션\n\n```typescript\n{\n  settingSources: [],              // 파일시스템 설정 의존 없음\n  permissionMode: ''bypassPermissions'',  // 자율 운영\n  env: { \"CLAUDE_CODE_EXPERIMENTAL_AGENT_TEAMS\": \"1\" },  // DESIGN에서만\n  allowedTools: [''Read'', ''Write'', ''Edit'', ''Bash'', ''Glob'', ''Grep''],\n}\n```\n\n## Hook 기반 모니터링\n\n```typescript\nconst hooks = {\n  preToolUse: async (event) => { /* 도구 호출 전 검증 */ },\n  postToolUse: async (event) => { /* 도구 호출 후 기록 */ },\n  teammateIdle: async (event) => { /* 팀원 유휴 감지 */ },\n};\n```\n\n상세 패턴: `references/v2-session-pattern.md`\n알려진 이슈: `references/known-issues.md`\n"},"lastSynced":"2026-03-07T04:13:23.394Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents requiring streamlined development cycles, such as those built with Claude Agent SDK V2 and RAG","zh":"适用于需要简化开发周期的AI代理，例如使用Claude Agent SDK V2和RAG构建的代理","ja":"Claude Agent SDK V2とRAGで構築されたエージェントなど、開発サイクルをストリームライン化する必要があるAIエージェントに適しています","ko":"클라우드 에이전트 SDK V2와 RAG로 구축된 에이전트와 같은 개발 주기 스트림 라인을 요구하는 AI 에이전트에 적합합니다","es":"Ideal para agentes de IA que requieren ciclos de desarrollo optimizados, como aquellos construidos con Claude Agent SDK V2 y RAG","fr":"Idéal pour les agents IA nécessitant des cycles de développement rationalisés, tels que ceux construits avec Claude Agent SDK V2 et RAG","de":"Ideal für KI-Agents, die optimierte Entwicklungszyklen erfordern, wie z.B. solche, die mit Claude Agent SDK V2 und RAG erstellt werden","pt":"Ideal para Agentes de IA que exigem ciclos de desenvolvimento otimizados, como aqueles construídos com Claude Agent SDK V2 e RAG","ru":"Идеально для агентов ИИ, требующих оптимизированных циклов разработки, таких как те, которые построены с помощью Claude Agent SDK V2 и RAG","ar":"مثالي لوكلاء الذكاء الاصطناعي الذين يحتاجون إلى دورات تطوير محسنة، مثل تلك التي تم بناؤها باستخدام Claude Agent SDK V2 و RAG"},"recommendation":{"en":"Empowers agents to automate design, code, test, and verification phases using unstable_v2_createSession and session.stream, while leveraging hooks for monitoring and Promise.all for concurrent execution, all within a permission-bypassed environment","zh":"通过使用unstable_v2_createSession和session.stream来实现设计、编码、测试和验证阶段的自动化，同时利用hooks进行监控和Promise.all进行并发执行，所有这些都在权限绕过的环境中进行","ja":"unstable_v2_createSessionとsession.streamを使用して設計、コード、テスト、検証の各段階を自動化し、hooksを使用して監視を行い、Promise.allを使用して並列実行を行う。これらはすべて、権限をバイパスした環境で実行されます","ko":"unstable_v2_createSession과 session.stream를 사용하여 디자인, 코드, 테스트 및 검증 단계를 자동화하고, hook을 사용하여 모니터링을 수행하며, Promise.all을 사용하여 동시 실행을 수행합니다. 모든 작업은 권한을 우회한 환경에서 수행됩니다.","es":"Permite a los agentes automatizar las fases de diseño, codificación, prueba y verificación utilizando unstable_v2_createSession y session.stream, al mismo tiempo que aprovecha los hooks para la supervisión y Promise.all para la ejecución concurrente, todo dentro de un entorno que omite permisos","fr":"Permet aux agents d''automatiser les phases de conception, de codage, de test et de vérification en utilisant unstable_v2_createSession et session.stream, tout en exploitant les hooks pour la surveillance et Promise.all pour l''exécution concurrente, le tout dans un environnement qui ignore les autorisations","de":"Ermöglicht es den Agents, die Phasen des Designs, der Codierung, der Überprüfung und der Verifizierung mithilfe von unstable_v2_createSession und session.stream zu automatisieren, während gleichzeitig die Hooks für die Überwachung und Promise.all für die parallele Ausführung genutzt werden, all dies in einer Umgebung, die die Bypassing-Berechtigungen umgeht","pt":"Habilita os agentes a automatizar as fases de design, código, teste e verificação usando unstable_v2_createSession e session.stream, aproveitando hooks para monitoramento e Promise.all para execução concorrente, tudo dentro de um ambiente com permissões ignoradas","ru":"Позволяет агентам автоматизировать фазы проектирования, кодирования, тестирования и верификации, используя unstable_v2_createSession и session.stream, используя хуки для мониторинга и Promise.all для параллельного выполнения, все в среде с обходом разрешений","ar":"تمكن الوكلاء من تutomation مراحل التصميم والкод والاختبار والتحقق باستخدام unstable_v2_createSession و session.stream، وتفويض hooks للرصد و Promise.all للتنفيذ المتزامن، كل ذلك في بيئة مع تجاوز الأذونات"},"useCases":{"en":["Automating development workflows with Claude Agent SDK V2 Session API","Streamlining design phases with session.stream and Agent Teams environment","Concurrently executing code generation tasks using unstable_v2_prompt and Promise.all"],"zh":["使用Claude Agent SDK V2 Session API自动化开发工作流程","使用session.stream和Agent Teams环境简化设计阶段","使用unstable_v2_prompt和Promise.all并发执行代码生成任务"],"ja":["Claude Agent SDK V2 Session APIを使用して開発ワークフローを自動化する","session.streamとAgent Teams環境を使用して設計段階をストリームライン化する","unstable_v2_promptとPromise.allを使用してコード生成タスクを並列実行する"],"ko":["클라우드 에이전트 SDK V2 세션 API를 사용하여 개발 워크플로우를 자동화하는 것","세션 스트림과 에이전트 팀 환경을 사용하여 디자인 단계를 간소화하는 것","unstable_v2_prompt와 Promise.all을 사용하여 코드 생성 작업을 동시 실행하는 것"],"es":["Automatizar flujos de trabajo de desarrollo con Claude Agent SDK V2 Session API","Optimizar fases de diseño con session.stream y entorno de Agent Teams","Ejecutar tareas de generación de código de forma concurrente utilizando unstable_v2_prompt y Promise.all"],"fr":["Automatiser les flux de travail de développement avec Claude Agent SDK V2 Session API","Rationaliser les phases de conception avec session.stream et l''environnement Agent Teams","Exécuter des tâches de génération de code de manière concurrente en utilisant unstable_v2_prompt et Promise.all"],"de":["Automatisieren von Entwicklungsworkflows mit Claude Agent SDK V2 Session API","Optimieren von Entwurfsphasen mit session.stream und Agent-Teams-Umgebung","Parallele Ausführung von Codegenerierungsaufgaben unter Verwendung von unstable_v2_prompt und Promise.all"],"pt":["Automatizar fluxos de trabalho de desenvolvimento com Claude Agent SDK V2 Session API","Otimizar fases de design com session.stream e ambiente do Agent Teams","Executar tarefas de geração de código de forma concorrente usando unstable_v2_prompt e Promise.all"],"ru":["Автоматизировать рабочие процессы разработки с помощью Claude Agent SDK V2 Session API","Оптимизировать фазы проектирования с помощью session.stream и среды Agent Teams","Выполнять задачи генерации кода параллельно, используя unstable_v2_prompt и Promise.all"],"ar":["توفير سير عمل التطوير مع واجهة برمجة تطبيقات الدورة الجلسة V2 للوكيل كلود","تحسين مراحل التصميم باستخدام session.stream وبيئة فرق الوكيل","تنفيذ مهام توليد الكود المتزامن باستخدام unstable_v2_prompt و Promise.all"]},"limitations":{"en":["Requires Claude Agent SDK V2 and RAG setup","Needs permissionMode set to ''bypassPermissions'' for autonomous operation","Dependent on specific environment variables like CLAUDE_CODE_EXPERIMENTAL_AGENT"],"zh":["需要Claude Agent SDK V2和RAG设置","需要将permissionMode设置为''bypassPermissions''以实现自主操作","依赖于特定的环境变量，如CLAUDE_CODE_EXPERIMENTAL_AGENT"],"ja":["Claude Agent SDK V2とRAGの設定が必要","permissionModeを''bypassPermissions''に設定して自律操作を行う必要がある","特定の環境変数（CLAUDE_CODE_EXPERIMENTAL_AGENTなど）に依存する"],"ko":["클라우드 에이전트 SDK V2와 RAG 설정이 필요합니다","permissionMode를 ''bypassPermissions''로 설정하여 자율 작동을 수행해야 합니다","특정 환경 변수 (CLAUDE_CODE_EXPERIMENTAL_AGENT 등)에 의존합니다"],"es":["Requiere la configuración de Claude Agent SDK V2 y RAG","Necesita que el modo de permisos esté establecido en ''bypassPermissions'' para la operación autónoma","Dependiente de variables de entorno específicas como CLAUDE_CODE_EXPERIMENTAL_AGENT"],"fr":["Nécessite la configuration de Claude Agent SDK V2 et RAG","Nécessite que le mode d''autorisation soit défini sur ''bypassPermissions'' pour le fonctionnement autonome","Dépend de variables d''environnement spécifiques comme CLAUDE_CODE_EXPERIMENTAL_AGENT"],"de":["Benötigt die Konfiguration von Claude Agent SDK V2 und RAG","Benötigt, dass der Berechtigungsmodus auf ''bypassPermissions'' für den autonomen Betrieb festgelegt wird","Abhängig von bestimmten Umgebungsvariablen wie CLAUDE_CODE_EXPERIMENTAL_AGENT"],"pt":["Exige configuração do Claude Agent SDK V2 e RAG","Necessita permissionMode definido como ''bypassPermissions'' para operação autônoma","Depende de variáveis de ambiente específicas, como CLAUDE_CODE_EXPERIMENTAL_AGENT"],"ru":["Требует настройки Claude Agent SDK V2 и RAG","Требует permissionMode, установленного на ''bypassPermissions'', для автономной работы","Зависит от определенных переменных среды, таких как CLAUDE_CODE_EXPERIMENTAL_AGENT"],"ar":["يتطلب إعداد كلود ووكيل SDK V2 و RAG","يحتاج إلى permissionMode معين على ''bypassPermissions'' للتشغيل المستقل","يعتمد على متغيرات بيئة محددة، مثل CLAUDE_CODE_EXPERIMENTAL_AGENT"]},"version":4},"contentHash":"d2eb8bd918273dc19c3ca7de2142896ee61df83855ef32a772e8592d2e205910","qualityScore":36}');
