INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('uygnoey/autonomous-dev-agent-ts/dev-agent-orchestration', 'dev-agent-orchestration', 'uygnoey', 'autonomous-dev-agent-ts', 'community', 'dev-agent-orchestration uygnoey autonomous-dev-agent-ts community dev-agent-orchestration is a system that automates the development cycle using Claude Agent SDK V2 and RAG, benefiting developers by streamlining design, code, test, and verification phases. dev-agent-orchestration是一种自主开发代理系统，使用Claude Agent SDK和RAG实现设计、编码、测试和验证的自动化 dev-agent-orchestrationは、Claude Agent SDKとRAGを使用して設計、コード、テスト、検証を自動化する自律的な開発エージェントシステムです dev-agent-orchestration은 Claude Agent SDK와 RAG 기반의 자율 개발 에이전트 시스템으로 설계부터 검증까지 전체 개발 사이클을 자율적으로 수행합니다 dev-agent-orchestration es un sistema de agente de desarrollo autónomo basado en Claude Agent SDK y RAG que automatiza el ciclo de desarrollo dev-agent-orchestration est un système d''agent de développement autonome basé sur Claude Agent SDK et RAG qui automatise le cycle de développement dev-agent-orchestration ist ein autonomes Entwicklungsagenten-System basierend auf Claude Agent SDK und RAG, das den Entwicklungszyklus automatisiert O dev-agent-orchestration é um sistema de agentes autônomos que executa todo o ciclo de desenvolvimento com Claude Agent SDK e RAG. dev-agent-orchestration - это система автономных агентов, которая выполняет весь цикл разработки с помощью ИИ Агентов и RAG. dev-agent-orchestration هو نظام وكلاء自ونی یقوم بتنفیذ کل دورة التطوير باستخدام وكلاء إيه إيه و RAG. dev-agent-orchestration setup guide how to use Claude Agent SDK V2 RAG-based development workflows autonomous development agent systems dev-agent-orchestration vs traditional development methods installing dev-agent-orchestration what is dev-agent-orchestration dev-agent-orchestration tutorial dev-agent-orchestration best practices 开发智能代理 AI代理系统 Claude Agent SDK RAG 自动化开发 设计自动化 代码自动化 测试自动化 验证自动化 Utilizes unstable_v2_createSession() for session creation and session.stream() for execution Employs hooks for monitoring and supports different execution methods per phase Executes DESIGN phase with session.stream() and Agent Teams environment activation Performs CODE phase with unstable_v2_prompt() using Promise.all for concurrent execution Runs TEST/VERIFY phase with sequential unstable_v2_prompt() execution Configures with settingSources and permissionMode options for customized operation dev-agent-orchestration is an autonomous development agent system based on Claude Agent SDK V2 and RAG, executing entire development cycles through 7 specialized agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('iwbc-mzk/obsidian/obsidian-cli', 'community', 'iwbc-mzk', 'obsidian', 'iwbc-mzk/obsidian', 'obsidian-cli', 0, 0, 36, '2026-03-04T13:04:16Z', '2026-03-07T13:10:34.309Z', 'b54257cdc0e5d04488b35b0c797bfe427b24359f0848d3c73924dcacf8da6358', '{"id":"iwbc-mzk/obsidian/obsidian-cli","name":"obsidian-cli","description":{"en":"The obsidian-cli skill allows developers to interact with a running Obsidian instance using the command line. It provides a range of commands for creating and managing notes.","zh":"Obsidian CLI 是一种命令行工具，用于与运行中的 Obsidian 实例交互。它提供了一系列命令来创建、管理和操作 Obsidian 笔记","ja":"Obsidian CLI は、実行中の Obsidian インスタンスと相互作用するためのコマンドラインツールです。Obsidian ノートを作成、管理、および操作するためのコマンドセットを提供します","ko":"Obsidian CLI는 실행 중인 Obsidian 인스턴스와 상호 작용하기 위한 명령줄 도구입니다. Obsidian 노트를 생성, 관리 및操作하기 위한 명령어 세트를 제공합니다","es":"La línea de comandos de Obsidian permite a los desarrolladores interactuar con instancias de Obsidian. Ofrece comandos como ''create'' y ''help'' con parámetros y opciones","fr":"La ligne de commande Obsidian permet aux développeurs d''interagir avec les instances Obsidian. Elle propose des commandes telles que ''create'' et ''help'' avec des paramètres et des options","de":"Die Obsidian-CLI ermöglicht es Entwicklern, mit Obsidian-Instanzen zu interagieren. Sie bietet Befehle wie ''create'' und ''help'' mit Parametern und Optionen","pt":"O Obsidian-CLI é uma ferramenta de linha de comando para interagir com instâncias do Obsidian. Requer o Obsidian estar aberto.","ru":"Obsidian-CLI - это инструмент командной строки для взаимодействия с экземплярами Obsidian. Требуется открыть Obsidian.","ar":"Obsidian-CLI هو أداة سطر أوامر للتفاعل مع مثيلات Obsidian. يتطلب فتح Obsidian."},"seo":{"title":{"en":"obsidian-cli: Command Line Interface Setup Guide | AI Age...","zh":"Obsidian CLI 设置指南 - 使用命令行工具与 Obsidian 交互","ja":"Obsidian CLI Setup Guide - Obsidian と相互作用するためのコマンドラインツール","ko":"Obsidian CLI 설정 가이드 - Obsidian과 상호 작용하기 위한 명령줄 도구","es":"Guía de configuración de Obsidian CLI para desarrolladores","fr":"Guide de démarrage rapide pour Obsidian CLI","de":"Obsidian CLI-Setup-Anleitung für Entwickler","pt":"Guia de Configuração do Obsidian-CLI: Ferramenta de Linha...","ru":"Настройка Obsidian-CLI: Инструмент командной строки для И...","ar":"دليل إعداد Obsidian-CLI: أداة سطر الأوامر للوكلاء الذكيين"},"description":{"en":"Unlock Obsidian''s full potential with the obsidian-cli. Learn how to interact with your Obsidian instance via the command line and streamline your workflow. ...","zh":"了解如何使用 Obsidian CLI 与 Obsidian 实例交互，包括命令参考、语法和示例","ja":"Obsidian インスタンスと相互作用するための Obsidian CLI の使用方法について学びます。コマンドリファレンス、構文、例を含みます","ko":"Obsidian 인스턴스와 상호 작용하기 위한 Obsidian CLI 사용 방법을 알아보세요. 명령 참조, 구문 및 예제 포함","es":"Aprende a utilizar la línea de comandos de Obsidian para interactuar con instancias de Obsidian. Descubre los comandos disponibles y la sintaxis","fr":"Découvrez comment utiliser la ligne de commande Obsidian pour interagir avec les instances Obsidian. Consultez les commandes disponibles et la syntaxe","de":"Erfahren Sie, wie Sie die Obsidian-CLI verwenden, um mit Obsidian-Instanzen zu interagieren. Entdecken Sie die verfügbaren Befehle und die Syntax","pt":"Aprenda a utilizar o Obsidian-CLI para interagir com instâncias do Obsidian. Veja a documentação completa e os comandos disponíveis.","ru":"Узнайте, как использовать Obsidian-CLI для взаимодействия с экземплярами Obsidian. Просмотрите полную документацию и доступные команды.","ar":"تعلم كيفية استخدام Obsidian-CLI للتفاعل مع مثيلات Obsidian. استعرض الوثائق الكاملة والأوامر المتاحة."},"definition":{"en":"obsidian-cli is a command line interface for interacting with Obsidian, a note-taking and knowledge management tool.","zh":"Obsidian CLI 是一种用于与 Obsidian 交互的命令行工具","ja":"Obsidian CLI は、Obsidian と相互作用するためのコマンドラインツールです","ko":"Obsidian CLI는 Obsidian과 상호 작용하기 위한 명령줄 도구입니다","es":"La herramienta de línea de comandos de Obsidian es una interfaz de línea de comandos para interactuar con instancias de Obsidian","fr":"L''outil de ligne de commande Obsidian est une interface de ligne de commande pour interagir avec les instances Obsidian","de":"Das Obsidian-CLI-Tool ist eine Kommandozeilen-Schnittstelle zur Interaktion mit Obsidian-Instanzen","pt":"O que é Obsidian-CLI? É uma ferramenta de linha de comando para interagir com o Obsidian.","ru":"Что такое Obsidian-CLI? Это инструмент командной строки для взаимодействия с Obsidian.","ar":"ما هو Obsidian-CLI؟ هو أداة سطر أوامر للتفاعل مع Obsidian."},"features":{"en":["Run `obsidian help` to see all available commands","Use `obsidian create` to create new notes with custom names and content","Utilize parameters with `=` and quote values with spaces","Employ flags as boolean switches with no value","Access full documentation at https://help.obsidian.md/cli"],"zh":["支持创建和管理 Obsidian 笔记","提供命令参考和语法指导","支持使用参数和标志自定义命令","可与运行中的 Obsidian 实例交互","支持使用silent和overwrite标志控制命令行为"],"ja":["Obsidian ノートの作成と管理をサポート","コマンドリファレンスと構文ガイドを提供","パラメータとフラグを使用したコマンドのカスタマイズをサポート","実行中の Obsidian インスタンスと相互作用","silent と overwrite フラグを使用したコマンドの動作の制御をサポート"],"ko":["Obsidian 노트의 생성과 관리를 지원","명령 참조와 구문 가이드를 제공","매개변수와 플래그를 사용한 명령의 사용자 정의를 지원","실행 중인 Obsidian 인스턴스와 상호 작용","silent와 overwrite 플래그를 사용한 명령의 동작 제어를 지원"],"es":["Soporte para parámetros con valores mediante ''=''","Opción para citar valores con espacios","Comando ''create'' para crear notas","Comando ''help'' para ver la ayuda","Opción ''silent'' para suprimir la salida","Opción ''overwrit'' para sobrescribir notas existentes"],"fr":["Prise en charge des paramètres avec des valeurs via ''=''","Option pour citer les valeurs avec des espaces","Commande ''create'' pour créer des notes","Commande ''help'' pour afficher l''aide","Option ''silent'' pour supprimer la sortie","Option ''overwrit'' pour écraser les notes existantes"],"de":["Unterstützung für Parameter mit Werten über ''=''","Option, Werte mit Leerzeichen zu zitieren","Befehl ''create'', um Notizen zu erstellen","Befehl ''help'', um die Hilfe anzuzeigen","Option ''silent'', um die Ausgabe zu unterdrücken","Option ''overwrit'', um vorhandene Notizen zu überschreiben"],"pt":["Parâmetros com valores atribuídos com ''=''","Comandos com flags booleanos","Criação de notas com conteúdo personalizado","Suporte à documentação completa em https://help.obsidian.md/cli","Comando ''obsidian help'' para visualizar comandos disponíveis"],"ru":["Параметры с значениями, присвоенными с ''=''","Команды с булевыми флагами","Создание заметок с пользовательским содержимым","Поддержка полной документации на https://help.obsidian.md/cli","Команда ''obsidian help'' для просмотра доступных команд"],"ar":["معلمات مع قيم معينة بواسطة ''=''","أوامر مع أعلام منطقية","إنشاء ملاحظات مع محتوى مخصص","دعم الوثائق الكاملة على https://help.obsidian.md/cli","أمر ''obsidian help'' لعرض الأوامر المتاحة"]},"keywords":{"en":["how to use obsidian-cli","obsidian-cli setup guide","obsidian-cli alternative","obsidian-cli vs other note-taking tools","obsidian-cli install","what is obsidian-cli","obsidian-cli commands","obsidian-cli documentation","obsidian-cli tutorial"],"zh":["Obsidian CLI","命令行工具","Obsidian 交互","笔记创建","命令参考","语法指导","AI エージェント","CLI 工具"],"ja":["Obsidian CLI","コマンドラインツール","Obsidian 相互作用","ノート作成","コマンドリファレンス","構文ガイド","AIエージェント","CLIツール"],"ko":["Obsidian CLI","명령줄 도구","Obsidian 상호 작용","노트 생성","명령 참조","구문 가이드","AI 에이전트","CLI 도구"],"es":["obsidian cli","herramientas de línea de comandos","desarrollo de software","interfaz de línea de comandos","parámetros y opciones","comandos de ayuda","creación de notas","supresión de salida"],"fr":["obsidian cli","outils de ligne de commande","développement de logiciels","interface de ligne de commande","paramètres et options","commandes d''aide","création de notes","suppression de sortie"],"de":["obsidian cli","kommandozeilen-tools","software-entwicklung","kommandozeilen-schnittstelle","parameter und optionen","hilfebefehle","erstellung von notizen","unterdrückung der ausgabe"],"pt":["Obsidian-CLI","ferramenta de linha de comando","interação com Obsidian","parâmetros e flags","criação de notas","documentação Obsidian","comando obsidian help","CLI para desenvolvedores"],"ru":["Obsidian-CLI","инструмент командной строки","взаимодействие с Obsidian","параметры и флаги","создание заметок","документация Obsidian","команда obsidian help","CLI для разработчиков","ИИ Агенты"],"ar":["Obsidian-CLI","أداة سطر الأوامر","التفاعل مع Obsidian","معلمات وأعلام","إنشاء ملاحظات","وثائق Obsidian","أمر obsidian help","CLI للمطورين","الوكلاء الذكيين"]}},"owner":"iwbc-mzk","repo":"obsidian","repoPath":"iwbc-mzk/obsidian","stars":0,"forks":0,"updatedAt":"2026-03-04T13:04:16Z","topics":[],"category":"community","skillMd":{"name":"obsidian-cli","description":"Interact with Obsidian vaults using the Obsidian CLI to read, create, search, and manage notes, tasks, properties, and more. Also supports plugin and theme development with commands to reload plugins, run JavaScript, capture errors, take screenshots, and inspect the DOM. Use when the user asks to interact with their Obsidian vault, manage notes, search vault content, perform vault operations from the command line, or develop and debug Obsidian plugins and themes.","bodyPreview":"# Obsidian CLI\n\nUse the `obsidian` CLI to interact with a running Obsidian instance. Requires Obsidian to be open.\n\n## Command reference\n\nRun `obsidian help` to see all available commands. This is always up to date. Full docs: https://help.obsidian.md/cli\n\n## Syntax\n\n**Parameters** take a value with `=`. Quote values with spaces:\n\n```bash\nobsidian create name=\"My Note\" content=\"Hello world\"\n```\n\n**Flags** are boolean switches with no value:\n\n```bash\nobsidian create name=\"My Note\" silent overwrit","body":"# Obsidian CLI\n\nUse the `obsidian` CLI to interact with a running Obsidian instance. Requires Obsidian to be open.\n\n## Command reference\n\nRun `obsidian help` to see all available commands. This is always up to date. Full docs: https://help.obsidian.md/cli\n\n## Syntax\n\n**Parameters** take a value with `=`. Quote values with spaces:\n\n```bash\nobsidian create name=\"My Note\" content=\"Hello world\"\n```\n\n**Flags** are boolean switches with no value:\n\n```bash\nobsidian create name=\"My Note\" silent overwrite\n```\n\nFor multiline content use `\\n` for newline and `\\t` for tab.\n\n## File targeting\n\nMany commands accept `file` or `path` to target a file. Without either, the active file is used.\n\n- `file=<name>` — resolves like a wikilink (name only, no path or extension needed)\n- `path=<path>` — exact path from vault root, e.g. `folder/note.md`\n\n## Vault targeting\n\nCommands target the most recently focused vault by default. Use `vault=<name>` as the first parameter to target a specific vault:\n\n```bash\nobsidian vault=\"My Vault\" search query=\"test\"\n```\n\n## Common patterns\n\n```bash\nobsidian read file=\"My Note\"\nobsidian create name=\"New Note\" content=\"# Hello\" template=\"Template\" silent\nobsidian append file=\"My Note\" content=\"New line\"\nobsidian search query=\"search term\" limit=10\nobsidian daily:read\nobsidian daily:append content=\"- [ ] New task\"\nobsidian property:set name=\"status\" value=\"done\" file=\"My Note\"\nobsidian tasks daily todo\nobsidian tags sort=count counts\nobsidian backlinks file=\"My Note\"\n```\n\nUse `--copy` on any command to copy output to clipboard. Use `silent` to prevent files from opening. Use `total` on list commands to get a count.\n\n## Plugin development\n\n### Develop/test cycle\n\nAfter making code changes to a plugin or theme, follow this workflow:\n\n1. **Reload** the plugin to pick up changes:\n   ```bash\n   obsidian plugin:reload id=my-plugin\n   ```\n2. **Check for errors** — if errors appear, fix and repeat from step 1:\n   ```bash\n   obsidian dev:errors\n   ```\n3. **Verify visually** with a screenshot or DOM inspection:\n   ```bash\n   obsidian dev:screenshot path=screenshot.png\n   obsidian dev:dom selector=\".workspace-leaf\" text\n   ```\n4. **Check console output** for warnings or unexpected logs:\n   ```bash\n   obsidian dev:console level=error\n   ```\n\n### Additional developer commands\n\nRun JavaScript in the app context:\n\n```bash\nobsidian eval code=\"app.vault.getFiles().length\"\n```\n\nInspect CSS values:\n\n```bash\nobsidian dev:css selector=\".workspace-leaf\" prop=background-color\n```\n\nToggle mobile emulation:\n\n```bash\nobsidian dev:mobile on\n```\n\nRun `obsidian help` to see additional developer commands including CDP and debugger controls.\n"},"lastSynced":"2026-03-07T13:10:34.309Z","agentAnalysis":{"suitability":{"en":"Perfect for Note-Taking Agents needing advanced Obsidian instance management via command line interface.","zh":"非常适合需要高级 Obsidian 实例管理的笔记记录代理，通过命令行接口实现管理。","ja":"Obsidian インスタンスの高度な管理が必要なノートテイクエージェントに最適です。コマンドラインインターフェイスを介して管理されます。","ko":"고급 Obsidian 인스턴스 관리가 필요한 노트 기록 에이전트에게 적합합니다. 명령줄 인터페이스를 통해 관리됩니다.","es":"Perfecto para agentes de toma de notas que necesitan una gestión avanzada de instancias de Obsidian a través de la interfaz de línea de comandos.","fr":"Parfait pour les agents de prise de notes nécessitant une gestion avancée d''instances Obsidian via l''interface de ligne de commande.","de":"Perfekt für Notiz-Agents, die eine erweiterte Instanzverwaltung von Obsidian über die Kommandozeilenoberfläche benötigen.","pt":"Perfeito para Agentes de Notas que precisam de gerenciamento avançado de instâncias do Obsidian via interface de linha de comando.","ru":"Идеально подходит для агентов заметок, которым требуется продвинутый менеджмент экземпляров Obsidian через командную строку.","ar":"مثالي للوكلاء الذين يحتاجون إلى إدارة متقدمة لمثيلات Obsidian عبر واجهة سطر الأوامر."},"recommendation":{"en":"Empowers agents to create and manage notes in Obsidian using commands like `obsidian create` with parameters and flags, enabling seamless interaction with the Obsidian instance, and leveraging the `obsidian help` command for up-to-date documentation.","zh":"赋予代理创建和管理 Obsidian 中的笔记的能力，使用诸如 `obsidian create` 的命令和参数以及标志，实现与 Obsidian 实例的无缝交互，并利用 `obsidian help` 命令获取最新的文档。","ja":"エージェントに Obsidian でノートを作成および管理する能力を与え、`obsidian create` のようなコマンドやパラメータとフラグを使用して Obsidian インスタンスとのシームレスなやり取りを実現し、`obsidian help` コマンドを使用して最新のドキュメントにアクセスします。","ko":"에이전트가 Obsidian에서 노트를 생성하고 관리하는 능력을 부여하며, `obsidian create`와 같은 명령 및 매개변수와 플래그를 사용하여 Obsidian 인스턴스와의 무결점 상호작용을 가능하게 하며, `obsidian help` 명령을 사용하여 최신 문서에 액세스합니다.","es":"Habilita a los agentes a crear y gestionar notas en Obsidian utilizando comandos como `obsidian create` con parámetros y banderas, lo que permite una interacción fluida con la instancia de Obsidian y aprovecha el comando `obsidian help` para documentación actualizada.","fr":"Permet aux agents de créer et de gérer des notes dans Obsidian en utilisant des commandes comme `obsidian create` avec des paramètres et des indicateurs, ce qui permet une interaction fluide avec l''instance Obsidian et tire parti de la commande `obsidian help` pour une documentation à jour.","de":"Ermächtigt Agents, Notizen in Obsidian zu erstellen und zu verwalten, indem sie Befehle wie `obsidian create` mit Parametern und Flags verwenden, was eine nahtlose Interaktion mit der Obsidian-Instanz ermöglicht und den `obsidian help`-Befehl für aktuelle Dokumentation nutzt.","pt":"Habilita os agentes a criar e gerenciar notas no Obsidian usando comandos como `obsidian create` com parâmetros e flags, permitindo interação sem problemas com o exemplo do Obsidian, e aproveitando o comando `obsidian help` para documentação atualizada.","ru":"Наделяет агентов возможностью создавать и управлять заметками в Obsidian с помощью команд типа `obsidian create` с параметрами и флагами, обеспечивая беспрепятственное взаимодействие с экземпляром Obsidian и используя команду `obsidian help` для получения самой актуальной документации.","ar":"يمنح الوكلاء القدرة على إنشاء وإدارة الملاحظات في Obsidian باستخدام أوامر مثل `obsidian create` مع المعلمات والflags، مما يسمح بالتفاعل السلس مع مثيل Obsidian، ويمكنهم الاستفادة من الأمر `obsidian help` للحصول على توثيق محدث."},"useCases":{"en":["Creating new notes with custom content","Managing existing notes using command line flags","Automating note creation workflows"],"zh":["使用自定义内容创建新笔记","使用命令行标志管理现有笔记","自动化笔记创建工作流"],"ja":["カスタムコンテンツで新しいノートを作成する","コマンドラインフラグを使用して既存のノートを管理する","ノート作成ワークフローを自動化する"],"ko":["사용자 정의 콘텐츠로 새로운 노트を作成하는 것","명령줄 플래그를 사용하여 기존 노트를 관리하는 것","노트 생성 워크플로를 자동화하는 것"],"es":["Creación de nuevas notas con contenido personalizado","Gestión de notas existentes utilizando indicadores de línea de comandos","Automatización de flujos de trabajo de creación de notas"],"fr":["Création de nouvelles notes avec un contenu personnalisé","Gestion de notes existantes à l''aide d''indicateurs de ligne de commande","Automatisation des flux de travail de création de notes"],"de":["Erstellung neuer Notizen mit benutzerdefiniertem Inhalt","Verwaltung bestehender Notizen unter Verwendung von Kommandozeilenflags","Automatisierung von Notiz-Erstellungsworkflows"],"pt":["Criar novas notas com conteúdo personalizado","Gerenciar notas existentes usando flags de linha de comando","Automatizar fluxos de trabalho de criação de notas"],"ru":["Создание новых заметок с пользовательским содержимым","Управление существующими заметками с помощью флагов командной строки","Автоматизация рабочих процессов создания заметок"],"ar":["إنشاء ملاحظات جديدة بمحتوى مخصص","إدارة الملاحظات الحالية باستخدام أعلام سطر الأوامر","تأتمتة سير عمل إنشاء الملاحظات"]},"limitations":{"en":["Requires Obsidian to be open","Command line interface only"],"zh":["需要 Obsidian 已经打开","仅限命令行接口"],"ja":["Obsidian が開いている必要がある","コマンドラインインターフェイスのみ"],"ko":["Obsidian이 이미 열려 있는必要가 있음","명령줄 인터페이스만"],"es":["Requiere que Obsidian esté abierto","Solo interfaz de línea de comandos"],"fr":["Nécessite que Obsidian soit ouvert","Interface de ligne de commande uniquement"],"de":["Erfordert, dass Obsidian geöffnet ist","Nur Kommandozeilenoberfläche"],"pt":["Requer que o Obsidian esteja aberto","Interface de linha de comando apenas"],"ru":["Требует того, чтобы Obsidian был открыт","Только командная строка"],"ar":["يتطلب أن يكون Obsidian مفتوحا","واجهة سطر الأوامر فقط"]},"version":4},"contentHash":"b54257cdc0e5d04488b35b0c797bfe427b24359f0848d3c73924dcacf8da6358","qualityScore":36}');
