INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('iwbc-mzk/obsidian/obsidian-cli', 'obsidian-cli', 'iwbc-mzk', 'obsidian', 'community', 'obsidian-cli iwbc-mzk obsidian community The obsidian-cli skill allows developers to interact with a running Obsidian instance using the command line. It provides a range of commands for creating and managing notes. Obsidian CLI 是一种命令行工具，用于与运行中的 Obsidian 实例交互。它提供了一系列命令来创建、管理和操作 Obsidian 笔记 Obsidian CLI は、実行中の Obsidian インスタンスと相互作用するためのコマンドラインツールです。Obsidian ノートを作成、管理、および操作するためのコマンドセットを提供します Obsidian CLI는 실행 중인 Obsidian 인스턴스와 상호 작용하기 위한 명령줄 도구입니다. Obsidian 노트를 생성, 관리 및操作하기 위한 명령어 세트를 제공합니다 La línea de comandos de Obsidian permite a los desarrolladores interactuar con instancias de Obsidian. Ofrece comandos como ''create'' y ''help'' con parámetros y opciones La ligne de commande Obsidian permet aux développeurs d''interagir avec les instances Obsidian. Elle propose des commandes telles que ''create'' et ''help'' avec des paramètres et des options Die Obsidian-CLI ermöglicht es Entwicklern, mit Obsidian-Instanzen zu interagieren. Sie bietet Befehle wie ''create'' und ''help'' mit Parametern und Optionen O Obsidian-CLI é uma ferramenta de linha de comando para interagir com instâncias do Obsidian. Requer o Obsidian estar aberto. Obsidian-CLI - это инструмент командной строки для взаимодействия с экземплярами Obsidian. Требуется открыть Obsidian. Obsidian-CLI هو أداة سطر أوامر للتفاعل مع مثيلات Obsidian. يتطلب فتح Obsidian. how to use obsidian-cli obsidian-cli setup guide obsidian-cli alternative obsidian-cli vs other note-taking tools obsidian-cli install what is obsidian-cli obsidian-cli commands obsidian-cli documentation obsidian-cli tutorial Obsidian CLI 命令行工具 Obsidian 交互 笔记创建 命令参考 语法指导 AI エージェント CLI 工具 Run `obsidian help` to see all available commands Use `obsidian create` to create new notes with custom names and content Utilize parameters with `=` and quote values with spaces Employ flags as boolean switches with no value Access full documentation at https://help.obsidian.md/cli obsidian-cli is a command line interface for interacting with Obsidian, a note-taking and knowledge management tool.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('maciejjankowski/dtc-compass/focus', 'community', 'maciejjankowski', 'dtc-compass', 'maciejjankowski/dtc-compass', 'focus', 0, 0, 36, '2026-03-06T12:59:22.275Z', '2026-03-06T15:06:56.372Z', '320b72db925b0ab90eb557410de06efb2503ee42a9b92b43d86a1960840ea37d', '{"id":"maciejjankowski/dtc-compass/focus","name":"focus","description":{"en":"The Focus skill enables AI agents to manage current tasks, supporting sustained attention by reading and writing focus state to a JSON file. This benefits developers working on complex projects.","zh":"Focus技能用于管理当前任务，支持持续注意力。通过状态文件和JSON模式实现任务管理","ja":"Focus AIエージェントは現在のタスクを管理し、持続した注意力をサポートします。ステートファイルとJSONスキーマを使用してタスク管理を実現","ko":"Focus 기능은 현재 작업을 관리하여 지속적인 집중력을 지원합니다. 상태 파일과 JSON 스키마를 사용하여 작업 관리를 구현","es":"La función de enfoque permite a los desarrolladores gestionar tareas y mejorar la productividad. Utiliza un archivo de estado JSON para almacenar información de la tarea actual","fr":"La fonction Focus permet aux développeurs de gérer les tâches et d''améliorer la productivité. Elle utilise un fichier d''état JSON pour stocker les informations de la tâche en cours","de":"Die Fokus-Funktion ermöglicht es Entwicklern, Aufgaben zu verwalten und die Produktivität zu steigern. Sie verwendet eine JSON-Zustandsdatei, um Informationen über die aktuelle Aufgabe zu speichern","pt":"O Focus é uma habilidade que gerencia a tarefa atual, permitindo que você defina e acompanhe suas metas com eficiência, utilizando um arquivo de estado em JSON","ru":"Фокус - это навык, который управляет текущей задачей, позволяя вам устанавливать и отслеживать ваши цели эффективно, используя файл состояния в JSON","ar":"التركيز هو مهارة تدير المهمة الحالية، مما يسمح لك بتحديد وأداء أهدافك بفعالية، باستخدام ملف حالة JSON"},"seo":{"title":{"en":"Focus: Task Management Setup Guide | AI Agent Skill","zh":"Focus技能设置指南 - AIエージェント任务管理","ja":"Focus AIエージェント - タスク管理のベストプラクティス","ko":"Focus 기능 설정 가이드 - AI 에이전트 작업 관리","es":"Configuración de Enfoque: Guía de Implementación para Des...","fr":"Mise en place de la fonction Focus : Guide d''installation...","de":"Fokus-Setup: Anleitung für Entwickler","pt":"Guia de Configuração do Focus - Gerenciamento de Tarefas ...","ru":"Настройка Фокуса - Управление Текущей Задачей с Использов...","ar":"دليل إعداد التركيز - إدارة المهام الحالية باستخدام تقنيات..."},"description":{"en":"Discover how to set up and utilize the Focus skill for AI agents, streamlining task management with JSON state files and ISO timestamps","zh":"了解Focus技能的设置和管理，提高任务管理效率。包括状态文件、设置焦点和JSON模式等技术细节","ja":"Focus AIエージェントの設定と管理を学び、タスク管理の効率を高める。ステートファイル、フォーカスの設定、JSONスキーマなど","ko":"Focus 기능의 설정과 관리를 알아보고 작업 관리 효율성을 높이세요. 상태 파일,焦点 설정, JSON 스키마 등","es":"Aprende a configurar la función de enfoque para gestionar tareas y mejorar la productividad con nuestra guía para desarrolladores","fr":"Découvrez comment configurer la fonction Focus pour gérer les tâches et améliorer la productivité avec notre guide pour les développeurs","de":"Erfahren Sie, wie Sie die Fokus-Funktion einrichten, um Aufgaben zu verwalten und die Produktivität zu steigern","pt":"Aprenda a configurar e gerenciar o foco em suas tarefas com o arquivo de estado em JSON, incluindo sub-tarefas e estimativas de tempo","ru":"Узнайте, как настроить и управлять фокусом на ваших задачах с помощью файла состояния в JSON, включая подзадачи и оценки времени","ar":"تعرف على كيفية ضبط وإدارة التركيز على مهامك باستخدام ملف حالة JSON، بما في ذلك المهام الفرعية وتقديرات الوقت"},"definition":{"en":"Focus is a task management skill that allows AI agents to set and manage current tasks, utilizing a JSON state file for data storage","zh":"Focus技能是一种AIエージェント任务管理技术，用于设置和管理当前任务","ja":"Focus AIエージェントは、現在のタスクを設定して管理するための技術です","ko":"Focus 기능은 현재 작업을 설정하고 관리하기 위한 AI 에이전트 작업 관리 기술입니다","es":"La función de enfoque es una característica que permite a los desarrolladores gestionar la tarea actual y mejorar la productividad","fr":"La fonction Focus est une caractéristique qui permet aux développeurs de gérer la tâche en cours et d''améliorer la productivité","de":"Die Fokus-Funktion ist eine Funktion, die es Entwicklern ermöglicht, die aktuelle Aufgabe zu verwalten und die Produktivität zu steigern","pt":"O Focus é uma habilidade de gerenciamento de tarefas que utiliza um arquivo de estado em JSON para armazenar informações da tarefa atual","ru":"Фокус - это навык управления задачами, который использует файл состояния в JSON для хранения информации о текущей задаче","ar":"التركيز هو مهارة لإدارة المهام التي تستخدم ملف حالة JSON لتخزين المعلومات حول المهمة الحالية"},"features":{"en":["Reads and writes focus state to a `.codex/skills/_state/current_focus.json` file","Utilizes a JSON schema for task data, including task name, start time, and time estimate","Supports the creation of subtasks for breaking down larger tasks","Manages task context with a dedicated string field","Uses ISO timestamps for accurate task start time tracking"],"zh":["状态文件读写：.codex/skills/_state/current_focus.json","JSON模式支持：任务、开始时间、时间估计、上下文和子任务","设置焦点：读取当前状态并更新焦点任务","任务管理：支持持续注意力和任务拆分","技术集成：支持React、Python、CLI等技术"],"ja":["ステートファイルの読み書き：.codex/skills/_state/current_focus.json","JSONスキーマのサポート：タスク、開始時間、時間の見積もり、コンテキスト、サブタスク","フォーカスの設定：現在の状態を読み込みフォーカスタスクを更新","タスク管理：持続した注意力とタスクの分割をサポート","技術統合：React、Python、CLIなど"],"ko":["상태 파일 읽기/쓰기：.codex/skills/_state/current_focus.json","JSON 스키마 지원：작업, 시작 시간, 시간 추정, 컨텍스트, 서브 작업","초점 설정：현재 상태 읽기 및 초점 작업 업데이트","작업 관리：지속적인 집중력 및 작업 분할 지원","기술 통합：React, Python, CLI 등"],"es":["Almacenamiento de información de la tarea actual en un archivo JSON","Gestión de la tarea actual mediante la lectura y escritura de un archivo de estado","Soporte para la creación de subtareas y contexto","Uso de un esquema JSON para almacenar información de la tarea","Compatibilidad con la gestión de tareas y la productividad"],"fr":["Stockage des informations de la tâche en cours dans un fichier JSON","Gestion de la tâche en cours via la lecture et l''écriture d''un fichier d''état","Prise en charge de la création de sous-tâches et de contexte","Utilisation d''un schéma JSON pour stocker les informations de la tâche","Compatibilité avec la gestion de tâches et la productivité"],"de":["Speicherung von Informationen über die aktuelle Aufgabe in einer JSON-Datei","Verwaltung der aktuellen Aufgabe durch Lesen und Schreiben einer Zustandsdatei","Unterstützung für die Erstellung von Teilaufgaben und Kontext","Verwendung eines JSON-Schemas zur Speicherung von Aufgabeninformationen","Kompatibilität mit der Aufgabenverwaltung und der Produktivität"],"pt":["Gerenciamento de tarefas com arquivo de estado em JSON","Definição de sub-tarefas e estimativas de tempo","Leitura e escrita de estado de foco em `.codex/skills/_state/current_focus.json`","Suporte a sustentação de atenção","Integração com tecnologias de gerenciamento de tarefas"],"ru":["Управление задачами с помощью файла состояния в JSON","Определение подзадач и оценок времени","Чтение и запись состояния фокуса в `.codex/skills/_state/current_focus.json`","Поддержка устойчивого внимания","Интеграция с технологиями управления задачами"],"ar":["إدارة المهام باستخدام ملف حالة JSON","تحديد المهام الفرعية وتقديرات الوقت","قراءة وكتابة حالة التركيز في `.codex/skills/_state/current_focus.json`","دعم الاستمرار في الانتباه","التكامل مع تقنيات إدارة المهام"]},"keywords":{"en":["how to use focus skill","focus skill setup guide","what is focus skill","focus vs task management tools","focus alternative for AI agents","focus install for developers","focus skill for sustained attention","json state file management","iso timestamp task tracking"],"zh":["AIエージェント","任务管理","Focus技能","状态文件","JSON模式","设置焦点","React","Python","CLI"],"ja":["AIエージェント","タスク管理","Focus AIエージェント","ステートファイル","JSONスキーマ","フォーカスの設定","React","Python","CLI"],"ko":["AI 에이전트","작업 관리","Focus 기능","상태 파일","JSON 스키마","초점 설정","React","Python","CLI"],"es":["enfoque para desarrolladores","gestión de tareas","productividad para desarrolladores","archivo de estado JSON","esquema JSON para tareas","subtareas y contexto","compatibilidad con la gestión de tareas","herramientas de productividad para desarrolladores","configuración de enfoque"],"fr":["focus pour les développeurs","gestion de tâches","productivité pour les développeurs","fichier d''état JSON","schéma JSON pour les tâches","sous-tâches et contexte","compatibilité avec la gestion de tâches","outils de productivité pour les développeurs","mise en place de la fonction Focus"],"de":["Fokus für Entwickler","Aufgabenverwaltung","Produktivität für Entwickler","JSON-Zustandsdatei","JSON-Schema für Aufgaben","Teilaufgaben und Kontext","Kompatibilität mit der Aufgabenverwaltung","Produktivitätstools für Entwickler","Einrichtung der Fokus-Funktion"],"pt":["focus","gerenciamento de tarefas","arquivo de estado em JSON","sub-tarefas","estimativas de tempo","sustentação de atenção","tecnologias de gerenciamento de tarefas","IA","agentes de IA"],"ru":["фокус","управление задачами","файл состояния в JSON","подзадачи","оценки времени","устойчивое внимание","технологии управления задачами","ИИ","ИИ Агенты"],"ar":["التركيز","إدارة المهام","ملف حالة JSON","المهام الفرعية","تقديرات الوقت","الاستمرار في الانتباه","تقنيات إدارة المهام","الذكاء الاصطناعي","أدوات الذكاء الاصطناعي"]}},"owner":"maciejjankowski","repo":"dtc-compass","repoPath":"maciejjankowski/dtc-compass","stars":0,"forks":0,"updatedAt":"2026-03-06T12:59:22.275Z","topics":[],"category":"community","skillMd":{"name":"focus","description":"Set or check current focus task for ADHD executive function support. Use when user says focus on, working on, my focus is, what am I working on, or needs help staying on task. Manages focus state and redirects tangents.","bodyPreview":"# Focus - Set Current Task\n\nManage the current focus task to support sustained attention.\n\n## State File\n\nRead and write focus state to: `.codex/skills/_state/current_focus.json`\n\nSchema:\n```json\n{\n  \"task\": \"string - what we''re working on\",\n  \"started_at\": \"ISO timestamp\",\n  \"time_estimate_minutes\": \"number or null\",\n  \"context\": \"string - any relevant context\",\n  \"subtasks\": [\"list of smaller steps if broken down\"]\n}\n```\n\n## Setting Focus\n\nWhen user sets a new focus:\n\n1. Read current state fro","body":"# Focus - Set Current Task\n\nManage the current focus task to support sustained attention.\n\n## State File\n\nRead and write focus state to: `.codex/skills/_state/current_focus.json`\n\nSchema:\n```json\n{\n  \"task\": \"string - what we''re working on\",\n  \"started_at\": \"ISO timestamp\",\n  \"time_estimate_minutes\": \"number or null\",\n  \"context\": \"string - any relevant context\",\n  \"subtasks\": [\"list of smaller steps if broken down\"]\n}\n```\n\n## Setting Focus\n\nWhen user sets a new focus:\n\n1. Read current state from `.codex/skills/_state/current_focus.json`\n2. If there was a previous focus, acknowledge it briefly (\"Switching from X\")\n3. Write new focus with:\n   - task: what they said\n   - started_at: current ISO timestamp\n   - time_estimate_minutes: if they mentioned time, otherwise null\n   - context: any relevant details\n4. Confirm with a brief, action-oriented message:\n   - State the focus task clearly\n   - If time estimate given, note it\n   - Give the first concrete step if the task is vague\n\n## Checking Focus\n\nWhen user asks \"what am I working on\" or seems lost:\n\n1. Read `.codex/skills/_state/current_focus.json`\n2. If no focus set: suggest setting one\n3. If focus exists:\n   - State the task\n   - Calculate time elapsed since started_at\n   - Remind of any subtasks\n   - Suggest next action\n\n## Tangent Detection\n\nWhen user brings up something unrelated to current focus:\n\n1. Politely note this seems like a tangent\n2. Suggest using the `tangent` skill to capture it for later\n3. Redirect back to the current focus task\n\nDo not lecture. Do not ask questions. State what we''re doing and move forward.\n\n## Example Responses\n\nSetting focus:\n```\nFocus set: Write Q1 roadmap document\n\nTime estimate: 45 minutes\nStarted: now\n\nFirst step: Open the roadmap template and list the 3 main sections.\n```\n\nChecking focus:\n```\nCurrent focus: Write Q1 roadmap document\nTime elapsed: 23 minutes (of estimated 45)\n\nNext: Complete the timeline section.\n```\n"},"lastSynced":"2026-03-06T15:06:56.372Z","agentAnalysis":{"suitability":{"en":"Ideal for Task Management Agents requiring sustained attention and project organization capabilities.","zh":"适用于需要持续关注和项目组织能力的任务管理代理。","ja":"タスク管理エージェントが持続的な注目とプロジェクトの組織化能力を必要とする場合に適しています。","ko":"지속적인 주의와 프로젝트 조직화 능력이 필요한 태스크 관리 에이전트에 적합합니다.","es":"Ideal para Agentes de Gestión de Tareas que requieren atención sostenida y capacidades de organización de proyectos.","fr":"Idéal pour les Agents de Gestion de Tâches nécessitant une attention soutenue et des capacités d''organisation de projet.","de":"Ideal für Task-Management-Agents, die eine anhaltende Aufmerksamkeit und Projektorganisationsfähigkeiten erfordern.","pt":"Ideal para Agentes de Gerenciamento de Tarefas que requerem atenção sustentada e capacidades de organização de projetos.","ru":"Идеально для агентов управления задачами, требующих устойчивого внимания и возможностей организации проектов.","ar":"مثالي للوكلاء إدارة المهام التي تتطلب الانتباه المستدام وقدرات تنظيم المشروع."},"recommendation":{"en":"Empowers agents to manage complex projects by reading and writing focus state to a JSON file, utilizing ISO timestamps and supporting task contextualization with subtasks, all while estimating time requirements in minutes.","zh":"通过读写JSON文件、利用ISO时间戳并支持任务上下文化以子任务为单位来管理复杂项目，同时估计时间要求（以分钟为单位），从而赋予代理管理复杂项目的能力。","ja":"JSONファイルを読み書きしてISOタイムスタンプを利用し、サブタスクを使用したタスクのコンテキスト化をサポートし、時間要件を分単位で推定することで、複雑なプロジェクトを管理するエージェントの能力を提供します。","ko":"JSON 파일을 읽고 쓰며 ISO 시간戳를 사용하고, 서브태스크를 사용한 태스크의 문맥화도 지원하며, 시간 요구 사항을 분 단위로 추정함으로써 복잡한 프로젝트를 관리할 수 있는 에이전트의 능력을 제공합니다.","es":"Habilita a los agentes a gestionar proyectos complejos leyendo y escribiendo el estado de enfoque en un archivo JSON, utilizando marcas de tiempo ISO y soportando la contextualización de tareas con subtareas, todo mientras se estiman los requisitos de tiempo en minutos.","fr":"Permet aux agents de gérer des projets complexes en lisant et en écrivant l''état de focalisation dans un fichier JSON, en utilisant des horodatages ISO et en supportant la contextualisation des tâches avec des sous-tâches, le tout en estimant les besoins en temps en minutes.","de":"Ermächtigt Agenten, komplexe Projekte zu verwalten, indem sie den Fokusstatus in eine JSON-Datei lesen und schreiben, ISO-Timestamps verwenden und die Kontextualisierung von Aufgaben mit UnterAufgaben unterstützen, während sie die Zeitanforderungen in Minuten schätzen.","pt":"Habilita os agentes a gerenciar projetos complexos lendo e escrevendo o estado de foco em um arquivo JSON, utilizando carimbos de data e hora ISO e suportando contextualização de tarefas com subtarefas, tudo isso estimando os requisitos de tempo em minutos.","ru":"Наделяет агентов возможностью управлять сложными проектами, читая и записывая состояние фокуса в файл JSON, используя метки времени ISO и поддерживая контекстуализацию задач с подзадачами, все это при оценке временных требований в минутах.","ar":"يمنح الوكلاء إمكانية إدارة مشاريع معقدة من خلال قراءة وكتابة حالة التركيز إلى ملف JSON ، باستخدام توقيعات ISO وتدعم سياقية المهام مع المهام الفرعية ، وكل ذلك مع تقدير متطلبات الوقت بدقائق."},"useCases":{"en":["Setting and tracking current tasks with JSON state files","Automating focus state updates with ISO timestamp tracking","Breaking down large projects into smaller, manageable subtasks"],"zh":["使用JSON状态文件设置和跟踪当前任务","使用ISO时间戳跟踪自动更新焦点状态","将大型项目分解为较小、可管理的子任务"],"ja":["JSON状態ファイルを使用して現在のタスクを設定して追跡する","ISOタイムスタンプを使用して自動でフォーカス状態を更新する","大規模なプロジェクトをより小さく、管理可能なサブタスクに分解する"],"ko":["JSON 상태 파일을 사용하여 현재 태스크를 설정하고 추적하는 것","ISO 시간戳를 사용하여 자동으로 포커스 상태를 업데이트하는 것","큰 프로젝트를 더 작은 관리 가능한 서브태스크로 나누는 것"],"es":["Establecer y realizar un seguimiento de las tareas actuales con archivos de estado JSON","Automatizar las actualizaciones del estado de enfoque con seguimiento de marcas de tiempo ISO","Dividir proyectos grandes en subtareas más pequeñas y manejables"],"fr":["Définir et suivre les tâches actuelles avec des fichiers d''état JSON","Automatiser les mises à jour de l''état de focalisation avec un suivi d''horodatage ISO","Diviser les grands projets en sous-tâches plus petites et gérables"],"de":["Aktuelle Aufgaben mit JSON-Zustandsdateien festlegen und verfolgen","Fokusstatus-Updates mit ISO-Timestamp-Verfolgung automatisieren","Große Projekte in kleinere, handhabbare UnterAufgaben aufteilen"],"pt":["Definir e rastrear tarefas atuais com arquivos de estado JSON","Automatizar atualizações de estado de foco com rastreamento de carimbo de data e hora ISO","Dividir projetos grandes em subtarefas menores e gerenciáveis"],"ru":["Установка и отслеживание текущих задач с помощью файлов состояния JSON","Автоматизация обновлений состояния фокуса с помощью отслеживания метки времени ISO","Разделение крупных проектов на более мелкие и управляемые подзадачи"],"ar":["تعيين وتحديد المهام الحالية مع ملفات حالة JSON","تأتمتة تحديثات حالة التركيز مع تتبع توقيع ISO","تقسيم المشاريع الكبيرة إلى مهام فرعية صغيرة وقابلة للإدارة"]},"limitations":{"en":["Requires filesystem access to read and write .codex/skills/_state/current_focus.json","JSON file format adherence necessary for state management"],"zh":["需要文件系统访问权限来读写.codex/skills/_state/current_focus.json","JSON文件格式的遵守对于状态管理是必要的"],"ja":[".codex/skills/_state/current_focus.jsonを読み書きするためにファイルシステムへのアクセスが必要","状態管理のためにJSONファイル形式の遵守が必要"],"ko":[".codex/skills/_state/current_focus.json을 읽고 쓰기 위해 파일 시스템에 접근할 수 있어야 함","상태 관리를 위해 JSON 파일 형식의 준수를 필요로 함"],"es":["Requiere acceso al sistema de archivos para leer y escribir .codex/skills/_state/current_focus.json","Se requiere adherencia al formato de archivo JSON para la gestión del estado"],"fr":["Nécessite un accès au système de fichiers pour lire et écrire .codex/skills/_state/current_focus.json","L''adhérence au format de fichier JSON est nécessaire pour la gestion de l''état"],"de":["Benötigt Dateizugriff, um .codex/skills/_state/current_focus.json zu lesen und zu schreiben","Einhaltung des JSON-Dateiformats ist für die Zustandsverwaltung erforderlich"],"pt":["Requer acesso ao sistema de arquivos para ler e gravar .codex/skills/_state/current_focus.json","Necessária aderência ao formato de arquivo JSON para gerenciamento de estado"],"ru":["Требуется доступ к файловой системе для чтения и записи .codex/skills/_state/current_focus.json","Необходимо соблюдение формата файла JSON для управления состоянием"],"ar":["يتطلب الوصول إلى نظام الملفات لقراءة وكتابة .codex/skills/_state/current_focus.json","الامتثال اللازم لتنسيق ملف JSON لإدارة الحالة"]},"version":4},"contentHash":"320b72db925b0ab90eb557410de06efb2503ee42a9b92b43d86a1960840ea37d","qualityScore":36}');
