INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('finan-eu/finan-website/pseo-templates', 'pseo-templates', 'finan-eu', 'finan-website', 'community', 'pseo-templates finan-eu finan-website community pseo-templates generates unique content at scale through dynamic routing and structured data rendering, benefiting developers and content creators. It produces substantial, differentiated content for specific search intents. pseo-templates 是一种构建网页的方法，使用动态路由和结构化数据渲染来生成独特的内容 pseo-templates は、動的ルーティングと構造化データレンダリングを使用して一意のコンテンツを生成する Web ページ構築方法です pseo-templates는 동적 라우팅과 구조화된 데이터 렌더링을 사용하여 고유한 콘텐츠를 생성하는 웹 페이지 구축 방법입니다 pseo-templates permite a los desarrolladores crear plantillas de página que generan contenido único y escalable con enrutamiento dinámico y representación de datos estructurados pseo-templates permet aux développeurs de créer des modèles de page qui génèrent du contenu unique et évolutif avec un routage dynamique et une représentation de données structurées pseo-templates ermöglicht es Entwicklern, Seitenvorlagen zu erstellen, die einzigartigen und skalierbaren Inhalt mit dynamischer Routing und strukturierter Datenrendering generieren pseo-templates permite criar modelos de página personalizados e escaláveis, utilizando roteamento dinâmico e renderização de dados estruturados. pseo-templates позволяет создавать персонализированные и масштабируемые шаблоны страниц, используя динамический маршрутизацию и рендеринг структурированных данных. pseo-templates يسمح بإنشاء قوالب صفحة قابلة للتطوير ومتوافقة، باستخدام التوجيه الديناميكي وتحويل البيانات المنظمة. how to use pseo-templates pseo-templates setup guide dynamic routing for content generation structured data rendering best practices pseo-templates alternative pseo-templates vs traditional templating install pseo-templates pseo-templates tutorial intent matching for SEO semantic HTML for accessibility pseo-templates 动态路由 结构化数据渲染 网页构建 搜索引擎优化 AIエージェント 网页开发 One template, many unique pages through dynamic routing No thin pages: every generated page has substantial, differentiated content Intent matching: each page targets a specific search intent derived from its data Semantic HTML: uses correct heading hierarchy for improved accessibility Structured data rendering for enhanced search engine understanding Supports scalable content generation through content-agnostic templates pseo-templates is a technology for building page templates that render data into unique, intent-matched content through dynamic routing and semantic HTML.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kreuzberg-dev/html-to-markdown/git-standards', 'community', 'kreuzberg-dev', 'html-to-markdown', 'kreuzberg-dev/html-to-markdown', 'git-standards', 538, 48, 36, '2026-02-26T07:34:41Z', '2026-03-06T06:28:28.374Z', 'fc8fb9ca20df8e0c13e14c7612ee9ea091e38a8b20ed803d80c5a9c0f47759e0', '{"id":"kreuzberg-dev/html-to-markdown/git-standards","name":"git-standards","description":{"en":"git-standards is a high-performance HTML to Markdown converter that maintains Conventional Commits 1.0.0 standards, benefiting developers with structured data extraction from 56+ document formats.","zh":"git-standards 是一个高性能的 HTML 到 Markdown 转换器，支持 Conventional Commits 1.0.0 和预提交钩子","ja":"git-standards は、高性能の HTML から Markdown へのコンバータであり、Conventional Commits 1.0.0 と事前コミットフックをサポートする","ko":"git-standards는 Conventional Commits 1.0.0 및 사전 커밋 훅을 지원하는 고성능 HTML에서 Markdown로의 변환기","es":"git-standards es una herramienta para commits convencionales que utiliza un formato de mensaje y scopes personalizables para mejorar la calidad de tus commits","fr":"git-standards est un outil pour des commits conventionnels qui utilise un format de message et des scopes personnalisables pour améliorer la qualité de vos commits","de":"git-standards ist ein Tool für Conventional Commits, das ein benutzerdefiniertes Nachrichtenformat und Bereiche verwendet, um die Qualität Ihrer Commits zu verbessern","pt":"O git-standards é uma ferramenta que ajuda a manter a qualidade do código com convenções de commit e hooks de pré-commit","ru":"git-standards - это инструмент, который помогает поддерживать качество кода с помощью конвенций для коммитов и хуков предкоммита","ar":"معايير git-standards هي أداة تساعد في الحفاظ على جودة الكود باستخدام اتفاقيات الإلتزام و Hooks قبل الإلتزام"},"seo":{"title":{"en":"git-standards: Conventional Commits Setup Guide | AI Agen...","zh":"git-standards 设置指南：Conventional Commits 1.0.0 实践","ja":"git-standards 導入ガイド：Conventional Commits 1.0.0 を使用したコミットメ...","ko":"git-standards 설정 가이드: Conventional Commits 1.0.0 적용","es":"Guía de configuración de git-standards para commits conve...","fr":"Guide de mise en place de git-standards pour des commits ...","de":"Einrichtungsleitfaden für git-standards mit Conventional ...","pt":"Guia de Configuração do git-standards: Padrões de Commit","ru":"Настройка git-standards: Конвенции для коммитов","ar":"إعداد معايير git-standards: دليل أفضل الممارسات"},"description":{"en":"Unlock the power of git-standards with our expert guide. Learn how to enforce quality with pre-commit hooks and Conventional Commits 1.0.0","zh":"了解 git-standards 的技术细节，掌握 Conventional Commits 1.0.0 的 commit 消息格式和预提交钩子","ja":"git-standards の技術的詳細を学び、Conventional Commits 1.0.0 のコミットメッセージ形式と事前コミットフックを理解する","ko":"git-standards의 기술적 세부 사항을 학습하고 Conventional Commits 1.0.0의 커밋 메시지 형식 및 사전 커밋 훅을 이해","es":"Aprende a implementar git-standards para mejorar la calidad de tus commits con formato de mensaje y scopes personalizables","fr":"Découvrez comment mettre en place git-standards pour améliorer la qualité de vos commits avec un format de message et des scopes personnalisables","de":"Erfahren Sie, wie Sie git-standards implementieren, um die Qualität Ihrer Commits mit benutzerdefiniertem Nachrichtenformat und Bereichen zu verbessern","pt":"Aprenda a configurar o git-standards para melhorar a qualidade do seu código com convenções de commit e hooks de pré-commit","ru":"Узнайте, как настроить git-standards для повышения качества кода с помощью конвенций для коммитов и хуков предкоммита","ar":"تعلم كيفية إعداد معايير git-standards لتحسين جودة الكود باستخدام اتفاقيات الإلتزام و Hooks قبل الإلتزام"},"definition":{"en":"git-standards is a set of guidelines for committing code changes using Conventional Commits 1.0.0, ensuring high-quality and readable commit history","zh":"git-standards 是一个用于规范 Git 提交消息的工具，支持 Conventional Commits 1.0.0","ja":"git-standards は、Git のコミットメッセージを規格化するためのツールであり、Conventional Commits 1.0.0 をサポートする","ko":"git-standards는 Git 커밋 메시지를 규격화하는 도구로서 Conventional Commits 1.0.0를 지원","es":"git-standards es un conjunto de reglas para commits que utiliza Conventional Commits 1.0.0 y pre-commit hooks para garantizar la calidad","fr":"git-standards est un ensemble de règles pour des commits qui utilise Conventional Commits 1.0.0 et des hooks de pré-commit pour garantir la qualité","de":"git-standards ist eine Sammlung von Regeln für Commits, die Conventional Commits 1.0.0 und Pre-Commit-Hooks verwendet, um die Qualität zu gewährleisten","pt":"O que é git-standards? É uma ferramenta que define convenções para commits","ru":"Что такое git-standards? Это инструмент, определяющий конвенции для коммитов","ar":"ما هي معايير git-standards؟ هي أداة تحدد اتفاقيات للإلتزام"},"features":{"en":["Enforces Conventional Commits 1.0.0 format for commit messages","Supports scopes such as rust-core, py-binding, and ts-binding","Handles nested lists in Markdown output","Exposes sanitization options to Python API via py-binding","Utilizes pre-commit hooks for quality assurance","Streams parsers for 56+ document formats"],"zh":["支持 Conventional Commits 1.0.0 的 commit 消息格式","预提交钩子（pre-commit hooks）用于强制执行代码质量","支持 Rust 核心和多种语言绑定（包括 Python、JavaScript 和 Ruby）","高性能的 HTML 到 Markdown 转换","支持 56+ 种文档格式和内置的 OCR"],"ja":["Conventional Commits 1.0.0 のコミットメッセージ形式をサポート","事前コミットフック（pre-commit hooks）を使用してコード品質を強制する","Rust コアと多くの言語バインディング（Python、JavaScript、Ruby など）をサポート","高性能の HTML から Markdown へのコンバート","56 種以上のドキュメント形式と組み込みの OCR をサポート"],"ko":["Conventional Commits 1.0.0의 커밋 메시지 형식을 지원","사전 커밋 훅을 사용하여 코드 품질을 강제","Rust 핵심 및 여러 언어 바인딩(파이썬, 자바스크립트, 루비 등)을 지원","고성능의 HTML에서 Markdown로의 변환","56종 이상의 문서 형식 및 내장 OCR을 지원"],"es":["Soporte para formato de mensaje de commit personalizable","Scopes personalizables para diferentes partes del proyecto","Compatibilidad con Conventional Commits 1.0.0","Pre-commit hooks para garantizar la calidad de los commits","Soporte para diferentes lenguajes de programación como Rust, Python y TypeScript"],"fr":["Prise en charge d''un format de message de commit personnalisable","Scopes personnalisables pour différentes parties du projet","Compatibilité avec Conventional Commits 1.0.0","Hooks de pré-commit pour garantir la qualité des commits","Prise en charge de différents langages de programmation tels que Rust, Python et TypeScript"],"de":["Unterstützung für benutzerdefiniertes Commit-Nachrichtenformat","Benutzerdefinierte Bereiche für unterschiedliche Teile des Projekts","Kompatibilität mit Conventional Commits 1.0.0","Pre-Commit-Hooks für die Qualitätsgarantie von Commits","Unterstützung für verschiedene Programmiersprachen wie Rust, Python und TypeScript"],"pt":["Convenções de commit com formato feat/fix/docs/refactor/test/chore","Suporte a scopes como rust-core, py-binding e ts-binding","Hooks de pré-commit para garantir a qualidade do código","Compatibilidade com Markdown e HTML","Suporte a streaming parsers e OCR"],"ru":["Конвенции для коммитов с форматом feat/fix/docs/refactor/test/chore","Поддержка scopes как rust-core, py-binding и ts-binding","Хуки предкоммита для обеспечения качества кода","Совместимость с Markdown и HTML","Поддержка потоковых парсеров и OCR"],"ar":["اتفاقيات الإلتزام بفورمت feat/fix/docs/refactor/test/chore","دعم نطاقات مثل rust-core، py-binding و ts-binding","Hooks قبل الإلتزام لتأمين جودة الكود","توافق مع Markdown و HTML","دعم معالجات التدفق و OCR"]},"keywords":{"en":["git-standards setup guide","Conventional Commits 1.0.0 tutorial","how to use git-standards","git-standards alternative","git-standards vs markdown converter","install git-standards","git-standards best practices","what is git-standards","git-standards and pre-commit hooks"],"zh":["git-standards","Conventional Commits 1.0.0","预提交钩子","Rust 核心","HTML 到 Markdown 转换","文档格式","OCR","代码质量","AI工具","AIエージェント"],"ja":["git-standards","Conventional Commits 1.0.0","事前コミットフック","Rust コア","HTML から Markdown へのコンバート","ドキュメント形式","OCR","コード品質","AIエージェント","AIツール"],"ko":["git-standards","Conventional Commits 1.0.0","사전 커밋 훅","Rust 핵심","HTML에서 Markdown로의 변환","문서 형식","OCR","코드 품질","AI 에이전트","AI 도구"],"es":["git-standards","Conventional Commits","pre-commit hooks","formato de mensaje de commit","scopes personalizables","Rust","Python","TypeScript","herramientas de desarrollo","calidad de código"],"fr":["git-standards","Conventional Commits","hooks de pré-commit","format de message de commit","scopes personnalisables","Rust","Python","TypeScript","outils de développement","qualité de code"],"de":["git-standards","Conventional Commits","Pre-Commit-Hooks","Commit-Nachrichtenformat","benutzerdefinierte Bereiche","Rust","Python","TypeScript","Entwicklungstools","Code-Qualität"],"pt":["git-standards","convenções de commit","hooks de pré-commit","qualidade de código","Markdown","HTML","rust-core","py-binding","ts-binding"],"ru":["git-standards","конвенции для коммитов","хуки предкоммита","качество кода","Markdown","HTML","rust-core","py-binding","ts-binding"],"ar":["معايير git-standards","اتفاقيات الإلتزام","Hooks قبل الإلتزام","جودة الكود","Markdown","HTML","rust-core","py-binding","ts-binding","أدوات إصطناعية","ИИ Агенты"]}},"owner":"kreuzberg-dev","repo":"html-to-markdown","repoPath":"kreuzberg-dev/html-to-markdown","stars":538,"forks":48,"updatedAt":"2026-02-26T07:34:41Z","topics":["hocr","html","html-converter","markdown","markdown-converter","rag","text-extraction","text-processing"],"category":"community","skillMd":{"name":"git-standards","description":"","bodyPreview":"______________________________________________________________________\n\n## priority: medium\n\n# Git Commit Standards\n\n**Conventional Commits 1.0.0 · Pre-commit hooks enforce quality**\n\n- Commit message format: feat/fix/docs/refactor/test/chore(scope): description\n- Scopes: rust-core, py-binding, ts-binding, rb-binding, php-binding, build, ci, docs\n- Example: fix(rust-core): handle nested lists in markdown output\n- Example: feat(py-binding): expose sanitization options to Python API\n- Example: tes","body":"______________________________________________________________________\n\n## priority: medium\n\n# Git Commit Standards\n\n**Conventional Commits 1.0.0 · Pre-commit hooks enforce quality**\n\n- Commit message format: feat/fix/docs/refactor/test/chore(scope): description\n- Scopes: rust-core, py-binding, ts-binding, rb-binding, php-binding, build, ci, docs\n- Example: fix(rust-core): handle nested lists in markdown output\n- Example: feat(py-binding): expose sanitization options to Python API\n- Example: test(ts-binding): add parametrized tests for edge cases\n- Commits MUST pass prek hooks: fmt, lint, tests (at min)\n- NEVER include AI signatures in commits; commits authored by humans\n- NEVER force push to main/development; require PR reviews\n"},"lastSynced":"2026-03-06T06:28:28.374Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing standardized git commit formatting and Conventional Commits 1.0.0 compliance.","zh":"非常适合需要标准化git提交格式并符合Conventional Commits 1.0.0标准的开发者代理。","ja":"標準的なgitコミット形式とConventional Commits 1.0.0の準拠が必要な開発者エージェントに最適です。","ko":"표준화된 git 커밋 형식 및 Conventional Commits 1.0.0 준수를 필요로 하는 개발자 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan un formato de confirmación de git estandarizado y cumplimiento con Conventional Commits 1.0.0.","fr":"Parfait pour les agents de développement ayant besoin d''un format de commit git standardisé et de la conformité Conventional Commits 1.0.0.","de":"Perfekt für Entwickleragenten, die ein standardisiertes git-Commit-Format und die Einhaltung von Conventional Commits 1.0.0 benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de formatação de commit do git padronizada e conformidade com Conventional Commits 1.0.0.","ru":"Идеально подходит для агентов-разработчиков, которым необходима стандартизированная форматировка коммитов git и соответствие Conventional Commits 1.0.0.","ar":"مثالي لعميل المطور الذي يحتاج إلى تنسيق إلتزامات الجيت المعيارية والامتثال لмоاصفات الإلتزامات التقليدية 1.0.0."},"recommendation":{"en":"Empowers agents to enforce quality through pre-commit hooks, maintaining structured data extraction from 56+ document formats and adhering to Conventional Commits 1.0.0 standards, utilizing feat/fix/docs/refactor/test/chore commit message formats.","zh":"赋予代理人通过预提交钩子强制执行质量的能力，维护来自56+文档格式的结构化数据提取，并遵守Conventional Commits 1.0.0标准，利用feat/fix/docs/refactor/test/chore提交消息格式。","ja":"エージェントに、事前コミットフックを介して品質を強制する能力を与え、56以上のドキュメント形式からの構造化されたデータ抽出を維持し、Conventional Commits 1.0.0の標準に従い、feat/fix/docs/refactor/test/choreコミットメッセージ形式を利用します。","ko":"에이전트에게 사전 커밋 훅을 통해 품질을 강제하는 능력을 부여하여 56개 이상의 문서 형식에서 구조화된 데이터 추출을 유지하고 Conventional Commits 1.0.0 표준을 준수하며 feat/fix/docs/refactor/test/chore 커밋 메시지 형식을 사용합니다.","es":"Habilita a los agentes a hacer cumplir la calidad a través de ganchos pre-confirmación, manteniendo la extracción de datos estructurados de más de 56 formatos de documento y ajustándose a los estándares de Conventional Commits 1.0.0, utilizando formatos de mensaje de confirmación feat/fix/docs/refactor/test/chore.","fr":"Permet aux agents d''assurer la qualité grâce aux hooks pré-commit, en maintenant l''extraction de données structurées de plus de 56 formats de document et en respectant les normes Conventional Commits 1.0.0, en utilisant des formats de message de commit feat/fix/docs/refactor/test/chore.","de":"Ermächtigt die Agenten, die Qualität durch Pre-Commit-Hooks durchzusetzen, indem sie die strukturierte Datenerfassung aus mehr als 56 Dokumentformaten aufrechterhält und die Conventional Commits 1.0.0-Standards einhält, indem sie Commit-Mitteilungsformate wie feat/fix/docs/refactor/test/chore verwendet.","pt":"Habilita os agentes a impor qualidade por meio de hooks de pré-compromisso, mantendo extração estruturada de dados de 56+ formatos de documento e aderindo aos padrões Conventional Commits 1.0.0, utilizando formatos de mensagem de compromisso feat/fix/docs/refactor/test/chore.","ru":"Наделяет агентов возможностью обеспечивать качество посредством хуков до фиксации, сохраняя структурированное извлечение данных из 56+ форматов документов и соответствуя стандартам Conventional Commits 1.0.0, используя форматы сообщений о фиксации feat/fix/docs/refactor/test/chore.","ar":"تمكين الوكيل من فرض الجودة من خلال hooks ما قبل التعهد، والحفاظ على استخراج البيانات المنظم من 56+ تنسيقا للوثائق والامتثال لمواصفات الإلتزامات التقليدية 1.0.0، باستخدام تنسيقات رسائل التعهد feat/fix/docs/refactor/test/chore."},"useCases":{"en":["Automating commit message validation for Conventional Commits 1.0.0","Generating standardized commit messages with scopes like rust-core and py-binding","Enforcing pre-commit hooks for quality control in git repositories"],"zh":["为Conventional Commits 1.0.0自动化提交消息验证","使用rust-core和py-binding等作用域生成标准化提交消息","在git存储库中执行预提交钩子以进行质量控制"],"ja":["Conventional Commits 1.0.0のコミットメッセージ検証を自動化する","rust-coreやpy-bindingなどのスコープを使用して標準化されたコミットメッセージを生成する","gitリポジトリで事前コミットフックを実行して品質管理を行う"],"ko":["Conventional Commits 1.0.0 커밋 메시지 검증 자동화","rust-core 및 py-binding 등의 범위를 사용하여 표준화된 커밋 메시지 생성","git 저장소에서 사전 커밋 훅을 실행하여 품질 관리 수행"],"es":["Automatizar la validación de mensajes de confirmación para Conventional Commits 1.0.0","Generar mensajes de confirmación estandarizados con ámbitos como rust-core y py-binding","Hacer cumplir los ganchos pre-confirmación para el control de calidad en los repositorios git"],"fr":["Automatiser la validation des messages de commit pour Conventional Commits 1.0.0","Générer des messages de commit standardisés avec des portées comme rust-core et py-binding","Assurer les hooks pré-commit pour le contrôle de qualité dans les dépôts git"],"de":["Automatisieren der Überprüfung von Commit-Mitteilungen für Conventional Commits 1.0.0","Generieren standardisierter Commit-Mitteilungen mit Bereichen wie rust-core und py-binding","Durchsetzen von Pre-Commit-Hooks für Qualitätskontrolle in Git-Repositorys"],"pt":["Automatizar a validação da mensagem de compromisso para Conventional Commits 1.0.0","Gerar mensagens de compromisso padronizadas com escopos como rust-core e py-binding","Impor hooks de pré-compromisso para controle de qualidade em repositórios git"],"ru":["Автоматизировать проверку сообщения о фиксации для Conventional Commits 1.0.0","Генерировать стандартизированные сообщения о фиксации с областями действия, такими как rust-core и py-binding","Внедрять хуки до фиксации для контроля качества в репозиториях git"],"ar":["توفير التحقق التلقائي من رسائل الإلتزام لمواصفات الإلتزامات التقليدية 1.0.0","توليد رسائل إلتزام معيارية مع نطاقات مثل rust-core و py-binding","فرض hooks ما قبل التعهد للسيطرة على الجودة في مستودعات الجيت"]},"limitations":{"en":["Requires pre-commit hook setup","Limited to Conventional Commits 1.0.0 standards"],"zh":["需要预提交钩子设置","仅限于Conventional Commits 1.0.0标准"],"ja":["事前コミットフックの設定が必要","Conventional Commits 1.0.0の標準のみ"],"ko":["사전 커밋 훅 설정이 필요","Conventional Commits 1.0.0 표준만 해당"],"es":["Requiere la configuración del gancho pre-confirmación","Limitado a los estándares de Conventional Commits 1.0.0"],"fr":["Nécessite la configuration du hook pré-commit","Limité aux normes Conventional Commits 1.0.0"],"de":["Benötigt die Einrichtung des Pre-Commit-Hooks","Begrenzt auf die Conventional Commits 1.0.0-Standards"],"pt":["Requer configuração de hook de pré-compromisso","Limitado aos padrões Conventional Commits 1.0.0"],"ru":["Требует настройки хука до фиксации","Ограничен стандартами Conventional Commits 1.0.0"],"ar":["يتطلب إعداد hook ما قبل التعهد","محدود بمواصفات الإلتزامات التقليدية 1.0.0"]},"version":4},"contentHash":"fc8fb9ca20df8e0c13e14c7612ee9ea091e38a8b20ed803d80c5a9c0f47759e0","qualityScore":36}');
