INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('konecty/Konecty/testing-patterns', 'testing-patterns', 'konecty', 'Konecty', 'community', 'testing-patterns konecty Konecty community business-process business-solutions crm-platform The testing-patterns skill provides a comprehensive testing setup for Node.js/TypeScript backend using Jest and Supertest, ideal for developers and tech businesses. 测试模式是后端开发中的关键概念，使用Jest + Supertest可以有效地设置测试环境 テスティングパターンはバックエンド開発における重要な概念であり、Jest + Supertestを使用することで効果的にテスト環境を設定できます 테스팅 패턴은 백엔드 개발의 핵심 개념이며 Jest + Supertest를 사용하여 효과적으로 테스트 환경을 설정할 수 있습니다 Los patrones de pruebas son fundamentales para el desarrollo de software. Conoce cómo configurar Jest y Supertest para tu proyecto Node.js/TypeScript Les modèles de tests sont essentiels pour le développement de logiciels. Découvrez comment configurer Jest et Supertest pour votre projet Node.js/TypeScript Testmuster sind für die Softwareentwicklung von entscheidender Bedeutung. Erfahren Sie, wie Sie Jest und Supertest für Ihr Node.js/TypeScript-Projekt konfigurieren O padrão de teste é fundamental para garantir a qualidade do código. Aprenda a configurar Jest e Supertest para testar seu backend Node.js/TypeScript Шаблоны тестирования имеют важное значение для обеспечения качества кода. Узнайте, как настроить Jest и Supertest для тестирования вашего бэкенда Node.js/TypeScript для ИИ Агентов نماذج الاختبار أساسية لضمان جودة الرمز. تعرف على كيفية تكوين Jest و Supertest لاختبار خلفية Node.js/TypeScript لأدوات الذكاء الاصطناعي how to use testing-patterns testing-patterns setup guide Node.js testing patterns Jest and Supertest tutorial testing-patterns vs Jest testing-patterns install testing-patterns alternative what is testing-patterns testing-patterns best practices 测试模式 Jest Supertest 后端测试 Node.js TypeScript mongodb-m AIエージェント 测试环境设置 Implements a testing pyramid with 70% Unit, 20% Integration, and 10% E2E tests Utilizes Jest and Supertest for efficient testing Supports TypeScript for typed testing Installs with npm using commands like ''npm install -D jest @types/jest ts-jest supertest @types/supertest'' Integrates with MongoDB using ''mongodb-m'' package Follows a recommended testing proportion for optimal coverage testing-patterns is a set of testing principles and tools for Node.js/TypeScript backend, following a testing pyramid with recommended proportions of Unit, Integration, and E2E tests.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cooldaemon/dotfiles/ruby-patterns', 'community', 'cooldaemon', 'dotfiles', 'cooldaemon/dotfiles', 'ruby-patterns', 13, 8, 36, '2026-03-07T12:49:32Z', '2026-03-08T01:58:22.034Z', 'e90b0140698ff24c81d8950ba132cfa5afdc410d43a23b6a5a0b884edd6f174e', '{"id":"cooldaemon/dotfiles/ruby-patterns","name":"ruby-patterns","description":{"en":"The ruby-patterns skill provides a set of best practices for Ruby development, including package manager detection and new project setup. It benefits developers by ensuring consistent and efficient project configuration.","zh":"Ruby 模式设置指南，介绍包管理器检测和新项目设置","ja":"Ruby パターンセットアップガイド、パッケージマネージャー検出と新規プロジェクト設定を紹介","ko":"Ruby 패턴 설정 가이드, 패키지 관리자 감지 및 새로운 프로젝트 설정 소개","es":"Los patrones de Ruby permiten detectar el administrador de paquetes y configurar nuevos proyectos de manera efectiva","fr":"Les modèles Ruby permettent de détecter le gestionnaire de paquets et de configurer de nouveaux projets de manière efficace","de":"Die Ruby-Muster ermöglichen die Erkennung des Paket-Managers und die Einrichtung neuer Projekte auf effektive Weise","pt":"O ruby-patterns é um conjunto de padrões e práticas para desenvolvedores Ruby, incluindo detecção de gerenciadores de pacotes e configuração de projetos","ru":"Ruby-паттерны - это набор шаблонов и практик для разработчиков Ruby, включая обнаружение менеджеров пакетов и настройку проектов","ar":"أنماط روبي هي مجموعة من الأنماط والممارسات للمانعين روبي، بما في ذلك كشف المديرين الحزمة وتكوين المشاريع"},"seo":{"title":{"en":"ruby-patterns: Best Practices Setup Guide | AI Agent Skill","zh":"Ruby 模式设置指南 - AI工具","ja":"Ruby パターンセットアップガイド - AIエージェント","ko":"Ruby 패턴 설정 가이드 - AI 에이전트","es":"Guía de Configuración de Patrones de Ruby","fr":"Guide de Configuration des Modèles Ruby","de":"Ruby-Muster-Setup-Anleitung","pt":"Ruby-Patterns: Guia de Configuração para D