INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('F3-Nation/f3-nation/f3-git-workflow', 'f3-git-workflow', 'F3-Nation', 'f3-nation', 'community', 'f3-git-workflow F3-Nation f3-nation community The f3-git-workflow skill enables AI agents to manage a monorepo using a git workflow with feature branches, merge commits, and clear history. It benefits developers working on large-scale projects F3 Nation Git 工作流程使用特性分支和合并提交来维护清晰的历史记录。主要分支包括 main、staging 和 dev。 F3 Nation Git ワークフローは、機能ブランチとマージコミットを使用して明確な履歴を維持します。主なブランチには main、staging、dev があります。 F3 Nation Git 워크플로우는 기능 브랜치와 मर지 커밋을 사용하여 명확한 히스토리를 유지합니다. 주요 브랜치에는 main, staging, dev가 있습니다. El flujo de trabajo de Git de F3 Nation utiliza ramas de características con confirmaciones de merge para mantener un historial claro Le workflow f3-git-workflow utilise des branches de fonctionnalités avec des confirmations de merge pour maintenir un historique clair Der Git-Workflow von F3 Nation verwendet Feature-Branches mit Merge-Commits, um eine klare Historie beizubehalten O F3-Git-Workflow é um fluxo de trabalho de Git que utiliza branches de recursos com commits de merge para manter um histórico claro F3-Git-Workflow - это рабочий процесс Git, который использует ветки функций с коммитами слияния для поддержания четкой истории الف3-جيت-ووركفلو هو تدفق عمل جيت يستخدم فروع الميزات مع عمليات الدمج للتحافظ على سجل واضح how to use f3-git-workflow f3-git-workflow setup guide git workflow management feature branch management monorepo development f3-git-workflow vs gitflow f3-git-workflow install f3 nation monorepo F3 Nation Git 工作流程 Git 工作流程 AIエージェント 软件开发工作流程 Git 分支结构 Git 远程仓库 功能分支 合并提交 Uses feature branches with merge commits for clear history Supports branch structure with main, staging, dev, feat, fix, and bug branches Manages remotes with md and f3 repositories for seamless collaboration Enables push and pull requests from dev to staging and main branches Utilizes merge commits for pre-production testing and production deployment f3-git-workflow is a git workflow management system using feature branches with merge commits for clear history and streamlined development');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('frankxai/arcanea/ReasoningBank with AgentDB', 'community', 'frankxai', 'arcanea', 'frankxai/arcanea', 'ReasoningBank with AgentDB', 3, 1, 36, '2026-02-25T02:23:41Z', '2026-03-06T07:00:20.351Z', 'ac77beb5bd7741be9ecfc1c97874b5a588df87b409b665b5dff863e19db4f355', '{"id":"frankxai/arcanea/ReasoningBank with AgentDB","name":"ReasoningBank with AgentDB","description":{"en":"ReasoningBank with AgentDB provides adaptive learning patterns for AI agents, enabling them to learn from experiences and improve decision-making. This skill benefits developers building intelligent systems with Node.js and AgentDB.","zh":"ReasoningBank with AgentDB 是一个高性能的 AI 智能开发工具，提供快速的模式检索和批处理操作，用于构建高性能的 AI 应用","ja":"ReasoningBank with AgentDB は、高性能の AI エージェント開発ツールで、高速のパターン検索とバッチ処理を提供し、高性能の AI アプリケーションを構築するために使用されます","ko":"ReasoningBank with AgentDB는 고성능의 AI 에이전트 개발 도구로, 빠른 패턴 검색과 배치 처리를 제공하여 고성능의 AI 애플리케이션을 구축하는 데 사용됩니다","es":"ReasoningBank con AgentDB proporciona patrones de aprendizaje adaptativos para agentes AI, mejorando la toma de decisiones y el rendimiento con Node.js y AgentDB","fr":"ReasoningBank avec AgentDB offre des modèles d''apprentissage adaptatifs pour les agents IA, améliorant la prise de décision et les performances avec Node.js et AgentDB","de":"ReasoningBank mit AgentDB bietet adaptive Lernmuster für KI-Agenten, um die Entscheidungsfindung und Leistung mit Node.js und AgentDB zu verbessern","pt":"O ReasoningBank com AgentDB oferece padrões de aprendizado adaptáveis com backend de alto desempenho, permitindo que agentes aprendam com experiências e melhorem a tomada de decisões.","ru":"ReasoningBank с AgentDB предоставляет адаптивные образцы обучения с высокопроизводительным бэкендом, позволяя агентам учиться на опыте и улучшать принятие решений.","ar":"يقدم ReasoningBank مع AgentDB أنماطًا تعليمية قابلة للتكيف مع خلفية عالية الأداء، مما يسمح للوكلاء بالتعلم من الخبرات وتحسين اتخاذ القرارات."},"seo":{"title":{"en":"ReasoningBank with AgentDB: Adaptive Learning Patterns fo...","zh":"ReasoningBank with AgentDB - 高性能AI智能开发指南","ja":"ReasoningBank with AgentDB - 高速AIエージェント開発ガイド","ko":"ReasoningBank with AgentDB - 고성능 AI 에이전트 개발 설정 가이드","es":"Guía de configuración de ReasoningBank con AgentDB para d...","fr":"Mise en place de ReasoningBank avec AgentDB pour les déve...","de":"Einrichtungsleitfaden für ReasoningBank mit AgentDB für E...","pt":"Guia de Configuração do ReasoningBank com AgentDB para De...","ru":"Настройка ReasoningBank с AgentDB: Руководство для Разраб...","ar":"إعداد ReasoningBank مع AgentDB: دليل للمطورين"},"description":{"en":"Unlock 150x faster pattern retrieval with ReasoningBank and AgentDB. Learn how to integrate adaptive learning into your AI agents and improve decision-making...","zh":"ReasoningBank with AgentDB 提供 150x 快速的模式检索和 500x 快速的批处理操作，实现 AI 智能的高性能开发","ja":"ReasoningBank with AgentDB は、150x高速のパターン検索と 500x高速のバッチ処理を提供し、AIエージェントの高性能開発を実現します","ko":"ReasoningBank with AgentDB는 150x 빠른 패턴 검색과 500x 빠른 배치 처리를 제공하여 AI 에이전트의 고성능 개발을 실현합니다","es":"Aprende a implementar ReasoningBank con AgentDB y mejora la toma de decisiones de tus agentes AI con patrones de aprendizaje adaptativos","fr":"Découvrez comment mettre en place ReasoningBank avec AgentDB et améliorer la prise de décision de vos agents IA avec des modèles d''apprentissage adaptatifs","de":"Erfahren Sie, wie Sie ReasoningBank mit AgentDB implementieren und die Entscheidungsfindung Ihrer KI-Agenten mit adaptiven Lernmustern verbessern","pt":"Aprenda a integrar o ReasoningBank com AgentDB para melhorar a tomada de decisões em tempo real com 150x mais rapidez","ru":"Узнайте, как интегрировать ReasoningBank с AgentDB для улучшения принятия решений в режиме реального времени с скоростью 150 раз быстрее","ar":"تعرف على كيفية دمج ReasoningBank مع AgentDB لتحسين اتخاذ القرارات في الوقت الفعلي بسرعة 150 مرة"},"definition":{"en":"ReasoningBank with AgentDB is a living intelligence overlay that enables adaptive learning patterns using AgentDB''s high-performance backend, supporting creators who build universes.","zh":"ReasoningBank with AgentDB 是一个高性能的 AI 智能开发工具，用于构建高性能的 AI 应用","ja":"ReasoningBank with AgentDB は、高性能の AI エージェント開発ツールです","ko":"ReasoningBank with AgentDB는 고성능의 AI 에이전트 개발 도구입니다","es":"ReasoningBank con AgentDB es una tecnología de inteligencia artificial que permite a los agentes aprender de experiencias y mejorar la toma de decisiones","fr":"ReasoningBank avec AgentDB est une technologie d''intelligence artificielle qui permet aux agents d''apprendre à partir d''expériences et d''améliorer la prise de décision","de":"ReasoningBank mit AgentDB ist eine KI-Technologie, die es Agenten ermöglicht, aus Erfahrungen zu lernen und die Entscheidungsfindung zu verbessern","pt":"O que é ReasoningBank com AgentDB? É uma tecnologia de inteligência artificial que fornece padrões de aprendizado adaptáveis para agentes.","ru":"Что такое ReasoningBank с AgentDB? Это технология искусственного интеллекта, предоставляющая адаптивные образцы обучения для агентов.","ar":"ما هو ReasoningBank مع AgentDB؟ هو تقنية ذكاء اصطناعي تقدم أنماطًا تعليمية قابلة للتكيف للوكلاء."},"features":{"en":["Provides 150x faster pattern retrieval using AgentDB''s high-performance backend","Enables agents to learn from experiences, judge outcomes, and distill memories","Supports 100% backward compatibility with existing systems","Requires Node.js 18+ and AgentDB v1.0.7+ for seamless integration","Offers <1ms memory access for efficient decision-making","Utilizes agentic-flow for streamlined AgentDB integration"],"zh":["150x 快速的模式检索","500x 快速的批处理操作","支持 Node.js 18+","支持 AgentDB v1.0.7+","提供高性能的 AI 智能开发"],"ja":["150x高速のパターン検索","500x高速のバッチ処理","Node.js 18+ をサポート","AgentDB v1.0.7+ をサポート","高性能の AI エージェント開発を提供"],"ko":["150x 빠른 패턴 검색","500x 빠른 배치 처리","Node.js 18+ 지원","AgentDB v1.0.7+ 지원","고성능의 AI 에이전트 개발을 제공"],"es":["Patrones de aprendizaje adaptativos con AgentDB","Mejora de la toma de decisiones con aprendizaje de experiencias","Compatibilidad con Node.js 18+","Integración con AgentDB v1.0.7+","Rendimiento mejorado con acceso a memoria en menos de 1ms","Operaciones por lotes 500 veces más rápidas"],"fr":["Modèles d''apprentissage adaptatifs avec AgentDB","Amélioration de la prise de décision avec apprentissage d''expériences","Compatibilité avec Node.js 18+","Intégration avec AgentDB v1.0.7+","Performances améliorées avec accès à la mémoire en moins de 1ms","Opérations par lot 500 fois plus rapides"],"de":["Adaptive Lernmuster mit AgentDB","Verbesserung der Entscheidungsfindung durch Erfahrungslernen","Kompatibilität mit Node.js 18+","Integration mit AgentDB v1.0.7+","Verbesserte Leistung mit Zugriff auf Speicher in weniger als 1ms","Batch-Operationen 500-mal schneller"],"pt":["Padrões de aprendizado adaptáveis com backend de alto desempenho","Aumento de 150x na velocidade de recuperação de padrões","Acesso à memória em menos de 1ms","Compatibilidade de 100% para trás","Integração com Node.js 18+ e AgentDB v1.0.7+"],"ru":["Адаптивные образцы обучения с высокопроизводительным бэкендом","Увеличение скорости извлечения образцов в 150 раз","Доступ к памяти менее 1мс","Совместимость 100% для старых версий","Интеграция с Node.js 18+ и AgentDB v1.0.7+"],"ar":["أنماط تعليمية قابلة للتكيف مع خلفية عالية الأداء","زيادة 150 مرة في سرعة استرجاع الأنماط","وصول إلى الذاكرة في أقل من 1 مللي ثانية","التوافق 100% للخلف","التكامل مع Node.js 18+ و AgentDB v1.0.7+"]},"keywords":{"en":["ReasoningBank with AgentDB setup guide","how to use ReasoningBank with AgentDB for AI agents","ReasoningBank with AgentDB vs other AI overlays","what is ReasoningBank with AgentDB","ReasoningBank with AgentDB install for Node.js","adaptive learning patterns for AI agents with ReasoningBank","AgentDB integration with ReasoningBank","improving decision-making with ReasoningBank and AgentDB","ReasoningBank with AgentDB for creative AI applications"],"zh":["AI智能","高性能开发","ReasoningBank","AgentDB","Node.js","AI开发工具","高性能AI","AIエージェント"],"ja":["AIエージェント","高速開発","ReasoningBank","AgentDB","Node.js","AI開発ツール","高性能AI","AIアプリケーション"],"ko":["AI 에이전트","고성능 개발","ReasoningBank","AgentDB","Node.js","AI 개발 도구","고성능 AI","AI 애플리케이션"],"es":["ReasoningBank con AgentDB","agentes AI","inteligencia artificial","aprendizaje adaptativo","Node.js","AgentDB","desarrollo de software","tecnologías de IA","herramientas de desarrollo"],"fr":["ReasoningBank avec AgentDB","agents IA","intelligence artificielle","apprentissage adaptatif","Node.js","AgentDB","développement de logiciels","technologies de l''IA","outils de développement"],"de":["ReasoningBank mit AgentDB","KI-Agenten","künstliche Intelligenz","adaptives Lernen","Node.js","AgentDB","Software-Entwicklung","KI-Technologien","Entwickler-Tools"],"pt":["ReasoningBank com AgentDB","inteligência artificial","agentes de IA","padrões de aprendizado adaptáveis","backend de alto desempenho","Node.js 18+","AgentDB v1.0.7+","desenvolvimento de IA","ferramentas de IA"],"ru":["ReasoningBank с AgentDB","искусственный интеллект","ИИ агенты","адаптивные образцы обучения","высокопроизводительный бэкенд","Node.js 18+","AgentDB v1.0.7+","разработка ИИ","инструменты ИИ"],"ar":["ReasoningBank مع AgentDB","ذكاء اصطناعي","وكلاء ذكاء اصطناعي","أنماط تعليمية قابلة للتكيف","خلفية عالية الأداء","Node.js 18+","AgentDB v1.0.7+","تطوير ذكاء اصطناعي","أدوات ذكاء اصطناعي"]}},"owner":"frankxai","repo":"arcanea","repoPath":"frankxai/arcanea","stars":3,"forks":1,"updatedAt":"2026-02-25T02:23:41Z","topics":["agents","ai","claude-code","creative-ai","creative-writing","intelligence","mcp","multi-agent","next-js","orchestration","prompts","skills","typescript","vercel-ai-sdk","world-building"],"category":"community","skillMd":{"name":"ReasoningBank with AgentDB","description":"Implement ReasoningBank adaptive learning with AgentDBs 150x faster vector database. Includes trajectory tracking, verdict judgment, memory distillation, and pattern recognition. Use when building self-learning agents, optimizing decision-making, or implementing experience replay systems.","bodyPreview":"# ReasoningBank with AgentDB\r\n\r\n## What This Skill Does\r\n\r\nProvides ReasoningBank adaptive learning patterns using AgentDB''s high-performance backend (150x-12,500x faster). Enables agents to learn from experiences, judge outcomes, distill memories, and improve decision-making over time with 100% backward compatibility.\r\n\r\n**Performance**: 150x faster pattern retrieval, 500x faster batch operations, <1ms memory access.\r\n\r\n## Prerequisites\r\n\r\n- Node.js 18+\r\n- AgentDB v1.0.7+ (via agentic-flow)\r\n-","body":"# ReasoningBank with AgentDB\r\n\r\n## What This Skill Does\r\n\r\nProvides ReasoningBank adaptive learning patterns using AgentDB''s high-performance backend (150x-12,500x faster). Enables agents to learn from experiences, judge outcomes, distill memories, and improve decision-making over time with 100% backward compatibility.\r\n\r\n**Performance**: 150x faster pattern retrieval, 500x faster batch operations, <1ms memory access.\r\n\r\n## Prerequisites\r\n\r\n- Node.js 18+\r\n- AgentDB v1.0.7+ (via agentic-flow)\r\n- Understanding of reinforcement learning concepts (optional)\r\n\r\n---\r\n\r\n## Quick Start with CLI\r\n\r\n### Initialize ReasoningBank Database\r\n\r\n```bash\r\n# Initialize AgentDB for ReasoningBank\r\nnpx agentdb@latest init ./.agentdb/reasoningbank.db --dimension 1536\r\n\r\n# Start MCP server for Claude Code integration\r\nnpx agentdb@latest mcp\r\nclaude mcp add agentdb npx agentdb@latest mcp\r\n```\r\n\r\n### Migrate from Legacy ReasoningBank\r\n\r\n```bash\r\n# Automatic migration with validation\r\nnpx agentdb@latest migrate --source .swarm/memory.db\r\n\r\n# Verify migration\r\nnpx agentdb@latest stats ./.agentdb/reasoningbank.db\r\n```\r\n\r\n---\r\n\r\n## Quick Start with API\r\n\r\n```typescript\r\nimport { createAgentDBAdapter, computeEmbedding } from ''agentic-flow/reasoningbank'';\r\n\r\n// Initialize ReasoningBank with AgentDB\r\nconst rb = await createAgentDBAdapter({\r\n  dbPath: ''.agentdb/reasoningbank.db'',\r\n  enableLearning: true,      // Enable learning plugins\r\n  enableReasoning: true,      // Enable reasoning agents\r\n  cacheSize: 1000,            // 1000 pattern cache\r\n});\r\n\r\n// Store successful experience\r\nconst query = \"How to optimize database queries?\";\r\nconst embedding = await computeEmbedding(query);\r\n\r\nawait rb.insertPattern({\r\n  id: '''',\r\n  type: ''experience'',\r\n  domain: ''database-optimization'',\r\n  pattern_data: JSON.stringify({\r\n    embedding,\r\n    pattern: {\r\n      query,\r\n      approach: ''indexing + query optimization'',\r\n      outcome: ''success'',\r\n      metrics: { latency_reduction: 0.85 }\r\n    }\r\n  }),\r\n  confidence: 0.95,\r\n  usage_count: 1,\r\n  success_count: 1,\r\n  created_at: Date.now(),\r\n  last_used: Date.now(),\r\n});\r\n\r\n// Retrieve similar experiences with reasoning\r\nconst result = await rb.retrieveWithReasoning(embedding, {\r\n  domain: ''database-optimization'',\r\n  k: 5,\r\n  useMMR: true,              // Diverse results\r\n  synthesizeContext: true,    // Rich context synthesis\r\n});\r\n\r\nconsole.log(''Memories:'', result.memories);\r\nconsole.log(''Context:'', result.context);\r\nconsole.log(''Patterns:'', result.patterns);\r\n```\r\n\r\n---\r\n\r\n## Core ReasoningBank Concepts\r\n\r\n### 1. Trajectory Tracking\r\n\r\nTrack agent execution paths and outcomes:\r\n\r\n```typescript\r\n// Record trajectory (sequence of actions)\r\nconst trajectory = {\r\n  task: ''optimize-api-endpoint'',\r\n  steps: [\r\n    { action: ''analyze-bottleneck'', result: ''found N+1 query'' },\r\n    { action: ''add-eager-loading'', result: ''reduced queries'' },\r\n    { action: ''add-caching'', result: ''improved latency'' }\r\n  ],\r\n  outcome: ''success'',\r\n  metrics: { latency_before: 2500, latency_after: 150 }\r\n};\r\n\r\nconst embedding = await computeEmbedding(JSON.stringify(trajectory));\r\n\r\nawait rb.insertPattern({\r\n  id: '''',\r\n  type: ''trajectory'',\r\n  domain: ''api-optimization'',\r\n  pattern_data: JSON.stringify({ embedding, pattern: trajectory }),\r\n  confidence: 0.9,\r\n  usage_count: 1,\r\n  success_count: 1,\r\n  created_at: Date.now(),\r\n  last_used: Date.now(),\r\n});\r\n```\r\n\r\n### 2. Verdict Judgment\r\n\r\nJudge whether a trajectory was successful:\r\n\r\n```typescript\r\n// Retrieve similar past trajectories\r\nconst similar = await rb.retrieveWithReasoning(queryEmbedding, {\r\n  domain: ''api-optimization'',\r\n  k: 10,\r\n});\r\n\r\n// Judge based on similarity to successful patterns\r\nconst verdict = similar.memories.filter(m =>\r\n  m.pattern.outcome === ''success'' &&\r\n  m.similarity > 0.8\r\n).length > 5 ? ''likely_success'' : ''needs_review'';\r\n\r\nconsole.log(''Verdict:'', verdict);\r\nconsole.log(''Confidence:'', similar.memories[0]?.similarity || 0);\r\n```\r\n\r\n### 3. Memory Distillation\r\n\r\nConsolidate similar experiences into patterns:\r\n\r\n```typescript\r\n// Get all experiences in domain\r\nconst experiences = await rb.retrieveWithReasoning(embedding, {\r\n  domain: ''api-optimization'',\r\n  k: 100,\r\n  optimizeMemory: true,  // Automatic consolidation\r\n});\r\n\r\n// Distill into high-level pattern\r\nconst distilledPattern = {\r\n  domain: ''api-optimization'',\r\n  pattern: ''For N+1 queries: add eager loading, then cache'',\r\n  success_rate: 0.92,\r\n  sample_size: experiences.memories.length,\r\n  confidence: 0.95\r\n};\r\n\r\nawait rb.insertPattern({\r\n  id: '''',\r\n  type: ''distilled-pattern'',\r\n  domain: ''api-optimization'',\r\n  pattern_data: JSON.stringify({\r\n    embedding: await computeEmbedding(JSON.stringify(distilledPattern)),\r\n    pattern: distilledPattern\r\n  }),\r\n  confidence: 0.95,\r\n  usage_count: 0,\r\n  success_count: 0,\r\n  created_at: Date.now(),\r\n  last_used: Date.now(),\r\n});\r\n```\r\n\r\n---\r\n\r\n## Integration with Reasoning Agents\r\n\r\nAgentDB provides 4 reasoning modules that enhance ReasoningBank:\r\n\r\n### 1. PatternMatcher\r\n\r\nFind similar successful patterns:\r\n\r\n```typescript\r\nconst result = await rb.retrieveWithReasoning(queryEmbedding, {\r\n  domain: ''problem-solving'',\r\n  k: 10,\r\n  useMMR: true,  // Maximal Marginal Relevance for diversity\r\n});\r\n\r\n// PatternMatcher returns diverse, relevant memories\r\nresult.memories.forEach(mem => {\r\n  console.log(`Pattern: ${mem.pattern.approach}`);\r\n  console.log(`Similarity: ${mem.similarity}`);\r\n  console.log(`Success Rate: ${mem.success_count / mem.usage_count}`);\r\n});\r\n```\r\n\r\n### 2. ContextSynthesizer\r\n\r\nGenerate rich context from multiple memories:\r\n\r\n```typescript\r\nconst result = await rb.retrieveWithReasoning(queryEmbedding, {\r\n  domain: ''code-optimization'',\r\n  synthesizeContext: true,  // Enable context synthesis\r\n  k: 5,\r\n});\r\n\r\n// ContextSynthesizer creates coherent narrative\r\nconsole.log(''Synthesized Context:'', result.context);\r\n// \"Based on 5 similar optimizations, the most effective approach\r\n//  involves profiling, identifying bottlenecks, and applying targeted\r\n//  improvements. Success rate: 87%\"\r\n```\r\n\r\n### 3. MemoryOptimizer\r\n\r\nAutomatically consolidate and prune:\r\n\r\n```typescript\r\nconst result = await rb.retrieveWithReasoning(queryEmbedding, {\r\n  domain: ''testing'',\r\n  optimizeMemory: true,  // Enable automatic optimization\r\n});\r\n\r\n// MemoryOptimizer consolidates similar patterns and prunes low-quality\r\nconsole.log(''Optimizations:'', result.optimizations);\r\n// { consolidated: 15, pruned: 3, improved_quality: 0.12 }\r\n```\r\n\r\n### 4. ExperienceCurator\r\n\r\nFilter by quality and relevance:\r\n\r\n```typescript\r\nconst result = await rb.retrieveWithReasoning(queryEmbedding, {\r\n  domain: ''debugging'',\r\n  k: 20,\r\n  minConfidence: 0.8,  // Only high-confidence experiences\r\n});\r\n\r\n// ExperienceCurator returns only quality experiences\r\nresult.memories.forEach(mem => {\r\n  console.log(`Confidence: ${mem.confidence}`);\r\n  console.log(`Success Rate: ${mem.success_count / mem.usage_count}`);\r\n});\r\n```\r\n\r\n---\r\n\r\n## Legacy API Compatibility\r\n\r\nAgentDB maintains 100% backward compatibility with legacy ReasoningBank:\r\n\r\n```typescript\r\nimport {\r\n  retrieveMemories,\r\n  judgeTrajectory,\r\n  distillMemories\r\n} from ''agentic-flow/reasoningbank'';\r\n\r\n// Legacy API works unchanged (uses AgentDB backend automatically)\r\nconst memories = await retrieveMemories(query, {\r\n  domain: ''code-generation'',\r\n  agent: ''coder''\r\n});\r\n\r\nconst verdict = await judgeTrajectory(trajectory, query);\r\n\r\nconst newMemories = await distillMemories(\r\n  trajectory,\r\n  verdict,\r\n  query,\r\n  { domain: ''code-generation'' }\r\n);\r\n```\r\n\r\n---\r\n\r\n## Performance Characteristics\r\n\r\n- **Pattern Search**: 150x faster (100µs vs 15ms)\r\n- **Memory Retrieval**: <1ms (with cache)\r\n- **Batch Insert**: 500x faster (2ms vs 1s for 100 patterns)\r\n- **Trajectory Judgment**: <5ms (including retrieval + analysis)\r\n- **Memory Distillation**: <50ms (consolidate 100 patterns)\r\n\r\n---\r\n\r\n## Advanced Patterns\r\n\r\n### Hierarchical Memory\r\n\r\nOrganize memories by abstraction level:\r\n\r\n```typescript\r\n// Low-level: Specific implementation\r\nawait rb.insertPattern({\r\n  type: ''concrete'',\r\n  domain: ''debugging/null-pointer'',\r\n  pattern_data: JSON.stringify({\r\n    embedding,\r\n    pattern: { bug: ''NPE in UserService.getUser()'', fix: ''Add null check'' }\r\n  }),\r\n  confidence: 0.9,\r\n  // ...\r\n});\r\n\r\n// Mid-level: Pattern across similar cases\r\nawait rb.insertPattern({\r\n  type: ''pattern'',\r\n  domain: ''debugging'',\r\n  pattern_data: JSON.stringify({\r\n    embedding,\r\n    pattern: { category: ''null-pointer'', approach: ''defensive-checks'' }\r\n  }),\r\n  confidence: 0.85,\r\n  // ...\r\n});\r\n\r\n// High-level: General principle\r\nawait rb.insertPattern({\r\n  type: ''principle'',\r\n  domain: ''software-engineering'',\r\n  pattern_data: JSON.stringify({\r\n    embedding,\r\n    pattern: { principle: ''fail-fast with clear errors'' }\r\n  }),\r\n  confidence: 0.95,\r\n  // ...\r\n});\r\n```\r\n\r\n### Multi-Domain Learning\r\n\r\nTransfer learning across domains:\r\n\r\n```typescript\r\n// Learn from backend optimization\r\nconst backendExperience = await rb.retrieveWithReasoning(embedding, {\r\n  domain: ''backend-optimization'',\r\n  k: 10,\r\n});\r\n\r\n// Apply to frontend optimization\r\nconst transferredKnowledge = backendExperience.memories.map(mem => ({\r\n  ...mem,\r\n  domain: ''frontend-optimization'',\r\n  adapted: true,\r\n}));\r\n```\r\n\r\n---\r\n\r\n## CLI Operations\r\n\r\n### Database Management\r\n\r\n```bash\r\n# Export trajectories and patterns\r\nnpx agentdb@latest export ./.agentdb/reasoningbank.db ./backup.json\r\n\r\n# Import experiences\r\nnpx agentdb@latest import ./experiences.json\r\n\r\n# Get statistics\r\nnpx agentdb@latest stats ./.agentdb/reasoningbank.db\r\n# Shows: total patterns, domains, confidence distribution\r\n```\r\n\r\n### Migration\r\n\r\n```bash\r\n# Migrate from legacy ReasoningBank\r\nnpx agentdb@latest migrate --source .swarm/memory.db --target .agentdb/reasoningbank.db\r\n\r\n# Validate migration\r\nnpx agentdb@latest stats .agentdb/reasoningbank.db\r\n```\r\n\r\n---\r\n\r\n## Troubleshooting\r\n\r\n### Issue: Migration fails\r\n```bash\r\n# Check source database exists\r\nls -la .swarm/memory.db\r\n\r\n# Run with verbose logging\r\nDEBUG=agentdb:* npx agentdb@latest migrate --source .swarm/memory.db\r\n```\r\n\r\n### Issue: Low confidence scores\r\n```typescript\r\n// Enable context synthesis for better quality\r\nconst result = await rb.retrieveWithReasoning(embedding, {\r\n  synthesizeContext: true,\r\n  useMMR: true,\r\n  k: 10,\r\n});\r\n```\r\n\r\n### Issue: Memory growing too large\r\n```typescript\r\n// Enable automatic optimization\r\nconst result = await rb.retrieveWithReasoning(embedding, {\r\n  optimizeMemory: true,  // Consolidates similar patterns\r\n});\r\n\r\n// Or manually optimize\r\nawait rb.optimize();\r\n```\r\n\r\n---\r\n\r\n## Learn More\r\n\r\n- **AgentDB Integration**: node_modules/agentic-flow/docs/AGENTDB_INTEGRATION.md\r\n- **GitHub**: https://github.com/ruvnet/agentic-flow/tree/main/packages/agentdb\r\n- **MCP Integration**: `npx agentdb@latest mcp`\r\n- **Website**: https://agentdb.ruv.io\r\n\r\n---\r\n\r\n**Category**: Machine Learning / Reinforcement Learning\r\n**Difficulty**: Intermediate\r\n**Estimated Time**: 20-30 minutes\r\n"},"lastSynced":"2026-03-06T07:00:20.351Z","agentAnalysis":{"suitability":{"en":"Perfect for Intelligent Agents needing adaptive learning patterns with high-performance backend capabilities.","zh":"非常适合需要自适应学习模式和高性能后端能力的智能代理。","ja":"高性能バックエンド機能と適応型学習パターンを必要とするインテリジェントエージェントに最適です。","ko":"적응형 학습 패턴과 고성능 백엔드 기능이 필요한 인텔리전트 에이전트에게 완벽합니다.","es":"Perfecto para Agentes Inteligentes que necesitan patrones de aprendizaje adaptativo con capacidades de backend de alto rendimiento.","fr":"Parfait pour les Agents Intelligents ayant besoin de modèles d''apprentissage adaptatif avec des capacités de backend haute performance.","de":"Perfekt für intelligente Agenten, die adaptive Lernmuster mit Hochleistungs-Backend-Fähigkeiten benötigen.","pt":"Perfeito para Agentes Inteligentes que necessitam de padrões de aprendizado adaptativos com capacidades de backend de alto desempenho.","ru":"Идеально подходит для интеллектуальных агентов, требующих адаптивных моделей обучения с возможностями высокопроизводительного бэкенда.","ar":"مثالي للوكلاء الذكيين الذين يحتاجون إلى أنماط تعلم متكيفة مع إمكانيات خلفية عالية الأداء."},"recommendation":{"en":"Empowers agents to learn from experiences, judge outcomes, and improve decision-making using AgentDB''s high-performance backend, enabling 150x-12,500x faster pattern retrieval and 100% backward compatibility with Node.js and AgentDB.","zh":"赋予代理从经验中学习、判断结果并使用AgentDB的高性能后端提高决策能力的能力，实现150x-12,500x更快的模式检索和与Node.js和AgentDB 100%向后兼容。","ja":"エージェントに経験から学び、結果を判断し、AgentDBの高性能バックエンドを使用して意思決定を改善する能力を付与し、150x-12,500x高速なパターン取得とNode.jsおよびAgentDBとの100%の後方互換性を実現します。","ko":"에이전트가 경험에서 학습하고 결과를 판단하며 AgentDB의 고성능 백엔드를 사용하여 의사결정 능력을 향상시키는 기능을 제공하여 150x-12,500x 더 빠른 패턴 검색과 Node.js 및 AgentDB와 100%의 하위 호환성을 구현합니다.","es":"Habilita a los agentes a aprender de las experiencias, juzgar los resultados y mejorar la toma de decisiones utilizando el backend de alto rendimiento de AgentDB, lo que permite una recuperación de patrones 150x-12.500x más rápida y una compatibilidad hacia atrás del 100% con Node.js y AgentDB.","fr":"Permet aux agents d''apprendre des expériences, de juger les résultats et d''améliorer la prise de décision en utilisant le backend haute performance d''AgentDB, permettant une récupération de modèles 150x-12 500x plus rapide et une compatibilité descendante de 100 % avec Node.js et AgentDB.","de":"Ermöglicht es Agenten, aus Erfahrungen zu lernen, Ergebnisse zu beurteilen und die Entscheidungsfindung mithilfe des Hochleistungs-Backends von AgentDB zu verbessern, wodurch eine 150x-12.500x schnellere Musterabruf und eine 100%ige Abwärtskompatibilität mit Node.js und AgentDB ermöglicht wird.","pt":"Habilita os agentes a aprender com experiências, julgar resultados e melhorar a tomada de decisões usando o backend de alto desempenho do AgentDB, permitindo uma recuperação de padrões 150x-12.500x mais rápida e 100% de compatibilidade retroativa com Node.js e AgentDB.","ru":"Наделяет агентов возможностью учиться на опыте, оценивать результаты и совершенствовать принятие решений с помощью высокопроизводительного бэкенда AgentDB, обеспечивая 150x-12.500x более быстрое извлечение моделей и 100% обратную совместимость с Node.js и AgentDB.","ar":"تمكّن الوكلاء من التعلم من الخبرات وتقييم النتائج وتحسين اتخاذ القرارات باستخدام الخلفية ذات الأداء العالي من AgentDB، مما يسمح باحتواء أنماط 150x-12،500x أسرع و100٪ من التوافق العكسي مع Node.js وAgentDB."},"useCases":{"en":["Enhancing decision-making capabilities through adaptive learning","Improving agent performance with high-speed pattern retrieval","Developing intelligent systems with Node.js and AgentDB"],"zh":["通过自适应学习增强决策能力","使用高速模式检索提高代理性能","使用Node.js和AgentDB开发智能系统"],"ja":["適応型学習による意思決定能力の向上","高速パターン取得によるエージェントの性能向上","Node.jsおよびAgentDBを使用したインテリジェントシステムの開発"],"ko":["적응형 학습을 통한 의사결정 능력 향상","고속 패턴 검색을 통한 에이전트 성능 개선","Node.js 및 AgentDB를 사용한 인텔리전트 시스템 개발"],"es":["Mejorar las capacidades de toma de decisiones a través del aprendizaje adaptativo","Mejorar el rendimiento del agente con una recuperación de patrones de alta velocidad","Desarrollar sistemas inteligentes con Node.js y AgentDB"],"fr":["Améliorer les capacités de prise de décision grâce à l''apprentissage adaptatif","Améliorer les performances de l''agent avec une récupération de modèles à haute vitesse","Développer des systèmes intelligents avec Node.js et AgentDB"],"de":["Verbesserung der Entscheidungskapazitäten durch adaptives Lernen","Verbesserung der Leistung des Agents durch Hochgeschwindigkeitsmusterabruf","Entwicklung intelligenter Systeme mit Node.js und AgentDB"],"pt":["Melhorar as capacidades de tomada de decisões por meio do aprendizado adaptativo","Melhorar o desempenho do agente com recuperação de padrões de alta velocidade","Desenvolver sistemas inteligentes com Node.js e AgentDB"],"ru":["Улучшение возможностей принятия решений за счет адаптивного обучения","Повышение производительности агента за счет высокоскоростной извлечения моделей","Разработка интеллектуальных систем с помощью Node.js и AgentDB"],"ar":["تحسين قدرات اتخاذ القرارات من خلال التعلم المتكيف","تحسين أداء الوكيل بسرعة استرجاع الأنماط العالية","تطوير الأنظمة الذكية مع Node.js وAgentDB"]},"limitations":{"en":["Requires Node.js 18+","AgentDB v1.0.7+ via agentic-flow"],"zh":["需要Node.js 18+","需要通过agentic-flow的AgentDB v1.0.7+"],"ja":["Node.js 18+が必要","agentic-flow経由のAgentDB v1.0.7+が必要"],"ko":["Node.js 18+ 필요","agentic-flow를 통한 AgentDB v1.0.7+ 필요"],"es":["Requiere Node.js 18+","AgentDB v1.0.7+ a través de agentic-flow"],"fr":["Nécessite Node.js 18+","AgentDB v1.0.7+ via agentic-flow"],"de":["Benötigt Node.js 18+","AgentDB v1.0.7+ über agentic-flow"],"pt":["Requer Node.js 18+","AgentDB v1.0.7+ via agentic-flow"],"ru":["Требуется Node.js 18+","AgentDB v1.0.7+ через agentic-flow"],"ar":["يتطلب Node.js 18+","AgentDB v1.0.7+ من خلال agentic-flow"]},"version":4},"contentHash":"ac77beb5bd7741be9ecfc1c97874b5a588df87b409b665b5dff863e19db4f355","qualityScore":36}');
