INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('frankxai/arcanea/ReasoningBank with AgentDB', 'ReasoningBank with AgentDB', 'frankxai', 'arcanea', 'community', 'ReasoningBank with AgentDB frankxai arcanea community agents ai claude-code creative-ai creative-writing intelligence mcp multi-agent next-js orchestration prompts skills typescript vercel-ai-sdk world-building ReasoningBank with AgentDB provides adaptive learning patterns for AI agents, enabling them to learn from experiences and improve decision-making. This skill benefits developers building intelligent systems with Node.js and AgentDB. ReasoningBank with AgentDB 是一个高性能的 AI 智能开发工具，提供快速的模式检索和批处理操作，用于构建高性能的 AI 应用 ReasoningBank with AgentDB は、高性能の AI エージェント開発ツールで、高速のパターン検索とバッチ処理を提供し、高性能の AI アプリケーションを構築するために使用されます ReasoningBank with AgentDB는 고성능의 AI 에이전트 개발 도구로, 빠른 패턴 검색과 배치 처리를 제공하여 고성능의 AI 애플리케이션을 구축하는 데 사용됩니다 ReasoningBank con AgentDB proporciona patrones de aprendizaje adaptativos para agentes AI, mejorando la toma de decisiones y el rendimiento con Node.js y AgentDB ReasoningBank avec AgentDB offre des modèles d''apprentissage adaptatifs pour les agents IA, améliorant la prise de décision et les performances avec Node.js et AgentDB ReasoningBank mit AgentDB bietet adaptive Lernmuster für KI-Agenten, um die Entscheidungsfindung und Leistung mit Node.js und AgentDB zu verbessern O ReasoningBank com AgentDB oferece padrões de aprendizado adaptáveis com backend de alto desempenho, permitindo que agentes aprendam com experiências e melhorem a tomada de decisões. ReasoningBank с AgentDB предоставляет адаптивные образцы обучения с высокопроизводительным бэкендом, позволяя агентам учиться на опыте и улучшать принятие решений. يقدم ReasoningBank مع AgentDB أنماطًا تعليمية قابلة للتكيف مع خلفية عالية الأداء، مما يسمح للوكلاء بالتعلم من الخبرات وتحسين اتخاذ القرارات. ReasoningBank with AgentDB setup guide how to use ReasoningBank with AgentDB for AI agents ReasoningBank with AgentDB vs other AI overlays what is ReasoningBank with AgentDB ReasoningBank with AgentDB install for Node.js adaptive learning patterns for AI agents with ReasoningBank AgentDB integration with ReasoningBank improving decision-making with ReasoningBank and AgentDB ReasoningBank with AgentDB for creative AI applications AI智能 高性能开发 ReasoningBank AgentDB Node.js AI开发工具 高性能AI AIエージェント Provides 150x faster pattern retrieval using AgentDB''s high-performance backend Enables agents to learn from experiences, judge outcomes, and distill memories Supports 100% backward compatibility with existing systems Requires Node.js 18+ and AgentDB v1.0.7+ for seamless integration Offers <1ms memory access for efficient decision-making Utilizes agentic-flow for streamlined AgentDB integration ReasoningBank with AgentDB is a living intelligence overlay that enables adaptive learning patterns using AgentDB''s high-performance backend, supporting creators who build universes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('addozhang/openclaw-forge/research-prep', 'community', 'addozhang', 'openclaw-forge', 'addozhang/openclaw-forge', 'research-prep', 0, 0, 36, '2026-03-08T01:57:15.264Z', '2026-03-08T01:59:42.502Z', 'ba14d8cb34cd0a0cd8586cdfc1f19bc373192e6b71f0ef9c2f9b95dc7ac3188f', '{"id":"addozhang/openclaw-forge/research-prep","name":"research-prep","description":{"en":"The research-prep skill automates research tasks for developers, collecting and organizing primary sources from official documentation, GitHub, and Stack Overflow. It benefits developers by streamlining their research process.","zh":"研究准备工具是一种AI助手技能，专注于研究阶段的资料收集和整理，支持多源搜索和智能过滤","ja":"研究準備ツールは、研究ステージでの資料収集と整理に特化したAIエージェントのスキルです","ko":"연구 준비도구는 연구 단계의 자료 수집과 정리를 위한 AI 에이전트의 기술입니다","es":"Research-prep es una herramienta de investigación de AI que recopila y estructura datos de fuentes oficiales como GitHub y Stack Overflow para simplificar la investigación","fr":"Research-prep est un outil de recherche d''IA qui collecte et structure des données à partir de sources officielles comme GitHub et Stack Overflow pour simplifier la recherche","de":"Research-prep ist ein KI-Recherche-Tool, das Daten aus offiziellen Quellen wie GitHub und Stack Overflow sammelt und strukturiert, um die Recherche zu vereinfachen","pt":"O research-prep é uma habilidade de coleta e organização de materiais de pesquisa, utilizando fontes oficiais e tecnologias como GitHub CLI. Ele ajuda a preparar o conteúdo para escrita de blogs.","ru":"Research-prep - это навык сбора и организации исследовательских материалов, использующий официальные источники и технологии, такие как GitHub CLI и ИИ Агенты. Он помогает подготовить контент для написания блогов.","ar":"research-prep هو مهارة لجمع وتنظيم مواد البحث، باستخدام المصادر الرسمية وتقنيات مثل GitHub CLI وأدوات الذكاء الاصطناعي. يساعد في إعداد المحتوى للكتابة على المدونات."},"seo":{"title":{"en":"research-prep: AI-Powered Research Assistance for Develop...","zh":"研究准备工具设置指南 - 多源搜索和智能过滤","ja":"研究準備ツールのベストプラクティス - AIエージェントによる多元検索","ko":"연구 준비도구 설정 가이드 - 다중 소스 검색과 스마트 필터링","es":"Guía de configuración de research-prep: Herramienta de in...","fr":"Guide de mise en place de research-prep: Outil de recherc...","de":"Einrichtungsleitfaden für research-prep: KI-Recherche-Tool","pt":"Configuração de Pesquisa Avançada com research-prep","ru":"Настройка исследовательской подготовки с помощью research...","ar":"إعداد البحث المسبق مع research-prep أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient research with research-prep. Discover how to automate research tasks, filter credible sources, and generate structured research materials wi...","zh":"研究准备工具帮助您高效收集和整理研究资料，支持多源搜索、智能过滤和结构化输出","ja":"研究準備ツールは、AIエージェントを使用して多元検索を行い、関連情報をスマートにフィルタリングして構造化された資料を出力します","ko":"연구 준비도구는 다중 소스 검색, 스마트 필터링, 구조화된 출력을 지원하여 연구 자료 수집과 정리를 효율적으로 도와줍니다","es":"Descubre cómo configurar research-prep, una herramienta de investigación de AI que recopila y estructura datos de fuentes oficiales como GitHub y Stack Overflow","fr":"Découvrez comment configurer research-prep, un outil de recherche d''IA qui collecte et structure des données à partir de sources officielles comme GitHub et ...","de":"Erfahren Sie, wie Sie research-prep einrichten, ein KI-Recherche-Tool, das Daten aus offiziellen Quellen wie GitHub und Stack Overflow sammelt und strukturiert","pt":"Aprenda a configurar o research-prep para coletar e organizar materiais de pesquisa de forma eficiente, utilizando fontes oficiais e tecnologias como GitHub CLI","ru":"Узнайте, как настроить research-prep для сбора и организации исследовательских материалов, используя официальные источники и технологии, такие как GitHub CLI...","ar":"تعلم كيفية إعداد research-prep لجمع وتنظيم مواد البحث بفعالية، باستخدام المصادر الرسمية وتقنيات مثل GitHub CLI وأدوات الذكاء الاصطناعي"},"definition":{"en":"research-prep is an AI agent skill that automates the research stage of blog writing, collecting primary sources and organizing them into a structured library.","zh":"研究准备工具是一种AI助手技能，用于高效收集和整理研究资料","ja":"研究準備ツールは、研究資料の収集と整理を効率化するためのAIエージェントのスキルです","ko":"연구 준비도구는 연구 자료의 수집과 정리를 효율적으로 도와주는 AI 에이전트의 기술입니다","es":"Research-prep es una herramienta de investigación de AI que utiliza técnicas de búsqueda avanzadas para recopilar y estructurar datos","fr":"Research-prep est un outil de recherche d''IA qui utilise des techniques de recherche avancées pour collecter et structurer des données","de":"Research-prep ist ein KI-Recherche-Tool, das fortschrittliche Suchtechniken verwendet, um Daten zu sammeln und zu strukturieren","pt":"O que é research-prep? É uma habilidade de coleta e organização de materiais de pesquisa para escrita de blogs.","ru":"Что такое research-prep? Это навык сбора и организации исследовательских материалов для написания блогов с помощью ИИ Агентов.","ar":"ما هو research-prep؟ هو مهارة لجمع وتنظيم مواد البحث للكتابة على المدونات باستخدام أدوات الذكاء الاصطناعي."},"features":{"en":["Utilizes Web search with site syntax to gather official documentation","Leverages GitHub CLI for searching real project codes and README files","Analyzes Stack Overflow for high-vote questions and practical problems","Filters and categorizes sources based on authority and relevance","Generates standardized research material files in a designated directory"],"zh":["多源搜索：支持官方文档、GitHub源码、技术讨论和Stack Overflow的搜索","智能过滤：识别一手资料和二手资料，按权威性和相关性排序","结构化输出：生成标准格式的研究资料文件","自动去重和归类：自动去除重复信息和归类资料","提取关键信息摘要：自动提取研究资料的关键信息摘要"],"ja":["多元検索：公式ドキュメント、GitHubソースコード、技術ディスカッション、Stack Overflowの検索をサポート","スマートフィルタリング：一次資料と二次資料を識別し、権威性と関連性でソート","構造化出力：標準形式の研究資料ファイルを生成","自動除重と分類：重複情報を自動除去し、資料を分類","重要情報の抽出：研究資料の重要情報を自動抽出"],"ko":["다중 소스 검색：공식 문서, GitHub 소스 코드, 기술 토론, Stack Overflow의 검색을 지원","스마트 필터링：1차 자료와 2차 자료를 식별하고, 권위성과 관련성으로 정렬","구조화된 출력：표준 형식의 연구 자료 파일을 생성","자동 제거와 분류：중복 정보를 자동 제거하고, 자료를 분류","핵심 정보 추출：연구 자료의 핵심 정보를 자동 추출"],"es":["Búsqueda avanzada en fuentes oficiales como GitHub y Stack Overflow","Estructuración de datos en un formato estándar","Filtrado y clasificación automática de resultados","Extracción de información clave y resumen","Integración con herramientas de desarrollo como GitHub CLI"],"fr":["Recherche avancée dans des sources officielles comme GitHub et Stack Overflow","Structuration des données dans un format standard","Filtrage et classification automatique des résultats","Extraction d''informations clés et résumé","Intégration avec des outils de développement comme GitHub CLI"],"de":["Erweiterte Suche in offiziellen Quellen wie GitHub und Stack Overflow","Strukturierung von Daten in einem Standardformat","Automatische Filterung und Klassifizierung von Ergebnissen","Extraktion von Schlüsselinformationen und Zusammenfassung","Integration mit Entwicklungstools wie GitHub CLI"],"pt":["Coleta de materiais de pesquisa de fontes oficiais","Utilização de GitHub CLI para busca de código","Filtragem e classificação de materiais","Geração de arquivos de pesquisa em formato padrão","Suporte a múltiplas fontes de pesquisa, incluindo Stack Overflow"],"ru":["Сбор исследовательских материалов из официальных источников","Использование GitHub CLI для поиска кода","Фильтрация и классификация материалов","Генерация исследовательских файлов в стандартном формате","Поддержка множества источников исследования, включая Stack Overflow и ИИ Агенты"],"ar":["جمع مواد البحث من المصادر الرسمية","استخدام GitHub CLI للبحث عن الكود","تنقية وتصنيف المواد","إنتاج ملفات البحث في تنسيق معياري","دعم مصادر بحث متعددة، بما في ذلك Stack Overflow وأدوات الذكاء الاصطناعي"]},"keywords":{"en":["research-prep setup guide","what is research-prep","research-prep alternative","how to use research-prep for blog writing","research-prep vs traditional research methods","installing research-prep for AI agents","research-prep for developers","automating research with research-prep","research-prep and GitHub integration","research-prep tutorial"],"zh":["研究准备工具","AI助手技能","多源搜索","智能过滤","结构化输出","研究资料收集","研究资料整理","AI工具","研究辅助工具"],"ja":["研究準備ツール","AIエージェントのスキル","多元検索","スマートフィルタリング","構造化出力","研究資料の収集","研究資料の整理","AIエージェント","研究支援ツール"],"ko":["연구 준비도구","AI 에이전트의 기술","다중 소스 검색","스마트 필터링","구조화된 출력","연구 자료 수집","연구 자료 정리","AI 에이전트","연구 지원 도구"],"es":["herramientas de investigación de AI","research-prep","GitHub","Stack Overflow","desarrollo de software","investigación de datos","análisis de datos","integración de herramientas de desarrollo"],"fr":["outils de recherche d''IA","research-prep","GitHub","Stack Overflow","développement de logiciels","recherche de données","analyse de données","intégration d''outils de développement"],"de":["KI-Recherche-Tools","research-prep","GitHub","Stack Overflow","Software-Entwicklung","Datenrecherche","Datenanalyse","Integration von Entwicklungstools"],"pt":["research-prep","coleta de materiais de pesquisa","GitHub CLI","fontes oficiais","escrita de blogs","otimização de pesquisa","ferramentas de pesquisa","tecnologias de pesquisa"],"ru":["research-prep","сбор исследовательских материалов","GitHub CLI","официальные источники","написание блогов","оптимизация поиска","инструменты поиска","технологии поиска","ИИ Агенты"],"ar":["research-prep","جمع مواد البحث","GitHub CLI","المصادر الرسمية","كتابة على المدونات","تحسين البحث","أدوات البحث","تكنولوجيا البحث","أدوات الذكاء الاصطناعي"]}},"owner":"addozhang","repo":"openclaw-forge","repoPath":"addozhang/openclaw-forge","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.264Z","topics":[],"category":"community","skillMd":{"name":"research-prep","description":"Collect and organize first-hand research materials for technical writing. Use when the user wants to gather official documentation, source code examples, GitHub issues, or original technical resources before writing. Outputs structured research files ready for the writing phase.","bodyPreview":"# Research Prep - 写作素材收集整理\n\n专注于博客写作前的研究阶段，收集一手资料并整理成结构化素材库。\n\n## 核心能力\n\n### 1. 多源搜索一手资料\n- **官方文档**: Web 搜索限定官方域名（site: 语法）\n- **源码示例**: GitHub CLI (`gh`) 搜索真实项目代码、README\n- **技术讨论**: GitHub Issues、Discussions、Pull Requests\n- **Stack Overflow**: 高票问答和实战问题\n\n### 2. 智能过滤与分类\n- 识别一手资料 vs 二手资料\n- 按权威性和相关性排序\n- 自动去重和归类\n- 提取关键信息摘要\n\n### 3. 结构化输出\n生成标准格式的研究素材文件，保存到 `~/my-obsidian-vault/个人/草稿/` 目录\n\n## 使用流程\n\n### 基本工作流\n\n```\n用户输入主题 → 多源搜索 → 过滤分类 → 提取关键信息 → 生成素材文件\n```\n\n### 快速开始\n\n**场景1: 全新主题研究**\n```\n帮我收集 Kubernetes Gat","body":"# Research Prep - 写作素材收集整理\n\n专注于博客写作前的研究阶段，收集一手资料并整理成结构化素材库。\n\n## 核心能力\n\n### 1. 多源搜索一手资料\n- **官方文档**: Web 搜索限定官方域名（site: 语法）\n- **源码示例**: GitHub CLI (`gh`) 搜索真实项目代码、README\n- **技术讨论**: GitHub Issues、Discussions、Pull Requests\n- **Stack Overflow**: 高票问答和实战问题\n\n### 2. 智能过滤与分类\n- 识别一手资料 vs 二手资料\n- 按权威性和相关性排序\n- 自动去重和归类\n- 提取关键信息摘要\n\n### 3. 结构化输出\n生成标准格式的研究素材文件，保存到 `~/my-obsidian-vault/个人/草稿/` 目录\n\n## 使用流程\n\n### 基本工作流\n\n```\n用户输入主题 → 多源搜索 → 过滤分类 → 提取关键信息 → 生成素材文件\n```\n\n### 快速开始\n\n**场景1: 全新主题研究**\n```\n帮我收集 Kubernetes Gateway API 的资料\n```\n\nAI会：\n1. 使用 `scripts/github_search.sh` 搜索 Kubernetes Gateway API 相关仓库\n2. 使用 `scripts/web_search.sh` 查找官方文档（限定 kubernetes.io 域名）\n3. 使用 `scripts/github_search.sh` 搜索相关 issues 和代码示例\n4. 使用 `scripts/stackoverflow_search.sh` 查找高票问答\n5. 过滤和分类资料（使用 `authority_scorer.py` 评分）\n6. 生成结构化素材文件到 `~/my-obsidian-vault/个人/草稿/k8s-gateway-api.md`\n\n**场景2: 深入特定方面**\n```\n继续收集 Gateway API 的安全实践相关资料\n```\n\nAI会：\n1. 读取现有素材文件\n2. 针对\"安全实践\"深入搜索\n3. 追加新资料到现有文件\n\n**场景3: 更新过期资料**\n```\n更新这篇素材中的官方文档链接\n```\n\nAI会：\n1. 检查素材文件中的链接有效性\n2. 搜索最新版本的文档\n3. 更新失效链接\n\n## 素材文件结构\n\n每个研究素材文件遵循统一格式：\n\n```markdown\n# 研究素材：{主题}\n\n**创建时间**: YYYY-MM-DD  \n**最后更新**: YYYY-MM-DD  \n**状态**: 收集中 | 已完成 | 已使用  \n**相关博客**: [链接] (如果已写成博客)\n\n---\n\n## 📚 官方文档\n\n### {文档标题}\n- **来源**: {官方网站}\n- **链接**: {URL}\n- **版本**: {如适用}\n- **关键要点**:\n  - 要点1\n  - 要点2\n\n## 💻 源码示例\n\n### {项目名称}\n- **仓库**: {GitHub URL}\n- **相关文件**: {文件路径}\n- **代码片段**:\n```language\n// 关键代码\n```\n- **说明**: {为什么这个示例有价值}\n\n## 💬 技术讨论\n\n### {Issue/Discussion 标题}\n- **类型**: Issue | Discussion | PR\n- **链接**: {GitHub URL}\n- **状态**: Open | Closed | Merged\n- **核心观点**:\n  - 观点1\n  - 观点2\n\n## 📝 官方博客/公告\n\n### {文章标题}\n- **来源**: {官方博客}\n- **链接**: {URL}\n- **发布日期**: YYYY-MM-DD\n- **摘要**: {简短总结}\n\n## 🔑 概念卡片\n\n### {术语/概念}\n- **定义**: {清晰定义}\n- **来源**: {权威来源}\n- **相关概念**: {关联术语}\n- **使用场景**: {何时使用}\n\n## 🎯 写作建议\n\n基于收集的资料，建议的写作角度：\n- 角度1\n- 角度2\n\n## 🔗 参考资源\n\n其他有价值的资源：\n- [资源名称](URL) - 简短说明\n\n---\n\n## 📊 素材统计\n\n- 官方文档: X 篇\n- 源码示例: X 个\n- 技术讨论: X 条\n- 官方博客: X 篇\n- 概念卡片: X 个\n```\n\n## 搜索策略\n\n### 官方文档搜索 (Context7)\n\n**目标**: 获取最权威的技术说明\n\n```\n搜索模式:\n- \"{技术名称} official documentation\"\n- \"{技术名称} getting started\"\n- \"{技术名称} API reference\"\n- \"{技术名称} best practices\"\n```\n\n**筛选标准**:\n- ✅ 官方文档网站\n- ✅ 版本化文档\n- ❌ 第三方教程\n- ❌ 博客文章\n\n### 源码搜索 (GitHub)\n\n**目标**: 找到真实的生产级代码示例\n\n```\n搜索策略:\n- 仓库搜索: \"topic:{技术名称} stars:>100\"\n- 代码搜索: \"{关键API} language:{语言} path:{路径模式}\"\n- Issues搜索: \"is:issue label:{标签} state:closed\"\n```\n\n**筛选标准**:\n- ✅ 官方仓库\n- ✅ 知名开源项目\n- ✅ 完整可运行示例\n- ❌ 未维护的旧项目\n- ❌ Demo/测试代码\n\n### 官方博客搜索 (Brave Search)\n\n**目标**: 获取官方的最佳实践和案例研究\n\n```\n搜索策略:\n- \"site:官方域名 {技术名称} {主题}\"\n- \"{技术名称} official blog {关键词}\"\n- \"{技术名称} announcement {版本号}\"\n```\n\n**筛选标准**:\n- ✅ 官方技术博客\n- ✅ 官方更新公告\n- ✅ 官方案例研究\n- ❌ 第三方转载\n- ❌ 营销软文\n\n## 资料质量评估\n\n### 一手资料识别\n\n**一手资料**（优先）:\n- 官方文档、规范、RFC\n- 源代码、配置文件\n- 官方博客、公告\n- 官方 GitHub Issues/PRs\n- 官方示例项目\n\n**二手资料**（谨慎使用）:\n- 技术博客（非官方）\n- 教程、课程\n- Stack Overflow\n- 技术媒体文章\n\n### 权威性评分\n\n参考 [`scripts/authority_scorer.py`](scripts/authority_scorer.py) 自动评估资料权威性。\n\n评分维度：\n- 来源官方性 (40%)\n- 内容时效性 (30%)\n- 技术深度 (20%)\n- 社区认可度 (10%)\n\n## 素材管理\n\n### 文件命名规范\n\n文件保存在 Obsidian 草稿目录：`~/my-obsidian-vault/个人/草稿/`\n\n命名格式：`{topic-slug}.md` 或 `YYYY-MM-DD-{topic-slug}.md`\n\n示例:\n- `~/my-obsidian-vault/个人/草稿/k8s-gateway-api.md`\n- `~/my-obsidian-vault/个人/草稿/2026-02-03-grpc-vs-rest.md`\n\n### 状态标记\n\n素材文件头部的状态字段：\n\n- **收集中**: 正在添加资料\n- **已完成**: 资料收集完成，待写作\n- **已使用**: 已基于此素材写成博客\n- **已归档**: 资料过期或不再使用\n\n### 更新策略\n\n参考 [`scripts/update_research.py`](scripts/update_research.py) 自动更新素材文件。\n\n```bash\n# 检查链接有效性\npython3 scripts/update_research.py ~/my-obsidian-vault/个人/草稿/topic.md\n```\n\n定期检查：\n- 链接有效性（自动识别 404、重定向）\n- 文档版本更新\n- 新增官方资源\n\n## CLI 工具使用\n\n所有搜索功能通过命令行工具实现，无需 MCP servers。\n\n### GitHub 搜索（`scripts/github_search.sh`）\n\n```bash\n# 搜索仓库\n./scripts/github_search.sh repos \"kubernetes gateway\" --limit 10\n\n# 搜索代码\n./scripts/github_search.sh code \"Gateway API\" --repo kubernetes/kubernetes\n\n# 搜索 Issues\n./scripts/github_search.sh issues \"bug\" --repo istio/istio --state closed\n\n# 获取 README\n./scripts/github_search.sh readme kubernetes/gateway-api\n```\n\n**输出**: JSON 格式，包含仓库信息、星标数、更新时间等。\n\n### Web 搜索（`scripts/web_search.sh`）\n\n```bash\n# 搜索网页（DuckDuckGo）\n./scripts/web_search.sh \"kubernetes gateway api official\" 10\n```\n\n**输出**: URL 列表（每行一个）。\n\n**技巧**: 使用 `site:` 限定官方域名：\n```bash\n./scripts/web_search.sh \"site:kubernetes.io gateway api\"\n```\n\n### Stack Overflow 搜索（`scripts/stackoverflow_search.sh`）\n\n```bash\n# 搜索问题\n./scripts/stackoverflow_search.sh \"kubernetes gateway\" 5\n\n# 带标签搜索\n./scripts/stackoverflow_search.sh \"gateway api\" 5 kubernetes\n```\n\n**输出**: 问题标题、URL、评分、回答数、标签。\n\n### 权威性评分（`scripts/authority_scorer.py`）\n\n```bash\n# 评估单个链接\npython3 scripts/authority_scorer.py --url \"https://kubernetes.io/docs/concepts/services-networking/gateway/\" --date \"2025-12-15\" --type \"api-reference\"\n```\n\n**输出**: 总分（0-100）+ 评级星标 + 详细分数。\n\n## 工作模式\n\n### 模式1: 快速收集\n\n适用于新主题的初步研究。\n\n1. 广泛搜索各个来源\n2. 快速过滤明显不相关的资料\n3. 生成初版素材文件\n4. 标记状态为\"收集中\"\n\n### 模式2: 深度挖掘\n\n适用于特定方面的深入研究。\n\n1. 基于已有素材文件\n2. 针对特定子主题深入搜索\n3. 追加高质量资料\n4. 完善概念卡片\n\n### 模式3: 质量提升\n\n适用于准备写作前的最后整理。\n\n1. 检查所有链接有效性\n2. 补充缺失的关键资料\n3. 完善摘要和要点\n4. 添加写作建议\n5. 标记状态为\"已完成\"\n\n## 与 Writing Skill 配合\n\n研究素材文件是 Writing Skill 的输入：\n\n**Research Prep 输出** → **Writing Skill 输入**\n\n```\n~/my-obsidian-vault/个人/草稿/topic.md\n    ↓\nWriting Skill 读取素材\n    ↓\n生成大纲（基于一手资料）\n    ↓\n完善文章内容\n```\n\n**协作流程**:\n\n1. 用户: \"收集 X 技术的资料\"\n2. Research Prep: 生成 `~/my-obsidian-vault/个人/草稿/x.md`\n3. 用户: \"基于这个素材写博客\"\n4. Writing Skill: 读取素材 → 生成大纲 → 完成文章\n\n## 最佳实践\n\n### 收集阶段\n\n1. **广度优先**: 先覆盖主要来源，再深入细节\n2. **权威优先**: 官方文档 > 知名项目 > 技术博客\n3. **版本注意**: 标记文档/代码的版本信息\n4. **及时归纳**: 搜索时同步整理关键要点\n\n### 整理阶段\n\n1. **结构清晰**: 严格遵循素材文件模板\n2. **摘要精炼**: 每条资料附简短摘要\n3. **去重合并**: 相似内容合并，保留最权威的\n4. **标记来源**: 每条资料必须有清晰来源链接\n\n### 质量控制\n\n1. **一手为主**: 80%以上应为一手资料\n2. **时效性**: 优先选择最新版本的资料\n3. **可验证**: 所有链接必须可访问\n4. **相关性**: 每条资料都应与主题直接相关\n\n## 常见问题\n\n**Q: 如何判断是一手还是二手资料？**\nA: 一手资料来自技术的创造者/维护者；二手资料是他人的转述或解读。\n\n**Q: 搜索不到官方文档怎么办？**\nA: 先用 Web Search 限定官方域名（`site:官方域名`），再尝试直接访问项目官网。\n\n**Q: 资料太多怎么办？**\nA: 按权威性评分排序，只保留前20-30条最有价值的。\n\n**Q: 如何处理版本不一致？**\nA: 优先使用最新稳定版本的资料，旧版本标注版本号供参考。\n\n**Q: 素材文件何时算\"完成\"？**\nA: 当包含足够的官方文档、3-5个代码示例、重要技术讨论，且概念卡片完整时。\n\n## 技巧提示\n\n- 💡 说 \"收集 X 技术的资料\" 启动完整研究流程\n- 💡 说 \"深入收集 X 方面的资料\" 针对性补充\n- 💡 说 \"检查这个素材文件的链接\" 维护资料质量\n- 💡 说 \"基于这个素材写博客\" 无缝切换到 Writing Skill\n- 💡 定期运行 `scripts/update_research.py` 保持资料新鲜度\n\n## 参考资料\n\n- [权威性评分算法](references/authority-scoring.md) - 资料评分标准和算法\n- [搜索策略详解](references/search-strategies.md) - 高效搜索技巧和策略\n- [CLI 工具使用指南](references/cli-tools-usage.md) - 完整的命令行工具使用说明\n"},"lastSynced":"2026-03-08T01:59:42.502Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Research Agents needing automated content collection and organization from official documentation, GitHub, and Stack Overflow.","zh":"适合需要从官方文档、GitHub和Stack Overflow自动收集和组织内容的AI研究代理。","ja":"公式ドキュメント、GitHub、Stack Overflowから自動コンテンツ収集と整理が必要なAI研究エージェントに最適です。","ko":"공식 문서, GitHub 및 Stack Overflow에서 자동으로 콘텐츠를 수집하고 조직하는 데 필요한 AI 연구 에이전트에 적합합니다.","es":"Perfecto para agentes de investigación de IA que necesitan una recopilación y organización de contenido automatizada a partir de documentación oficial, GitHub y Stack Overflow.","fr":"Parfait pour les agents de recherche d''IA nécessitant une collecte et une organisation de contenu automatisées à partir de la documentation officielle, GitHub et Stack Overflow.","de":"Perfekt für KI-Forschungsagenten, die eine automatisierte Inhaltsbeschaffung und -organisation aus offizieller Dokumentation, GitHub und Stack Overflow benötigen.","pt":"Perfeito para Agentes de Pesquisa de IA que precisam de coleta e organização de conteúdo automatizadas a partir de documentação oficial, GitHub e Stack Overflow.","ru":"Идеально для агентов исследований ИИ, которым необходима автоматизированная сборка и организация контента из официальной документации, GitHub и Stack Overflow.","ar":"مثالي للوكلاء البحثية في مجال الذكاء الاصطناعي الذين يحتاجون إلى جمع وتنظيم المحتوى автомاتيكيًا من المستندات الرسمية و GitHub و Stack Overflow."},"recommendation":{"en":"Empowers agents to streamline research tasks by collecting and organizing primary sources, utilizing Web searches, GitHub CLI, and Stack Overflow to provide structured and authoritative research materials in a standardized format, leveraging intelligent filtering and classification.","zh":"通过收集和组织原始资料，利用网络搜索、GitHub CLI和Stack Overflow提供结构化和权威的研究资料，从而实现研究任务的简化，利用智能过滤和分类。","ja":"Web検索、GitHub CLI、Stack Overflowを利用して一次資料を収集・整理し、構造化された権威ある研究資料を提供することで、研究タスクを効率化し、インテリジェントなフィルタリングと分類を活用します。","ko":"웹 검색, GitHub CLI 및 Stack Overflow를 사용하여 1차 자료를 수집 및 정리하고 구조화된 권위 있는 연구 자료를 제공하여 연구 작업을 간소화하고 지능형 필터링 및 분류를 활용합니다.","es":"Permite a los agentes optimizar las tareas de investigación recopilando y organizando fuentes primarias, utilizando búsquedas web, GitHub CLI y Stack Overflow para proporcionar materiales de investigación estructurados y autorizados en un formato estandarizado, aprovechando el filtrado y la clasificación inteligentes.","fr":"Permet aux agents de rationaliser les tâches de recherche en collectant et en organisant les sources primaires, en utilisant des recherches web, GitHub CLI et Stack Overflow pour fournir des matériaux de recherche structurés et autorisés dans un format standardisé, en exploitant le filtrage et la classification intelligents.","de":"Ermächtigt Agenten, Forschungsaufgaben zu optimieren, indem sie Primärquellen sammeln und organisieren, Web-Suchen, GitHub CLI und Stack Overflow nutzen, um strukturierte und autorisierte Forschungsmaterialien in einem standardisierten Format bereitzustellen, wobei intelligente Filterung und Klassifizierung genutzt werden.","pt":"Permite que os agentes otimizem as tarefas de pesquisa coletando e organizando fontes primárias, utilizando pesquisas na Web, GitHub CLI e Stack Overflow para fornecer materiais de pesquisa estruturados e autorizados em um formato padronizado, aproveitando a filtragem e classificação inteligentes.","ru":"Позволяет агентам оптимизировать задачи исследования, собирая и организуя первичные источники, используя веб-поиск, GitHub CLI и Stack Overflow для предоставления структурированных и авторитетных исследовательских материалов в стандартизированном формате, используя интеллектуальную фильтрацию и классификацию.","ar":"يمكن للوكلاء بفضلها تحسين مهام البحث من خلال جمع وتنظيم المصادر الأولية، واستخدام عمليات البحث على الويب وواجهة سطر الأوامر GitHub و Stack Overflow لتوفير مواد بحثية منظمة وموثوقة في تنسيق معياري، واستغلال التصفية والتصنيف الذكيين."},"useCases":{"en":["Automating research for technical blog posts","Collecting and organizing GitHub project examples and discussions","Generating structured research materials from Stack Overflow and official documentation"],"zh":["自动化技术博客文章的研究","收集和组织GitHub项目示例和讨论","从Stack Overflow和官方文档生成结构化研究资料"],"ja":["技術ブログ投稿の研究を自動化する","GitHubプロジェクトの例と議論を収集・整理する","Stack Overflowと公式ドキュメントから構造化された研究資料を生成する"],"ko":["기술 블로그 게시물에 대한 연구 자동화","GitHub 프로젝트 예제 및 토론 수집 및 조직","Stack Overflow 및 공식 문서에서 구조화된 연구 자료 생성"],"es":["Automatizar la investigación para publicaciones de blogs técnicos","Recopilar y organizar ejemplos y discusiones de proyectos de GitHub","Generar materiales de investigación estructurados a partir de Stack Overflow y documentación oficial"],"fr":["Automatiser la recherche pour les publications de blog techniques","Collecter et organiser les exemples et les discussions de projets GitHub","Générer des matériaux de recherche structurés à partir de Stack Overflow et de la documentation officielle"],"de":["Automatisierung der Recherche für technische Blog-Beiträge","Sammeln und Organisieren von GitHub-Projektbeispielen und -diskussionen","Erzeugen von strukturierten Forschungsmaterialien aus Stack Overflow und offizieller Dokumentation"],"pt":["Automatizar a pesquisa para postagens de blogues técnicos","Coletar e organizar exemplos e discussões de projetos do GitHub","Gerar materiais de pesquisa estruturados a partir do Stack Overflow e da documentação oficial"],"ru":["Автоматизировать исследования для технических блог-постов","Собирать и организовывать примеры и обсуждения проектов GitHub","Генерировать структурированные исследовательские материалы из Stack Overflow и официальной документации"],"ar":["تعتيم أتمتة البحث لمشاركات المدونة الفنية","اجماع وتدوين أمثلة ومناقشات مشاريع GitHub","توليد مواد بحثية منظمة من Stack Overflow والتوثيق الرسمي"]},"limitations":{"en":["Requires internet access for Web searches and GitHub CLI functionality","Dependent on the quality and availability of primary sources","Limited to research tasks and does not include writing or content generation capabilities"],"zh":["需要网络访问以进行Web搜索和GitHub CLI功能","依赖于原始资料的质量和可用性","仅限于研究任务，不包括写作或内容生成功能"],"ja":["Web検索とGitHub CLIの機能のためにインターネットアクセスが必要","一次資料の品質と可用性に依存する","研究タスクのみに限定され、執筆やコンテンツ生成機能は含まない"],"ko":["웹 검색 및 GitHub CLI 기능을 위해 인터넷 액세스가 필요합니다.","1차 자료의 품질 및 가용성에 종속됩니다.","연구 작업만 해당하며, 작성을 포함한 콘텐츠 생성 기능은 포함되지 않음"],"es":["Requiere acceso a Internet para búsquedas web y funcionalidad de GitHub CLI","Depende de la calidad y disponibilidad de las fuentes primarias","Limitado a tareas de investigación y no incluye capacidades de escritura o generación de contenido"],"fr":["Nécessite un accès à Internet pour les recherches web et la fonctionnalité GitHub CLI","Dépend de la qualité et de la disponibilité des sources primaires","Limité aux tâches de recherche et ne comprend pas les capacités d''écriture ou de génération de contenu"],"de":["Benötigt Internetzugang für Web-Suchen und GitHub CLI-Funktionalität","Hängt von der Qualität und Verfügbarkeit der Primärquellen ab","Begrenzt auf Forschungsaufgaben und umfasst keine Schreib- oder Inhaltsgenerierungs-Funktionen"],"pt":["Requer acesso à internet para funcionalidades de pesquisa na Web e GitHub CLI","Depende da qualidade e disponibilidade das fontes primárias","Limitado a tarefas de pesquisa e não inclui capacidades de escrita ou geração de conteúdo"],"ru":["Требует доступа к интернету для функций веб-поиска и GitHub CLI","Зависит от качества и доступности первичных источников","Ограничен задачами исследования и не включает возможности написания или генерации контента"],"ar":["يتطلب الوصول إلى الإنترنت لميزات البحث على الويب وواجهة سطر الأوامر GitHub","يعتمد على جودة ومتاحة للمصادر الأولية","محدود بمهمات البحث ولا يتضمن إمكانيات الكتابة أو توليد المحتوى"]},"version":4},"contentHash":"ba14d8cb34cd0a0cd8586cdfc1f19bc373192e6b71f0ef9c2f9b95dc7ac3188f","qualityScore":36}');
