INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('addozhang/openclaw-forge/research-prep', 'research-prep', 'addozhang', 'openclaw-forge', 'community', 'research-prep addozhang openclaw-forge community The research-prep skill automates research tasks for developers, collecting and organizing primary sources from official documentation, GitHub, and Stack Overflow. It benefits developers by streamlining their research process. 研究准备工具是一种AI助手技能，专注于研究阶段的资料收集和整理，支持多源搜索和智能过滤 研究準備ツールは、研究ステージでの資料収集と整理に特化したAIエージェントのスキルです 연구 준비도구는 연구 단계의 자료 수집과 정리를 위한 AI 에이전트의 기술입니다 Research-prep es una herramienta de investigación de AI que recopila y estructura datos de fuentes oficiales como GitHub y Stack Overflow para simplificar la investigación Research-prep est un outil de recherche d''IA qui collecte et structure des données à partir de sources officielles comme GitHub et Stack Overflow pour simplifier la recherche Research-prep ist ein KI-Recherche-Tool, das Daten aus offiziellen Quellen wie GitHub und Stack Overflow sammelt und strukturiert, um die Recherche zu vereinfachen O research-prep é uma habilidade de coleta e organização de materiais de pesquisa, utilizando fontes oficiais e tecnologias como GitHub CLI. Ele ajuda a preparar o conteúdo para escrita de blogs. Research-prep - это навык сбора и организации исследовательских материалов, использующий официальные источники и технологии, такие как GitHub CLI и ИИ Агенты. Он помогает подготовить контент для написания блогов. research-prep هو مهارة لجمع وتنظيم مواد البحث، باستخدام المصادر الرسمية وتقنيات مثل GitHub CLI وأدوات الذكاء الاصطناعي. يساعد في إعداد المحتوى للكتابة على المدونات. research-prep setup guide what is research-prep research-prep alternative how to use research-prep for blog writing research-prep vs traditional research methods installing research-prep for AI agents research-prep for developers automating research with research-prep research-prep and GitHub integration research-prep tutorial 研究准备工具 AI助手技能 多源搜索 智能过滤 结构化输出 研究资料收集 研究资料整理 AI工具 研究辅助工具 Utilizes Web search with site syntax to gather official documentation Leverages GitHub CLI for searching real project codes and README files Analyzes Stack Overflow for high-vote questions and practical problems Filters and categorizes sources based on authority and relevance Generates standardized research material files in a designated directory research-prep is an AI agent skill that automates the research stage of blog writing, collecting primary sources and organizing them into a structured library.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('brixtonpham/claude-config/github-search', 'community', 'brixtonpham', 'claude-config', 'brixtonpham/claude-config', 'github-search', 0, 0, 36, '2026-03-08T01:57:15.266Z', '2026-03-08T01:59:57.183Z', '6bb106204adc91adfcf7e7e98263735ea30df9cbbbb599d1db32931ff91bb04b', '{"id":"brixtonpham/claude-config/github-search","name":"github-search","description":{"en":"The github-search skill enables developers to efficiently search GitHub repositories, code, issues, and pull requests using specific commands like gh search repos and gh search code. It benefits developers who need to find projects or specific code snippets quickly.","zh":"GitHub搜索功能允许您快速找到项目和代码，支持搜索存储库、代码、问题和PR","ja":"GitHub検索機能は、プロジェクトやコードをすばやく見つけるための強力なツールです","ko":"GitHub 검색 기능은 프로젝트와 코드를 빠르게 찾을 수 있는 강력한 도구입니다","es":"La búsqueda de GitHub permite a los desarrolladores encontrar proyectos y repositorios por criterios específicos","fr":"La recherche GitHub permet aux développeurs de trouver des projets et des référentiels en fonction de critères spécifiques","de":"Die GitHub-Suche ermöglicht es Entwicklern, Projekte und Repositories nach bestimmten Kriterien zu finden","pt":"O GitHub Search é uma ferramenta poderosa para encontrar repositórios e código no GitHub. Aprenda a usá-la com facilidade","ru":"GitHub Search - это мощный инструмент для поиска репозиториев и кода на GitHub. Узнайте, как им пользоваться","ar":"أداة البحث في GitHub هي أداة قوية للعثور على المستودعات ورمز المصدر في GitHub. تعلم كيفية استخدامها بسهولة"},"seo":{"title":{"en":"github-search: Mastering GitHub Search Queries | AI Agent...","zh":"GitHub搜索Setup指南","ja":"GitHub検索ベストプラクティス - AIエージェント","ko":"GitHub 검색 가이드 - AI Tools","es":"Guía de configuración de búsqueda de GitHub","fr":"Guide de mise en route de la recherche GitHub","de":"GitHub-Suche-Setup-Anleitung","pt":"Guia de Configuração do GitHub Search","ru":"Настройка GitHub Search: Руководство","ar":"إعداد أداة البحث في GitHub: دليل المستخدم"},"description":{"en":"Unlock the full potential of GitHub search with AI-powered queries. Learn how to use gh search repos, code, issues, and PRs commands to streamline your workflow","zh":"了解如何使用GitHub搜索功能快速找到项目和代码，包括搜索存储库、代码、问题和PR","ja":"GitHub検索の使い方をマスターし、プロジェクトやコードをすばやく見つける方法を学びます","ko":"GitHub 검색 기능을 사용하여 프로젝트와 코드를 빠르게 찾는 방법을 알아보세요","es":"Aprende a utilizar la búsqueda de GitHub con nuestra guía de configuración y mejores prácticas para desarrolladores","fr":"Découvrez comment utiliser la recherche GitHub avec notre guide de configuration et les meilleures pratiques pour les développeurs","de":"Erfahren Sie, wie Sie die GitHub-Suche mit unserer Setup-Anleitung und Best Practices für Entwickler nutzen können","pt":"Aprenda a usar o GitHub Search para encontrar repositórios, código, problemas e solicitações de pull com facilidade","ru":"Используйте GitHub Search, чтобы найти репозитории, код, проблемы и запросы на объединение с легкостью","ar":"تعلم كيفية استخدام أداة البحث في GitHub للعثور على المستودعات ورمز المصدر والمشكلات وطلبات الدمج بسهولة"},"definition":{"en":"github-search is a skill that allows developers to utilize GitHub''s search functionality through commands like gh search, enabling efficient discovery of repositories, code, issues, and pull requests","zh":"GitHub搜索是GitHub中的一个功能，允许用户搜索存储库、代码、问题和PR","ja":"GitHub検索は、GitHubにおけるプロジェクトやコードを検索するための機能です","ko":"GitHub 검색은 GitHub에서 프로젝트와 코드를 검색하는 기능입니다","es":"La búsqueda de GitHub es una herramienta de línea de comandos que permite buscar repositorios, código, problemas y solicitudes de extracción","fr":"La recherche GitHub est un outil de ligne de commande qui permet de rechercher des référentiels, du code, des problèmes et des demandes d''extraction","de":"Die GitHub-Suche ist ein Kommandozeilen-Tool, mit dem Sie nach Repositorys, Code, Issues und Pull-Requests suchen können","pt":"O GitHub Search é uma ferramenta de busca que permite encontrar repositórios, código, problemas e solicitações de pull no GitHub","ru":"GitHub Search - это инструмент поиска, который позволяет найти репозитории, код, проблемы и запросы на объединение на GitHub","ar":"أداة البحث في GitHub هي أداة بحث تتيح العثور على المستودعات ورمز المصدر والمشكلات وطلبات الدمج في GitHub"},"features":{"en":["Searches repositories using the gh search repos command","Finds specific code snippets with the gh search code command","Supports searching issues with the gh search issues command","Enables searching pull requests using the gh search prs command","Limits search results with the --limit flag, such as --limit 30"],"zh":["支持搜索存储库、代码、问题和PR","使用gh search repos命令搜索存储库","使用gh search code命令搜索代码","使用gh search issues命令搜索问题","使用gh search prs命令搜索PR"],"ja":["リポジトリ、コード、課題、PRの検索をサポート","gh search reposコマンドを使用してリポジトリを検索","gh search codeコマンドを使用してコードを検索","gh search issuesコマンドを使用して課題を検索","gh search prsコマンドを使用してPRを検索"],"ko":["저장소, 코드, 문제, PR 검색 지원","gh search repos 명령을 사용하여 저장소를 검색","gh search code 명령을 사용하여 코드를 검색","gh search issues 명령을 사용하여 문제를 검색","gh search prs 명령을 사용하여 PR을 검색"],"es":["Búsqueda de repositorios con `gh search repos`","Búsqueda de código con `gh search code`","Búsqueda de problemas con `gh search issues`","Búsqueda de solicitudes de extracción con `gh search prs`","Uso de patrones de búsqueda para encontrar proyectos y repositorios"],"fr":["Recherche de référentiels avec `gh search repos`","Recherche de code avec `gh search code`","Recherche de problèmes avec `gh search issues`","Recherche de demandes d''extraction avec `gh search prs`","Utilisation de modèles de recherche pour trouver des projets et des référentiels"],"de":["Repository-Suche mit `gh search repos`","Code-Suche mit `gh search code`","Issue-Suche mit `gh search issues`","Pull-Request-Suche mit `gh search prs`","Verwendung von Suchmustern, um Projekte und Repositorys zu finden"],"pt":["Pesquisa de repositórios com critérios personalizados","Pesquisa de código em repositórios públicos e privados","Pesquisa de problemas e solicitações de pull com facilidade","Uso de comandos CLI para automação de tarefas","Limitação de resultados para melhorar a eficiência da busca"],"ru":["Поиск репозиториев по индивидуальным критериям","Поиск кода в публичных и приватных репозиториях","Поиск проблем и запросов на объединение с легкостью","Использование команд CLI для автоматизации задач","Ограничение результатов для улучшения эффективности поиска"],"ar":["بحث المستودعات بالمعايير المخصصة","بحث رمز المصدر في المستودعات العامة والخاصة","بحث المشكلات وطلبات الدمج بسهولة","استخدام أوامر CLI للتحكم الآلي في المهام","تحديد النتائج لتحسين كفاءة البحث"]},"keywords":{"en":["how to use github-search","github-search setup guide","github-search alternative","github-search vs git search","github-search install","what is github-search","github-search commands","github-search query examples"],"zh":["GitHub搜索","GitHub存储库搜索","GitHub代码搜索","GitHub问题搜索","GitHub PR搜索","gh search repos","gh search code","gh search issues","gh search prs"],"ja":["GitHub検索","GitHubリポジトリ検索","GitHubコード検索","GitHub課題検索","GitHub PR検索","gh search repos","gh search code","gh search issues","gh search prs"],"ko":["GitHub 검색","GitHub 저장소 검색","GitHub 코드 검색","GitHub 문제 검색","GitHub PR 검색","gh search repos","gh search code","gh search issues","gh search prs"],"es":["herramientas de búsqueda de GitHub","guía de configuración de búsqueda de GitHub","mejores prácticas de búsqueda de GitHub","búsqueda de repositorios en GitHub","búsqueda de código en GitHub","búsqueda de problemas en GitHub","búsqueda de solicitudes de extracción en GitHub"],"fr":["outils de recherche GitHub","guide de configuration de la recherche GitHub","meilleures pratiques de recherche GitHub","recherche de référentiels sur GitHub","recherche de code sur GitHub","recherche de problèmes sur GitHub","recherche de demandes d''extraction sur GitHub"],"de":["GitHub-Suchtools","GitHub-Suche-Setup-Anleitung","Best Practices für die GitHub-Suche","Repository-Suche auf GitHub","Code-Suche auf GitHub","Issue-Suche auf GitHub","Pull-Request-Suche auf GitHub"],"pt":["github search","pesquisa de repositórios","pesquisa de código","problemas github","solicitações de pull","comandos cli","automatização de tarefas","ferramentas de desenvolvimento"],"ru":["github search","поиск репозиториев","поиск кода","проблемы github","запросы на объединение","команды cli","автоматизация задач","инструменты разработки"],"ar":["بحث github","بحث المستودعات","بحث رمز المصدر","مشكلات github","طلبات الدمج","أوامر cli","التحكم الآلي في المهام","أدوات التطوير"]}},"owner":"brixtonpham","repo":"claude-config","repoPath":"brixtonpham/claude-config","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.266Z","topics":[],"category":"community","skillMd":{"name":"github-search","description":"Search GitHub for repos, code, and usage examples using gh CLI. Capabilities: repo discovery, code search, finding library usage patterns, issue/PR search. Actions: search, find, discover repos/code/examples. Keywords: gh, github, search repos, search code, find examples, how to use library, stars, language filter. Use when: finding repositories, searching code patterns, discovering how libraries are used, exploring open source.","bodyPreview":"# GitHub Search\n\n## Quick Commands\n\n| Goal | Command |\n|------|---------|\n| Search repos | `gh search repos \"<query>\" --limit 30` |\n| Search code | `gh search code \"<query>\" --limit 30` |\n| Search issues | `gh search issues \"<query>\" --limit 30` |\n| Search PRs | `gh search prs \"<query>\" --limit 30` |\n\n## Patterns\n\n### Finding Repositories\n\n**When you see:** User wants to find projects/repos by criteria\n**Use:** `gh search repos`\n\n```bash\n# Basic search with stars\ngh search repos \"stars:>500 lang","body":"# GitHub Search\n\n## Quick Commands\n\n| Goal | Command |\n|------|---------|\n| Search repos | `gh search repos \"<query>\" --limit 30` |\n| Search code | `gh search code \"<query>\" --limit 30` |\n| Search issues | `gh search issues \"<query>\" --limit 30` |\n| Search PRs | `gh search prs \"<query>\" --limit 30` |\n\n## Patterns\n\n### Finding Repositories\n\n**When you see:** User wants to find projects/repos by criteria\n**Use:** `gh search repos`\n\n```bash\n# Basic search with stars\ngh search repos \"stars:>500 language:rust\" --sort=stars --limit=50\n\n# Multiple languages (OR logic)\ngh search repos \"language:rust language:go language:typescript\"\n\n# Exclude topics\ngh search repos \"stars:>1000 -topic:cryptocurrency -topic:blockchain\"\n\n# By topic\ngh search repos \"topic:cli topic:terminal stars:>100\"\n\n# Recently updated\ngh search repos \"language:python pushed:>2024-01-01\"\n```\n\n**Output formats:**\n```bash\n--json name,url,description,stargazersCount  # JSON output\n--web                                         # Open in browser\n```\n\n### Finding Code Examples\n\n**When you see:** User wants to know how to use a library\n**Use:** `gh search code`\n\n```bash\n# Find usage patterns\ngh search code \"from zod import\" --limit=20\ngh search code \"import { z } from ''zod''\" --limit=20\n\n# In specific file types\ngh search code \"useQuery\" extension:tsx --limit=30\n\n# In specific paths\ngh search code \"tanstack/query\" path:src/ extension:ts\n\n# Exact phrase\ngh search code ''\"createTRPCRouter\"'' extension:ts\n```\n\n**Pro tip:** Combine with repo filter for focused results:\n```bash\ngh search code \"pattern\" repo:owner/repo\n```\n\n### Finding Issues/Discussions\n\n**When you see:** User looking for bug reports, feature requests, or discussions\n**Use:** `gh search issues` or `gh search prs`\n\n```bash\n# Open issues with label\ngh search issues \"is:open label:bug repo:facebook/react\"\n\n# PRs by author\ngh search prs \"author:username is:merged\"\n\n# Issues mentioning error\ngh search issues ''\"connection refused\" language:go''\n```\n\n## Query Qualifiers Reference\n\n### Repo Search\n| Qualifier | Example | Description |\n|-----------|---------|-------------|\n| `stars:` | `stars:>1000`, `stars:100..500` | Star count |\n| `forks:` | `forks:>100` | Fork count |\n| `language:` | `language:rust` | Primary language |\n| `topic:` | `topic:cli` | Repository topic |\n| `-topic:` | `-topic:blockchain` | Exclude topic |\n| `pushed:` | `pushed:>2024-01-01` | Last push date |\n| `created:` | `created:>2023-01-01` | Creation date |\n| `license:` | `license:mit` | License type |\n| `archived:` | `archived:false` | Archive status |\n| `is:` | `is:public`, `is:private` | Visibility |\n\n### Code Search\n| Qualifier | Example | Description |\n|-----------|---------|-------------|\n| `extension:` | `extension:ts` | File extension |\n| `path:` | `path:src/` | File path |\n| `repo:` | `repo:owner/name` | Specific repo |\n| `language:` | `language:javascript` | Code language |\n| `filename:` | `filename:package.json` | File name |\n\n### Common Flags\n| Flag | Description |\n|------|-------------|\n| `--limit N` | Number of results (max 1000) |\n| `--sort X` | Sort by: stars, forks, updated, best-match |\n| `--order X` | asc or desc |\n| `--json FIELDS` | JSON output with specific fields |\n| `--web` | Open results in browser |\n\n## Common Use Cases\n\n### \"Find popular X repos\"\n```bash\ngh search repos \"language:X stars:>500\" --sort=stars --limit=50\n```\n\n### \"How do people use library Y\"\n```bash\ngh search code \"import Y\" extension:ts --limit=30\ngh search code \"from Y import\" extension:py --limit=30\n```\n\n### \"Find repos like Z but exclude crypto\"\n```bash\ngh search repos \"topic:Z -topic:cryptocurrency -topic:blockchain -topic:web3\"\n```\n\n### \"Find recent active projects\"\n```bash\ngh search repos \"language:go pushed:>2024-06-01 stars:>100\" --sort=updated\n```\n\n## Tips\n\n1. **Quote the query** when it contains special chars: `gh search repos \"stars:>500\"`\n2. **Multiple languages = OR**: `language:rust language:go` matches either\n3. **Use `--json`** for scripting: `--json name,url,stargazersCount`\n4. **Date ranges**: `pushed:2024-01-01..2024-06-01`\n5. **Numeric ranges**: `stars:100..500`\n"},"lastSynced":"2026-03-08T01:59:57.183Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing efficient GitHub repository and code search capabilities.","zh":"非常适合需要高效的 GitHub 仓库和代码搜索功能的开发者代理。","ja":"GitHub リポジトリおよびコードの効率的な検索機能が必要な Developer エージェントに最適です。","ko":"효율적인 GitHub 저장소 및 코드 검색 기능이 필요한 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan capacidades de búsqueda de repositorio y código de GitHub eficientes.","fr":"Parfait pour les agents de développement ayant besoin de capacités de recherche de référentiel et de code GitHub efficaces.","de":"Perfekt für Entwickleragenten, die effiziente GitHub-Repository- und Code-Suchfunktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que precisam de capacidades eficientes de pesquisa de repositório e código do GitHub.","ru":"Идеально для агентов-разработчиков, которым необходимы эффективные возможности поиска репозиториев и кода GitHub.","ar":"مثالي لعميل المطور الذي يحتاج إلى إمكانيات بحث كفؤة لمخزن GitHub واكتشاف الكود."},"recommendation":{"en":"Empowers agents to efficiently search GitHub repositories, code, issues, and pull requests using specific commands like `gh search repos` and `gh search code`, leveraging GitHub''s query syntax and filters like `--limit` for refined results.","zh":"赋予代理高效搜索 GitHub 仓库、代码、问题和拉取请求的能力，使用诸如 `gh search repos` 和 `gh search code` 的特定命令，利用 GitHub 的查询语法和过滤器，如 `--limit` 进行精细搜索。","ja":"エージェントが `gh search repos` や `gh search code` などの特定のコマンドを使用して、GitHub リポジトリ、コード、問題、プルリクエストを効率的に検索できるようにし、GitHub のクエリーシンタックスや `--limit` などのフィルターを利用してリファインされた結果を取得します。","ko":"에이전트가 `gh search repos` 및 `gh search code`와 같은 특정 명령을 사용하여 GitHub 저장소, 코드, 문제 및 풀 요청을 효율적으로 검색할 수 있도록 하며, GitHub의 쿼리 구문 및 `--limit`와 같은 필터를 활용하여 세부적인 결과를 얻습니다.","es":"Habilita a los agentes a buscar de forma eficiente repositorios de GitHub, código, problemas y solicitudes de extracción utilizando comandos específicos como `gh search repos` y `gh search code`, aprovechando la sintaxis de consulta y los filtros de GitHub como `--limit` para resultados refinados.","fr":"Permet aux agents de rechercher efficacement des référentiels GitHub, du code, des problèmes et des demandes d''extraction en utilisant des commandes spécifiques comme `gh search repos` et `gh search code`, en exploitant la syntaxe de requête et les filtres GitHub tels que `--limit` pour des résultats affinés.","de":"Ermöglicht es Agenten, GitHub-Repositorys, Code, Probleme und Pull-Requests mithilfe spezifischer Befehle wie `gh search repos` und `gh search code` effizient zu suchen und nutzt dabei die GitHub-Abfragesyntax und Filter wie `--limit` für verfeinerte Ergebnisse.","pt":"Permite que os agentes procurem de forma eficiente repositórios do GitHub, código, problemas e solicitações de pull usando comandos específicos como `gh search repos` e `gh search code`, aproveitando a sintaxe de consulta e filtros do GitHub, como `--limit` para resultados refinados.","ru":"Позволяет агентам эффективно искать репозитории GitHub, код, проблемы и запросы на включение, используя конкретные команды, такие как `gh search repos` и `gh search code`, используя синтаксис запросов и фильтры GitHub, такие как `--limit` для уточнения результатов.","ar":"تمكن العميل من البحث بفعالية في مستودعات GitHub والكود والمشاكل وطلبات السحب باستخدام أوامر محددة مثل `gh search repos` و `gh search code` ، واستخدام بناء جملة استعلام GitHub والمرشحات مثل `--limit` للحصول على نتائج محسنة."},"useCases":{"en":["Searching for open-source projects by specific criteria","Finding relevant code snippets for reference or reuse","Debugging issues by searching GitHub issues and pull requests"],"zh":["根据特定标准搜索开源项目","找到相关的代码片段以供参考或重用","通过搜索 GitHub 问题和拉取请求来调试问题"],"ja":["特定の基準でオープンソース プロジェクトを検索する","参照または再利用するための関連するコード スニペットを見つける","GitHub の問題やプルリクエストを検索して問題をデバッグする"],"ko":["특정 기준으로 오픈소스 프로젝트를 검색하는 것","참고 또는 재사용을 위한 관련 코드 스니펫을 찾는 것","GitHub 문제 및 풀 요청을 검색하여 문제를 디버깅하는 것"],"es":["Buscar proyectos de código abierto según criterios específicos","Encontrar fragmentos de código relevantes para referencia o reutilización","Depurar problemas al buscar problemas y solicitudes de extracción de GitHub"],"fr":["Rechercher des projets open source selon des critères spécifiques","Trouver des extraits de code pertinents pour référence ou réutilisation","Déboguer des problèmes en recherchant des problèmes et des demandes d''extraction GitHub"],"de":["Nach Open-Source-Projekten nach bestimmten Kriterien suchen","Relevante Code-Snippets für Referenz oder Wiederverwendung finden","Probleme durch Suche nach GitHub-Problemen und Pull-Requests debuggen"],"pt":["Pesquisar projetos de código aberto por critérios específicos","Encontrar trechos de código relevantes para referência ou reutilização","Depurar problemas pesquisando problemas e solicitações de pull do GitHub"],"ru":["Поиск проектов с открытым исходным кодом по конкретным критериям","Поиск релевантных фрагментов кода для справки или повторного использования","Отладка проблем путем поиска проблем и запросов на включение GitHub"],"ar":["البحث عن مشاريع الكود المفتوح بواسطة معايير محددة","العثور على شفرات الكود ذات الصلة للرجوع إليها أو إعادة استخدامها","تصحيح الأخطاء عن طريق البحث في مشاكل GitHub وطلبات السحب"]},"limitations":{"en":["Requires GitHub CLI installation and configuration","Dependent on GitHub''s search query syntax and limitations"],"zh":["需要 GitHub CLI 安装和配置","依赖于 GitHub 的搜索查询语法和限制"],"ja":["GitHub CLI のインストールと設定が必要","GitHub の検索クエリーシンタックスと制限に依存する"],"ko":["GitHub CLI 설치 및 구성이 필요함","GitHub의 검색 쿼리 구문 및 제한에 의존"],"es":["Requiere instalación y configuración de GitHub CLI","Dependiente de la sintaxis de consulta de búsqueda y limitaciones de GitHub"],"fr":["Nécessite l''installation et la configuration de GitHub CLI","Dépend de la syntaxe de requête de recherche et des limitations de GitHub"],"de":["Benötigt die Installation und Konfiguration von GitHub CLI","Hängt von der GitHub-Suchabfragesyntax und -Einschränkungen ab"],"pt":["Requer instalação e configuração do GitHub CLI","Depende da sintaxe de consulta de pesquisa e limitações do GitHub"],"ru":["Требует установки и настройки GitHub CLI","Зависит от синтаксиса запросов поиска и ограничений GitHub"],"ar":["يتطلب تثبيت وضبط واجهة سطر الأوامر GitHub","يعتمد على بناء جملة استعلام البحث وقيود GitHub"]},"version":4},"contentHash":"6bb106204adc91adfcf7e7e98263735ea30df9cbbbb599d1db32931ff91bb04b","qualityScore":36}');
