INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('brixtonpham/claude-config/github-search', 'github-search', 'brixtonpham', 'claude-config', 'community', 'github-search brixtonpham claude-config community The github-search skill enables developers to efficiently search GitHub repositories, code, issues, and pull requests using specific commands like gh search repos and gh search code. It benefits developers who need to find projects or specific code snippets quickly. GitHub搜索功能允许您快速找到项目和代码，支持搜索存储库、代码、问题和PR GitHub検索機能は、プロジェクトやコードをすばやく見つけるための強力なツールです GitHub 검색 기능은 프로젝트와 코드를 빠르게 찾을 수 있는 강력한 도구입니다 La búsqueda de GitHub permite a los desarrolladores encontrar proyectos y repositorios por criterios específicos La recherche GitHub permet aux développeurs de trouver des projets et des référentiels en fonction de critères spécifiques Die GitHub-Suche ermöglicht es Entwicklern, Projekte und Repositories nach bestimmten Kriterien zu finden O GitHub Search é uma ferramenta poderosa para encontrar repositórios e código no GitHub. Aprenda a usá-la com facilidade GitHub Search - это мощный инструмент для поиска репозиториев и кода на GitHub. Узнайте, как им пользоваться أداة البحث في GitHub هي أداة قوية للعثور على المستودعات ورمز المصدر في GitHub. تعلم كيفية استخدامها بسهولة how to use github-search github-search setup guide github-search alternative github-search vs git search github-search install what is github-search github-search commands github-search query examples GitHub搜索 GitHub存储库搜索 GitHub代码搜索 GitHub问题搜索 GitHub PR搜索 gh search repos gh search code gh search issues gh search prs Searches repositories using the gh search repos command Finds specific code snippets with the gh search code command Supports searching issues with the gh search issues command Enables searching pull requests using the gh search prs command Limits search results with the --limit flag, such as --limit 30 github-search is a skill that allows developers to utilize GitHub''s search functionality through commands like gh search, enabling efficient discovery of repositories, code, issues, and pull requests');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('upstash/workflow-js/upstash-workflow-js', 'community', 'upstash', 'workflow-js', 'upstash/workflow-js', 'upstash-workflow-js', 0, 0, 36, '2026-03-08T01:57:15.270Z', '2026-03-08T02:00:08.580Z', '8d94ad14a754cbf10a5c6908205a38955dfae9232cd197d2187830435c7f017b', '{"id":"upstash/workflow-js/upstash-workflow-js","name":"upstash-workflow-js","description":{"en":"upstash-workflow-js enables developers to expose serverless workflow endpoints and run them reliably using QStash. It benefits developers building serverless applications.","zh":"Upstash Workflow JS 是一个用于构建可靠和高性能的 Serverless 函数的 SDK。它提供了一个简单的方式来定义和运行工作流","ja":"Upstash Workflow JS は、耐久性とパフォーマンスの高いサーバーレス関数を構築するための SDK です。ワークフローを定義して実行するためのシンプルな方法を提供します","ko":"Upstash Workflow JS는 안정적이고 성능 좋은 Serverless 함수를 구축하는 데 사용되는 SDK입니다. 워크플로우를 정의하고 실행하는 쉬운 방법을 제공합니다","es":"Upstash-workflow-js permite exponer puntos de conexión de flujo de trabajo de servidoras y ejecutarlos de manera confiable utilizando QStash. Instala con npm y define flujos de trabajo simples","fr":"Upstash-workflow-js permet d''exposer des points de terminaison de workflow de serveur et de les exécuter de manière fiable en utilisant QStash. Installez avec npm et définissez des workflows simples","de":"Upstash-workflow-js ermöglicht das Exponieren von Workflow-Endpunkten für Serverless-Funktionen und ihre Ausführung mit QStash. Installieren Sie mit npm und definieren Sie einfache Workflows","pt":"O Upstash Workflow JS permite expor endpoints de workflow serverless e executá-los de forma confiável usando QStash.","ru":"Upstash Workflow JS позволяет экспонировать конечные точки серверных рабочих процессов и выполнять их надежно с помощью QStash.","ar":"يسمح Upstash Workflow JS بتعريض نهايات نقطة سير عمل الخادمية بدون خادم وتشغيلها بثبات باستخدام QStash."},"seo":{"title":{"en":"upstash-workflow-js: Reliable Serverless Workflow Setup G...","zh":"Upstash Workflow JS 设置指南：可靠的 Serverless 函数","ja":"Upstash Workflow JS のベストプラクティス：耐久性とパフォーマンスの高いサーバーレス関数","ko":"Upstash Workflow JS 설정 가이드: 안정적이고 성능 좋은 Serverless 함수","es":"Guía de configuración de upstash-workflow-js para funcion...","fr":"Guide de mise en place de upstash-workflow-js pour des fo...","de":"Einrichtungsleitfaden für upstash-workflow-js für zuverlä...","pt":"Guia de Configuração do Upstash Workflow JS para Funções ...","ru":"Настройка Upstash Workflow JS для Надежных Серверных Функций","ar":"دليل إعداد Upstash Workflow JS للأدوات الخادمية بدون خادم"},"description":{"en":"Discover how to trigger durable serverless functions with upstash-workflow-js. Learn to install and define workflow endpoints with ease.","zh":"了解如何使用 Upstash Workflow JS 构建可靠和高性能的 Serverless 函数，包括安装、定义工作流端点和触发工作流","ja":"Upstash Workflow JS を使用して耐久性とパフォーマンスの高いサーバーレス関数を構築する方法を学びます。インストール、ワークフロー エンドポイントの定義、ワークフロー トリガーなど","ko":"Upstash Workflow JS를 사용하여 안정적이고 성능 좋은 Serverless 함수를 구축하는 방법에 대해 알아보세요. 설치, 워크플로우 엔드포인트 정의, 워크플로우 트리거 등","es":"Aprende a crear funciones servidoras duraderas y confiables con upstash-workflow-js. Descubre cómo exponer puntos de conexión de flujo de trabajo y ejecutarl...","fr":"Découvrez comment créer des fonctions serveur durables et fiables avec upstash-workflow-js. Apprenez à exposer des points de terminaison de workflow et à les...","de":"Erfahren Sie, wie Sie mit upstash-workflow-js zuverlässige und ausfallsichere Serverless-Funktionen erstellen. Entdecken Sie, wie Sie Workflow-Endpunkte expo...","pt":"Aprenda a criar funções serverless confiáveis com o Upstash Workflow JS. Instale e defina endpoints de workflow com facilidade.","ru":"Узнайте, как создать надежные серверные функции с помощью Upstash Workflow JS. Установите и определите конечные точки рабочего процесса легко.","ar":"تعلم كيفية إنشاء أدوات خادمية بدون خادم موثوقة باستخدام Upstash Workflow JS. قم بتثبيت وتحديد نهايات نقطة سير عمل بسهولة."},"definiti