INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('upstash/workflow-js/upstash-workflow-js', 'upstash-workflow-js', 'upstash', 'workflow-js', 'community', 'upstash-workflow-js upstash workflow-js community upstash-workflow-js enables developers to expose serverless workflow endpoints and run them reliably using QStash. It benefits developers building serverless applications. Upstash Workflow JS 是一个用于构建可靠和高性能的 Serverless 函数的 SDK。它提供了一个简单的方式来定义和运行工作流 Upstash Workflow JS は、耐久性とパフォーマンスの高いサーバーレス関数を構築するための SDK です。ワークフローを定義して実行するためのシンプルな方法を提供します Upstash Workflow JS는 안정적이고 성능 좋은 Serverless 함수를 구축하는 데 사용되는 SDK입니다. 워크플로우를 정의하고 실행하는 쉬운 방법을 제공합니다 Upstash-workflow-js permite exponer puntos de conexión de flujo de trabajo de servidoras y ejecutarlos de manera confiable utilizando QStash. Instala con npm y define flujos de trabajo simples Upstash-workflow-js permet d''exposer des points de terminaison de workflow de serveur et de les exécuter de manière fiable en utilisant QStash. Installez avec npm et définissez des workflows simples Upstash-workflow-js ermöglicht das Exponieren von Workflow-Endpunkten für Serverless-Funktionen und ihre Ausführung mit QStash. Installieren Sie mit npm und definieren Sie einfache Workflows O Upstash Workflow JS permite expor endpoints de workflow serverless e executá-los de forma confiável usando QStash. Upstash Workflow JS позволяет экспонировать конечные точки серверных рабочих процессов и выполнять их надежно с помощью QStash. يسمح Upstash Workflow JS بتعريض نهايات نقطة سير عمل الخادمية بدون خادم وتشغيلها بثبات باستخدام QStash. how to use upstash-workflow-js upstash-workflow-js setup guide upstash-workflow-js install upstash-workflow-js vs qstash upstash-workflow-js alternative serverless workflow sdk reliable serverless functions performant workflow execution Upstash Workflow JS Serverless 函数 QStash 工作流运行 async/await npm 安装 AI エージェント Serverless 架构 Installs via npm using `npm install @upstash/workflow` Defines simple workflow endpoints using the `serve` function from `@upstash/workflow` Triggers workflow endpoints using `context.run` method Supports asynchronous workflow steps Uses QStash for reliable and performant workflow execution Exports workflow endpoints as serverless functions upstash-workflow-js is a serverless workflow SDK that lets you run reliable and performant workflows using QStash under the hood.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('remorses/playwriter/playwriter', 'community', 'remorses', 'playwriter', 'remorses/playwriter', 'playwriter', 0, 0, 36, '2026-03-08T01:57:15.274Z', '2026-03-08T02:00:32.689Z', '0c5f07a0de4bab4f9ee16861eaba0dfb739b5d1462870a03345b2e3223756fff', '{"id":"remorses/playwriter/playwriter","name":"playwriter","description":{"en":"playwriter is a Chrome extension that lets agents control your browser, running Playwright snippets in a stateful sandbox. It benefits AI agents and developers who need to automate browser interactions.","zh":"Playwriter是一个Chrome扩展，允许代理控制浏览器，运行Playwright代码段在stateful sandbox中","ja":"PlaywriterはChrome拡張機能で、エージェントがブラウザを制御できるようにし、Playwrightスニペットをstateful sandboxで実行","ko":"Playwriter는 크롬 확장 프로그램으로 에이전트가 브라우저를 제어할 수 있게 해주고 stateful sandbox에서 Playwright 코드 조각을 실행합니다.","es":"playwriter es una extensión de Chrome que permite a los agentes controlar tu navegador ejecutando snippets de Playwright en un entorno de sandbox con estado","fr":"playwriter est une extension Chrome qui permet aux outils IA de contrôler votre navigateur en exécutant des extraits de code Playwright dans un environnement de sandbox étatique","de":"playwriter ist eine Chrome-Erweiterung, die es KI-Tools ermöglicht, Ihren Browser zu steuern, indem sie Playwright-Snippets in einer stateful Sandbox ausführt","pt":"O Playwriter é uma extensão do Chrome que permite controlar o navegador com snippets de Playwright em um sandbox estado. Saiba mais sobre como configurá-lo.","ru":"Playwriter - расширение Chrome, которое позволяет управлять браузером с помощью фрагментов Playwright в состоянии песочницы. Узнайте, как его настроить.","ar":"Playwriter هو امتداد كروم يسمح بالتحكم في المتصفح باستخدام شفرات Playwright في sandbox حالة. تعلم كيفية إعداده."},"seo":{"title":{"en":"playwriter: Setup Guide for AI Agents | AI Agent Skill","zh":"Playwriter_setup_guide_AIエージェント浏览器控制","ja":"Playwriter_setup_guide_AIエージェントブラウザ制御","ko":"Playwriter_setup_guide_AI에이전트브라우저제어","es":"Guía de configuración de playwriter: Control de navegador...","fr":"Guide de configuration de playwriter: Contrôle du navigat...","de":"Einrichtungsleitfaden für playwriter: Browsersteuerung mi...","pt":"Guia de Configuração do Playwriter: Controle de Navegador...","ru":"Настройка Playwriter: Управление браузером с помощью ИИ А...","ar":"دليل إعداد Playwriter: التحكم في المتصفح باستخدام أدوات ا..."},"description":{"en":"Unlock playwriter''s full potential with our expert guide. Learn how to run Playwright snippets in a stateful sandbox and master session management.","zh":"了解Playwriter的设置和最佳实践，使用Playwright控制浏览器，实现stateful sandbox和CLI/MCP功能","ja":"Playwriterの設定とベストプラクティスを学び、Playwrightを使用してブラウザを制御し、stateful sandboxとCLI/MCP機能を実現","ko":"Playwriter의 설정과 최고의 실践을 알아보세요. Playwright로 브라우저를 제어하고 stateful sandbox와 CLI/MCP 기능을 구현합니다.","es":"Aprende a configurar playwriter para controlar tu navegador con snippets de Playwright en un entorno de sandbox con estado","fr":"Découvrez comment configurer playwriter pour contrôler votre navigateur avec des extraits de code Playwright dans un environnement de sandbox étatique","de":"Erfahren Sie, wie Sie playwriter konfigurieren, um Ihren Browser mit Playwright-Snippets in einer stateful Sandbox zu steuern","pt":"Aprenda a configurar o Playwriter, uma extensão do Chrome que permite controlar o navegador com snippets de Playwright em um sandbox estado","ru":"Узнайте, как настроить Playwriter, расширение Chrome, которое позволяет управлять браузером с помощью фрагментов Playwright в состоянии песочницы","ar":"تعلم كيفية إعداد Playwriter، امتداد كروم يسمح بالتحكم في المتصفح باستخدام شفرات Playwright في sandbox حالة"},"definition":{"en":"playwriter is a Chrome extension that enables agents to control browsers using Playwright snippets in a stateful sandbox, available as CLI or MCP.","zh":"Playwriter是一种AIエージェント工具，用于控制浏览器和执行Playwright代码","ja":"PlaywriterはAIエージェントツールで、ブラウザを制御し、Playwrightコードを実行する","ko":"Playwriter는 AI에이전트 도구로 브라우저를 제어하고 Playwright 코드를 실행합니다.","es":"playwriter es una herramienta de AI Agent que permite controlar el navegador mediante snippets de Playwright","fr":"playwriter est un outil IA qui permet de contrôler le navigateur à l''aide d''extraits de code Playwright","de":"playwriter ist ein KI-Tool, das die Steuerung des Browsers mithilfe von Playwright-Snippets ermöglicht","pt":"O Playwriter é uma ferramenta que permite controlar o navegador com snippets de Playwright em um sandbox estado","ru":"Playwriter - это инструмент, который позволяет управлять браузером с помощью фрагментов Playwright в состоянии песочницы","ar":"Playwriter هو أداة تتيح التحكم في المتصفح باستخدام شفرات Playwright في sandbox حالة"},"features":{"en":["Runs Playwright snippets in a stateful sandbox","Supports session management and timeout configuration","Provides selector strategies and best practices for slow pages and SPAs","Includes context variables and utility functions","Available as CLI or MCP"],"zh":["支持Playwright代码段在stateful sandbox中运行","提供CLI和MCP功能","实现会话管理和超时配置","支持选择器策略和上下文变量","提供最佳实践和规则以防止超时和失败"],"ja":["Playwrightスニペットをstateful sandboxで実行","CLIとMCP機能を提供","セッション管理とタイムアウト設定を実現","セレクタ戦略とコンテキスト変数をサポート","ベストプラクティスとルールを提供してタイムアウトと失敗を防止"],"ko":["Playwright 코드 조각을 stateful sandbox에서 실행","CLI와 MCP 기능을 제공","세션 관리와 시간 초과 설정을 구현","셀렉터 전략과 컨텍스트 변수를 지원","최佳의 실践과 규칙을 제공하여 시간 초과와 실패를 방지"],"es":["Ejecución de snippets de Playwright en un entorno de sandbox con estado","Gestión de sesiones y configuración de tiempo de espera","Estrategias de selección y reglas para prevenir tiempos de espera y fallos","Compatibilidad con CLI y MCP","Variables de contexto y funciones de utilidad"],"fr":["Exécution d''extraits de code Playwright dans un environnement de sandbox étatique","Gestion de sessions et configuration de délai d''attente","Stratégies de sélection et règles pour prévenir les délais d''attente et les échecs","Compatibilité avec CLI et MCP","Variables de contexte et fonctions d''utilité"],"de":["Ausführung von Playwright-Snippets in einer stateful Sandbox","Sitzungsverwaltung und Timeout-Konfiguration","Selektionsstrategien und Regeln zur Vermeidung von Timeouts und Fehlern","Kompatibilität mit CLI und MCP","Kontextvariablen und Utility-Funktionen"],"pt":["Controle de navegador com snippets de Playwright","Sandbox estado para execução de código","Suporte a CLI e MCP","Gerenciamento de sessões e configuração de tempo de espera","Estratégias de seletor e regras para prevenir timeouts e falhas"],"ru":["Управление браузером с помощью фрагментов Playwright","Песочница состояния для выполнения кода","Поддержка CLI и MCP","Управление сессиями и настройка времени ожидания","Стратегии селектора и правила для предотвращения таймаутов и ошибок"],"ar":["التحكم في المتصفح باستخدام شفرات Playwright","sandbox حالة لتنفيذ الشفرة","دعم CLI و MCP","إدارة الجلسات وضبط وقت الانتظار","استراتيجيات المحدد وقواعد لمنع انتهاء الوقت و الأخطاء"]},"keywords":{"en":["how to use playwriter","playwriter setup guide","playwriter alternative","playwriter vs puppeteer","playwriter install","what is playwriter","playwriter documentation","playwriter tutorial","playwriter chrome extension"],"zh":["Playwriter","AIエージェント","浏览器控制","Playwright","stateful sandbox","CLI","MCP","会话管理","超时配置"],"ja":["Playwriter","AIエージェント","ブラウザ制御","Playwright","stateful sandbox","CLI","MCP","セッション管理","タイムアウト設定"],"ko":["Playwriter","AI에이전트","브라우저 제어","Playwright","stateful sandbox","CLI","MCP","세션 관리","시간 초과 설정"],"es":["playwriter","AI Agent","herramientas de AI","control de navegador","snippets de Playwright","sandbox con estado","gestión de sesiones","configuración de tiempo de espera","estrategias de selección"],"fr":["playwriter","Outil IA","outils de développement","contrôle du navigateur","extraits de code Playwright","environnement de sandbox étatique","gestion de sessions","configuration de délai d''attente","stratégies de sélection"],"de":["playwriter","KI-Tool","Entwicklungstools","Browsersteuerung","Playwright-Snippets","stateful Sandbox","Sitzungsverwaltung","Timeout-Konfiguration","Selektionsstrategien"],"pt":["playwriter","playwright","controle de navegador","sandbox estado","CLI","MCP","gerenciamento de sessões","configuração de tempo de espera","estratégias de seletor"],"ru":["playwriter","playwright","управление браузером","песочница состояния","CLI","MCP","управление сессиями","настройка времени ожидания","стратегии селектора"],"ar":["playwriter","playwright","التحكم في المتصفح","sandbox حالة","CLI","MCP","إدارة الجلسات","ضبط وقت الانتظار","استراتيجيات المحدد"]}},"owner":"remorses","repo":"playwriter","repoPath":"remorses/playwriter","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.274Z","topics":[],"category":"community","skillMd":{"name":"playwriter","description":"Control the user own Chrome browser via Playwriter extension with Playwright code snippets in a stateful local js sandbox via playwriter cli. Use this over other Playwright MCPs to automate the browser — it connects to the users existing Chrome instead of launching a new one. Use this for JS-heavy websites (Instagram, Twitter, cookie/login walls, lazy-loaded UIs) instead of webfetch/curl. Run `playwriter skill` command to read the complete up to date skill","bodyPreview":"## REQUIRED: Read Full Documentation First\n\n**Before using playwriter, you MUST run this command:**\n\n```bash\nplaywriter skill\n```\n\nThis outputs the complete documentation including:\n\n- Session management and timeout configuration\n- Selector strategies (and which ones to AVOID)\n- Rules to prevent timeouts and failures\n- Best practices for slow pages and SPAs\n- Context variables, utility functions, and more\n\n**Do NOT skip this step.** The quick examples below will fail without understanding timeou","body":"## REQUIRED: Read Full Documentation First\n\n**Before using playwriter, you MUST run this command:**\n\n```bash\nplaywriter skill\n```\n\nThis outputs the complete documentation including:\n\n- Session management and timeout configuration\n- Selector strategies (and which ones to AVOID)\n- Rules to prevent timeouts and failures\n- Best practices for slow pages and SPAs\n- Context variables, utility functions, and more\n\n**Do NOT skip this step.** The quick examples below will fail without understanding timeouts, selector rules, and common pitfalls from the full docs.\n\n**Read the ENTIRE output.** Do NOT pipe through `head`, `tail`, or any truncation command. The skill output must be read in its entirety — critical rules about timeouts, selectors, and common pitfalls are spread throughout the document, not just at the top.\n\n## Minimal Example (after reading full docs)\n\n```bash\nplaywriter session new\nplaywriter -s 1 -e ''await page.goto(\"https://example.com\")''\n```\n\n**Always use single quotes** for the `-e` argument. Single quotes prevent bash from interpreting `$`, backticks, and backslashes inside your JS code. Use double quotes or backtick template literals for strings inside the JS.\n\nIf `playwriter` is not found, use `npx playwriter@latest` or `bunx playwriter@latest`.\n"},"lastSynced":"2026-03-08T02:00:32.689Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced browser automation capabilities through Playwright snippets in a stateful sandbox.","zh":"适用于需要通过Playwright代码片段在有状态沙盒中实现高级浏览器自动化功能的AI代理。","ja":"Playwrightスニペットを使用した高度なブラウザ自動化機能が必要なAIエージェントに適しています。","ko":"Playwright 코드 조각을 사용하여 상태 저장 샌드박스에서 고급 브라우저 자동화 기능을 구현해야 하는 AI 에이전트에 적합합니다.","es":"Perfecto para Agentes de IA que necesitan capacidades de automatización de navegador avanzadas a través de fragmentos de Playwright en un entorno de sandbox con estado.","fr":"Parfait pour les Agents IA nécessitant des capacités d''automatisation de navigateur avancées via des extraits de Playwright dans un environnement de sandbox avec état.","de":"Perfekt für KI-Agents, die erweiterte Browser-Automatisierungsfunktionen durch Playwright-Snippets in einer stateful Sandbox benötigen.","pt":"Perfeito para Agentes de IA que precisam de capacidades avançadas de automação de navegador por meio de trechos do Playwright em um sandbox stateful.","ru":"Идеально для агентов ИИ, которым необходимы продвинутые возможности автоматизации браузера через фрагменты Playwright в stateful sandbox.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى قدرات متقدمة في автоматизации المتصفح من خلال شذرات Playwright في sandbox ذي حالة"},"recommendation":{"en":"Empowers agents to control browsers, run Playwright snippets, and automate browser interactions using session management, selector strategies, and context variables, while preventing timeouts and failures through best practices for slow pages and SPAs.","zh":"赋予代理控制浏览器、运行Playwright代码片段和使用会话管理、选择器策略和上下文变量自动化浏览器交互的能力，同时通过针对慢页面和SPAs的最佳实践防止超时和故障。","ja":"エージェントがブラウザを制御し、Playwrightスニペットを実行し、セッション管理、セレクタ戦略、コンテキスト変数を使用してブラウザのインタラクションを自動化する能力を付与します。また、ベストプラクティスを使用して、遅いページやSPAsのタイムアウトや障害を防ぎます。","ko":"에이전트가 브라우저를 제어하고 Playwright 코드 조각을 실행하며 세션 관리, 선택기 전략 및 컨텍스트 변수를 사용하여 브라우저 상호 작용을 자동화할 수 있는 기능을 부여합니다. 또한 최고의 관행을 사용하여 느린 페이지 및 SPAs의 시간 초과 및 장애를 방지합니다.","es":"Habilita a los agentes a controlar navegadores, ejecutar fragmentos de Playwright y automatizar interacciones del navegador utilizando la gestión de sesiones, estrategias de selectores y variables de contexto, mientras previene tiempos de espera y fallos a través de las mejores prácticas para páginas lentas y SPAs.","fr":"Permet aux agents de contrôler les navigateurs, d''exécuter des extraits de Playwright et d''automatiser les interactions de navigateur en utilisant la gestion de sessions, les stratégies de sélection et les variables de contexte, tout en prévenant les délais d''attente et les défaillances grâce aux meilleures pratiques pour les pages lentes et les SPAs.","de":"Ermächtigt Agents, Browser zu steuern, Playwright-Snippets auszuführen und Browser-Interaktionen mithilfe von Sitzungsverwaltung, Selektor-Strategien und Kontextvariablen zu automatisieren, während es Timeouts und Ausfälle durch bewährte Verfahren für langsame Seiten und SPAs verhindert.","pt":"Habilita os agentes a controlar navegadores, executar trechos do Playwright e automatizar interações de navegador usando gerenciamento de sessão, estratégias de seletor e variáveis de contexto, enquanto evita tempos de inatividade e falhas por meio de práticas recomendadas para páginas lentas e SPAs.","ru":"Наделяет агентов возможностью контролировать браузеры, выполнять фрагменты Playwright и автоматизировать взаимодействия браузера с помощью управления сессиями, стратегий селектора и контекстных переменных, а также предотвращает таймауты и сбои за счет передовых практик для медленных страниц и SPA.","ar":"تمكّن الوكلاء من التحكم في المتصفحات، وتشغيل شذرات Playwright، وتنفيذ عمليات автоматизации للمتصفح باستخدام إدارة الجلسات، و استراتيجيات المحدد، ومتغيرات السياق، مع منع انتهاء الوقت و الفشل من خلال أفضل الممارسات للصفحات البطيئة وتطبيقات صفحة واحدة"},"useCases":{"en":["Automating browser interactions for web scraping","Generating user journeys through stateful sandbox environments","Debugging web applications using Playwright snippets"],"zh":["用于网页抓取的浏览器交互自动化","通过有状态沙盒环境生成用户旅程","使用Playwright代码片段调试Web应用程序"],"ja":["Webスクレイピングのためのブラウザのインタラクションを自動化する","状態を保存したサンドボックス環境を介してユーザージャーニーを生成する","Playwrightスニペットを使用してWebアプリケーションをデバッグする"],"ko":["웹 스크래핑을 위한 브라우저 상호 작용 자동화","상태를 저장한 샌드박스 환경을 통해 사용자 여정을 생성하는 것","Playwright 코드 조각을 사용하여 웹 애플리케이션을 디버깅하는 것"],"es":["Automatización de interacciones del navegador para web scraping","Generación de trayectos de usuario a través de entornos de sandbox con estado","Depuración de aplicaciones web utilizando fragmentos de Playwright"],"fr":["Automatisation des interactions de navigateur pour le web scraping","Génération de parcours d''utilisateur via des environnements de sandbox avec état","Débogage d''applications web en utilisant des extraits de Playwright"],"de":["Automatisierung von Browser-Interaktionen für Web Scraping","Erzeugung von Benutzerreisen durch stateful Sandbox-Umgebungen","Fehlerbehebung von Webanwendungen unter Verwendung von Playwright-Snippets"],"pt":["Automatizar interações de navegador para web scraping","Gerar jornadas de usuário por meio de ambientes de sandbox stateful","Depurar aplicações web usando trechos do Playwright"],"ru":["Автоматизация взаимодействий браузера для веб-скрейпинга","Генерация пользовательских путей через среды stateful sandbox","Отладка веб-приложений с помощью фрагментов Playwright"],"ar":["أتمتة تفاعلات المتصفح لاستخراج البيانات من الويب","توليد مسارات المستخدم من خلال بيئات sandbox ذات حالة","تصحيح الأخطاء في تطبيقات الويب باستخدام شذرات Playwright"]},"limitations":{"en":["Requires running the command ''playwriter skill'' to access complete documentation","Needs understanding of session management and timeout configuration","Specific selector strategies should be avoided as per documentation"],"zh":["需要运行命令''playwriter skill''来访问完整文档","需要了解会话管理和超时配置","应避免使用特定的选择器策略，如文档所述"],"ja":["完全なドキュメントにアクセスするには、コマンド''playwriter skill''を実行する必要がある","セッション管理とタイムアウトの設定を理解する必要がある","ドキュメントに記載されているように、特定のセレクタ戦略を避けるべきである"],"ko":["완전한 문서에 액세스하려면 명령 ''playwriter skill''을 실행해야 함","세션 관리 및 시간 초과 구성에 대한 이해가 필요함","문서에 설명된 대로 특정 선택기 전략을 피해야 함"],"es":["Requiere ejecutar el comando ''playwriter skill'' para acceder a la documentación completa","Necesita comprensión de la gestión de sesiones y la configuración de timeouts","Deben evitarse estrategias de selectores específicas según la documentación"],"fr":["Nécessite l''exécution de la commande ''playwriter skill'' pour accéder à la documentation complète","Nécessite une compréhension de la gestion de sessions et de la configuration des délais d''attente","Des stratégies de sélection spécifiques doivent être évitées selon la documentation"],"de":["Erfordert die Ausführung des Befehls ''playwriter skill'', um auf die vollständige Dokumentation zuzugreifen","Benötigt das Verständnis von Sitzungsverwaltung und Timeout-Konfiguration","Bestimmte Selektor-Strategien sollten gemäß der Dokumentation vermieden werden"],"pt":["Requer a execução do comando ''playwriter skill'' para acessar a documentação completa","Exige compreensão do gerenciamento de sessão e configuração de tempo de inatividade","Estratégias de seletor específicas devem ser evitadas de acordo com a documentação"],"ru":["Требует выполнения команды ''playwriter skill'' для доступа к полной документации","Требует понимания управления сессиями и конфигурации таймаута","Определенные стратегии селектора должны быть избегаемы в соответствии с документацией"],"ar":["يتطلب تشغيل الأمر ''playwriter skill'' للوصول إلى الوثائق الكاملة","يتطلب فهم إدارة الجلسات وتكوين انتهاء الوقت","يجب تجنب استراتيجيات محددة للمحدد وفقًا للوثائق"]},"version":4},"contentHash":"0c5f07a0de4bab4f9ee16861eaba0dfb739b5d1462870a03345b2e3223756fff","qualityScore":36}');
