INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('whawkinsiv/solo-founder-superpowers/build', 'build', 'whawkinsiv', 'solo-founder-superpowers', 'community', 'build whawkinsiv solo-founder-superpowers community The build skill enables non-technical founders to complete the software development lifecycle using AI tools. It optimizes SaaS application development with tools like Lovable, Replit, and Claude Code. 构建技能提供了完整的软件开发周期，使用Lovable，Replit，Claude Code等AI工具优化非技术创始人构建SaaS应用 ビルドスキルは、Lovable，Replit，Claude CodeなどのAIエージェントを使用して、非技術的な創設者がSaaSアプリケーションを構築するための完全なソフトウェア開発ライフサイクルを提供します 빌드 기능은 Lovable, Replit, Claude Code 등의 AI 도구를 사용하여 비기술 창립자가 SaaS 애플리케이션을 구축하기 위한 완전한 소프트웨어 개발 주기를 제공합니다 Construye aplicaciones SaaS con agentes de IA como Lovable, Replit y Claude Code. Nuestro enfoque optimizado para fundadores no técnicos Construisez des applications SaaS avec des outils d''IA comme Lovable, Replit et Claude Code. Notre approche optimisée pour les fondateurs non techniques Erstellen Sie SaaS-Anwendungen mit KI-Tools wie Lovable, Replit und Claude Code. Unser optimierter Ansatz für nicht-technische Gründer O skill de build é uma solução de ciclo de vida de desenvolvimento de software otimizada para fundadores não técnicos que constroem aplicações SaaS com ferramentas de IA. Навык сборки - это решение жизненного цикла разработки программного обеспечения, оптимизированное для неквалифицированных основателей, строящих приложения SaaS с помощью инструментов ИИ Агентов. مهارة البناء هي حل دورة حياة تطوير البرمجيات المُختصة بالمسؤولين غير التقنيين الذين يبنين تطبيقات السحابة باستخدام أدوات الإيمان العامل. how to use build skill what is build skill build alternative tools build vs Lovable build setup guide for SaaS build install for AI agents Replit vs Claude Code Lovable for MVP development build workflow optimization AI工具 软件开发周期 SaaS应用 非技术创始人 Lovable Replit Claude Code 代码学习 迭代开发 Utilizes Lovable for rapid MVP development Integrates Claude Code for context-aware code completion Supports Replit for educational coding and development Includes Cursor for power features and advanced coding Follows a structured build workflow with spec, testing, and iteration Enables deployment of SaaS applications with AI-driven development Build is a skill that streamlines the software development lifecycle for non-technical founders, leveraging AI tools for efficient SaaS application development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('feiskyer/codex-settings/deep-research', 'community', 'feiskyer', 'codex-settings', 'feiskyer/codex-settings', 'deep-research', 0, 0, 36, '2026-03-08T01:57:15.276Z', '2026-03-08T02:00:41.091Z', '44bf8a38bb93d1f937e1da5bfb0fa4b2987fca617575d9887938cdb03cecff99', '{"id":"feiskyer/codex-settings/deep-research","name":"deep-research","description":{"en":"The deep-research skill enables developers to execute vibe coding workflows efficiently, utilizing OpenAI Codex CLI settings and configurations. It benefits developers seeking to streamline their coding processes","zh":"深度调研是一种可复用、可并行的生产流程，使用OpenAI Codex CLI配置与优化","ja":"ディープリサーチは、OpenAI Codex CLIを使用して設定および最適化できる再利用可能な並列プロセスです","ko":"딥 리서치는 OpenAI Codex CLI를 사용하여 설정 및 최적화할 수 있는 재사용 가능한 병렬 프로세스입니다","es":"Deep-research es un flujo de trabajo de investigación que utiliza OpenAI Codex CLI para realizar tareas de investigación en paralelo","fr":"Deep-research est un flux de travail de recherche qui utilise OpenAI Codex CLI pour effectuer des tâches de recherche en parallèle","de":"Deep-research ist ein Forschungsworkflow, der OpenAI Codex CLI nutzt, um Forschungsaufgaben parallel durchzuführen","pt":"O deep-research é um skill que permite a execução de fluxos de trabalho de pesquisa em profundidade, utilizando OpenAI Codex CLI para vibe coding","ru":"Глубокое исследование - это навык, который позволяет выполнять рабочие процессы глубокой исследовательской работы, используя OpenAI Codex CLI для vibe coding ИИ Агентов","ar":"الdeep-research هو مهارة تسمح بتنفيذ تدفقات عمل بحثية متعمقة، باستخدام OpenAI Codex CLI لتدفق العمل المثالي للآلات الذكية"},"seo":{"title":{"en":"deep-research: Setup Guide for AI Agents","zh":"深度调研Setup Guide：OpenAI Codex CLI配置与优化","ja":"ディープリサーチSetup Guide：OpenAI Codex CLI設定と最適化","ko":"딥 리서치 설정 가이드: OpenAI Codex CLI 설정 및 최적화","es":"Guía de configuración de deep-research para agentes de IA","fr":"Guide de configuration de deep-research pour les outils d''IA","de":"Konfigurationsleitfaden für deep-research in AI-Agenten","pt":"Guia de Configuração Deep-Research: Otimização de Fluxo d...","ru":"Настройка глубокого исследования: лучшие практики для ИИ ...","ar":"دليل إعداد глубين-ريسرش: تحسين تدفق العمل للآلات الذكية"},"description":{"en":"Unlock efficient vibe coding with deep-research skill. Learn how to configure OpenAI Codex CLI for seamless workflow execution and discover its key features","zh":"了解如何配置OpenAI Codex CLI进行深度调研，优化生产流程，提高开发效率","ja":"OpenAI Codex CLIを設定してディープリサーチを実行する方法を学び、開発効率を向上させる","ko":"OpenAI Codex CLI를 설정하여 딥 리서치를 수행하는 방법을 배우고 개발 효율성을 높여보세요","es":"Aprende a configurar deep-research para agentes de IA con OpenAI Codex CLI y mejora tus flujos de trabajo de investigación","fr":"Découvrez comment configurer deep-research pour les outils d''IA avec OpenAI Codex CLI et améliorez vos flux de travail de recherche","de":"Erfahren Sie, wie Sie deep-research für AI-Agenten mit OpenAI Codex CLI konfigurieren und Ihre Forschungsworkflows verbessern","pt":"Aprenda a configurar o deep-research para vibe coding com OpenAI Codex CLI, incluindo skills e prompts para um fluxo de trabalho eficaz","ru":"Узнайте, как настроить глубокое исследование для vibe coding с помощью OpenAI Codex CLI, включая навыки и промпты для эффективного рабочего процесса ИИ Агентов","ar":"تعلم كيفية تهيئة глубين-ريسرش لتدفق العمل المثالي مع OpenAI Codex CLI، بما في ذلك المهارات والتحفيزات للآلات الذكية"},"definition":{"en":"deep-research is a reusable and parallel production flow process that clarifies targets, decomposes sub-targets, schedules sub-processes, and aggregates outputs","zh":"深度调研是指使用OpenAI Codex CLI进行复杂任务的自动化与优化","ja":"ディープリサーチは、OpenAI Codex CLIを使用して複雑なタスクを自動化および最適化すること","ko":"딥 리서치는 OpenAI Codex CLI를 사용하여 복잡한 태스크를 자동화 및 최적화하는 것을 의미합니다","es":"Deep-research es un proceso de investigación automatizado que utiliza agentes de IA para recopilar y analizar información","fr":"Deep-research est un processus de recherche automatisé qui utilise des outils d''IA pour collecter et analyser des informations","de":"Deep-research ist ein automatisierter Forschungsprozess, der AI-Agenten nutzt, um Informationen zu sammeln und zu analysieren","pt":"Deep-research é um skill de pesquisa em profundidade que utiliza OpenAI Codex CLI para execução de fluxos de trabalho","ru":"Глубокое исследование - это навык глубокой исследовательской работы, который использует OpenAI Codex CLI для выполнения рабочих процессов ИИ Агентов","ar":"الdeep-research هو مهارة بحثية متعمقة تستخدم OpenAI Codex CLI لتنفيذ تدفقات العمل للآلات الذكية"},"features":{"en":["Executes vibe coding workflows using OpenAI Codex CLI settings and configurations","Utilizes default models and configurations without explicit overrides","Runs sub-processes in sandbox workspace-write mode with optional network access","Supports skills installation and MCP usage with firecrawl and tavily prioritization","Generates structured Markdown outputs for final deliverables"],"zh":["保持默认模型与配置不变","默认最小权限，仅在必要时启用网络等权限","优先使用已安装skills，若必须使用MCP，则优先firecrawl","支持结构化Markdown素材输出","子进程默认在--sandbox workspace-write下运行"],"ja":["デフォルトのモデルと設定を変更しない","デフォルトで最小限の権限を使用し、必要な場合のみネットワークなどの権限を有効にする","インストールされたスキルを優先的に使用し、MCPを使用する場合はfirecrawlを優先する","構造化されたMarkdown素材の出力をサポート","サブプロセスはデフォルトで--sandbox workspace-write下で実行される"],"ko":["기본 모델 및 구성 변경하지 않음","기본적으로 최소한의 권한을 사용하고, 필요한 경우에만 네트워크 등의 권한을 활성화","설치된 스킬을 우선적으로 사용하고, MCP를 사용하는 경우 firecrawl을 우선","구조화된 Markdown 자료의 출력을 지원","서브 프로세스는 기본적으로 --sandbox workspace-write에서 실행"],"es":["Utiliza OpenAI Codex CLI para configurar y ejecutar flujos de trabajo de investigación","Permite la ejecución de tareas de investigación en paralelo","Utiliza un enfoque de sandbox para garantizar la seguridad y la privacidad","Soporta la integración con habilidades y modelos de lenguaje","Proporciona una salida de Markdown estructurada para los resultados de la investigación"],"fr":["Utilise OpenAI Codex CLI pour configurer et exécuter des flux de travail de recherche","Permet l''exécution de tâches de recherche en parallèle","Utilise une approche de sandbox pour garantir la sécurité et la confidentialité","Prend en charge l''intégration avec des compétences et des modèles de langage","Fournit une sortie de Markdown structurée pour les résultats de la recherche"],"de":["Nutzt OpenAI Codex CLI, um Forschungsworkflows zu konfigurieren und auszuführen","Ermöglicht die Ausführung von Forschungsaufgaben in Parallelschritten","Verwendet einen Sandbox-Ansatz, um Sicherheit und Privatsphäre zu gewährleisten","Unterstützt die Integration mit Fähigkeiten und Sprachmodellen","Bietet eine strukturierte Markdown-Ausgabe für die Forschungsergebnisse"],"pt":["Configuração de OpenAI Codex CLI para vibe coding","Utilização de skills e prompts para fluxo de trabalho eficaz","Execução de subprocessos em sandbox com permissões mínimas","Acesso à rede apenas quando necessário","Priorização do uso de skills instalados em vez de MCP"],"ru":["Настройка OpenAI Codex CLI для vibe coding ИИ Агентов","Использование навыков и промптов для эффективного рабочего процесса","Выполнение subprocessов в sandbox с минимальными разрешениями","Доступ к сети только при необходимости","Приоритет использования установленных навыков вместо MCP для ИИ Агентов"],"ar":["تهيئة OpenAI Codex CLI لتدفق العمل المثالي للآلات الذكية","استخدام المهارات والتحفيزات لتدفق عمل فعال","تنفيذ subprocesses في sandbox مع صلاحيات دنيا","الوصول إلى الشبكة فقط عند الحاجة","الأولوية لاستخدام المهارات المثبتة بدلاً من MCP للآلات الذكية"]},"keywords":{"en":["how to use deep-research","deep-research setup guide","what is deep-research","deep-research alternative","deep-research vs OpenAI Codex","deep-research install","configuring OpenAI Codex CLI","vibe coding workflow optimization","deep-research skill for AI agents"],"zh":["深度调研","OpenAI Codex CLI","AIエージェント","自动化与优化","结构化Markdown","最小权限","firecrawl","MCP"],"ja":["ディープリサーチ","OpenAI Codex CLI","AIエージェント","自動化と最適化","構造化されたMarkdown","最小限の権限","firecrawl","MCP"],"ko":["딥 리서치","OpenAI Codex CLI","AI 에이전트","자동화 및 최적화","구조화된 Markdown","최소한의 권한","firecrawl","MCP"],"es":["agentes de IA","OpenAI Codex CLI","flujos de trabajo de investigación","investigación en paralelo","sandbox","integración con habilidades","modelos de lenguaje","Markdown estructurado"],"fr":["outils d''IA","OpenAI Codex CLI","flux de travail de recherche","recherche en parallèle","sandbox","intégration avec des compétences","modèles de langage","Markdown structuré"],"de":["AI-Agenten","OpenAI Codex CLI","Forschungsworkflows","Forschung in Parallelschritten","Sandbox","Integration mit Fähigkeiten","Sprachmodelle","strukturierter Markdown"],"pt":["deep-research","OpenAI Codex CLI","vibe coding","fluxo de trabalho","pesquisa em profundidade","skills de pesquisa","prompts de pesquisa","sandbox","permissões mínimas"],"ru":["глубокое исследование","OpenAI Codex CLI","vibe coding ИИ Агентов","рабочий процесс","глубокая исследовательская работа","навыки исследования","промпты исследования","sandbox","минимальные разрешения"],"ar":["الdeep-research","OpenAI Codex CLI","تدفق العمل المثالي للآلات الذكية","تدفق العمل","البحث المتعمق","المهارات البحثية","التحفيزات البحثية","sandbox","الصلاحيات الدنيا"]}},"owner":"feiskyer","repo":"codex-settings","repoPath":"feiskyer/codex-settings","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.276Z","topics":[],"category":"community","skillMd":{"name":"deep-research","description":"深度调研的多实例（多 Agent）编排工作流：把一个调研目标拆成可并行子目标，用 Codex CLI（`codex exec`）在默认 `workspace-write` 沙箱内运行子进程；联网与采集优先使用已安装的 skills，其次使用 MCP 工具；用脚本聚合子结果并分章精修，最终交付“成品报告文件路径 + 关键结论/建议摘要”。用于：系统性网页/资料调研、竞品/行业分析、批量链接/数据集分片检索、长文写作与证据整合，或用户提及“深度调研/Deep Research/Wide Research/多 Agent 并行调研/多进程调研”等场景。","bodyPreview":"# Deep Research（深度调研编排工作流）\n\n把“深度调研”当作一个可复用、可并行的生产流程来执行：主控负责澄清目标、拆解子目标、调度子进程、聚合与精修；子进程负责采集/抽取/局部分析并输出结构化 Markdown 素材；最终交付物必须是独立成品文件而不是聊天贴文。\n\n**关键约束（必须遵守）**\n\n- **保持默认模型与配置不变**：不要显式覆盖 `--model` 或用额外 `-c` 覆写默认模型/推理设置；只有在用户明确授权时才调整相关配置。\n- **默认最小权限**：子进程默认在 `--sandbox workspace-write` 下运行；仅在必要时启用网络等权限。若子任务必须执行“需要 shell 联网”的命令（例如 `curl`/`wget`），在 `codex exec` 中添加 `-c sandbox_workspace_write.network_access=true`。\n- **联网优先走 skills，其次 MCP**：优先使用已安装 skills；若必须使用 MCP，则优先 `firecrawl`，其次 `tavily`；确实无法满足时再考虑 `","body":"# Deep Research（深度调研编排工作流）\n\n把“深度调研”当作一个可复用、可并行的生产流程来执行：主控负责澄清目标、拆解子目标、调度子进程、聚合与精修；子进程负责采集/抽取/局部分析并输出结构化 Markdown 素材；最终交付物必须是独立成品文件而不是聊天贴文。\n\n**关键约束（必须遵守）**\n\n- **保持默认模型与配置不变**：不要显式覆盖 `--model` 或用额外 `-c` 覆写默认模型/推理设置；只有在用户明确授权时才调整相关配置。\n- **默认最小权限**：子进程默认在 `--sandbox workspace-write` 下运行；仅在必要时启用网络等权限。若子任务必须执行“需要 shell 联网”的命令（例如 `curl`/`wget`），在 `codex exec` 中添加 `-c sandbox_workspace_write.network_access=true`。\n- **联网优先走 skills，其次 MCP**：优先使用已安装 skills；若必须使用 MCP，则优先 `firecrawl`，其次 `tavily`；确实无法满足时再考虑 `curl`/`wget`。\n- **非交互式友好**：子进程不使用 plan 工具，不与用户“等确认/等反馈”式互动；以文件落地、日志可追溯为主。\n- **文件交付优先**：最终交付物必须落地为独立文件，禁止在聊天中贴出完整成稿。\n- **每一步输出决策与进度日志**：尤其在拆分、调度、聚合、精修、交付前。\n\n## 任务目标\n\n1. 从用户的高层目标推导出可并行的子目标集合（如链接清单、数据分片、模块列表、时间切片等）。\n2. 为每个子目标启动独立的 `codex exec` 子进程，并为其分配合适权限（默认 sandbox；必要时启网）。\n3. 并行执行并产出子报告（自然语言 Markdown，可含小节/表格/列表）；失败时输出带原因的错误说明与后续建议。\n4. 用脚本按顺序聚合子输出，生成统一的基础稿。\n5. 对基础稿做理智检查与**最小化修复**，然后给出最终 artefact 路径与关键发现摘要。\n\n## 交付标准\n\n- 交付物必须是**结构化、洞察驱动**的整体成品；禁止把子任务 Markdown 直接拼接当作最终稿。\n- 需要保留子任务原文时，将其另存为内部文件（例如 `.research/<name>/aggregated_raw.md`），在成品中仅吸收关键洞察/证据。\n- 润色与修订要**按章节逐段迭代**，不得整篇删除后一次性重写；每次修改后核对引用、数据与上下文，保证可追溯。\n- 默认交付详实、深入的分析型报告。\n- 交付前做“双重体检质检”：\n  1) 检查是否真的是“分章节、多轮整合”产出；若只是一次性生成，退回按章节重写。\n  2) 评估是否足够细致；若偏单薄，先判断是“子任务素材不足”还是“统稿时压缩过度”：前者驱动补充/追加调研，后者在既有素材上继续扩展润色，直至达到详细标准。\n\n## 端到端流程（严格按序执行）\n\n0. **预执行规划与摸底（必做；主控亲自完成）**\n   - 先澄清目标、风险、资源/权限约束，并识别后续扩散依赖的核心维度（主题簇、人物/组织、地域、时间切片等）。\n   - 若存在公开目录/索引（标签页、API 列表等），用最小化方式抓取缓存并统计条目；若不存在，做“案头调研”获取真实样本（新闻、资料、数据集等），记录来源/时间/要点作为证据。\n   - 形成清单前至少展示一次真实检索或浏览的代表样本；只靠经验推测不算完成摸底。\n   - 摸底阶段必须至少通过一次“可追溯的工具链”拿到真实样本并记录引用：优先使用已安装 skills；若需要 MCP，则优先 `firecrawl`，其次 `tavily`；若都不可用，记录原因并选择替代方案（必要时再降级到最小化直接联网抓取）。\n   - 输出初步（或草拟）清单：列出发现的维度、各维度已掌握的选项及样本、规模估算，并标注不确定性/缺口。若尚未获得真实样本，先补齐调研，禁止进入下一步。\n   - 依据上述结构补全可执行计划（拆分、脚本/工具、输出格式、权限、超时策略等），用用户语言汇报维度统计与计划内容；在得到明确“执行/开始”回应前保持等待。\n\n1. **初始化与总体规划**\n   - 明确目标、预期输出格式与评价标准。\n   - 根据当前任务生成一个语义化且不重复的名字 `name`（建议：`<YYYYMMDD>-<短题>-<随机后缀>`，全小写、短横线分隔、无空格）。\n   - 创建运行目录 `.research/<name>/`，并把**所有**产物都保存到该目录下（子目录如 `prompts/`、`logs/`、`child_outputs/`、`raw/`、`cache/`、`tmp/`）。\n   - 保持默认模型与配置不变；需要调整任何模型/推理/权限相关设置时先征得用户同意，并在日志中注明变更原因与影响范围。\n\n2. **子目标识别**\n   - 通过脚本/命令提取或构造子目标列表。\n   - 源数据不足时（例如页面只给两个主链接），如实记录原因，然后由主进程直接接手完成剩余工作。\n\n3. **生成调度脚本**\n   - 创建调度脚本（例如 `.research/<name>/run_children.sh`），要求：\n     - 接收子目标列表（可存 JSON/CSV）并逐项调度。\n     - 为每个子目标构造 `codex exec` 调用，推荐要点：\n       - 推荐形式：`codex exec --full-auto --sandbox workspace-write ...`（以 `codex exec --help` 为准）。\n       - 在 prompt 中声明：一切联网需求优先使用已安装 skills（技能优先）；若必须走 MCP，则优先 `firecrawl`，其次 `tavily`；确实没办法才用 `curl`/`wget`；不使用 plan 工具与“人工交互等待”。\n       - 非经用户要求不传 `--model`，也不要用额外 `-c` 覆写默认模型/推理设置；仅在用户明确授权且结果质量确实不足时才考虑调整。\n       - 为子输出指定落盘路径（例如 `.research/<name>/child_outputs/<id>.md`）。\n       - 明确禁止使用已废弃参数（如 `--prompt-file`、`--mcp`、`--name`），并提醒先运行 `codex exec --help` 获取最新说明。可引用如下调用模板（仅演示参数，不涉及并行）：\n         ```bash\n         timeout 600 codex exec --full-auto --sandbox workspace-write \\\n            --output-last-message \"$output_file\" \\\n            - <\"$prompt_file\"\n         ```\n       - 如需允许子进程执行“需要 shell 联网”的命令（例如 `curl`/`wget`），在 `codex exec` 调用中追加：`-c sandbox_workspace_write.network_access=true`。\n       - 依据任务规模设置超时：小任务先给 5 分钟（`timeout 300`），较大任务可放宽到最多 15 分钟（`timeout 900`），通过外部 `timeout` 命令兜底。首次命中 5 分钟超时时，结合任务实际判断是否拆分/改参数再重试；15 分钟仍未完成则视为 prompt 或流程需要排查。\n       - 小规模任务（<8 个）用循环 + 后台任务（或队列控制）实现并行，避免命令行长度限制导致失败；大规模任务用 `xargs`/GNU Parallel，但必须先用小规模验证参数展开。默认并行 8 个，可按硬件或配额调整。\n       - 不要用“串行一个个跑”来替代并行；也不要用“主进程随便搜搜”等方式绕过既定流程。\n       - 捕获每个子进程退出码并写日志到运行目录；用 `stdbuf -oL -eL codex exec … | tee .research/<name>/logs/<id>.log` 等方式保证实时刷新，便于 `tail -f` 观察进度。\n       - 注意 `codex exec` 不提供 `--output`、`--log-level` 等参数；需要通过管道写文件，并在多段管道后用正确的 `PIPESTATUS` 索引确认退出码。运行前可用 `codex exec --help` 复核可用参数。\n   - 数据量足够时，主控尽量不亲自承担下载/解析等重活；把这些工作交给子进程完成，主控专注于 prompt、模板与环境准备。\n\n4. **设计子进程 Prompt**\n   - 动态生成 prompt 模板，至少包含：\n     - 子目标描述、输入数据、约束边界。\n     - 规划阶段限制联网检索/抽取的总轮数不超过 X（按复杂度选择；通常建议 10），信息足够就收敛结束；工具优先级：skills → MCP（`firecrawl` → `tavily`）→ 最小化直接抓取。\n     - 结果输出为自然语言 Markdown：包含结论、关键证据列表、引用链接；出现错误时给出 Markdown 形式的错误说明与后续建议。\n     - 生成实际 prompt 文件时，优先用 `printf`/逐行写入注入变量，避免 Bash 3.2 在多字节字符场景下 `cat <<EOF` 截断变量的已知问题。\n   - 将模板写入文件（例如 `.research/<name>/child_prompt_template.md`）以便审计与复用。\n   - 在启动调度脚本前，逐一快速审阅生成的 prompt 文件（例如 `cat .research/<name>/prompts/<id>.md`），确认变量替换正确、指令完整后再派发任务。\n\n5. **并行执行与监控**\n   - 运行调度脚本。\n   - 记录每个子进程的开始/结束时间、耗时与状态。\n   - 对失败/超时子进程做明确决策：标记、重试、或在最终报告中说明；触及 15 分钟超时上限时记录 prompt/流程待排查。长任务执行中可提示用户用 `tail -f .research/<name>/logs/<id>.log` 追踪实时输出。\n\n6. **程序化聚合（生成基础稿）**\n   - 用脚本（例如 `.research/<name>/aggregate.py`）读取 `.research/<name>/child_outputs/` 下所有 Markdown，按预设顺序聚合为初版主文档（例如 `.research/<name>/final_report.md`）。\n\n7. **解读聚合结果并设计结构**\n   - 通读 `.research/<name>/final_report.md` 与关键子输出。\n   - 设计精修报告章节大纲与“素材映射”（例如 `.research/<name>/polish_outline.md`），明确目标受众、章节顺序与每章核心论点。\n\n8. **分章精修与出稿**\n   - 新建精修稿（例如 `.research/<name>/polished_report.md`），按大纲逐章撰写；每写完一章立刻自查事实、引用与语言要求，必要时回溯子稿核实。\n   - 避免一次性全篇重写；坚持“按章迭代”以维持一致性并降低遗漏风险，同时记录每章亮点、问题与处理方式。\n   - 对重复信息、引用格式、待确认条目做统一整理，同时保留核心事实与量化数据。\n\n9. **落地交付**\n   - 确认精修稿满足交付标准（结构完整、语气统一、引用准确），以该成品作为对外报告。\n   - 最终交付物必须落地为独立文件（位于 `.research/<name>/`）；通过提供文件路径与必要摘要向用户回报，禁止在聊天中贴出完整成稿。\n   - 在最终答复中概述核心结论与可执行建议；必要时补充待确认事项的跟进方式。\n   - 不对外附带中间稿或内部笔记，确保用户看到的是高质量成品。\n\n## 注意事项\n\n- 保持流程幂等：每次运行都生成新的 `.research/<name>/`，避免覆盖旧文件。\n- 所有结构化输出必须是合法 UTF-8 文本。\n- 仅在得到授权或确有必要时提升权限；避免使用 `--dangerously-bypass-approvals-and-sandbox`。\n- 清理临时资源时保持谨慎，确保日志与输出可追溯。\n- 对失败流程给出可降级的说明：抓取类任务至少尝试两次；仍失败则在 Markdown 中新增“失败原因/后续建议”小节，避免聚合阶段出现空白。\n- **缓存优先**：通过 skills/MCP 获取的原始资料，先写入 `.research/<name>/raw/` 等缓存目录，后续处理优先读取本地缓存以减少重复请求。\n- **先完整理解再总结**：总结/提炼前先处理完整原文，不得机械截取固定长度（例如前 500 字符）。可写脚本做全文解析、提取关键句或生成要点，但不得依赖“硬截断”。\n- **临时目录隔离**：中间产物（脚本日志、解析结果、缓存、调试输出等）放在 `.research/<name>/tmp/`、`.research/<name>/raw/`、`.research/<name>/cache/` 等子目录，必要时在流程结束后按需清理。\n- **搜索服务优先级**：联网操作优先使用已安装 skills；若需要 MCP，先查看可用 MCP server（例如运行 `codex mcp list`），并优先选择 `firecrawl`，其次 `tavily`；缺少 MCP 时再退回最小化直接抓取能力。\n- **MCP 参数与输出控制**：对返回可能过大的工具，避免请求“原始全文”类字段导致响应膨胀；必要时分段抽取、先列目录后按需深入。\n- **图像检索**：若 MCP 支持图像搜索/描述，除非用户明确要求“仅纯文本”，否则开启并将图像线索与文本证据一起呈现。\n\n## 通用经验与最佳实践\n\n- **先验证环境假设**：写调度脚本前用 `realpath`/`test -d` 等确认关键路径（如 `venv`、资源目录）存在；必要时用 `dirname \"$0\"` 推导仓库根路径并通过参数传入，避免硬编码。\n- **让提取逻辑可配置**：不要假设网页共享同一 DOM；解析脚本提供可配置选择器/边界条件/可读性解析器，跨站点复用时只需改配置。\n- **先小规模跑通再并行**：全面并行前先串行跑 1–2 个子目标验证 agent 配置、skills/MCP 工具链与输出路径；确认链路稳定后再提高并发，避免“起飞后看不清错误”。\n- **分层日志便于追溯**：调度器写 `.research/<name>/dispatcher.log`；子任务单独写 `.research/<name>/logs/<id>.log`，失败时直接 `tail` 对应日志定位 MCP/调用细节。\n- **失败隔离与重试**：并行失败时先记录失败 ID 与日志，优先对单个失败任务重试；可维护 `failed_ids` 列表并在收尾阶段统一提示后续建议。\n- **避免重复抓取**：重试前先检查 `.research/<name>/child_outputs/<id>.md` 是否已合法存在；存在则跳过，减少配额消耗与重复访问。\n- **终审与润色**：交付前必须审阅聚合与精修稿是否满足语言要求（例如要求中文则全程中文），并核对引用与数据点与源文件一致；润色时不丢失关键事实与量化信息，让成品具备洞察而非堆事实。\n- **引用就地呈现**：每条要点后直接用 Markdown 链接给来源（例如 `[来源](https://example.com)`），避免把链接集中到段尾，便于即时查证。\n- **覆盖率校验脚本**：批量生成后用轻量脚本统计缺失条目、空字段或标签数量，确保问题在报告前被发现并补救。\n- **对子进程做边界约束**：在子 prompt 中明确可访问范围（仅指定 URL/目录）与可用工具，降低越界与重复抓取风险，让流程在任意站点都安全可控。\n\n## 思考与写作指南\n\n先思考再动手：追求有深度、有独立思考、超出预期的洞见（但不要在回答里提到“惊喜”）；揣摩用户为什么会问这个问题、背后的假设是什么、有没有更本质的问法；同时明确你的答案应满足的成功标准，再围绕标准组织内容。\n\n保持协作：你的目标不是机械执行指令、也不是在信息不足时强行给出确定答案；而是与用户共同推进，逐步逼近更好的问题与更可靠的结论。\n\n写作风格要求：\n\n- 不滥用 bullet points，把它们尽量限制在 top level；能用自然语言段落就用段落。\n- 除非直接引用，否则不使用引号。\n- 写作时保持亲切、深入浅出、理性克制的语气。\n\n执行本技能时，在每一步输出清晰的决策与进度日志。\n"},"lastSynced":"2026-03-08T02:00:41.091Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code requiring efficient vibe coding workflows and OpenAI Codex CLI integration.","zh":"适用于像Cursor、Windsurf和Claude Code这样的AI代理，需要高效的vibe编码工作流和OpenAI Codex CLI集成。","ja":"Cursor、Windsurf、Claude CodeのようなAIエージェントに適しています。エージェントは、効率的なvibeコーディングワークフローとOpenAI Codex CLIの統合を必要とします。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에게 적합합니다. 효율적인 vibe 코딩 워크플ロー와 OpenAI Codex CLI 통합이 필요합니다.","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que requieren flujos de trabajo de codificación de vibraciones eficientes y la integración de OpenAI Codex CLI.","fr":"Idéal pour les agents d''IA comme Cursor, Windsurf et Claude Code nécessitant des flux de travail de codage de vibrations efficaces et l''intégration de OpenAI Codex CLI.","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die effiziente Vibe-Coding-Workflows und OpenAI Codex CLI-Integration erfordern.","pt":"Ideal para Agentes de IA como Cursor, Windsurf e Claude Code que exigem fluxos de trabalho de codificação de vibe eficientes e integração do OpenAI Codex CLI.","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, требующих эффективных рабочих процессов кодирования vibe и интеграции с OpenAI Codex CLI.","ar":"مثالي للوكلاء الذكيين مثل Cursor و Windsurf و Claude Code الذين يتطلبون سير عمل编码 الكفء ودمج OpenAI Codex CLI."},"recommendation":{"en":"Empowers agents to execute deep-research workflows utilizing OpenAI Codex CLI settings, streamlining coding processes with structured Markdown outputs, and leveraging skills like firecrawl and tavily for network access and data gathering.","zh":"赋予代理执行利用OpenAI Codex CLI设置的深度研究工作流的能力，通过结构化的Markdown输出来简化编码过程，并利用firecrawl和tavily等技能来访问网络和收集数据。","ja":"OpenAI Codex CLIの設定を使用して、深度研究ワークフローを実行するエージェントの能力を提供します。構造化されたMarkdown出力を使用してコーディングプロセスを簡素化し、firecrawlとtavilyなどのスキルを使用してネットワークにアクセスし、データを収集します。","ko":"OpenAI Codex CLI 설정을 사용하여 깊은 연구 워크플ロー를 실행하는 에이전트의 능력을 제공합니다. 구조화된 Markdown 출력을 사용하여 코딩 프로세스를 단순화하고, firecrawl 및 tavily와 같은 스킬을 사용하여 네트워크에 액세스하고 데이터를 수집합니다.","es":"Permite a los agentes ejecutar flujos de trabajo de investigación a fondo utilizando la configuración de OpenAI Codex CLI, simplificando los procesos de codificación con salidas de Markdown estructuradas y aprovechando habilidades como firecrawl y tavily para el acceso y la recopilación de datos en la red.","fr":"Permet aux agents d''exécuter des flux de travail de recherche approfondie en utilisant les paramètres de OpenAI Codex CLI, en simplifiant les processus de codage avec des sorties Markdown structurées et en exploitant des compétences comme firecrawl et tavily pour l''accès et la collecte de données sur le réseau.","de":"Ermöglicht es Agents, tiefe Rechercheworkflows mit OpenAI Codex CLI-Einstellungen auszuführen, indem es die Codierprozesse mit strukturierten Markdown-Ausgaben rationalisiert und Fähigkeiten wie firecrawl und tavily für den Netzwerkzugriff und die Datensammlung nutzt.","pt":"Habilita os agentes a executar fluxos de trabalho de pesquisa aprofundada utilizando configurações do OpenAI Codex CLI, otimizando processos de codificação com saídas de Markdown estruturadas e aproveitando habilidades como firecrawl e tavily para acesso à rede e coleta de dados.","ru":"Позволяет агентам выполнять глубокие исследовательские рабочие процессы, используя настройки OpenAI Codex CLI, оптимизируя процессы кодирования с помощью структурированных выходных данных Markdown и используя навыки, такие как firecrawl и tavily, для доступа к сети и сбора данных.","ar":"تمكّن الوكلاء من تنفيذ سير عمل بحث متعمق باستخدام إعدادات OpenAI Codex CLI، وتبسيط عمليات البرمجة مع مخرجات Markdown المهيكلة، وتحقيق مهارات مثل firecrawl وتavily للوصول إلى الشبكة وجمع البيانات."},"useCases":{"en":["Automating coding workflows with vibe coding and OpenAI Codex CLI","Generating structured Markdown content through parallel sub-processes","Debugging and refining coding processes with default sandbox workspace-write permissions"],"zh":["使用vibe编码和OpenAI Codex CLI自动化编码工作流","通过并行子进程生成结构化的Markdown内容","使用默认的沙盒工作空间写入权限调试和完善编码过程"],"ja":["vibeコーディングとOpenAI Codex CLIを使用してコーディングワークフローを自動化する","並列サブプロセスを使用して構造化されたMarkdownコンテンツを生成する","デフォルトのサンドボックスワークスペース書き込み権限を使用してコーディングプロセスをデバッグおよび改良する"],"ko":["vibe 코딩과 OpenAI Codex CLI를 사용하여 코딩 워크플ロー 자동화","병렬 子 프로세스를 사용하여 구조화된 Markdown 내용 생성","기본 샌드박스 작업 공간 쓰기 권한을 사용하여 코딩 프로세스 디버깅 및 개선"],"es":["Automatización de flujos de trabajo de codificación con codificación de vibraciones y OpenAI Codex CLI","Generación de contenido Markdown estructurado a través de subprocesos paralelos","Depuración y refinamiento de los procesos de codificación con permisos de escritura de espacio de trabajo de sandbox predeterminados"],"fr":["Automatisation des flux de travail de codage avec le codage de vibrations et OpenAI Codex CLI","Génération de contenu Markdown structuré via des sous-processus parallèles","Débogage et affinement des processus de codage avec les autorisations d''écriture d''espace de travail de sandbox par défaut"],"de":["Automatisierung von Codier-Workflows mit Vibe-Coding und OpenAI Codex CLI","Generierung von strukturiertem Markdown-Inhalt durch parallele Subprozesse","Fehlerbehebung und Verfeinerung von Codierprozessen mit Standard-Sandbox-Arbeitsbereich-Schreibberechtigungen"],"pt":["Automatizar fluxos de trabalho de codificação com codificação de vibe e OpenAI Codex CLI","Gerar conteúdo de Markdown estruturado por meio de subprocessos paralelos","Depurar e refinar processos de codificação com permissões de espaço de trabalho de areia padrão"],"ru":["Автоматизировать рабочие процессы кодирования с кодированием vibe и OpenAI Codex CLI","Генерировать структурированный контент Markdown посредством параллельных subprocessов","Отлаживать и совершенствовать процессы кодирования с настройками по умолчанию для песочницы"],"ar":["تأتمتة سير عمل البرمجة باستخدام 编码 الكفء و OpenAI Codex CLI","генерировать محتوى Markdown المهيكل من خلال عمليات فرعية متوازية","تصحيح الأخطاء وتهيئة عمليات البرمجة بإعدادات مساحة العمل الرملية الافتراضية"]},"limitations":{"en":["Requires keeping default model and configuration unchanged","Needs explicit user authorization for adjusting related configurations","Default minimum permissions with optional network access via codex exec"],"zh":["需要保持默认模型和配置不变","需要显式的用户授权来调整相关配置","默认的最小权限，通过codex exec可选网络访问"],"ja":["デフォルトのモデルと構成を変更しないことを要求する","関連する構成を調整するために、明示的なユーザー認証が必要","デフォルトの最小権限、codex execを介してオプションのネットワークアクセス"],"ko":["기본 모델 및 구성이 변경되지 않도록 요구","관련 구성 조정을 위해 명시적인 사용자 인증이 필요","기본 최소 권한, codex exec를 통해 선택적 네트워크 액세스"],"es":["Requiere mantener el modelo y la configuración predeterminados sin cambios","Necesita autorización de usuario explícita para ajustar las configuraciones relacionadas","Permisos mínimos predeterminados con acceso a la red opcional a través de codex exec"],"fr":["Nécessite de maintenir le modèle et la configuration par défaut inchangés","Nécessite une autorisation utilisateur explicite pour ajuster les configurations associées","Autorisations minimales par défaut avec accès réseau facultatif via codex exec"],"de":["Erfordert, dass das Standardmodell und die Konfiguration unverändert bleiben","Benötigt eine explizite Benutzerautorisierung zur Anpassung der zugehörigen Konfigurationen","Standardmäßige Mindestberechtigungen mit optionaler Netzwerkzugriff über codex exec"],"pt":["Exige manter o modelo e a configuração padrão inalterados","Necessita de autorização explícita do usuário para ajustar configurações relacionadas","Permissões mínimas padrão com acesso à rede opcional via codex exec"],"ru":["Требует сохранения модели и конфигурации по умолчанию без изменений","Требует явного разрешения пользователя для регулировки связанных конфигураций","Минимальные разрешения по умолчанию с опциональным доступом к сети через codex exec"],"ar":["يتطلب الحفاظ على النموذج والتهيئة الافتراضية غير محدثة","يحتاج إلى تفويض مستخدم صريح لتعديل التهيئات المرتبطة","صلاحيات دنيا افتراضية مع وصول الشبكة اختياري عبر codex exec"]},"version":4},"contentHash":"44bf8a38bb93d1f937e1da5bfb0fa4b2987fca617575d9887938cdb03cecff99","qualityScore":36}');
